ench/extensions/manager/utils/systemCompatibility.ts","../../src/workbench/extensions/manager/utils/versionUtil.ts","../../src/workbench/extensions/manager/utils/conflictUtils.ts","../../src/workbench/extensions/manager/composables/useConflictDetection.ts"],"sourcesContent":["import { until } from '@vueuse/core'\n\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport {\n  readsSignedInWebSession,\n  useCloudWebSessionStore\n} from '@/platform/auth/session/cloudWebSessionStore'\nimport { useApiKeyAuthStore } from '@/stores/apiKeyAuthStore'\nimport { useAuthStore } from '@/stores/authStore'\n\nexport type CloudSignIn = 'signed_in' | 'signed_out' | 'pending'\n\nconst DIFFERENT_LOGIN_SIGN_OUT_TIMEOUT_MS = 5_000\n\nconst boots = new WeakMap<object, Promise<void>>()\n\n/** With SSO on, a signed-in session outranks a stored key; the key stays the fallback. */\nasync function storedApiKeyIsTheLogin(): Promise<boolean> {\n  if (useApiKeyAuthStore().getApiKey() === null) return false\n  const { flags } = useFeatureFlags()\n  if (!flags.ssoEnabled || !flags.unifiedWebSessionEnabled) return true\n  return !(await readsSignedInWebSession())\n}\n\nasync function bootOnce(): Promise<void> {\n  const auth = useAuthStore()\n  if (auth.currentUser === null && (await storedApiKeyIsTheLogin())) return\n  const webSession = useCloudWebSessionStore()\n  if (!webSession.start()) return\n  await webSession.whenReady()\n  const sessionId = webSession.signedInUser?.id\n  if (sessionId && auth.currentUser && auth.currentUser.uid !== sessionId) {\n    await until(() => auth.currentUser === null).toBe(true, {\n      timeout: DIFFERENT_LOGIN_SIGN_OUT_TIMEOUT_MS\n    })\n  }\n}\n\n/** Starts the web session once Firebase has restored, so it sees the remembered login. */\nexport function bootCloudIdentity(): Promise<void> {\n  const webSession = useCloudWebSessionStore()\n  const boot = boots.get(webSession) ?? bootOnce()\n  boots.set(webSession, boot)\n  return boot\n}\n\nexport async function cloudSignIn(): Promise<CloudSignIn> {\n  const auth = useAuthStore()\n  const hasTokenLogin = async () => (await auth.getAuthHeader()) !== null\n  await bootCloudIdentity()\n  const webSession = useCloudWebSessionStore()\n  await webSession.whenSessionCreated()\n  if (!webSession.isActive()) {\n    return (await hasTokenLogin()) ? 'signed_in' : 'signed_out'\n  }\n  const { state } = webSession\n  if (state.phase === 'signed_in') return 'signed_in'\n  if (state.phase === 'signed_out' && state.outcome === 'revoked') {\n    return 'signed_out'\n  }\n  if (await hasTokenLogin()) return 'signed_in'\n  return state.phase === 'retry_wait' ? 'pending' : 'signed_out'\n}\n","import type { LocationQuery } from 'vue-router'\n\nimport { capturePreservedQuery } from '@/platform/navigation/preservedQueryManager'\nimport { PRESERVED_QUERY_NAMESPACES } from '@/platform/navigation/preservedQueryNamespaces'\n\nconst SHARE_QUERY_KEY = 'share'\nconst MAX_SHARE_ID_LENGTH = 128\nconst SHARE_ID_PATTERN = /^[a-zA-Z0-9][a-zA-Z0-9_.-]*$/\n\nexport function isValidShareId(shareId: string): boolean {\n  return shareId.length <= MAX_SHARE_ID_LENGTH && SHARE_ID_PATTERN.test(shareId)\n}\n\nexport function preserveLoggedOutShareAuthAttribution(\n  query: LocationQuery,\n  isLoggedIn: boolean\n): void {\n  if (isLoggedIn) return\n\n  const shareId = query[SHARE_QUERY_KEY]\n  if (typeof shareId !== 'string' || !isValidShareId(shareId)) return\n\n  capturePreservedQuery(\n    PRESERVED_QUERY_NAMESPACES.SHARE_AUTH,\n    { [SHARE_QUERY_KEY]: shareId },\n    [SHARE_QUERY_KEY]\n  )\n}\n","import { until, useAsyncState } from '@vueuse/core'\nimport axios from 'axios'\nimport { defineStore, storeToRefs } from 'pinia'\n\nimport { bootCloudIdentity } from '@/platform/auth/session/cloudIdentityBoot'\nimport { isCloud } from '@/platform/distribution/types'\nimport { bootstrapTracer } from '@/platform/telemetry/perf/bootstrapTracer'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { api } from '@/scripts/api'\nimport { useAuthStore } from '@/stores/authStore'\nimport { useUserStore } from '@/stores/userStore'\n\n/**\n * Backends that vendor no custom-node locale files do not implement\n * `/api/i18n`, so a 404 means \"no custom-node translations\", not a failure.\n */\nasync function fetchCustomNodesI18n() {\n  try {\n    return await api.getCustomNodesI18n()\n  } catch (error) {\n    if (axios.isAxiosError(error) && error.response?.status === 404) return\n    throw error\n  }\n}\n\n// Matches the Firebase-auth-wait timeout used elsewhere (router.ts,\n// WorkspaceAuthGate.vue) so a broken/stale session fails this bounded wait\n// on the same schedule those already fail theirs.\nconst AUTH_WAIT_TIMEOUT_MS = 16_000\nconst AUTH_WAIT_RETRY_DELAY_MS = 3_000\n\n/**\n * Waits for Firebase auth initialization to complete, bounded so a stale\n * token or a broken auth response can never hang bootstrap forever.\n *\n * Only isInitialized is awaited — onAuthStateChanged fires with null for\n * signed-out users, so a signed-out load resolves this wait immediately\n * instead of burning the timeout and firing a false Sentry report. Waiting\n * for an actual user is a separate, unbounded wait in the caller.\n *\n * Retries once after a short delay; if auth is still unresolved, reports it\n * to every observability sink and lets bootstrap continue rather than leaving\n * the caller stuck.\n */\nasync function waitForCloudAuth(): Promise<void> {\n  const { isInitialized } = storeToRefs(useAuthStore())\n  const waitForResolution = () =>\n    until(isInitialized).toBe(true, {\n      timeout: AUTH_WAIT_TIMEOUT_MS,\n      throwOnTimeout: true\n    })\n\n  try {\n    await waitForResolution()\n  } catch (error) {\n    console.warn(\n      '[bootstrapStore] Auth did not resolve in time, retrying once',\n      error\n    )\n    await new Promise((resolve) =>\n      setTimeout(resolve, AUTH_WAIT_RETRY_DELAY_MS)\n    )\n    try {\n      await waitForResolution()\n    } catch (retryError) {\n      reportError(retryError, {\n        surface: 'platform',\n        errorType: 'bootstrap_auth_wait_timeout'\n      })\n    }\n  }\n}\n\nexport const useBootstrapStore = defineStore('bootstrap', () => {\n  const settingStore = useSettingStore()\n  const workflowStore = useWorkflowStore()\n\n  const {\n    isReady: isI18nReady,\n    error: i18nError,\n    execute: loadI18n\n  } = useAsyncState(\n    async () => {\n      const { mergeCustomNodesI18n } = await import('@/i18n')\n      const i18nData = await fetchCustomNodesI18n()\n      if (i18nData) mergeCustomNodesI18n(i18nData)\n    },\n    undefined,\n    { immediate: false }\n  )\n\n  let storesLoaded = false\n\n  function loadAuthenticatedStores(): Promise<void>[] {\n    if (storesLoaded) return []\n    storesLoaded = true\n\n    return [\n      bootstrapTracer.settle('bootstrap/settings', () => settingStore.load()),\n      bootstrapTracer.settle('bootstrap/workflows', () =>\n        workflowStore.loadWorkflows()\n      )\n    ]\n  }\n\n  async function startStoreBootstrap() {\n    void loadI18n()\n\n    if (isCloud) {\n      await bootstrapTracer.settle('auth-gate/initialized', waitForCloudAuth)\n      await bootCloudIdentity()\n\n      // Signed-out cloud pages (/cloud/login) must issue no authenticated\n      // request, so bootstrap parks here until the user signs in rather than\n      // loading stores that can only answer 401.\n      const { isAuthenticated } = storeToRefs(useAuthStore())\n      await until(isAuthenticated).toBe(true)\n    }\n\n    const userStore = useUserStore()\n    await bootstrapTracer.settle('auth-gate/user-store', () =>\n      userStore.initialize()\n    )\n\n    const { needsLogin } = storeToRefs(userStore)\n    await bootstrapTracer.settle('auth-gate/needs-login', () =>\n      until(needsLogin).toBe(false)\n    )\n\n    const storeLoads = loadAuthenticatedStores()\n    void Promise.allSettled(storeLoads).then(() => {\n      bootstrapTracer.milestone('stores-ready')\n    })\n  }\n\n  return {\n    isI18nReady,\n    i18nError,\n    startStoreBootstrap\n  }\n})\n","<script setup lang=\"ts\">\nimport type { HTMLAttributes } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { class: customClass = '' } = defineProps<{\n  class?: HTMLAttributes['class']\n}>()\n</script>\n\n<template>\n  <div\n    :class=\"\n      cn(\n        'flex shrink-0 items-center justify-end gap-2 px-4 pt-2 pb-4',\n        customClass\n      )\n    \"\n  >\n    <slot />\n  </div>\n</template>\n","// Reka portals its dialogs / popovers / menus into the body. When a\n// separately rooted Reka layer opens on top of a dialog, the dialog's\n// DismissableLayer sees a pointer-down on it as \"outside\" and would dismiss\n// itself. These selectors cover the portaled roots so we can treat\n// interactions on them as inside.\nconst REKA_PORTAL_SELECTORS =\n  '[data-reka-popper-content-wrapper], [data-reka-dialog-content], [data-reka-menu-content], [data-reka-context-menu-content], [data-reka-nested-dialog-overlay], [role=\"dialog\"], [role=\"menu\"], [role=\"listbox\"], [role=\"tooltip\"]'\n\n// Dismissing a toast or using a docked progress panel over a dialog must not\n// take the dialog with it; the empty viewport space beside a toast stays an\n// ordinary scrim click.\nconst TOAST_SELECTORS = '[data-toast-kind], [data-toast-dock]'\n\nconst OUTSIDE_LAYER_SELECTORS = `${REKA_PORTAL_SELECTORS}, ${TOAST_SELECTORS}`\n\ntype OutsideEvent = CustomEvent<{ originalEvent: Event }>\n\nfunction isInsideOverlay(target: EventTarget | null): boolean {\n  return (\n    target instanceof Element &&\n    target.closest(OUTSIDE_LAYER_SELECTORS) !== null\n  )\n}\n\nexport function onRekaPointerDownOutside(\n  options: { dismissOnPointerDownOutside?: boolean },\n  event: OutsideEvent\n) {\n  if (isInsideOverlay(event.detail.originalEvent.target)) {\n    event.preventDefault()\n    return\n  }\n  if (options.dismissOnPointerDownOutside === false) {\n    event.preventDefault()\n  }\n}\n","export default {\n  app_title: 'ComfyUI',\n  app_version: __COMFYUI_FRONTEND_VERSION__\n}\n","<script setup lang=\"ts\">\nimport type { TooltipProviderProps } from 'reka-ui'\nimport { TooltipProvider, useForwardProps } from 'reka-ui'\n\nimport { appTooltipProviderDefaults } from './tooltipConfig'\n\nconst {\n  delayDuration = appTooltipProviderDefaults.delayDuration,\n  ignoreNonKeyboardFocus = appTooltipProviderDefaults.ignoreNonKeyboardFocus,\n  ...restProps\n} = defineProps<Omit<TooltipProviderProps, 'disableHoverableContent'>>()\nconst forwarded = useForwardProps(restProps)\n</script>\n\n<template>\n  <TooltipProvider\n    v-bind=\"forwarded\"\n    :delay-duration\n    :ignore-non-keyboard-focus\n    :disable-hoverable-content=\"\n      appTooltipProviderDefaults.disableHoverableContent\n    \"\n  >\n    <slot />\n  </TooltipProvider>\n</template>\n","import { useDialogService } from '@/services/dialogService'\n\nconst lazyCloudNotificationContent = () =>\n  import('@/platform/cloud/notification/components/CloudNotificationContent.vue')\n\nexport function useCloudNotificationDialog() {\n  /** Shows one-time cloud notification modal for macOS desktop users. */\n  async function showCloudNotification(): Promise<void> {\n    const { default: component } = await lazyCloudNotificationContent()\n    return new Promise<void>((resolve) => {\n      useDialogService().showLayoutDialog({\n        key: 'global-cloud-notification',\n        component,\n        props: {},\n        dialogComponentProps: {\n          closable: false,\n          onRemoved: () => resolve()\n        }\n      })\n    })\n  }\n\n  return { showCloudNotification }\n}\n","import type { AxiosError, AxiosResponse } from 'axios'\nimport axios from 'axios'\nimport { ref } from 'vue'\n\nimport type { components, operations } from '@/types/comfyRegistryTypes'\nimport { isAbortError } from '@/utils/typeGuardUtil'\n\nconst API_BASE_URL = 'https://api.comfy.org'\n\nconst registryApiClient = axios.create({\n  baseURL: API_BASE_URL,\n  headers: {\n    'Content-Type': 'application/json'\n  },\n  paramsSerializer: {\n    // Disables PHP-style notation (e.g. param[]=value) in favor of repeated params (e.g. param=value1&param=value2)\n    indexes: null\n  }\n})\n\n/**\n * Service for interacting with the Comfy Registry API\n */\nexport const useComfyRegistryService = () => {\n  const isLoading = ref(false)\n  const error = ref<string | null>(null)\n\n  const handleApiError = (\n    err: unknown,\n    context: string,\n    routeSpecificErrors?: Record<number, string>\n  ): string => {\n    if (!axios.isAxiosError(err))\n      return err instanceof Error\n        ? `${context}: ${err.message}`\n        : `${context}: Unknown error occurred`\n\n    const axiosError = err as AxiosError<components['schemas']['ErrorResponse']>\n\n    if (axiosError.response) {\n      const { status, data } = axiosError.response\n\n      if (routeSpecificErrors && routeSpecificErrors[status])\n        return routeSpecificErrors[status]\n\n      switch (status) {\n        case 400:\n          return `Bad request: ${data.message || 'Invalid input'}`\n        case 401:\n          return 'Unauthorized: Authentication required'\n        case 403:\n          return `Forbidden: ${data.message || 'Access denied'}`\n        case 404:\n          return `Not found: ${data.message || 'Resource not found'}`\n        case 409:\n          return `Conflict: ${data.message || 'Resource conflict'}`\n        case 500:\n          return `Server error: ${data.message || 'Internal server error'}`\n        default:\n          return `${context}: ${data.message || axiosError.message}`\n      }\n    }\n\n    return `${context}: ${axiosError.message}`\n  }\n\n  /**\n   * Execute an API request with error and loading state handling\n   * @param apiCall - Function that returns a promise with the API call\n   * @param errorContext - Context description for error messages\n   * @param routeSpecificErrors - Optional map of status codes to custom error messages\n   * @returns Promise with the API response data or null if the request failed\n   */\n  const executeApiRequest = async <T>(\n    apiCall: () => Promise<AxiosResponse<T>>,\n    errorContext: string,\n    routeSpecificErrors?: Record<number, string>\n  ): Promise<T | null> => {\n    isLoading.value = true\n    error.value = null\n\n    try {\n      const response = await apiCall()\n      return response.data\n    } catch (err) {\n      // Don't treat cancellations as errors\n      if (isAbortError(err)) return null\n\n      error.value = handleApiError(err, errorContext, routeSpecificErrors)\n      return null\n    } finally {\n      isLoading.value = false\n    }\n  }\n\n  /**\n   * Get the Comfy Node definitions in a specific version of a node pack\n   * @param packId - The ID of the node pack\n   * @param versionId - The version of the node pack\n   * @returns The node definitions or null if not found or an error occurred\n   */\n  const getNodeDefs = async (\n    params: {\n      packId: components['schemas']['Node']['id']\n      version: components['schemas']['NodeVersion']['version']\n    } & operations['ListComfyNodes']['parameters']['query'],\n    signal?: AbortSignal\n  ) => {\n    const { packId, version: versionId, ...queryParams } = params\n    if (!packId || !versionId) return null\n\n    const endpoint = `/nodes/${packId}/versions/${versionId}/comfy-nodes`\n    const errorContext = 'Failed to get node definitions'\n    const routeSpecificErrors = {\n      403: 'This pack has been banned and its definition is not available',\n      404: 'The requested node, version, or comfy node does not exist'\n    }\n\n    return executeApiRequest(\n      () =>\n        registryApiClient.get<\n          operations['ListComfyNodes']['responses'][200]['content']['application/json']\n        >(endpoint, {\n          params: queryParams,\n          signal\n        }),\n      errorContext,\n      routeSpecificErrors\n    )\n  }\n\n  /**\n   * Get a paginated list of packs matching specific criteria.\n   * Search packs using `search` param. Search individual nodes using `comfy_node_search` param.\n   */\n  const search = async (\n    params?: operations['searchNodes']['parameters']['query'],\n    signal?: AbortSignal\n  ) => {\n    const endpoint = '/nodes/search'\n    const errorContext = 'Failed to perform search'\n\n    return executeApiRequest(\n      () =>\n        registryApiClient.get<\n          operations['searchNodes']['responses'][200]['content']['application/json']\n        >(endpoint, { params, signal }),\n      errorContext\n    )\n  }\n\n  /**\n   * Get publisher information\n   */\n  const getPublisherById = async (\n    publisherId: components['schemas']['Publisher']['id'],\n    signal?: AbortSignal\n  ) => {\n    const endpoint = `/publishers/${publisherId}`\n    const errorContext = 'Failed to get publisher'\n    const routeSpecificErrors = {\n      404: `Publisher not found: The publisher with ID ${publisherId} does not exist`\n    }\n\n    return executeApiRequest(\n      () =>\n        registryApiClient.get<components['schemas']['Publisher']>(endpoint, {\n          signal\n        }),\n      errorContext,\n      routeSpecificErrors\n    )\n  }\n\n  /**\n   * List all packs associated with a specific publisher\n   */\n  const listPacksForPublisher = async (\n    publisherId: components['schemas']['Publisher']['id'],\n    includeBanned?: boolean,\n    signal?: AbortSignal\n  ) => {\n    const params = includeBanned ? { include_banned: true } : undefined\n    const endpoint = `/publishers/${publisherId}/nodes`\n    const errorContext = 'Failed to list packs for publisher'\n    const routeSpecificErrors = {\n      400: 'Bad request: Invalid input data',\n      404: `Publisher not found: The publisher with ID ${publisherId} does not exist`\n    }\n\n    return executeApiRequest(\n      () =>\n        registryApiClient.get<components['schemas']['Node'][]>(endpoint, {\n          params,\n          signal\n        }),\n      errorContext,\n      routeSpecificErrors\n    )\n  }\n\n  /**\n   * Add a review for a pack\n   */\n  const postPackReview = async (\n    packId: components['schemas']['Node']['id'],\n    star: number,\n    signal?: AbortSignal\n  ) => {\n    const endpoint = `/nodes/${packId}/reviews`\n    const params = { star }\n    const errorContext = 'Failed to add review'\n    const routeSpecificErrors = {\n      400: 'Bad request: Invalid review',\n      404: `Pack not found: Pack with ID ${packId} does not exist`\n    }\n\n    return executeApiRequest(\n      () =>\n        registryApiClient.post<components['schemas']['Node']>(endpoint, null, {\n          params,\n          signal\n        }),\n      errorContext,\n      routeSpecificErrors\n    )\n  }\n\n  /**\n   * Get a paginated list of all packs on the registry\n   */\n  const listAllPacks = async (\n    params?: operations['listAllNodes']['parameters']['query'],\n    signal?: AbortSignal\n  ) => {\n    const endpoint = '/nodes'\n    const errorContext = 'Failed to list packs'\n\n    return executeApiRequest(\n      () =>\n        registryApiClient.get<\n          operations['listAllNodes']['responses'][200]['content']['application/json']\n        >(endpoint, { params, signal }),\n      errorContext\n    )\n  }\n\n  /**\n   * Get a list of all pack versions\n   */\n  const getPackVersions = async (\n    packId: components['schemas']['Node']['id'],\n    params?: operations['listNodeVersions']['parameters']['query'],\n    signal?: AbortSignal\n  ) => {\n    const endpoint = `/nodes/${packId}/versions`\n    const errorContext = 'Failed to get pack versions'\n    const routeSpecificErrors = {\n      403: 'This pack has been banned and its versions are not available',\n      404: `Pack not found: Pack with ID ${packId} does not exist`\n    }\n\n    return executeApiRequest(\n      () =>\n        registryApiClient.get<components['schemas']['NodeVersion'][]>(\n          endpoint,\n          { params, signal }\n        ),\n      errorContext,\n      routeSpecificErrors\n    )\n  }\n\n  /**\n   * Get a specific pack by ID and version\n   */\n  const getPackByVersion = async (\n    packId: components['schemas']['Node']['id'],\n    versionId: components['schemas']['NodeVersion']['id'],\n    signal?: AbortSignal\n  ) => {\n    const endpoint = `/nodes/${packId}/versions/${versionId}`\n    const errorContext = 'Failed to get pack version'\n    const routeSpecificErrors = {\n      403: 'This pack has been banned and its versions are not available',\n      404: `Pack not found: Pack with ID ${packId} does not exist`\n    }\n\n    return executeApiRequest(\n      () =>\n        registryApiClient.get<components['schemas']['NodeVersion']>(endpoint, {\n          signal\n        }),\n      errorContext,\n      routeSpecificErrors\n    )\n  }\n\n  /**\n   * Get a specific pack by ID\n   */\n  const getPackById = async (\n    packId: operations['getNode']['parameters']['path']['nodeId'],\n    signal?: AbortSignal\n  ) => {\n    const endpoint = `/nodes/${packId}`\n    const errorContext = 'Failed to get pack'\n    const routeSpecificErrors = {\n      404: `Pack not found: The pack with ID ${packId} does not exist`\n    }\n\n    return executeApiRequest(\n      () =>\n        registryApiClient.get<components['schemas']['Node']>(endpoint, {\n          signal\n        }),\n      errorContext,\n      routeSpecificErrors\n    )\n  }\n\n  /**\n   * Get the node pack that contains a specific ComfyUI node by its name.\n   * This method queries the registry to find which pack provides the given node.\n   *\n   * When multiple packs contain a node with the same name, the API returns the best match based on:\n   * 1. Preemption match - If the node name matches any in the pack's preempted_comfy_node_names array\n   * 2. Search ranking - Lower search_ranking values are preferred\n   * 3. Total installs - Higher installation counts are preferred as a tiebreaker\n   *\n   * @param nodeName - The name of the ComfyUI node (e.g., 'KSampler', 'CLIPTextEncode')\n   * @param signal - Optional AbortSignal for request cancellation\n   * @returns The node pack containing the specified node, or null if not found or on error\n   *\n   * @example\n   * ```typescript\n   * const pack = await inferPackFromNodeName('KSampler')\n   * if (pack) {\n   *   console.log(`Node found in pack: ${pack.name}`)\n   * }\n   * ```\n   */\n  const inferPackFromNodeName = async (\n    nodeName:\n      | operations['getNodeByComfyNodeName']['parameters']['path']['comfyNodeName']\n      | null\n      | undefined,\n    signal?: AbortSignal\n  ) => {\n    if (!nodeName || nodeName === 'undefined') return null\n\n    const endpoint = `/comfy-nodes/${nodeName}/node`\n    const errorContext = 'Failed to infer pack from comfy node name'\n    const routeSpecificErrors = {\n      404: `Comfy node not found: The node with name ${nodeName} does not exist in the registry`\n    }\n\n    return executeApiRequest(\n      () =>\n        registryApiClient.get<components['schemas']['Node']>(endpoint, {\n          signal\n        }),\n      errorContext,\n      routeSpecificErrors\n    )\n  }\n\n  /**\n   * Get multiple pack versions in a single bulk request.\n   * This is more efficient than making individual requests for each pack version.\n   *\n   * @param nodeVersions - Array of node ID and version pairs to retrieve\n   * @param signal - Optional AbortSignal for request cancellation\n   * @returns Bulk response containing the requested node versions or null on error\n   *\n   * @example\n   * ```typescript\n   * const versions = await getBulkNodeVersions([\n   *   { node_id: 'ComfyUI-Manager', version: '1.0.0' },\n   *   { node_id: 'ComfyUI-Impact-Pack', version: '2.0.0' }\n   * ])\n   * if (versions) {\n   *   versions.node_versions.forEach(result => {\n   *     if (result.status === 'success' && result.node_version) {\n   *       console.log(`Retrieved ${result.identifier.node_id}@${result.identifier.version}`)\n   *     }\n   *   })\n   * }\n   * ```\n   */\n  const getBulkNodeVersions = async (\n    nodeVersions: components['schemas']['NodeVersionIdentifier'][],\n    signal?: AbortSignal\n  ) => {\n    const endpoint = '/bulk/nodes/versions'\n    const errorContext = 'Failed to get bulk node versions'\n    const routeSpecificErrors = {\n      400: 'Bad request: Invalid node version identifiers provided'\n    }\n\n    const requestBody: components['schemas']['BulkNodeVersionsRequest'] = {\n      node_versions: nodeVersions\n    }\n\n    return executeApiRequest(\n      () =>\n        registryApiClient.post<\n          components['schemas']['BulkNodeVersionsResponse']\n        >(endpoint, requestBody, {\n          signal\n        }),\n      errorContext,\n      routeSpecificErrors\n    )\n  }\n\n  return {\n    isLoading,\n    error,\n\n    listAllPacks,\n    search,\n    getPackById,\n    getPackVersions,\n    getPackByVersion,\n    getPublisherById,\n    listPacksForPublisher,\n    getNodeDefs,\n    postPackReview,\n    inferPackFromNodeName,\n    getBulkNodeVersions\n  }\n}\n","import QuickLRU from '@alloc/quick-lru'\n\nimport { paramsToCacheKey } from '@/utils/formatUtil'\n\nconst DEFAULT_MAX_SIZE = 50\n\ninterface CachedRequestOptions {\n  /**\n   * Maximum number of items to store in the cache\n   * @default 50\n   */\n  maxSize?: number\n  /**\n   * Function to generate a cache key from parameters\n   */\n  cacheKeyFn?: (params: unknown) => string\n}\n\n/**\n * Composable that wraps a function with memoization, request deduplication, and abort handling.\n */\nexport function useCachedRequest<TParams, TResult>(\n  requestFunction: (\n    params: TParams,\n    signal?: AbortSignal\n  ) => Promise<TResult | null>,\n  options: CachedRequestOptions = {}\n) {\n  const { maxSize = DEFAULT_MAX_SIZE, cacheKeyFn = paramsToCacheKey } = options\n\n  const cache = new QuickLRU<string, TResult | null>({ maxSize })\n  const pendingRequests = new Map<string, Promise<TResult | null>>()\n  const abortControllers = new Map<string, AbortController>()\n\n  const executeAndCacheCall = async (\n    params: TParams,\n    cacheKey: string\n  ): Promise<TResult | null> => {\n    try {\n      const controller = new AbortController()\n      abortControllers.set(cacheKey, controller)\n\n      const responsePromise = requestFunction(params, controller.signal)\n      pendingRequests.set(cacheKey, responsePromise)\n\n      const result = await responsePromise\n      cache.set(cacheKey, result)\n\n      return result\n    } catch {\n      // Set cache on error to prevent retrying bad requests\n      cache.set(cacheKey, null)\n      return null\n    } finally {\n      pendingRequests.delete(cacheKey)\n      abortControllers.delete(cacheKey)\n    }\n  }\n\n  const handlePendingRequest = async (\n    pendingRequest: Promise<TResult | null>\n  ): Promise<TResult | null> => {\n    try {\n      return await pendingRequest\n    } catch (err) {\n      console.error('Error in pending request:', err)\n      return null\n    }\n  }\n\n  const abortAllRequests = () => {\n    for (const controller of abortControllers.values()) {\n      controller.abort()\n    }\n  }\n\n  /**\n   * Cancel and clear any pending requests\n   */\n  const cancel = () => {\n    abortAllRequests()\n    abortControllers.clear()\n    pendingRequests.clear()\n  }\n\n  /**\n   * Cached version of the request function\n   */\n  const call = async (params: TParams): Promise<TResult | null> => {\n    const cacheKey = cacheKeyFn(params)\n\n    const cachedResult = cache.get(cacheKey)\n    if (cachedResult !== undefined) return cachedResult\n\n    const pendingRequest = pendingRequests.get(cacheKey)\n    if (pendingRequest) return handlePendingRequest(pendingRequest)\n\n    return executeAndCacheCall(params, cacheKey)\n  }\n\n  return {\n    call,\n    cancel,\n    clear: () => cache.clear()\n  }\n}\n","import QuickLRU from '@alloc/quick-lru'\nimport { partition } from 'es-toolkit/compat'\nimport { defineStore } from 'pinia'\n\nimport { useCachedRequest } from '@/composables/useCachedRequest'\nimport { useComfyRegistryService } from '@/services/comfyRegistryService'\nimport type { components, operations } from '@/types/comfyRegistryTypes'\n\nconst PACK_LIST_CACHE_SIZE = 20\nconst PACK_BY_ID_CACHE_SIZE = 64\n\ntype NodePack = components['schemas']['Node']\ntype ListPacksParams = operations['listAllNodes']['parameters']['query']\ntype ListPacksResult =\n  operations['listAllNodes']['responses'][200]['content']['application/json']\ntype GetNodeDefsParams = operations['ListComfyNodes']['parameters']['query'] & {\n  packId: components['schemas']['Node']['id']\n  version: components['schemas']['NodeVersion']['version']\n}\ntype GetPackByIdPath = operations['getNode']['parameters']['path']['nodeId']\n\nconst isNodePack = (pack: NodePack | undefined): pack is NodePack => {\n  return pack !== undefined && 'id' in pack\n}\n\n/**\n * Store for managing remote custom nodes\n */\nexport const useComfyRegistryStore = defineStore('comfyRegistry', () => {\n  const registryService = useComfyRegistryService()\n\n  let getPacksByIdController: AbortController | null = null\n  const getPacksByIdCache = new QuickLRU<NodePack['id'], NodePack>({\n    maxSize: PACK_BY_ID_CACHE_SIZE\n  })\n\n  /**\n   * Get a list of all node packs from the registry\n   */\n  const listAllPacks = useCachedRequest<ListPacksParams, ListPacksResult>(\n    registryService.listAllPacks,\n    { maxSize: PACK_LIST_CACHE_SIZE }\n  )\n\n  /**\n   * Get a pack by its ID from the registry\n   */\n  const getPackById = useCachedRequest<GetPackByIdPath, NodePack>(\n    async (params) => {\n      if (!params) return null\n      return registryService.getPackById(params)\n    },\n    { maxSize: PACK_BY_ID_CACHE_SIZE }\n  )\n\n  /**\n   * Get a list of packs by their IDs from the registry\n   */\n  const getPacksByIds = async (ids: NodePack['id'][]): Promise<NodePack[]> => {\n    const [cachedPacksIds, uncachedPacksIds] = partition(ids, (id) =>\n      getPacksByIdCache.has(id)\n    )\n\n    const resolvedPacks = cachedPacksIds\n      .map((id) => getPacksByIdCache.get(id))\n      .filter(isNodePack)\n\n    if (uncachedPacksIds.length) {\n      getPacksByIdController = new AbortController()\n      const uncachedPacks = await registryService.listAllPacks(\n        {\n          node_id: uncachedPacksIds.filter(\n            (id): id is string => id !== undefined\n          )\n        },\n        getPacksByIdController.signal\n      )\n\n      const { nodes = [] } = uncachedPacks ?? {}\n      nodes.forEach((pack) => {\n        if (pack.id) {\n          getPacksByIdCache.set(pack.id, pack)\n          resolvedPacks.push(pack)\n        }\n      })\n    }\n\n    return resolvedPacks\n  }\n\n  /**\n   * Get the node definitions for a pack\n   */\n  const getNodeDefs = useCachedRequest<\n    GetNodeDefsParams,\n    operations['ListComfyNodes']['responses'][200]['content']['application/json']\n  >(registryService.getNodeDefs, { maxSize: PACK_BY_ID_CACHE_SIZE })\n\n  /**\n   * Search for packs by pack name or node names\n   */\n  const search = useCachedRequest<\n    operations['searchNodes']['parameters']['query'],\n    ListPacksResult\n  >(registryService.search, { maxSize: PACK_LIST_CACHE_SIZE })\n\n  /**\n   * Get the node pack that contains a specific ComfyUI node by its name.\n   * Results are cached to avoid redundant API calls.\n   *\n   * @see {@link useComfyRegistryService.inferPackFromNodeName} for details on the ranking algorithm\n   */\n  const inferPackFromNodeName = useCachedRequest<\n    operations['getNodeByComfyNodeName']['parameters']['path']['comfyNodeName'],\n    NodePack\n  >(registryService.inferPackFromNodeName, { maxSize: PACK_BY_ID_CACHE_SIZE })\n\n  /**\n   * Clear all cached data\n   */\n  const clearCache = () => {\n    getNodeDefs.clear()\n    listAllPacks.clear()\n    getPackById.clear()\n    inferPackFromNodeName.clear()\n  }\n\n  /**\n   * Cancel all any in-flight requests.\n   */\n  const cancelRequests = () => {\n    getNodeDefs.cancel()\n    listAllPacks.cancel()\n    getPackById.cancel()\n    inferPackFromNodeName.cancel()\n    getPacksByIdController?.abort()\n  }\n\n  return {\n    listAllPacks,\n    getPackById,\n    getPacksByIds: {\n      call: getPacksByIds,\n      cancel: () => getPacksByIdController?.abort()\n    },\n    getNodeDefs,\n    search,\n    inferPackFromNodeName,\n\n    clearCache,\n    cancelRequests,\n\n    isLoading: registryService.isLoading,\n    error: registryService.error\n  }\n})\n","import { get, useAsyncState } from '@vueuse/core'\nimport type { Ref } from 'vue'\n\nimport { useComfyRegistryStore } from '@/stores/comfyRegistryStore'\nimport type { UseNodePacksOptions } from '@/workbench/extensions/manager/types/comfyManagerTypes'\n\n/**\n * Handles fetching node packs from the registry given a list of node pack IDs\n */\nexport const useNodePacks = (\n  packsIds: string[] | Ref<string[]>,\n  options: UseNodePacksOptions = {}\n) => {\n  const { immediate = false } = options\n  const { getPacksByIds } = useComfyRegistryStore()\n\n  const fetchPacks = () => getPacksByIds.call(get(packsIds).filter(Boolean))\n\n  const {\n    isReady,\n    isLoading,\n    error,\n    execute,\n    state: nodePacks\n  } = useAsyncState(fetchPacks, [], {\n    immediate\n  })\n\n  const cleanup = () => {\n    getPacksByIds.cancel()\n    isReady.value = false\n    isLoading.value = false\n  }\n\n  return {\n    error,\n    isLoading,\n    isReady,\n    nodePacks,\n    startFetch: execute,\n    cleanup\n  }\n}\n","import { useEventListener } from '@vueuse/core'\nimport { onUnmounted, ref } from 'vue'\n\nimport type { LogsWsMessage } from '@/platform/remote/comfyui/execution/types'\nimport { api } from '@/scripts/api'\nimport type { components } from '@/workbench/extensions/manager/types/generatedManagerTypes'\n\nconst LOGS_MESSAGE_TYPE = 'logs'\nconst MANAGER_WS_TASK_DONE_NAME = 'cm-task-completed'\nconst MANAGER_WS_TASK_STARTED_NAME = 'cm-task-started'\n\ntype ManagerWsTaskDoneMsg = components['schemas']['MessageTaskDone']\ntype ManagerWsTaskStartedMsg = components['schemas']['MessageTaskStarted']\n\ninterface UseServerLogsOptions {\n  ui_id?: string\n  immediate?: boolean\n  messageFilter?: (message: string) => boolean\n}\n\nexport const useServerLogs = (options: UseServerLogsOptions = {}) => {\n  const {\n    ui_id,\n    immediate = false,\n    messageFilter = (msg: string) => Boolean(msg.trim())\n  } = options\n\n  const logs = ref<string[]>([])\n  const isTaskStarted = ref(!ui_id) // If no ui_id, capture all logs immediately\n  let stopLogs: ReturnType<typeof useEventListener> | null = null\n  let stopTaskDone: ReturnType<typeof useEventListener> | null = null\n  let stopTaskStarted: ReturnType<typeof useEventListener> | null = null\n\n  const isValidLogEvent = (event: CustomEvent<LogsWsMessage>) =>\n    event.type === LOGS_MESSAGE_TYPE && event.detail.entries.length > 0\n\n  const parseLogMessage = (event: CustomEvent<LogsWsMessage>) =>\n    event.detail.entries.map((e) => e.m).filter(messageFilter)\n\n  const handleLogMessage = (event: CustomEvent<LogsWsMessage>) => {\n    // Only capture logs if this task has started\n    if (!isTaskStarted.value) return\n\n    if (isValidLogEvent(event)) {\n      const messages = parseLogMessage(event)\n      if (messages.length > 0) {\n        logs.value.push(...messages)\n      }\n    }\n  }\n\n  const handleTaskStarted = (event: CustomEvent<ManagerWsTaskStartedMsg>) => {\n    if (ui_id && event.detail.ui_id === ui_id) {\n      isTaskStarted.value = true\n    }\n  }\n\n  const handleTaskDone = (event: CustomEvent<ManagerWsTaskDoneMsg>) => {\n    if (ui_id && event.detail.ui_id === ui_id) {\n      isTaskStarted.value = false\n    }\n  }\n\n  const start = async () => {\n    await api.subscribeLogs(true)\n    stopLogs = useEventListener(api, LOGS_MESSAGE_TYPE, handleLogMessage)\n\n    if (ui_id) {\n      stopTaskStarted = useEventListener(\n        api,\n        MANAGER_WS_TASK_STARTED_NAME,\n        handleTaskStarted\n      )\n      stopTaskDone = useEventListener(\n        api,\n        MANAGER_WS_TASK_DONE_NAME,\n        handleTaskDone\n      )\n    }\n  }\n\n  const stopListening = async () => {\n    stopLogs?.()\n    stopTaskStarted?.()\n    stopTaskDone?.()\n    stopLogs = null\n    stopTaskStarted = null\n    stopTaskDone = null\n    await api.subscribeLogs(false)\n  }\n\n  if (immediate) {\n    void start()\n  }\n\n  onUnmounted(async () => {\n    await stopListening()\n    logs.value = []\n  })\n\n  return {\n    logs,\n    startListening: start,\n    stopListening\n  }\n}\n","import { mapKeys } from 'es-toolkit/compat'\n\n/**\n * Normalizes a pack ID by removing the version suffix.\n *\n * ComfyUI-Manager returns pack IDs in different formats:\n * - Enabled packs: \"packname\" (without version)\n * - Disabled packs: \"packname@1_0_3\" (with version suffix)\n * - Latest versions from registry: \"packname\" (without version)\n *\n * Since the pack object itself contains the version info (ver field),\n * we normalize all pack IDs to just the base name for consistent access.\n * This ensures we can always find a pack by its base name (nodePack.id)\n * regardless of its enabled/disabled state.\n *\n * @param packId - The pack ID that may contain a version suffix\n * @returns The normalized pack ID without version suffix\n */\nexport function normalizePackId(packId: string): string {\n  return packId.split('@')[0]\n}\n\n/**\n * Normalizes all keys in a pack record by removing version suffixes.\n * This is used when receiving pack data from the server to ensure\n * consistent key format across the application.\n *\n * @param packs - Record of packs with potentially versioned keys\n * @returns Record with normalized keys\n */\nexport function normalizePackKeys<T>(\n  packs: Record<string, T>\n): Record<string, T> {\n  return mapKeys(packs, (_value, key) => normalizePackId(key))\n}\n","import { useEventListener } from '@vueuse/core'\nimport { pickBy } from 'es-toolkit/compat'\nimport type { Ref } from 'vue'\nimport { computed, ref } from 'vue'\n\nimport { t } from '@/i18n'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { app } from '@/scripts/app'\nimport { normalizePackKeys } from '@/utils/packUtils'\nimport type { components } from '@/workbench/extensions/manager/types/generatedManagerTypes'\n\ntype ManagerTaskHistory = Record<\n  string,\n  components['schemas']['TaskHistoryItem']\n>\ntype ManagerTaskQueue = components['schemas']['TaskStateMessage']\ntype ManagerWsTaskDoneMsg = components['schemas']['MessageTaskDone']\ntype ManagerWsTaskStartedMsg = components['schemas']['MessageTaskStarted']\ntype QueueTaskItem = components['schemas']['QueueTaskItem']\ntype HistoryTaskItem = components['schemas']['TaskHistoryItem']\ntype Task = QueueTaskItem | HistoryTaskItem\n\nconst MANAGER_WS_TASK_DONE_NAME = 'cm-task-completed'\nconst MANAGER_WS_TASK_STARTED_NAME = 'cm-task-started'\n\nexport const useManagerQueue = (\n  taskHistory: Ref<ManagerTaskHistory>,\n  taskQueue: Ref<ManagerTaskQueue>,\n  installedPacks: Ref<Record<string, unknown>>\n) => {\n  const toast = useToast()\n\n  // Task queue state (read-only from server)\n  const maxHistoryItems = ref(64)\n  const isLoading = ref(false)\n  const isProcessing = ref(false)\n\n  // Computed values\n  const currentQueueLength = computed(\n    () =>\n      taskQueue.value.running_queue.length +\n      taskQueue.value.pending_queue.length\n  )\n\n  /**\n   * Update the processing state based on the current queue length.\n   * If the queue is empty, or all tasks in the queue are associated\n   * with different clients, then this client is not processing any tasks.\n   */\n  const updateProcessingState = (): void => {\n    isProcessing.value = currentQueueLength.value > 0\n  }\n\n  const allTasksDone = computed(() => currentQueueLength.value === 0)\n  const historyCount = computed(() => Object.keys(taskHistory.value).length)\n\n  /**\n   * Check if a task is associated with this client.\n   * Task can be from running queue, pending queue, or history.\n   * @param task - The task to check\n   * @returns True if the task belongs to this client\n   */\n  const isTaskFromThisClient = (task: Task): boolean =>\n    task.client_id === app.api.clientId\n\n  /**\n   * Check if a history task is associated with this client.\n   * @param task - The history task to check\n   * @returns True if the task belongs to this client\n   */\n  const isHistoryTaskFromThisClient = (task: HistoryTaskItem): boolean =>\n    task.client_id === app.api.clientId\n\n  /**\n   * Filter queue tasks by client id.\n   * Ensures that only tasks associated with this client are processed and\n   * added to client state.\n   * @param tasks - Array of queue tasks to filter\n   * @returns Filtered array containing only tasks from this client\n   */\n  const filterQueueByClientId = (tasks: QueueTaskItem[]): QueueTaskItem[] =>\n    tasks.filter(isTaskFromThisClient)\n\n  /**\n   * Filter history tasks by client id using pickBy for optimal performance.\n   * Returns a new object containing only tasks associated with this client.\n   * @param history - The history object to filter\n   * @returns Filtered history object containing only tasks from this client\n   */\n  const filterHistoryByClientId = (history: ManagerTaskHistory) =>\n    pickBy(history, isHistoryTaskFromThisClient)\n\n  /**\n   * Update task queue and history state with filtered data from server.\n   * Ensures only tasks from this client are stored in local state.\n   * @param state - The task state message from the server\n   */\n  const updateTaskState = (state: ManagerTaskQueue) => {\n    taskQueue.value.running_queue = filterQueueByClientId(state.running_queue)\n    taskQueue.value.pending_queue = filterQueueByClientId(state.pending_queue)\n    taskHistory.value = filterHistoryByClientId(state.history)\n\n    installedPacks.value = normalizePackKeys(state.installed_packs)\n    updateProcessingState()\n  }\n\n  // WebSocket event listener for task done\n  const cleanupTaskDoneListener = useEventListener(\n    app.api,\n    MANAGER_WS_TASK_DONE_NAME,\n    (event: CustomEvent<ManagerWsTaskDoneMsg>) => {\n      if (event.type === MANAGER_WS_TASK_DONE_NAME) {\n        const { ui_id: taskId, state, status, result } = event.detail\n        const wasCompleted = Object.hasOwn(taskHistory.value, taskId)\n        const completedTask = state.history[taskId]\n        updateTaskState(state)\n        if (\n          Object.hasOwn(state.history, taskId) &&\n          (status ?? completedTask.status)?.status_str === 'error' &&\n          isHistoryTaskFromThisClient(completedTask) &&\n          !wasCompleted\n        ) {\n          toast.error(t('g.error'), { description: result })\n        }\n      }\n    }\n  )\n\n  // WebSocket event listener for task started\n  const cleanupTaskStartedListener = useEventListener(\n    app.api,\n    MANAGER_WS_TASK_STARTED_NAME,\n    (event: CustomEvent<ManagerWsTaskStartedMsg>) => {\n      if (event.type === MANAGER_WS_TASK_STARTED_NAME) {\n        updateTaskState(event.detail.state)\n      }\n    }\n  )\n\n  /**\n   * Cleanup function to remove event listeners and reset state\n   */\n  const cleanup = () => {\n    cleanupTaskDoneListener()\n    cleanupTaskStartedListener()\n\n    // Reset state\n    isProcessing.value = false\n    isLoading.value = false\n  }\n\n  return {\n    // State\n    isLoading,\n    isProcessing,\n    maxHistoryItems,\n\n    // Computed\n    allTasksDone,\n    historyCount,\n    currentQueueLength,\n\n    // Actions\n    updateTaskState,\n    cleanup\n  }\n}\n","<template>\n  <ComboboxRoot\n    ref=\"comboboxRef\"\n    v-model:open=\"isOpen\"\n    ignore-filter\n    :reset-search-term-on-blur=\"false\"\n    :reset-search-term-on-select=\"false\"\n    :disabled\n    :open-on-focus\n    :open-on-click=\"openOnFocus\"\n    :class=\"className\"\n    @highlight=\"onHighlight\"\n  >\n    <ComboboxAnchor\n      :class=\"\n        cn(\n          searchInputVariants({ size }),\n          disabled && 'pointer-events-none opacity-50',\n          anchorClass\n        )\n      \"\n      @click=\"focus\"\n    >\n      <slot name=\"leading\" />\n      <Button\n        v-if=\"modelValue\"\n        :class=\"cn('absolute', sizeConfig.clearPos)\"\n        variant=\"textonly\"\n        size=\"icon-sm\"\n        :aria-label=\"$t('g.clear')\"\n        @click.stop=\"clearSearch\"\n      >\n        <i :class=\"cn('icon-[lucide--x]', sizeConfig.icon)\" />\n      </Button>\n      <i\n        v-else-if=\"loading\"\n        :class=\"\n          cn(\n            'pointer-events-none absolute icon-[lucide--loader-circle] animate-spin',\n            sizeConfig.iconPos,\n            sizeConfig.icon\n          )\n        \"\n      />\n      <i\n        v-else\n        :class=\"\n          cn(\n            'pointer-events-none absolute',\n            sizeConfig.iconPos,\n            sizeConfig.icon,\n            icon\n          )\n        \"\n      />\n\n      <ComboboxInput\n        :id=\"inputId\"\n        ref=\"inputRef\"\n        v-model=\"modelValue\"\n        :class=\"\n          cn(\n            'h-full min-w-0 flex-1 border-none bg-transparent outline-none',\n            sizeConfig.inputPl,\n            sizeConfig.inputText\n          )\n        \"\n        :placeholder=\"placeholderText\"\n        :auto-focus=\"autofocus\"\n        @compositionstart=\"isComposing = true\"\n        @compositionend=\"isComposing = false\"\n        @keydown.enter=\"onEnterKey\"\n      />\n    </ComboboxAnchor>\n\n    <ComboboxPortal>\n      <ComboboxContent\n        v-if=\"suggestions.length > 0\"\n        position=\"popper\"\n        :side-offset=\"4\"\n        :style=\"[contentStyle, liftedContentStyle]\"\n        :class=\"\n          cn(\n            'z-3000 max-h-60 w-(--reka-combobox-trigger-width) overflow-y-auto',\n            'rounded-lg border border-border-default bg-base-background p-1 shadow-lg'\n          )\n        \"\n      >\n        <ComboboxItem\n          v-for=\"(suggestion, index) in suggestions\"\n          :key=\"suggestionKey(suggestion, index)\"\n          :value=\"suggestionValue(suggestion)\"\n          :data-suggestion-index=\"index\"\n          :aria-label=\"suggestionLabel(suggestion)\"\n          :class=\"\n            cn(\n              'cursor-pointer rounded-sm px-3 py-2 text-sm outline-none',\n              'data-highlighted:bg-secondary-background-hover'\n            )\n          \"\n          @select.prevent=\"onSelectSuggestion(suggestion)\"\n        >\n          <slot name=\"suggestion\" :suggestion>\n            {{ suggestionLabel(suggestion) }}\n          </slot>\n        </ComboboxItem>\n      </ComboboxContent>\n    </ComboboxPortal>\n  </ComboboxRoot>\n</template>\n\n<script setup lang=\"ts\" generic=\"T\">\nimport type { HTMLAttributes, StyleValue } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\nimport {\n  ComboboxAnchor,\n  ComboboxContent,\n  ComboboxInput,\n  ComboboxItem,\n  ComboboxPortal,\n  ComboboxRoot\n} from 'reka-ui'\nimport { computed, nextTick, ref, useTemplateRef, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useModalLiftedZIndex } from '@/composables/useModalLiftedZIndex'\nimport type { SearchInputVariants } from './searchInput.variants'\nimport {\n  searchInputSizeConfig,\n  searchInputVariants\n} from './searchInput.variants'\n\nconst { t } = useI18n()\n\nconst {\n  placeholder,\n  icon = 'icon-[lucide--search]',\n  autofocus = false,\n  inputId,\n  loading = false,\n  disabled = false,\n  openOnFocus = false,\n  updateModelOnSelect = true,\n  size = 'md',\n  suggestions = [],\n  optionLabel,\n  optionKey,\n  class: className,\n  anchorClass,\n  contentStyle\n} = defineProps<{\n  placeholder?: string\n  icon?: string\n  autofocus?: boolean\n  inputId?: string\n  loading?: boolean\n  disabled?: boolean\n  openOnFocus?: boolean\n  updateModelOnSelect?: boolean\n  size?: SearchInputVariants['size']\n  suggestions?: T[]\n  optionLabel?: keyof T & string\n  optionKey?: keyof T & string\n  class?: HTMLAttributes['class']\n  anchorClass?: HTMLAttributes['class']\n  contentStyle?: StyleValue\n}>()\n\nconst emit = defineEmits<{\n  select: [item: T]\n  highlight: [item: T | undefined]\n}>()\n\nconst sizeConfig = computed(() => searchInputSizeConfig[size])\n\nconst modelValue = defineModel<string>({ required: true })\n\nconst comboboxRef = useTemplateRef('comboboxRef')\nconst inputRef = ref<InstanceType<typeof ComboboxInput> | null>(null)\nconst isOpen = ref(false)\nconst isComposing = ref(false)\nconst liftedContentStyle = useModalLiftedZIndex(isOpen)\n\nfunction focus() {\n  inputRef.value?.$el?.focus()\n}\n\nfunction open() {\n  isOpen.value = true\n}\n\ndefineExpose({ focus, open })\n\nconst placeholderText = computed(\n  () => placeholder ?? t('g.searchPlaceholder', { subject: '' })\n)\n\nfunction clearSearch() {\n  modelValue.value = ''\n  focus()\n}\n\nfunction getItemProperty(item: T, key: keyof T & string): string {\n  if (typeof item === 'object' && item !== null) {\n    return String(item[key])\n  }\n  return String(item)\n}\n\nfunction suggestionLabel(item: T): string {\n  if (optionLabel) return getItemProperty(item, optionLabel)\n  return String(item)\n}\n\nfunction suggestionKey(item: T, index: number): string {\n  if (optionKey) return getItemProperty(item, optionKey)\n  return `${suggestionLabel(item)}-${index}`\n}\n\nfunction suggestionValue(item: T): string {\n  return suggestionLabel(item)\n}\n\nfunction onSelectSuggestion(item: T) {\n  if (updateModelOnSelect) modelValue.value = suggestionLabel(item)\n  isOpen.value = false\n  emit('select', item)\n}\n\nfunction onHighlight(payload: { ref: HTMLElement } | undefined) {\n  const index = Number(payload?.ref.dataset.suggestionIndex)\n  emit('highlight', Number.isInteger(index) ? suggestions[index] : undefined)\n}\n\nfunction onEnterKey(e: KeyboardEvent) {\n  if (isComposing.value) {\n    e.preventDefault()\n    e.stopPropagation()\n  }\n}\n\nwatch(\n  () => suggestions,\n  async (items) => {\n    isOpen.value = items.length > 0 && (openOnFocus || !!modelValue.value)\n    if (isOpen.value) {\n      await nextTick()\n      comboboxRef.value?.highlightFirstItem?.()\n    }\n  }\n)\n</script>\n","<template>\n  <i :class=\"icon\" class=\"shrink-0 text-sm text-base-foreground\" />\n</template>\n\n<script setup lang=\"ts\">\nimport type { NavItemData } from '@/types/navTypes'\n\ndefineProps<{\n  icon: NavItemData['icon']\n}>()\n</script>\n","<template>\n  <Tooltip :disabled=\"!isOverflowing\">\n    <TooltipTrigger as-child>\n      <div\n        v-bind=\"$attrs\"\n        :class=\"\n          cn(\n            'flex cursor-pointer items-center-safe gap-2 rounded-md px-4 py-3 text-sm text-base-foreground transition-colors select-none',\n            active\n              ? 'bg-interface-menu-component-surface-selected'\n              : 'hover:bg-interface-menu-component-surface-hovered'\n          )\n        \"\n        role=\"button\"\n        @mouseenter=\"checkOverflow\"\n        @click=\"onClick\"\n      >\n        <NavIcon v-if=\"icon\" :icon=\"icon\" />\n        <i\n          v-else\n          class=\"icon-[lucide--folder] size-3.5 shrink-0 text-base-foreground\"\n        />\n        <span ref=\"textRef\" class=\"min-w-0 truncate\">\n          <slot />\n        </span>\n        <StatusBadge\n          v-if=\"badge !== undefined\"\n          :label=\"String(badge)\"\n          severity=\"contrast\"\n          variant=\"circle\"\n          class=\"ml-auto min-h-5 min-w-5 px-1 text-base-background\"\n        />\n        <i\n          v-else-if=\"suffixIcon\"\n          :class=\"cn('ml-auto size-4 shrink-0', suffixIcon)\"\n          aria-hidden=\"true\"\n        />\n      </div>\n    </TooltipTrigger>\n    <TooltipContent side=\"right\" class=\"w-max whitespace-nowrap\">{{\n      tooltipText\n    }}</TooltipContent>\n  </Tooltip>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\n\nimport StatusBadge from '@/components/common/StatusBadge.vue'\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\nimport type { NavItemData } from '@/types/navTypes'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport NavIcon from './NavIcon.vue'\n\ndefineOptions({ inheritAttrs: false })\n\nconst { icon, badge, suffixIcon, active, onClick } = defineProps<{\n  icon: NavItemData['icon']\n  badge?: NavItemData['badge']\n  suffixIcon?: NavItemData['suffixIcon']\n  active?: boolean\n  onClick: () => void\n}>()\n\nconst textRef = ref<HTMLElement | null>(null)\nconst isOverflowing = ref(false)\n\nconst checkOverflow = () => {\n  if (!textRef.value) return\n  isOverflowing.value =\n    textRef.value.scrollWidth > textRef.value.clientWidth + 1\n}\n\nconst tooltipText = computed(() => textRef.value?.textContent ?? '')\n</script>\n","<template>\n  <div\n    :class=\"\n      cn(\n        'm-0 flex items-center justify-between px-3 py-0 pt-5',\n        collapsible && 'cursor-pointer select-none'\n      )\n    \"\n    @click=\"collapsible && toggleCollapse()\"\n  >\n    <h3 class=\"text-xs font-bold text-text-secondary uppercase\">\n      {{ title }}\n    </h3>\n    <i\n      v-if=\"collapsible\"\n      :class=\"\n        cn(\n          'pi text-xs text-text-secondary transition-transform duration-200',\n          isCollapsed ? 'pi-chevron-right' : 'pi-chevron-down'\n        )\n      \"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  title,\n  modelValue = false,\n  collapsible = false\n} = defineProps<{\n  title: string\n  modelValue?: boolean\n  collapsible?: boolean\n}>()\n\nconst emit = defineEmits<{\n  'update:modelValue': [value: boolean]\n}>()\n\nconst isCollapsed = computed({\n  get: () => modelValue,\n  set: (value: boolean) => emit('update:modelValue', value)\n})\n\nconst toggleCollapse = () => {\n  isCollapsed.value = !isCollapsed.value\n}\n</script>\n","<template>\n  <div\n    class=\"flex min-h-0 scrollbar-hide w-full flex-auto flex-col gap-1 overflow-y-auto bg-modal-panel-background px-3\"\n  >\n    <template\n      v-for=\"item in navItems\"\n      :key=\"'title' in item ? item.title : item.id\"\n    >\n      <div v-if=\"'items' in item\" class=\"flex flex-col gap-2\">\n        <NavTitle\n          v-model=\"collapsedGroups[item.title]\"\n          :title=\"item.title\"\n          :collapsible=\"item.collapsible\"\n        />\n        <template v-if=\"!item.collapsible || !collapsedGroups[item.title]\">\n          <NavItem\n            v-for=\"subItem in item.items\"\n            :key=\"subItem.id\"\n            :icon=\"subItem.icon\"\n            :badge=\"subItem.badge\"\n            :active=\"activeItem === subItem.id\"\n            @click=\"activeItem = subItem.id\"\n          >\n            {{ subItem.label }}\n          </NavItem>\n        </template>\n      </div>\n      <div v-else class=\"flex flex-col gap-2\">\n        <NavItem\n          :icon=\"item.icon\"\n          :badge=\"item.badge\"\n          :active=\"activeItem === item.id\"\n          @click=\"activeItem = item.id\"\n        >\n          {{ item.label }}\n        </NavItem>\n      </div>\n    </template>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\n\nimport NavItem from '@/components/widget/nav/NavItem.vue'\nimport NavTitle from '@/components/widget/nav/NavTitle.vue'\nimport type { NavGroupData, NavItemData } from '@/types/navTypes'\n\nconst { navItems = [], modelValue } = defineProps<{\n  navItems?: (NavItemData | NavGroupData)[]\n  modelValue?: string | null\n}>()\n\nconst emit = defineEmits<{\n  'update:modelValue': [value: string | null]\n}>()\n\n// Track collapsed state for each group\nconst collapsedGroups = ref<Record<string, boolean>>({})\n\nconst getFirstItemId = () => {\n  if (!navItems || navItems.length === 0) {\n    return null\n  }\n\n  const firstEntry = navItems[0]\n\n  if ('items' in firstEntry && firstEntry.items.length > 0) {\n    return firstEntry.items[0].id\n  }\n  if ('id' in firstEntry) {\n    return firstEntry.id\n  }\n\n  return null\n}\n\nconst activeItem = computed({\n  get: () => modelValue ?? getFirstItemId(),\n  set: (value: string | null) => emit('update:modelValue', value)\n})\n</script>\n","<template>\n  <div\n    data-testid=\"dot-spinner\"\n    class=\"inline-flex items-center justify-center\"\n    :style=\"{ width: size + 'px', height: size + 'px' }\"\n  >\n    <svg\n      xmlns=\"http://www.w3.org/2000/svg\"\n      :width=\"size\"\n      :height=\"size\"\n      viewBox=\"0 0 14 14\"\n      fill=\"none\"\n      class=\"animate-spin\"\n      :style=\"{ animationDuration: duration }\"\n    >\n      <g clip-path=\"url(#clip0_776_9582)\">\n        <!-- Top dot -->\n        <path\n          class=\"dot-animation\"\n          style=\"animation-delay: 0s\"\n          fill-rule=\"evenodd\"\n          clip-rule=\"evenodd\"\n          d=\"M7 2.21053C7.61042 2.21053 8.10526 1.71568 8.10526 1.10526C8.10526 0.494843 7.61042 0 7 0C6.38958 0 5.89474 0.494843 5.89474 1.10526C5.89474 1.71568 6.38958 2.21053 7 2.21053Z\"\n          :fill=\"color\"\n        />\n        <!-- Left dot -->\n        <path\n          class=\"dot-animation\"\n          style=\"animation-delay: 0.25s\"\n          fill-rule=\"evenodd\"\n          clip-rule=\"evenodd\"\n          d=\"M2.21053 7C2.21053 7.61042 1.71568 8.105