      class=\"dot-animation\"\n          style=\"animation-delay: 0.875s\"\n          fill-rule=\"evenodd\"\n          clip-rule=\"evenodd\"\n          d=\"M2.05039 11.9496C2.48203 12.3812 3.18184 12.3812 3.61347 11.9496C4.0451 11.5179 4.0451 10.8181 3.61347 10.3865C3.18184 9.95485 2.48203 9.95485 2.05039 10.3865C1.61876 10.8181 1.61876 11.5179 2.05039 11.9496Z\"\n          :fill=\"color\"\n        />\n        <!-- Top-right dot -->\n        <path\n          class=\"dot-animation\"\n          style=\"animation-delay: 0.375s\"\n          fill-rule=\"evenodd\"\n          clip-rule=\"evenodd\"\n          d=\"M11.9496 3.61349C11.518 4.04513 10.8182 4.04513 10.3865 3.61349C9.9549 3.18186 9.9549 2.48205 10.3865 2.05042C10.8182 1.61878 11.518 1.61878 11.9496 2.05042C12.3812 2.48205 12.3812 3.18186 11.9496 3.61349Z\"\n          :fill=\"color\"\n        />\n      </g>\n      <defs>\n        <clipPath id=\"clip0_776_9582\">\n          <rect width=\"14\" height=\"14\" fill=\"white\" />\n        </clipPath>\n      </defs>\n    </svg>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\n\nconst { size = 24, duration = '2s' } = defineProps<{\n  size?: number\n  duration?: string\n}>()\n\nconst colorPaletteStore = useColorPaletteStore()\n\nconst color = computed(() =>\n  colorPaletteStore.completedActivePalette.light_theme ? '#2C2B30' : '#D4D4D4'\n)\n</script>\n\n<style scoped>\n.dot-animation {\n  animation: dot-pulse 1s ease-in-out infinite;\n}\n\n@keyframes dot-pulse {\n  0%,\n  80%,\n  100% {\n    opacity: 0.3;\n  }\n\n  40% {\n    opacity: 1;\n  }\n}\n</style>\n","<template>\n  <div\n    :class=\"{\n      'content-divider': true,\n      'content-divider--horizontal': orientation === 'horizontal',\n      'content-divider--vertical': orientation === 'vertical'\n    }\"\n    :style=\"{\n      backgroundColor: isLightTheme ? '#DCDAE1' : '#2C2C2C'\n    }\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\n\nconst colorPaletteStore = useColorPaletteStore()\nconst { orientation = 'horizontal', width = 0.3 } = defineProps<{\n  orientation?: 'horizontal' | 'vertical'\n  width?: number\n}>()\n\nconst isLightTheme = computed(\n  () => colorPaletteStore.completedActivePalette.light_theme\n)\n</script>\n\n<style scoped>\n.content-divider {\n  display: inline-block;\n  margin: 0;\n  padding: 0;\n  border: none;\n  flex-shrink: 0;\n  position: relative;\n  z-index: 1;\n}\n\n.content-divider--horizontal {\n  width: 100%;\n  height: v-bind('width + \"px\"');\n}\n\n.content-divider--vertical {\n  height: 100%;\n  width: v-bind('width + \"px\"');\n}\n</style>\n","import type { ConflictDetail } from '@/workbench/extensions/manager/types/conflictDetectionTypes'\n\n/**\n * Generates a localized conflict message for a given conflict detail.\n * This function should be used anywhere conflict messages need to be displayed.\n *\n * @param conflict The conflict detail object\n * @param t The i18n translation function\n * @returns A localized conflict message string\n */\nexport function getConflictMessage(\n  conflict: ConflictDetail,\n  t: (key: string, params?: Record<string, unknown>) => string\n): string {\n  const messageKey = `manager.conflicts.conflictMessages.${conflict.type}`\n\n  // For version and compatibility conflicts, use interpolated message\n  if (\n    conflict.type === 'comfyui_version' ||\n    conflict.type === 'frontend_version' ||\n    conflict.type === 'os' ||\n    conflict.type === 'accelerator'\n  ) {\n    return t(messageKey, {\n      current: conflict.current_value,\n      required: conflict.required_value\n    })\n  }\n\n  // For banned, pending, and import_failed, use simple message\n  if (conflict.type === 'banned' || conflict.type === 'pending') {\n    return t(messageKey)\n  }\n\n  // Fallback to generic message with interpolation\n  return t('manager.conflicts.conflictMessages.generic', {\n    current: conflict.current_value,\n    required: conflict.required_value\n  })\n}\n\n/**\n * Generates conflict messages for multiple conflicts and joins them.\n *\n * @param conflicts Array of conflict details\n * @param t The i18n translation function\n * @param separator The separator to use when joining messages (default: '; ')\n * @returns A single string with all conflict messages joined\n */\nexport function getJoinedConflictMessages(\n  conflicts: ConflictDetail[],\n  t: (key: string, params?: Record<string, unknown>) => string,\n  separator = '; '\n): string {\n  return conflicts\n    .map((conflict) => getConflictMessage(conflict, t))\n    .join(separator)\n}\n","<template>\n  <div class=\"flex w-138 flex-col\">\n    <ContentDivider :width=\"1\" />\n    <div class=\"flex size-full flex-col gap-2 px-4 py-6\">\n      <!-- Description -->\n      <div v-if=\"showAfterWhatsNew\">\n        <p class=\"m-0 mb-4 text-sm/4 text-base-foreground\">\n          {{ $t('manager.conflicts.description') }}\n          <br /><br />\n          {{ $t('manager.conflicts.info') }}\n        </p>\n      </div>\n\n      <!-- Import Failed List Wrapper -->\n      <div\n        v-if=\"importFailedConflicts.length > 0\"\n        class=\"flex min-h-8 w-full flex-col rounded-lg bg-base-background\"\n      >\n        <div\n          data-testid=\"conflict-dialog-panel-toggle\"\n          class=\"flex h-8 w-full items-center justify-between gap-2 pl-4\"\n          @click=\"toggleImportFailedPanel\"\n        >\n          <div class=\"flex flex-1\">\n            <span class=\"mr-2 text-xs font-bold text-warning-background\">{{\n              importFailedConflicts.length\n            }}</span>\n            <span class=\"text-xs font-bold text-base-foreground\">{{\n              $t('manager.conflicts.importFailedExtensions')\n            }}</span>\n          </div>\n          <div>\n            <Button variant=\"textonly\" class=\"bg-transparent text-muted\">\n              <i\n                :class=\"\n                  importFailedExpanded\n                    ? 'pi pi-chevron-down text-xs'\n                    : 'pi pi-chevron-right text-xs'\n                \"\n              />\n            </Button>\n          </div>\n        </div>\n        <!-- Import failed list -->\n        <div\n          v-if=\"importFailedExpanded\"\n          data-testid=\"conflict-dialog-panel-expanded\"\n          class=\"flex max-h-35.5 scrollbar-hide flex-col gap-2.5 overflow-y-auto px-4 py-2\"\n        >\n          <div\n            v-for=\"(packageName, i) in importFailedConflicts\"\n            :key=\"i\"\n            :aria-label=\"`Import failed package: ${packageName}`\"\n            class=\"flex min-h-6 shrink-0 items-center justify-between px-4 py-1 hover:bg-node-component-surface-hovered\"\n          >\n            <span class=\"text-xs text-muted\">\n              {{ packageName }}\n            </span>\n            <span class=\"pi pi-info-circle text-sm\"></span>\n          </div>\n        </div>\n      </div>\n      <!-- Conflict List Wrapper -->\n      <div\n        v-if=\"allConflictDetails.length > 0\"\n        class=\"flex min-h-8 w-full flex-col rounded-lg bg-base-background\"\n      >\n        <div\n          data-testid=\"conflict-dialog-panel-toggle\"\n          class=\"flex h-8 w-full items-center justify-between gap-2 pl-4\"\n          @click=\"toggleConflictsPanel\"\n        >\n          <div class=\"flex flex-1\">\n            <span class=\"mr-2 text-xs font-bold text-warning-background\">{{\n              allConflictDetails.length\n            }}</span>\n            <span class=\"text-xs font-bold text-base-foreground\">{{\n              $t('manager.conflicts.conflicts')\n            }}</span>\n          </div>\n          <div>\n            <Button variant=\"textonly\" class=\"bg-transparent text-muted\">\n              <i\n                :class=\"\n                  conflictsExpanded\n                    ? 'pi pi-chevron-down text-xs'\n                    : 'pi pi-chevron-right text-xs'\n                \"\n              />\n            </Button>\n          </div>\n        </div>\n        <!-- Conflicts list -->\n        <div\n          v-if=\"conflictsExpanded\"\n          data-testid=\"conflict-dialog-panel-expanded\"\n          class=\"flex max-h-[142px] scrollbar-hide flex-col gap-2.5 overflow-y-auto px-4 py-2\"\n        >\n          <div\n            v-for=\"(conflict, i) in allConflictDetails\"\n            :key=\"i\"\n            :aria-label=\"`Conflict: ${getConflictMessage(conflict, t)}`\"\n            class=\"flex min-h-6 shrink-0 items-center justify-between px-4 py-1 hover:bg-node-component-surface-hovered\"\n          >\n            <span class=\"text-xs text-muted\">{{\n              getConflictMessage(conflict, t)\n            }}</span>\n            <span class=\"pi pi-info-circle text-sm\"></span>\n          </div>\n        </div>\n      </div>\n      <!-- Extension List Wrapper -->\n      <div\n        v-if=\"conflictData.length > 0\"\n        class=\"flex min-h-8 w-full flex-col rounded-lg bg-base-background\"\n      >\n        <div\n          data-testid=\"conflict-dialog-panel-toggle\"\n          class=\"flex h-8 w-full items-center justify-between gap-2 pl-4\"\n          @click=\"toggleExtensionsPanel\"\n        >\n          <div class=\"flex flex-1\">\n            <span class=\"mr-2 text-xs font-bold text-warning-background\">{{\n              conflictData.length\n            }}</span>\n            <span class=\"text-xs font-bold text-base-foreground\">{{\n              $t('manager.conflicts.extensionAtRisk')\n            }}</span>\n          </div>\n          <div>\n            <Button variant=\"textonly\" class=\"bg-transparent text-muted\">\n              <i\n                :class=\"\n                  extensionsExpanded\n                    ? 'pi pi-chevron-down text-xs'\n                    : 'pi pi-chevron-right text-xs'\n                \"\n              />\n            </Button>\n          </div>\n        </div>\n        <!-- Extension list -->\n        <div\n          v-if=\"extensionsExpanded\"\n          data-testid=\"conflict-dialog-panel-expanded\"\n          class=\"flex max-h-35.5 scrollbar-hide flex-col gap-2.5 overflow-y-auto px-4 py-2\"\n        >\n          <div\n            v-for=\"conflictResult in conflictData\"\n            :key=\"conflictResult.package_id\"\n            class=\"flex min-h-6 shrink-0 items-center justify-between px-4 py-1 hover:bg-node-component-surface-hovered\"\n          >\n            <span class=\"text-xs text-muted\">\n              {{ conflictResult.package_name }}\n            </span>\n            <span class=\"pi pi-info-circle text-sm\"></span>\n          </div>\n        </div>\n      </div>\n    </div>\n    <ContentDivider :width=\"1\" />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { filter, flatMap, map, some } from 'es-toolkit/compat'\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport ContentDivider from '@/components/common/ContentDivider.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useConflictDetection } from '@/workbench/extensions/manager/composables/useConflictDetection'\nimport type {\n  ConflictDetail,\n  ConflictDetectionResult\n} from '@/workbench/extensions/manager/types/conflictDetectionTypes'\nimport { getConflictMessage } from '@/workbench/extensions/manager/utils/conflictMessageUtil'\n\nconst { showAfterWhatsNew = false, conflictedPackages } = defineProps<{\n  showAfterWhatsNew?: boolean\n  conflictedPackages?: ConflictDetectionResult[]\n}>()\n\nconst { t } = useI18n()\nconst { conflictedPackages: globalConflictPackages } = useConflictDetection()\n\nconst conflictsExpanded = ref<boolean>(false)\nconst extensionsExpanded = ref<boolean>(false)\nconst importFailedExpanded = ref<boolean>(false)\n\nconst conflictData = computed(\n  () => conflictedPackages || globalConflictPackages.value\n)\n\nconst allConflictDetails = computed(() => {\n  const allConflicts = flatMap(\n    conflictData.value,\n    (result: ConflictDetectionResult) => result.conflicts\n  )\n  return filter(\n    allConflicts,\n    (conflict: ConflictDetail) => conflict.type !== 'import_failed'\n  )\n})\n\nconst packagesWithImportFailed = computed(() => {\n  return filter(conflictData.value, (result: ConflictDetectionResult) =>\n    some(\n      result.conflicts,\n      (conflict: ConflictDetail) => conflict.type === 'import_failed'\n    )\n  )\n})\n\nconst importFailedConflicts = computed(() => {\n  return map(\n    packagesWithImportFailed.value,\n    (result: ConflictDetectionResult) =>\n      result.package_name || result.package_id\n  )\n})\n\nconst toggleImportFailedPanel = () => {\n  importFailedExpanded.value = !importFailedExpanded.value\n  conflictsExpanded.value = false\n  extensionsExpanded.value = false\n}\n\nconst toggleConflictsPanel = () => {\n  conflictsExpanded.value = !conflictsExpanded.value\n  extensionsExpanded.value = false\n  importFailedExpanded.value = false\n}\n\nconst toggleExtensionsPanel = () => {\n  extensionsExpanded.value = !extensionsExpanded.value\n  conflictsExpanded.value = false\n  importFailedExpanded.value = false\n}\n</script>\n","<template>\n  <div class=\"flex w-full items-center justify-between px-3 py-4\">\n    <div class=\"flex w-full items-center justify-between gap-2 pr-1\">\n      <Button\n        variant=\"muted-textonly\"\n        size=\"sm\"\n        class=\"text-sm\"\n        @click=\"handleConflictInfoClick\"\n      >\n        <i class=\"pi pi-info-circle\" />\n        {{ $t('manager.conflicts.conflictInfoTitle') }}\n      </Button>\n      <Button\n        v-if=\"buttonText\"\n        variant=\"secondary\"\n        size=\"sm\"\n        @click=\"handleButtonClick\"\n      >\n        {{ buttonText }}\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport { useExternalLink } from '@/composables/useExternalLink'\nimport { useDialogStore } from '@/stores/dialogStore'\n\ninterface Props {\n  buttonText?: string\n  onButtonClick?: () => void\n}\nconst { buttonText, onButtonClick } = defineProps<Props>()\nconst { buildDocsUrl } = useExternalLink()\nconst dialogStore = useDialogStore()\nconst handleConflictInfoClick = () => {\n  window.open(\n    buildDocsUrl('/troubleshooting/custom-node-issues', {\n      includeLocale: true\n    }),\n    '_blank'\n  )\n}\nconst handleButtonClick = () => {\n  // Close the conflict dialog\n  dialogStore.closeDialog({ key: 'global-node-conflict' })\n  // Execute the custom button action if provided\n  if (onButtonClick) {\n    onButtonClick()\n  }\n}\n</script>\n","<template>\n  <div class=\"flex h-12 w-full items-center justify-between pl-6\">\n    <div class=\"flex items-center gap-2\">\n      <!-- Warning Icon -->\n      <i class=\"icon-[lucide--triangle-alert] text-warning-background\" />\n      <!-- Title -->\n      <p class=\"text-base font-bold\">\n        {{ $t('manager.conflicts.title') }}\n      </p>\n    </div>\n  </div>\n</template>\n","import { useDialogService } from '@/services/dialogService'\nimport type { DialogComponentProps } from '@/stores/dialogStore'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport NodeConflictDialogContent from '@/workbench/extensions/manager/components/manager/NodeConflictDialogContent.vue'\nimport NodeConflictFooter from '@/workbench/extensions/manager/components/manager/NodeConflictFooter.vue'\nimport NodeConflictHeader from '@/workbench/extensions/manager/components/manager/NodeConflictHeader.vue'\nimport type { ConflictDetectionResult } from '@/workbench/extensions/manager/types/conflictDetectionTypes'\n\nconst DIALOG_KEY = 'global-node-conflict'\n\nexport function useNodeConflictDialog() {\n  const { showSmallLayoutDialog } = useDialogService()\n  const dialogStore = useDialogStore()\n\n  function hide() {\n    dialogStore.closeDialog({ key: DIALOG_KEY })\n  }\n\n  function show(\n    options: {\n      buttonText?: string\n      conflictedPackages?: ConflictDetectionResult[]\n      dialogComponentProps?: DialogComponentProps\n      onButtonClick?: () => void\n      showAfterWhatsNew?: boolean\n    } = {}\n  ) {\n    const {\n      dialogComponentProps,\n      buttonText,\n      onButtonClick,\n      showAfterWhatsNew,\n      conflictedPackages\n    } = options\n\n    showSmallLayoutDialog({\n      key: DIALOG_KEY,\n      headerComponent: NodeConflictHeader,\n      footerComponent: NodeConflictFooter,\n      component: NodeConflictDialogContent,\n      dialogComponentProps,\n      props: {\n        showAfterWhatsNew,\n        conflictedPackages\n      },\n      footerProps: {\n        buttonText,\n        onButtonClick\n      }\n    })\n  }\n\n  return { show, hide }\n}\n","import { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport type { components } from '@/types/comfyRegistryTypes'\nimport type { components as ManagerComponents } from '@/workbench/extensions/manager/types/generatedManagerTypes'\nimport { useConflictDetection } from '@/workbench/extensions/manager/composables/useConflictDetection'\nimport { useNodeConflictDialog } from '@/workbench/extensions/manager/composables/useNodeConflictDialog'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport type { ConflictDetail } from '@/workbench/extensions/manager/types/conflictDetectionTypes'\n\ntype NodePack = components['schemas']['Node']\n\nexport function usePackInstall(\n  getNodePacks: () => NodePack[],\n  getHasConflict?: () => boolean | undefined,\n  getConflictInfo?: () => ConflictDetail[] | undefined\n) {\n  const managerStore = useComfyManagerStore()\n  const { show: showNodeConflictDialog } = useNodeConflictDialog()\n  const { checkNodeCompatibility } = useConflictDetection()\n  const { t } = useI18n()\n\n  // Check if any of the packs are currently being installed\n  const isInstalling = computed(() => {\n    const nodePacks = getNodePacks()\n    if (!nodePacks.length) return false\n    return nodePacks.some((pack) => managerStore.isPackInstalling(pack.id))\n  })\n\n  const createPayload = (installItem: NodePack) => {\n    if (!installItem.id) {\n      console.error(t('manager.packInstall.nodeIdRequired'))\n      return\n    }\n\n    const isUnclaimedPack = installItem.publisher?.name === 'Unclaimed'\n    const versionToInstall = isUnclaimedPack\n      ? ('nightly' as ManagerComponents['schemas']['SelectedVersion'])\n      : (installItem.latest_version?.version ?? 'latest')\n\n    return {\n      id: installItem.id,\n      repository: installItem.repository ?? '',\n      channel: 'dev' as ManagerComponents['schemas']['ManagerChannel'],\n      mode: 'cache' as ManagerComponents['schemas']['ManagerDatabaseSource'],\n      selected_version: versionToInstall,\n      version: versionToInstall\n    }\n  }\n\n  const installPack = (item: NodePack) => {\n    const payload = createPayload(item)\n    if (!payload) return Promise.resolve()\n    return managerStore.installPack.call(payload)\n  }\n\n  const performInstallation = async (packs: NodePack[]) => {\n    try {\n      const results = await Promise.allSettled(packs.map(installPack))\n      const failures = results.filter(\n        (r): r is PromiseRejectedResult => r.status === 'rejected'\n      )\n      if (failures.length) {\n        console.error(\n          '[usePackInstall] Some installations failed:',\n          failures.map((f) => f.reason)\n        )\n      }\n    } finally {\n      managerStore.installPack.clear()\n    }\n  }\n\n  const installAllPacks = async () => {\n    const nodePacks = getNodePacks()\n    if (!nodePacks.length) return\n\n    const hasConflict = getHasConflict?.()\n    const conflictInfo = getConflictInfo?.()\n\n    if (hasConflict) {\n      if (!conflictInfo) return\n\n      const conflictedPackages = nodePacks\n        .map((pack) => {\n          const compatibilityCheck = checkNodeCompatibility(pack)\n          return {\n            package_id: pack.id || '',\n            package_name: pack.name || '',\n            has_conflict: compatibilityCheck.hasConflict,\n            conflicts: compatibilityCheck.conflicts,\n            is_compatible: !compatibilityCheck.hasConflict\n          }\n        })\n        .filter((result) => result.has_conflict)\n\n      showNodeConflictDialog({\n        conflictedPackages,\n        buttonText: t('manager.conflicts.installAnyway'),\n        onButtonClick: async () => {\n          const uninstalledPacks = nodePacks.filter(\n            (pack) => !managerStore.isPackInstalled(pack.id)\n          )\n          if (!uninstalledPacks.length) return\n          await performInstallation(uninstalledPacks)\n        }\n      })\n      return\n    }\n\n    const uninstalledPacks = nodePacks.filter(\n      (pack) => !managerStore.isPackInstalled(pack.id)\n    )\n    if (!uninstalledPacks.length) return\n    await performInstallation(uninstalledPacks)\n  }\n\n  return { isInstalling, installAllPacks, performInstallation }\n}\n","<template>\n  <Button\n    variant=\"primary\"\n    :size\n    :disabled=\"isLoading || isInstalling\"\n    @click.stop=\"installAllPacks\"\n  >\n    <i\n      v-if=\"hasConflict && !isInstalling && !isLoading\"\n      class=\"icon-[lucide--triangle-alert] text-warning-background\"\n    />\n    <DotSpinner\n      v-else-if=\"isLoading || isInstalling\"\n      duration=\"1s\"\n      :size=\"size === 'sm' ? 12 : 16\"\n    />\n    <i v-else class=\"icon-[lucide--download]\" />\n    <span>{{ computedLabel }}</span>\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport DotSpinner from '@/components/common/DotSpinner.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport type { ButtonVariants } from '@comfyorg/design-system/button.variants'\nimport type { components } from '@/types/comfyRegistryTypes'\nimport type { ConflictDetail } from '@/workbench/extensions/manager/types/conflictDetectionTypes'\nimport { usePackInstall } from '@/workbench/extensions/manager/composables/nodePack/usePackInstall'\n\ntype NodePack = components['schemas']['Node']\n\nconst {\n  nodePacks,\n  isLoading = false,\n  label,\n  size = 'sm',\n  hasConflict,\n  conflictInfo\n} = defineProps<{\n  nodePacks: NodePack[]\n  isLoading?: boolean\n  label?: string\n  size?: ButtonVariants['size']\n  hasConflict?: boolean\n  conflictInfo?: ConflictDetail[]\n}>()\n\nconst { t } = useI18n()\n\nconst { isInstalling, installAllPacks } = usePackInstall(\n  () => nodePacks,\n  () => hasConflict,\n  () => conflictInfo\n)\n\nconst computedLabel = computed(() =>\n  isInstalling.value\n    ? t('g.installing')\n    : (label ??\n      (nodePacks.length > 1 ? t('manager.installSelected') : t('g.install')))\n)\n</script>\n","<template>\n  <ButtonGroup class=\"shrink-0\">\n    <Button\n      :tooltip=\"\n        hasDisabledUpdatePacks\n          ? $t('manager.disabledNodesWontUpdate')\n          : $t('manager.updateLatestActiveTooltip')\n      \"\n      variant=\"primary\"\n      :size\n      class=\"flex-1 rounded-r-none\"\n      :disabled=\"isUpdating || !enabledPacks.length\"\n      @click=\"manager.updatePacks(nodePacks)\"\n    >\n      <DotSpinner v-if=\"isUpdating\" duration=\"1s\" />\n      <i v-else class=\"icon-[lucide--refresh-cw]\" />\n      <span>{{\n        nodePacks.length > 1 ? $t('manager.updateAll') : $t('manager.update')\n      }}</span>\n    </Button>\n    <Menu :items=\"updateOptions\" align=\"end\">\n      <template #trigger>\n        <Button\n          variant=\"primary\"\n          :size\n          class=\"shrink-0 rounded-l-none border-0 border-l border-solid border-border-subtle px-3\"\n          :disabled=\"isUpdating || !enabledPacks.length\"\n          :aria-label=\"$t('manager.updateOptions')\"\n        >\n          <TinyChevronIcon />\n        </Button>\n      </template>\n    </Menu>\n  </ButtonGroup>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport TinyChevronIcon from '@/components/actionbar/TinyChevronIcon.vue'\nimport DotSpinner from '@/components/common/DotSpinner.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport type { ButtonVariants } from '@comfyorg/design-system/button.variants'\nimport ButtonGroup from '@/components/ui/button-group/ButtonGroup.vue'\nimport type { components } from '@/types/comfyRegistryTypes'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\n\ntype NodePack = components['schemas']['Node']\n\nconst {\n  nodePacks,\n  hasDisabledUpdatePacks,\n  size = 'sm'\n} = defineProps<{\n  nodePacks: NodePack[]\n  hasDisabledUpdatePacks?: boolean\n  size?: ButtonVariants['size']\n}>()\n\nconst manager = useComfyManagerStore()\nconst { t } = useI18n()\nconst enabledPacks = computed(() =>\n  nodePacks.filter((pack) => manager.isPackEnabled(pack.id))\n)\nconst isUpdating = computed(() =>\n  enabledPacks.value.some((pack) => manager.isPackInstalling(pack.id))\n)\nconst updateOptions = computed(() => [\n  {\n    label: t('manager.latestActive'),\n    tooltip: t('manager.updateLatestActiveTooltip'),\n    command: () => manager.updatePacks(nodePacks, 'active')\n  },\n  {\n    label: t('manager.latestInstallable'),\n    tooltip: t('manager.updateLatestInstallableTooltip'),\n    command: () => manager.updatePacks(nodePacks, 'installable')\n  }\n])\n</script>\n","<script setup lang=\"ts\">\nimport { computed, onMounted, ref } from 'vue'\n\n// From: https://stackoverflow.com/a/71426342/22392721\ninterface Props {\n  duration?: number\n  easingEnter?: string\n  easingLeave?: string\n  opacityClosed?: number\n  opacityOpened?: number\n  disable?: boolean\n}\n\nconst {\n  duration = 150,\n  easingEnter = 'ease-in-out',\n  easingLeave = 'ease-in-out',\n  opacityClosed = 0,\n  opacityOpened = 1,\n  disable\n} = defineProps<Props>()\n\nconst closed = '0px'\n\nconst isMounted = ref(false)\nonMounted(() => (isMounted.value = true))\n\nconst animationDuration = computed(() =>\n  isMounted.value && !disable ? duration : 0\n)\n\ninterface initialStyle {\n  height: string\n  width: string\n  position: string\n  visibility: string\n  overflow: string\n  paddingTop: string\n  paddingBottom: string\n  borderTopWidth: string\n  borderBottomWidth: string\n  marginTop: string\n  marginBottom: string\n}\n\nfunction getElementStyle(element: HTMLElement) {\n  return {\n    height: element.style.height,\n    width: element.style.width,\n    position: element.style.position,\n    visibility: element.style.visibility,\n    overflow: element.style.overflow,\n    paddingTop: element.style.paddingTop,\n    paddingBottom: element.style.paddingBottom,\n    borderTopWidth: element.style.borderTopWidth,\n    borderBottomWidth: element.style.borderBottomWidth,\n    marginTop: element.style.marginTop,\n    marginBottom: element.style.marginBottom\n  }\n}\n\nfunction prepareElement(element: HTMLElement, initialStyle: initialStyle) {\n  const { width } = getComputedStyle(element)\n  element.style.width = width\n  element.style.position = 'absolute'\n  element.style.visibility = 'hidden'\n  element.style.height = ''\n  const { height } = getComputedStyle(element)\n  element.style.width = initialStyle.width\n  element.style.position = initialStyle.position\n  element.style.visibility = initialStyle.visibility\n  element.style.height = closed\n  element.style.overflow = 'hidden'\n  return initialStyle.height && initialStyle.height !== closed\n    ? initialStyle.height\n    : height\n}\n\nfunction animateTransition(\n  element: HTMLElement,\n  initialStyle: initialStyle,\n  done: () => void,\n  keyframes: Keyframe[] | PropertyIndexedKeyframes | null,\n  options?: number | KeyframeAnimationOptions\n) {\n  const animation = element.animate(keyframes, options)\n  // Set height to 'auto' to restore it after animation\n  element.style.height = initialStyle.height\n  animation.onfinish = () => {\n    element.style.overflow = initialStyle.overflow\n    done()\n  }\n}\n\nfunction getEnterKeyframes(height: string, initialStyle: initialStyle) {\n  return [\n    {\n      height: closed,\n      opacity: opacityClosed,\n      paddingTop: closed,\n      paddingBottom: closed,\n      borderTopWidth: closed,\n      borderBottomWidth: closed,\n      marginTop: closed,\n      marginBottom: closed\n    },\n    {\n      height,\n      opacity: opacityOpened,\n      paddingTop: initialStyle.paddingTop,\n      paddingBottom: initialStyle.paddingBottom,\n      borderTopWidth: initialStyle.borderTopWidth,\n      borderBottomWidth: initialStyle.borderBottomWidth,\n      marginTop: initialStyle.marginTop,\n      marginBottom: initialStyle.marginBottom\n    }\n  ]\n}\n\nfunction enterTransition(element: Element, done: () => void) {\n  const HTMLElement = element as HTMLElement\n  const initialStyle = getElementStyle(HTMLElement)\n  const height = prepareElement(HTMLElement, initialStyle)\n  const keyframes = getEnterKeyframes(height, initialStyle)\n  const options = { duration: animationDuration.value, easing: easingEnter }\n  animateTransition(HTMLElement, initialStyle, done, keyframes, options)\n}\n\nfunction leaveTransition(element: Element, done: () => void) {\n  const HTMLElement = element as HTMLElement\n  const initialStyle = getElementStyle(HTMLElement)\n  const { height } = getComputedStyle(HTMLElement)\n  HTMLElement.style.height = height\n  HTMLElement.style.overflow = 'hidden'\n  const keyframes = getEnterKeyframes(height, initialStyle).reverse()\n  const options = { duration: animationDuration.value, easing: easingLeave }\n  animateTransition(HTMLElement, initialStyle, done, keyframes, options)\n}\n</script>\n\n<template>\n  <Transition :css=\"false\" @enter=\"enterTransition\" @leave=\"leaveTransition\">\n    <slot />\n  </Transition>\n</template>\n","<script lang=\"ts\" setup>\nimport { computed } from 'vue'\n\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport TransitionCollapse from './TransitionCollapse.vue'\n\nconst {\n  disabled,\n  label,\n  enableEmptyState,\n  tooltip,\n  size = 'default',\n  class: className\n} = defineProps<{\n  disabled?: boolean\n  label?: string\n  enableEmptyState?: boolean\n  tooltip?: string\n  size?: 'default' | 'lg'\n  class?: string\n}>()\n\nconst isCollapse = defineModel<boolean>('collapse', { default: false })\n\nconst isExpanded = computed(() => !isCollapse.value && !disabled)\n</script>\n\n<template>\n  <div :class=\"cn('flex flex-col bg-comfy-menu-bg', className)\">\n    <div\n      class=\"sticky top-0 z-10 flex items-center justify-between bg-inherit backdrop-blur-xl\"\n    >\n      <Tooltip :disabled=\"!tooltip\">\n        <TooltipTrigger as-child>\n          <div class=\"w-full\" :tabindex=\"disabled && tooltip ? 0 : undefined\">\n            <button\n              type=\"button\"\n              :class=\"\n                cn(\n                  'group flex w-full items-center justify-between border-0 bg-transparent pr-3 pl-4 text-left ring-0 outline-0',\n                  size === 'lg' ? 'min-h-16' : 'min-h-12',\n                  !disabled && 'cursor-pointer'\n                )\n              \"\n              :disabled=\"disabled\"\n              @click=\"isCollapse = !isCollapse\"\n            >\n              <span class=\"line-clamp-2 flex-1 text-sm font-semibold\">\n                <slot name=\"label\">\n                  {{ label }}\n                </slot>\n              </span>\n\n              <i\n                :class=\"\n                  cn(\n                    'icon-[lucide--chevron-up] size-4 text-muted-foreground transition-all group-hover:text-base-foreground group-focus:text-base-foreground group-has-[.subbutton:hover]:text-muted-foreground',\n                    isCollapse && '-rotate-180',\n                    disabled && 'opacity-0'\n                  )\n                \"\n              />\n            </button>\n          </div>\n        </TooltipTrigger>\n        <TooltipContent>{{ tooltip }}</TooltipContent>\n      </Tooltip>\n    </div>\n    <TransitionCollapse>\n      <div v-if=\"isExpanded\" class=\"pb-4\">\n        <slot />\n      </div>\n      <slot v-else-if=\"enableEmptyState && disabled\" name=\"empty\">\n        <div>\n          {{ $t('g.empty') }}\n        </div>\n      </slot>\n    </TransitionCollapse>\n  </div>\n</template>\n","<template>\n  <div class=\"flex flex-col gap-2 px-4 py-2 text-sm text-base-foreground\">\n    <div class=\"relative flex items-center justify-between\">\n      <span class=\"select-none\">{{ label }}</span>\n      <slot name=\"label-action\" />\n    </div>\n    <slot />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\ndefineProps<{\n  label: string\n}>()\n</script>\n","<template>\n  <Message\n    :severity=\"statusSeverity\"\n    class=\"w-fit rounded-xl px-2 py-0.5 text-xs wrap-break-word\"\n  >\n    <i\n      class=\"pi pi-circle-fill mr-1.5 p-0 text-[0.6rem]\"\n      :style=\"{ opacity: 0.8 }\"\n    />\n    {{ $t(`manager.status.${statusLabel}`) }}\n  </Message>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport type { MessageVariants } from '@/components/ui/message/message.variants'\nimport Message from '@/components/ui/message/Message.vue'\nimport type { components } from '@/types/comfyRegistryTypes'\n\ntype PackVersionStatus = components['schemas']['NodeVersionStatus']\ntype PackStatus = components['schemas']['NodeStatus']\ntype Status = PackVersionStatus | PackStatus\n\ntype StatusProps = {\n  label: string\n  severity: MessageVariants['severity']\n}\n\nconst { statusType, hasCompatibilityIssues, hasImportFailed } = defineProps<{\n  statusType: Status\n  hasCompatibilityIssues?: boolean\n  hasImportFailed?: boolean\n}>()\n\nconst statusPropsMap: Record<Status, StatusProps> = {\n  NodeStatusActive: {\n    label: 'active',\n    severity: 'success'\n  },\n  NodeStatusDeleted: {\n    label: 'deleted',\n    severity: 'warning'\n  },\n  NodeStatusBanned: {\n    label: 'banned',\n    severity: 'error'\n  },\n  NodeVersionStatusActive: {\n    label: 'active',\n    severity: 'success'\n  },\n  NodeVersionStatusPending: {\n    label: 'pending',\n    severity: 'warning'\n  },\n  NodeVersionStatusDeleted: {\n    label: 'deleted',\n    severity: 'warning'\n  },\n  NodeVersionStatusFlagged: {\n    label: 'flagged',\n    severity: 'error'\n  },\n  NodeVersionStatusBanned: {\n    label: 'banned',\n    severity: 'error'\n  }\n}\n\nconst statusLabel = computed(() => {\n  if (hasImportFailed) return 'importFailed'\n  if (hasCompatibilityIssues) return 'conflicting'\n  return statusPropsMap[statusType]?.label || 'unknown'\n})\nconst statusSeverity = computed(() => {\n  if (hasCompatibilityIssues || hasImportFailed) return 'error'\n  return statusPropsMap[statusType]?.severity || 'secondary'\n})\n</script>\n","<template>\n  <svg\n    xmlns=\"http://www.w3.org/2000/svg\"\n    :width=\"size\"\n    :height=\"size\"\n    viewBox=\"0 0 16 16\"\n    fill=\"none\"\n    :class=\"iconClass\"\n  >\n    <path\n      d=\"M8.00049 1.3335C8.73661 1.33367 9.33332 1.93038 9.3335 2.6665V2.83447C9.82278 2.96041 10.2851 3.15405 10.7095 3.40479L10.8286 3.28564C11.3493 2.76525 12.1937 2.76519 12.7144 3.28564C13.235 3.80626 13.2348 4.65067 12.7144 5.17139L12.5952 5.29053C12.846 5.71486 13.0396 6.17725 13.1655 6.6665H13.3335C14.0699 6.6665 14.6665 7.26411 14.6665 8.00049C14.6663 8.73672 14.0698 9.3335 13.3335 9.3335H13.1655C13.0396 9.82284 12.846 10.2851 12.5952 10.7095L12.7144 10.8286C13.235 11.3493 13.235 12.1937 12.7144 12.7144C12.1937 13.235 11.3493 13.235 10.8286 12.7144L10.7095 12.5952C10.2851 12.846 9.82284 13.0396 9.3335 13.1655V13.3335C9.3335 14.0698 8.73672 14.6663 8.00049 14.6665C7.26411 14.6665 6.6665 14.0699 6.6665 13.3335V13.1655C6.17725 13.0396 5.71486 12.846 5.29053 12.5952L5.17139 12.7144C4.65067 13.2348 3.80626 13.235 3.28564 12.7144C2.76519 12.1937 2.76525 11.3493 3.28564 10.8286L3.40479 10.7095C3.15405 10.2851 2.96041 9.82278 2.83447 9.3335H2.6665C1.93038 9.33332 1.33367 8.73661 1.3335 8.00049C1.3335 7.26422 1.93027 6.66668 2.6665 6.6665H2.83447C2.96043 6.17722 3.15403 5.71488 3.40479 5.29053L3.28564 5.17139C2.76536 4.65065 2.76508 3.80621 3.28564 3.28564C3.80621 2.76508 4.65065 2.76536 5.17139 3.28564L5.29053 3.40479C5.71488 3.15403 6.17722 2.96043 6.6665 2.83447V2.6665C6.66668 1.93027 7.26422 1.3335 8.00049 1.3335ZM7.3335 8.00049L6.00049 6.6665L4.6665 8.00049L7.3335 10.6665L11.3335 6.6665L10.0005 5.3335L7.3335 8.00049Z\"\n      :fill=\"color\"\n    />\n  </svg>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\ninterface Props {\n  size?: number | string\n  color?: string\n  class?: string\n}\nconst { size = 16, color = '#60A5FA', class: className } = defineProps<Props>()\nconst iconClass = computed(() => className || '')\n</script>\n","import { maxSatisfying } from 'semver'\n\nimport type { components } from '@/types/comfyRegistryTypes'\n\ntype NodeVersion = components['schemas']['NodeVersion']\ntype NodeVersionStatus = components['schemas']['NodeVersionStatus']\n\nexport const versionStatusFilters: Record<\n  'active' | 'installable',\n  NodeVersionStatus[]\n> = {\n  active: ['NodeVersionStatusActive'],\n  installable: [\n    'NodeVersionStatusActive',\n    'NodeVersionStatusFlagged',\n    'NodeVersionStatusPending'\n  ]\n}\n\nexport function getLatestVersion(\n  versions: NodeVersion[],\n  statuses: NodeVersionStatus[]\n) {\n  const candidates = versions.filter(\n    (version) => version.status && statuses.includes(version.status)\n  )\n  const latest = maxSatisfying(\n    candidates.map((version) => version.version ?? ''),\n    '*',\n    { includePrerelease: true }\n  )\n  return candidates.find((version) => version.version === latest)\n}\n","<template>\n  <div class=\"w-80 pt-1\">\n    <div class=\"py-2\">\n      <span class=\"pl-3 text-base font-semibold text-neutral-500\">\n        {{ $t('manager.selectVersion') }}\n      </span>\n    </div>\n    <div\n      v-if=\"isBusy\"\n      class=\"flex flex-col items-center py-4 text-center text-muted\"\n    >\n      <Spinner class=\"mb-2 size-8\" />\n      {{ $t('manager.loadingVersions') }}\n    </div>\n    <div v-else-if=\"versionOptions.length === 0\" class=\"py-2\">\n      <NoResultsPlaceholder\n        :title=\"$t('g.noResultsFound')\"\n        :message=\"$t('manager.tryAgainLater')\"\n        icon=\"pi pi-exclamation-circle\"\n        class=\"p-0\"\n      />\n    </div>\n    <ListboxRoot\n      v-else\n      v-model=\"selectedVersion\"\n      selection-behavior=\"replace\"\n      class=\"w-full\"\n    >\n      <ListboxContent class=\"max-h-[50vh] scrollbar-hide overflow-y-auto p-1\">\n        <ListboxItem\n          v-for=\"option in processedVersionOptions\"\n          :key=\"option.value\"\n          :value=\"option.value\"\n          :disabled=\"option.isDisabled\"\n          :aria-disabled=\"option.isDisabled\"\n          class=\"flex cursor-pointer items-center justify-between rounded-md px-3 py-2 outline-none data-disabled:cursor-not-allowed data-disabled:opacity-50 data-highlighted:bg-secondary-background-hover\"\n        >\n          <div class=\"flex items-center gap-2\">\n            <div v-if=\"option.value === 'nightly'\" class=\"w-4\"></div>\n            <Tooltip\n              v-else-if=\"option.hasConflict\"\n              :disabled=\"!option.conflictMessage\"\n            >\n              <TooltipTrigger as-child>\n                <i\n                  class=\"icon-[lucide--triangle-alert] text-warning-background\"\n                  role=\"img\"\n                  :aria-label=\"option.conflictMessage\"\n                />\n              </TooltipTrigger>\n              <TooltipContent>{{ option.conflictMessage }}</TooltipContent>\n            </Tooltip>\n            <VerifiedIcon v-else :size=\"20\" class=\"relative right-0.5\" />\n            <span>{{ option.label }}</span>\n            <PackStatusMessage\n              v-if=\"option.isFlagged\"\n              status-type=\"NodeVersionStatusFlagged\"\n              class=\"shrink-0\"\n            />\n          </div>\n          <ListboxItemIndicator as-child>\n            <i class=\"icon-[lucide--check] text-highlight\" />\n          </ListboxItemIndicator>\n        </ListboxItem>\n      </ListboxContent>\n    </ListboxRoot>\n    <p role=\"status\" class=\"px-3 text-sm text-muted\">\n      {{ latestUnavailableMessage }}\n    </p>\n    <ContentDivider class=\"my-2\" />\n    <div class=\"flex justify-end gap-2 px-3 py-1\">\n      <Button\n        variant=\"muted-textonly\"\n        class=\"text-sm\"\n        :disabled=\"isQueueing\"\n        @click=\"emit('cancel')\"\n      >\n        {{ $t('g.cancel') }}\n      </Button>\n      <Button\n        variant=\"secondary\"\n        class=\"rounded-lg bg-secondary-background px-4 py-2.5 text-sm text-base-foreground\"\n        :disabled=\"isInstallDisabled\"\n        @click=\"handleSubmit\"\n      >\n        {{ $t('g.install') }}\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { whenever } from '@vueuse/core'\nimport {\n  ListboxContent,\n  ListboxItem,\n  ListboxItemIndicator,\n  ListboxRoot\n} from 'reka-ui'\nimport { valid as validSemver } from 'semver'\nimport { computed, onMounted, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport ContentDivider from '@/components/common/ContentDivider.vue'\nimport NoResultsPlaceholder from '@/components/common/NoResultsPlaceholder.vue'\nimport VerifiedIcon from '@/components/icons/VerifiedIcon.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Spinner from '@/components/ui/spinner/Spinner.vue'\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\nimport { useComfyRegistryService } from '@/services/comfyRegistryService'\nimport type { components } from '@/types/comfyRegistryTypes'\nimport PackStatusMessage from '@/workbench/extensions/manager/components/manager/PackStatusMessage.vue'\nimport { useConflictDetection } from '@/workbench/extensions/manager/composables/useConflictDetection'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport type { components as ManagerComponents } from '@/workbench/extensions/manager/types/generatedManagerTypes'\nimport { getJoinedConflictMessages } from '@/workbench/extensions/manager/utils/conflictMessageUtil'\nimport {\n  getLatestVersion,\n  versionStatusFilters\n} from '@/workbench/extensions/manager/utils/nodePackVersionUtil'\n\ntype ManagerChannel = ManagerComponents['schemas']['ManagerChannel']\ntype ManagerDatabaseSource =\n  ManagerComponents['schemas']['ManagerDatabaseSource']\ntype SelectedVersion = ManagerComponents['schemas']['SelectedVersion']\ntype VersionOption = {\n  value: string\n  label: string\n}\n\n// Enum values for runtime use\nconst SelectedVersionValues = {\n  LATEST: 'latest' as SelectedVersion,\n  NIGHTLY: 'nightly' as SelectedVersion\n}\n\nconst ManagerChannelValues: Record<string, ManagerChannel> = {\n  DEFAULT: 'default',\n  DEV: 'dev'\n}\n\nconst ManagerDatabaseSourceValues: Record<string, ManagerDatabaseSource> = {\n  CACHE: 'cache',\n  REMOTE: 'remote',\n  LOCAL: 'local'\n}\n\nconst { nodePack } = defineProps<{\n  nodePack: components['schemas']['Node']\n}>()\n\nconst emit = defineEmits<{\n  cancel: []\n  submit: []\n}>()\n\nconst { t } = useI18n()\nconst registryService = useComfyRegistryService()\nconst managerStore = useComfyManagerStore()\nconst { checkNodeCompatibility } = useConflictDetection()\n\nconst isQueueing = ref(false)\nconst isLoadingVersions = ref(false)\nconst isBusy = computed(() => isLoadingVersions.value || isQueueing.value)\nconst selectedVersion = ref<string>(SelectedVersionValues.LATEST)\nconst isInstallDisabled = computed(\n  () =>\n    !nodePack.id ||\n    isLoadingVersions.value ||\n    isQueueing.value ||\n    (selectedVersion.value === SelectedVersionValues.LATEST &&\n      !latestActiveVersion.value) ||\n    managerStore.isPackInstalling(nodePack.id) ||\n    isVersionInstalled(selectedVersion.value)\n)\nonMounted(() => {\n  const initialVersion =\n    getInitialSelectedVersion() ?? SelectedVersionValues.LATEST\n  selectedVersion.value =\n    // Use NIGHTLY when version is a Git hash\n    validSemver(initialVersion) ||\n    initialVersion === SelectedVersionValues.LATEST\n      ? initialVersion\n      : SelectedVersionValues.NIGHTLY\n})\n\nconst getInitialSelectedVersion = () => {\n  if (!nodePack.id) return\n\n  // If unclaimed, set selected version to nightly\n  if (nodePack.publisher?.name === 'Unclaimed')\n    return SelectedVersionValues.NIGHTLY\n\n  // If node pack is installed, set selected version to the installed version\n  if (managerStore.isPackInstalled(nodePack.id))\n    return managerStore.getInstalledPackVersion(nodePack.id)\n\n  // If node pack is not installed, set selected version to latest\n  return !nodePack.latest_version && nodePack.repository\n    ? SelectedVersionValues.NIGHTLY\n    : SelectedVersionValues.LATEST\n}\n\nconst fetchedVersions = ref<components['schemas']['NodeVersion'][]>([])\nconst latestActiveVersion = computed(() =>\n  getLatestVersion(fetchedVersions.value, versionStatusFilters.active)\n)\nconst latestInstallableVersion = computed(() =>\n  getLatestVersion(fetchedVersions.value, versionStatusFilters.installable)\n)\n\nconst latestUnavailableMessage = computed(() => {\n  if (isBusy.value || latestActiveVersion.value) return ''\n  if (registryService.error.value) return t('manager.versionLoadFailed')\n  return fetchedVersions.value.some(\n    (version) =>\n      version.version && version.status === 'NodeVersionStatusFlagged'\n  )\n    ? t('manager.noActiveVersionsFlagged')\n    : t('manager.noActiveVersions')\n})\n\nconst onNodePackChange = async () => {\n  isLoadingVersions.value = true\n  fetchedVersions.value = nodePack.id\n    ? ((await registryService.getPackVersions(nodePack.id)) ?? [])\n    : []\n  const installedVersion = nodePack.id\n    ? managerStore.getInstalledPackVersion(nodePack.id)\n    : undefined\n  if (\n    selectedVersion.value === installedVersion &&\n    installedVersion === latestActiveVersion.value?.version\n  ) {\n    selectedVersion.value = SelectedVersionValues.LATEST\n  }\n  isLoadingVersions.value = false\n}\n\nconst versionOptions = computed(() => {\n  if (!nodePack.id) return []\n  const latestVersionNumber = latestActiveVersion.value?.version\n  const latestInstallableNumber = latestInstallableVersion.value?.version\n  const hasSeparateLatest =\n    latestInstallableNumber && latestInstallableNumber !== latestVersionNumber\n\n  const availableVersionOptions = fetchedVersions.value\n    .map((version) => ({\n      value: version.version ?? '',\n      label: version.version ?? ''\n    }))\n    .filter(\n      (option) =>\n        option.value &&\n        option.value !== latestVersionNumber &&\n        option.value !== latestInstallableNumber\n    )\n\n  const activeLabel = hasSeparateLatest\n    ? t('manager.latestStableVersion')\n    : t('manager.latestVersion')\n  const latestLabel = latestVersionNumber\n    ? `${activeLabel} (${latestVersionNumber})`\n    : activeLabel\n\n  const defaultVersions: VersionOption[] = [\n    {\n      value: SelectedVersionValues.LATEST,\n      label: latestLabel\n    }\n  ]\n\n  if (hasSeparateLatest) {\n    defaultVersions.unshift({\n      value: latestInstallableNumber,\n      label: `${t('manager.latestVersion')} (${latestInstallableNumber})`\n    })\n  }\n\n  if (nodePack.repository) {\n    defaultVersions.push({\n      value: SelectedVersionValues.NIGHTLY,\n      label: t('manager.nightlyVersion')\n    })\n  }\n\n  return [...defaultVersions, ...availableVersionOptions]\n})\n\nwhenever(\n  () => nodePack.id,\n  (nodePackId, oldNodePackId) => {\n    if (nodePackId !== oldNodePackId) {\n      void onNodePackChange()\n    }\n  },\n  { deep: true, immediate: true }\n)\n\nconst handleSubmit = async () => {\n  if (!nodePack.id || isInstallDisabled.value) return\n  const actualVersion =\n    selectedVersion.value === 'latest'\n      ? latestActiveVersion.value?.version\n      : selectedVersion.value\n\n  if (!actualVersion) return\n  isQueueing.value = true\n\n  await managerStore.installPack.call({\n    id: nodePack.id,\n    repository: nodePack.repository ?? '',\n    channel: ManagerChannelValues.DEFAULT,\n    mode: ManagerDatabaseSourceValues.CACHE,\n    version: actualVersion,\n    selected_version: actualVersion\n  })\n\n  isQueueing.value = false\n  emit('submit')\n}\n\nconst getVersionData = (version: string) => {\n  if (version === 'latest') return latestActiveVersion.value ?? {}\n  const versionData = fetchedVersions.value.find((v) => v.version === version)\n  if (versionData) return versionData\n  return version === nodePack.latest_version?.version\n    ? (nodePack.latest_version ?? nodePack)\n    : nodePack\n}\n// Main function to get version compatibility info\nconst getVersionCompatibility = (version: string) => {\n  const versionData = getVersionData(version)\n  const compatibility = checkNodeCompatibility(versionData)\n  const conflictMessage = compatibility.hasConflict\n    ? getJoinedConflictMessages(compatibility.conflicts, t)\n    : ''\n  return {\n    hasConflict: compatibility.hasConflict,\n    conflictMessage\n  }\n}\nconst isVersionInstalled = (version: string) => {\n  const installed = nodePack.id\n    ? managerStore.getInstalledPackVersion(nodePack.id)\n    : undefined\n  if (!installed) return false\n  if (version === 'latest')\n    return installed === latestActiveVersion.value?.version\n  return version === installed\n}\n\nconst processedVersionOptions = computed(() => {\n  return versionOptions.value.map((option) => {\n    const compatibility = getVersionCompatibility(option.value)\n    return {\n      ...option,\n      isFlagged:\n        option.value !== 'latest' &&\n        option.value !== 'nightly' &&\n        getVersionData(option.value).status === 'NodeVersionStatusFlagged',\n      hasConflict: compatibility.hasConflict,\n      conflictMessage: compatibility.conflictMessage,\n      isDisabled:\n        isVersionInstalled(option.value) ||\n        (option.value === SelectedVersionValues.LATEST &&\n          !latestActiveVersion.value)\n    }\n  })\n})\n</script>\n","import { compare, valid } from 'semver'\n\nimport type { components } from '@/types/comfyRegistryTypes'\nimport type { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\n\ntype NodePack = components['schemas']['Node']\ntype ComfyManagerStore = ReturnType<typeof useComfyManagerStore>\n\ninterface PackUpdateStatus {\n  isInstalled: boolean\n  installedVersion: string | undefined\n  latestVersion: string | undefined\n  isNightly: boolean\n  isUpdateAvailable: boolean\n}\n\n/**\n * A pack is a nightly build when its installed version is not valid semver\n * (a git hash), so it cannot be compared against the latest release version.\n */\nexport function isNightlyVersion(version: string | undefined): boolean {\n  return !!version && !valid(version)\n}\n\n/**\n * Derives the update status of a pack from its installed version and the\n * latest release version advertised by the registry. A nightly build is never\n * \"outdated\" since git hashes cannot be ordered.\n */\nexport function getPackUpdateStatus(\n  pack: NodePack | undefined,\n  managerStore: ComfyManagerStore\n): PackUpdateStatus {\n  const isInstalled = managerStore.isPackInstalled(pack?.id)\n  const installedVersion = managerStore.getInstalledPackVersion(pack?.id ?? '')\n  const latestVersion = pack?.latest_version?.version\n  const isNightly = isNightlyVersion(installedVersion)\n\n  const isUpdateAvailable =\n    isInstalled &&\n    !isNightly &&\n    !!installedVersion &&\n    !!latestVersion &&\n    !!valid(latestVersion) &&\n    compare(latestVersion, installedVersion) > 0\n\n  return {\n    isInstalled,\n    installedVersion,\n    latestVersion,\n    isNightly,\n    isUpdateAvailable\n  }\n}\n","import type { MaybeRefOrGetter } from 'vue'\nimport { computed, toValue } from 'vue'\n\nimport type { components } from '@/types/comfyRegistryTypes'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport { getPackUpdateStatus } from '@/workbench/extensions/manager/utils/packUpdateStatus'\n\nexport const usePackUpdateStatus = (\n  nodePackSource: MaybeRefOrGetter<components['schemas']['Node']>\n) => {\n  const managerStore = useComfyManagerStore()\n\n  // Use toValue to unwrap the source reactively inside computeds\n  const nodePack = computed(() => toValue(nodePackSource))\n\n  const status = computed(() =>\n    getPackUpdateStatus(nodePack.value, managerStore)\n  )\n\n  const isInstalled = computed(() => status.value.isInstalled)\n  const isEnabled = computed(() =>\n    managerStore.isPackEnabled(nodePack.value.id)\n  )\n  const installedVersion = computed(() => status.value.installedVersion)\n  const latestVersion = computed(() => status.value.latestVersion)\n  const isNightlyPack = computed(() => status.value.isNightly)\n  const isUpdateAvailable = computed(() => status.value.isUpdateAvailable)\n\n  /**\n   * Nightly packs can always \"try update\" since we cannot compare git hashes\n   * to determine if an update is actually available. This allows users to\n   * pull the latest changes from the repository.\n   */\n  const canTryNightlyUpdate = computed(\n    () => isInstalled.value && isEnabled.value && isNightlyPack.value\n  )\n\n  return {\n    isUpdateAvailable,\n    isNightlyPack,\n    canTryNightlyUpdate,\n    installedVersion,\n    latestVersion\n  }\n}\n","<template>\n  <div>\n    <Button\n      :tooltip=\"isDisabled ? $t('manager.enablePackToChangeVersion') : ''\"\n      variant=\"textonly\"\n      size=\"unset\"\n      :class=\"\n        cn(\n          'gap-1 rounded-2xl py-1 text-xs font-normal',\n          fill && 'bg-dialog-surface px-1.5',\n          isDisabled && 'cursor-not-allowed opacity-60'\n        )\n      \"\n      :aria-haspopup=\"!isDisabled\"\n      :aria-disabled=\"isDisabled\"\n      @click=\"!isDisabled && toggleVersionSelector($event)\"\n    >\n      <i\n        v-if=\"isUpdateAvailable\"\n        class=\"pi pi-arrow-circle-up text-xs text-blue-600\"\n      />\n      <span>{{ installedVersion }}</span>\n      <i v-if=\"!isDisabled\" class=\"pi pi-chevron-right text-2xs\" />\n    </Button>\n\n    <Popover ref=\"popoverRef\" align=\"start\" content-class=\"p-0\">\n      <PackVersionSelectorPopover\n        :installed-version=\"installedVersion\"\n        :node-pack=\"nodePack\"\n        @cancel=\"closeVersionSelector\"\n        @submit=\"closeVersionSelector\"\n      />\n    </Popover>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { valid as validSemver } from 'semver'\nimport { computed, ref, watch } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport Popover from '@/components/common/ImperativePopover.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport type { components } from '@/types/comfyRegistryTypes'\nimport PackVersionSelectorPopover from '@/workbench/extensions/manager/components/manager/PackVersionSelectorPopover.vue'\nimport { usePackUpdateStatus } from '@/workbench/extensions/manager/composables/nodePack/usePackUpdateStatus'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\n\nconst TRUNCATED_HASH_LENGTH = 7\n\nconst {\n  nodePack,\n  isSelected,\n  fill = true\n} = defineProps<{\n  nodePack: components['schemas']['Node']\n  isSelected: boolean\n  fill?: boolean\n}>()\n\nconst { isUpdateAvailable } = usePackUpdateStatus(() => nodePack)\nconst popoverRef = ref()\n\nconst managerStore = useComfyManagerStore()\n\nconst isInstalled = computed(() => managerStore.isPackInstalled(nodePack?.id))\nconst isDisabled = computed(\n  () => isInstalled.value && !managerStore.isPackEnabled(nodePack?.id)\n)\n\nconst installedVersion = computed(() => {\n  if (!nodePack.id) return 'nightly'\n  const version =\n    managerStore.installedPacks[nodePack.id]?.ver ??\n    nodePack.latest_version?.version ??\n    'nightly'\n\n  // If Git hash, truncate to 7 characters\n  return validSemver(version)\n    ? version\n    : version.slice(0, TRUNCATED_HASH_LENGTH)\n})\n\nconst toggleVersionSelector = (event: Event) => {\n  popoverRef.value.toggle(event)\n}\n\nconst closeVersionSelector = () => {\n  popoverRef.value.hide()\n}\n\n// If the card is unselected, automatically close the version selector popover\nwatch(\n  () => isSelected,\n  (isSelected, wasSelected) => {\n    if (wasSelected && !isSelected) {\n      closeVersionSelector()\n    }\n  }\n)\n</script>\n","import { defineStore } from 'pinia'\nimport { computed, ref } from 'vue'\n\nimport type { ConflictDetectionResult } from '@/workbench/extensions/manager/types/conflictDetectionTypes'\n\nexport const useConflictDetectionStore = defineStore(\n  'conflictDetection',\n  () => {\n    // State\n    const conflictedPackages = ref<ConflictDetectionResult[]>([])\n    const isDetecting = ref(false)\n    const lastDetectionTime = ref<string | null>(null)\n\n    // Getters\n    const hasConflicts = computed(() =>\n      conflictedPackages.value.some((pkg) => pkg.has_conflict)\n    )\n\n    const getConflictsForPackageByID = computed(\n      () => (packageId: string) =>\n        conflictedPackages.value.find((pkg) => pkg.package_id === packageId)\n    )\n\n    const bannedPackages = computed(() =>\n      conflictedPackages.value.filter((pkg) =>\n        pkg.conflicts.some((conflict) => conflict.type === 'banned')\n      )\n    )\n\n    const securityPendingPackages = computed(() =>\n      conflictedPackages.value.filter((pkg) =>\n        pkg.conflicts.some((conflict) => conflict.type === 'pending')\n      )\n    )\n\n    // Actions\n    function setConflictedPackages(packages: ConflictDetectionResult[]) {\n      conflictedPackages.value = [...packages]\n    }\n\n    function clearConflicts() {\n      conflictedPackages.value = []\n    }\n\n    function setDetecting(detecting: boolean) {\n      isDetecting.value = detecting\n    }\n\n    function setLastDetectionTime(time: string) {\n      lastDetectionTime.value = time\n    }\n\n    return {\n      // State\n      conflictedPackages,\n      isDetecting,\n      lastDetectionTime,\n      // Getters\n      hasConflicts,\n      getConflictsForPackageByID,\n      bannedPackages,\n      securityPendingPackages,\n      // Actions\n      setConflictedPackages,\n      clearConflicts,\n      setDetecting,\n      setLastDetectionTime\n    }\n  }\n)\n","import { useStorage } from '@vueuse/core'\nimport { computed } from 'vue'\n\nimport { useConflictDetectionStore } from '@/workbench/extensions/manager/stores/conflictDetectionStore'\n\n/**\n * LocalStorage keys for conflict acknowledgment tracking\n */\nconst STORAGE_KEYS = {\n  CONFLICT_MODAL_DISMISSED: 'Comfy.ConflictModalDismissed',\n  CONFLICT_RED_DOT_DISMISSED: 'Comfy.ConflictRedDotDismissed',\n  CONFLICT_WARNING_BANNER_DISMISSED: 'Comfy.ConflictWarningBannerDismissed'\n} as const\n\n/**\n * Interface for conflict acknowledgment state\n */\nexport interface ConflictAcknowledgmentState {\n  modal_dismissed: boolean\n  red_dot_dismissed: boolean\n  warning_banner_dismissed: boolean\n}\n\n// Shared state - initialized once and reused across all composable calls\nconst modalDismissed = useStorage(STORAGE_KEYS.CONFLICT_MODAL_DISMISSED, false)\nconst redDotDismissed = useStorage(\n  STORAGE_KEYS.CONFLICT_RED_DOT_DISMISSED,\n  false\n)\nconst warningBannerDismissed = useStorage(\n  STORAGE_KEYS.CONFLICT_WARNING_BANNER_DISMISSED,\n  false\n)\n\n/**\n * Composable for managing conflict acknowledgment state in localStorage\n *\n * This handles:\n * - Tracking whether conflict modal has been dismissed\n * - Tracking whether red dot notification has been cleared\n * - Managing per-package conflict acknowledgments\n * - Detecting ComfyUI version changes to reset acknowledgment state\n */\nexport function useConflictAcknowledgment() {\n  const conflictDetectionStore = useConflictDetectionStore()\n\n  // Create computed state object for backward compatibility\n  const state = computed<ConflictAcknowledgmentState>(() => ({\n    modal_dismissed: modalDismissed.value,\n    red_dot_dismissed: redDotDismissed.value,\n    warning_banner_dismissed: warningBannerDismissed.value\n  }))\n\n  /**\n   * Mark red dot notification as dismissed\n   */\n  function dismissRedDotNotification(): void {\n    redDotDismissed.value = true\n  }\n\n  /**\n   * Mark manager warning banner as dismissed\n   */\n  function dismissWarningBanner(): void {\n    warningBannerDismissed.value = true\n    redDotDismissed.value = true\n  }\n\n  /**\n   * Mark conflicts as seen (unified function for help center and manager)\n   */\n  function markConflictsAsSeen(): void {\n    redDotDismissed.value = true\n    modalDismissed.value = true\n    warningBannerDismissed.value = true\n  }\n\n  const hasConflicts = computed(() => conflictDetectionStore.hasConflicts)\n  const shouldShowConflictModal = computed(() => !modalDismissed.value)\n  const shouldShowRedDot = computed(() => {\n    if (!hasConflicts.value) return false\n    if (redDotDismissed.value) return false\n    return true\n  })\n  const shouldShowManagerBanner = computed(() => {\n    return hasConflicts.value && !warningBannerDismissed.value\n  })\n\n  return {\n    // State\n    acknowledgmentState: state,\n    shouldShowConflictModal,\n    shouldShowRedDot,\n    shouldShowManagerBanner,\n\n    // Methods\n    dismissRedDotNotification,\n    dismissWarningBanner,\n    markConflictsAsSeen\n  }\n}\n","<template>\n  <div class=\"flex w-[490px] flex-col border-t border-border-default\">\n    <div class=\"flex size-full flex-col gap-4 p-4\">\n      <!-- Error Details -->\n      <div v-if=\"importFailedPackages.length > 0\" class=\"flex flex-col gap-3\">\n        <div\n          v-for=\"pkg in importFailedPackages\"\n          :key=\"pkg.packageId\"\n          class=\"flex scrollbar-custom max-h-60 flex-col gap-2 overflow-x-hidden overflow-y-auto\"\n          role=\"region\"\n          :aria-label=\"`Error traceback for ${pkg.packageId}`\"\n          tabindex=\"0\"\n        >\n          <!-- Error Message -->\n          <div\n            v-if=\"pkg.traceback || pkg.errorMessage\"\n            class=\"rounded-md bg-secondary-background p-4 font-mono text-xs\"\n          >\n            {{ pkg.traceback || pkg.errorMessage }}\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport type { ConflictDetectionResult } from '@/workbench/extensions/manager/types/conflictDetectionTypes'\n\nconst { conflictedPackages } = defineProps<{\n  conflictedPackages: ConflictDetectionResult[]\n}>()\n\ninterface ImportFailedPackage {\n  packageId: string\n  packageName: string\n  errorMessage: string\n  traceback: string\n}\n\nconst importFailedPackages = computed((): ImportFailedPackage[] => {\n  return conflictedPackages\n    .filter((pkg) =>\n      pkg.conflicts.some((conflict) => conflict.type === 'import_failed')\n    )\n    .map((pkg) => {\n      const importFailedConflict = pkg.conflicts.find(\n        (conflict) => conflict.type === 'import_failed'\n      )\n      if (!importFailedConflict) {\n        return {\n          packageId: pkg.package_id,\n          packageName: pkg.package_name,\n          errorMessage: 'Unknown import error',\n          traceback: ''\n        }\n      }\n\n      return {\n        packageId: pkg.package_id,\n        packageName: pkg.package_name,\n        errorMessage:\n          importFailedConflict.current_value || 'Unknown import error',\n        traceback: importFailedConflict.required_value || ''\n      }\n    })\n})\n</script>\n","<template>\n  <div class=\"flex w-full items-center justify-between px-3 pb-4\">\n    <div class=\"flex w-full items-start justify-end gap-2 pr-1\">\n      <Button variant=\"secondary\" @click=\"handleCopyError\">\n        {{ $t('importFailed.copyError') }}\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useCopyToClipboard } from '@/composables/useCopyToClipboard'\nimport type { ConflictDetectionResult } from '@/workbench/extensions/manager/types/conflictDetectionTypes'\n\nconst { conflictedPackages = [] } = defineProps<{\n  conflictedPackages?: ConflictDetectionResult[]\n}>()\n\nconst { copyToClipboard } = useCopyToClipboard()\n\nconst formatErrorText = computed(() => {\n  const errorParts: string[] = []\n\n  conflictedPackages.forEach((pkg) => {\n    const importFailedConflict = pkg.conflicts.find(\n      (conflict) => conflict.type === 'import_failed'\n    )\n\n    if (importFailedConflict?.required_value) {\n      errorParts.push(importFailedConflict.required_value)\n    }\n  })\n\n  return errorParts.join('\\n\\n')\n})\n\nconst handleCopyError = () => {\n  copyToClipboard(formatErrorText.value)\n}\n</script>\n","<template>\n  <div class=\"flex w-full items-center justify-between p-4\">\n    <div class=\"flex items-center gap-2\">\n      <i class=\"icon-[lucide--triangle-alert] text-warning-background\" />\n      <p class=\"m-0 text-sm\">\n        {{ $t('importFailed.title') }}\n      </p>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\"></script>\n","import { useDialogService } from '@/services/dialogService'\nimport type { DialogComponentProps } from '@/stores/dialogStore'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport ImportFailedNodeContent from '@/workbench/extensions/manager/components/manager/ImportFailedNodeContent.vue'\nimport ImportFailedNodeFooter from '@/workbench/extensions/manager/components/manager/ImportFailedNodeFooter.vue'\nimport ImportFailedNodeHeader from '@/workbench/extensions/manager/components/manager/ImportFailedNodeHeader.vue'\nimport type { ConflictDetectionResult } from '@/workbench/extensions/manager/types/conflictDetectionTypes'\n\nconst DIALOG_KEY = 'global-import-failed'\n\nexport function useImportFailedNodeDialog() {\n  const { showSmallLayoutDialog } = useDialogService()\n  const dialogStore = useDialogStore()\n\n  function hide() {\n    dialogStore.closeDialog({ key: DIALOG_KEY })\n  }\n\n  function show(\n    options: {\n      conflictedPackages?: ConflictDetectionResult[]\n      dialogComponentProps?: DialogComponentProps\n    } = {}\n  ) {\n    const { dialogComponentProps, conflictedPackages = [] } = options\n\n    showSmallLayoutDialog({\n      key: DIALOG_KEY,\n      headerComponent: ImportFailedNodeHeader,\n      footerComponent: ImportFailedNodeFooter,\n      component: ImportFailedNodeContent,\n      dialogComponentProps,\n      props: {\n        conflictedPackages\n      },\n      footerProps: {\n        conflictedPackages\n      }\n    })\n  }\n\n  return { show, hide }\n}\n","import { computed, unref } from 'vue'\nimport type { ComputedRef } from 'vue'\n\nimport { useImportFailedNodeDialog } from '@/workbench/extensions/manager/composables/useImportFailedNodeDialog'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport { useConflictDetectionStore } from '@/workbench/extensions/manager/stores/conflictDetectionStore'\nimport type {\n  ConflictDetail,\n  ConflictDetectionResult\n} from '@/workbench/extensions/manager/types/conflictDetectionTypes'\n\n/**\n * Extracting import failed conflicts from conflict list\n */\nfunction extractImportFailedConflicts(conflicts?: ConflictDetail[] | null) {\n  if (!conflicts) return null\n\n  const importFailedConflicts = conflicts.filter(\n    (item): item is ConflictDetail => item.type === 'import_failed'\n  )\n\n  return importFailedConflicts.length > 0 ? importFailedConflicts : null\n}\n\n/**\n * Creating import failed dialog\n */\nfunction createImportFailedDialog() {\n  const { show } = useImportFailedNodeDialog()\n\n  return (\n    conflictedPackages: ConflictDetectionResult[] | null,\n    onClose?: () => void\n  ) => {\n    if (conflictedPackages && conflictedPackages.length > 0) {\n      show({\n        conflictedPackages,\n        dialogComponentProps: {\n          onClose\n        }\n      })\n    }\n  }\n}\n\n/**\n * Composable for detecting and handling import failed conflicts\n * @param packageId - Package ID string or computed ref\n * @returns Object with import failed detection and dialog handler\n */\nexport function useImportFailedDetection(\n  packageId?: string | ComputedRef<string> | null\n) {\n  const { isPackInstalled } = useComfyManagerStore()\n  const { getConflictsForPackageByID } = useConflictDetectionStore()\n\n  const isInstalled = computed(() =>\n    packageId ? isPackInstalled(unref(packageId)) : false\n  )\n\n  const conflicts = computed(() => {\n    const currentPackageId = unref(packageId)\n    if (!currentPackageId || !isInstalled.value) return null\n    return getConflictsForPackageByID(currentPackageId) || null\n  })\n\n  const importFailedInfo = computed(() => {\n    return extractImportFailedConflicts(conflicts.value?.conflicts)\n  })\n\n  const importFailed = computed(() => {\n    return importFailedInfo.value !== null\n  })\n\n  const openDialog = createImportFailedDialog()\n\n  return {\n    importFailedInfo,\n    importFailed,\n    showImportFailedDialog: (onClose?: () => void) => {\n      if (conflicts.value) {\n        openDialog([conflicts.value], onClose)\n      }\n    },\n    isInstalled\n  }\n}\n","<template>\n  <div class=\"flex items-center gap-2\">\n    <Button\n      v-if=\"packageConflict?.has_conflict\"\n      :tooltip=\"$t('manager.conflicts.warningTooltip')\"\n      variant=\"muted-textonly\"\n      size=\"icon-sm\"\n      class=\"size-6\"\n      :aria-label=\"$t('manager.conflicts.warningTooltip')\"\n      @click=\"showConflictModal(true)\"\n    >\n      <i class=\"icon-[lucide--triangle-alert] size-6 text-warning-background\" />\n    </Button>\n    <Switch\n      v-if=\"!canToggleDirectly\"\n      :model-value=\"isEnabled\"\n      :disabled=\"isLoading\"\n      :readonly=\"!canToggleDirectly\"\n      :aria-label=\"$t('g.enableOrDisablePack')\"\n      @focus=\"handleToggleInteraction\"\n    />\n    <Switch\n      v-else\n      :model-value=\"isEnabled\"\n      :disabled=\"isLoading\"\n      :aria-label=\"$t('g.enableOrDisablePack')\"\n      @update:model-value=\"onToggle\"\n    />\n  </div>\n</template>\n<script setup lang=\"ts\">\nimport { debounce } from 'es-toolkit/compat'\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Switch from '@/components/ui/switch/Switch.vue'\nimport type { components } from '@/types/comfyRegistryTypes'\nimport { useConflictAcknowledgment } from '@/workbench/extensions/manager/composables/useConflictAcknowledgment'\nimport { useImportFailedDetection } from '@/workbench/extensions/manager/composables/useImportFailedDetection'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport { useNodeConflictDialog } from '@/workbench/extensions/manager/composables/useNodeConflictDialog'\nimport { useConflictDetectionStore } from '@/workbench/extensions/manager/stores/conflictDetectionStore'\nimport type { components as ManagerComponents } from '@/workbench/extensions/manager/types/generatedManagerTypes'\n\nconst TOGGLE_DEBOUNCE_MS = 256\n\nconst { nodePack } = defineProps<{\n  nodePack: components['schemas']['Node']\n}>()\n\nconst { t } = useI18n()\nconst { isPackEnabled, enablePack, disablePack, installedPacks } =\n  useComfyManagerStore()\nconst { getConflictsForPackageByID } = useConflictDetectionStore()\nconst { show: showNodeConflictDialog } = useNodeConflictDialog()\nconst { acknowledgmentState, markConflictsAsSeen } = useConflictAcknowledgment()\nconst { showImportFailedDialog } = useImportFailedDetection(nodePack.id || '')\n\nconst isLoading = ref(false)\n\nconst isEnabled = computed(() => isPackEnabled(nodePack.id))\nconst version = computed(() => {\n  const id = nodePack.id\n  if (!id) return 'nightly' as ManagerComponents['schemas']['SelectedVersion']\n  return (\n    installedPacks[id]?.ver ??\n    nodePack.latest_version?.version ??\n    ('nightly' as ManagerComponents['schemas']['SelectedVersion'])\n  )\n})\n\nconst packageConflict = computed(() => {\n  if (!nodePack.id) return undefined\n  return getConflictsForPackageByID(nodePack.id)\n})\nconst canToggleDirectly = computed(() => {\n  return !(\n    packageConflict.value?.has_conflict &&\n    !acknowledgmentState.value.modal_dismissed\n  )\n})\n\nconst showConflictModal = (skipModalDismissed: boolean) => {\n  let modal_dismissed = acknowledgmentState.value.modal_dismissed\n  if (skipModalDismissed) modal_dismissed = false\n\n  if (packageConflict.value && !modal_dismissed) {\n    // Check if there's an import failed conflict first\n    const hasImportFailed = packageConflict.value.conflicts.some(\n      (conflict) => conflict.type === 'import_failed'\n    )\n    if (hasImportFailed) {\n      // Show import failed dialog instead of general conflict dialog\n      showImportFailedDialog(() => {\n        markConflictsAsSeen()\n      })\n    } else {\n      // Show general conflict dialog for other types of conflicts\n      showNodeConflictDialog({\n        conflictedPackages: [packageConflict.value],\n        buttonText: !isEnabled.value\n          ? t('manager.conflicts.enableAnyway')\n          : t('manager.conflicts.understood'),\n        onButtonClick: async () => {\n          if (!isEnabled.value) {\n            await handleEnable()\n          }\n        },\n        dialogComponentProps: {\n          onClose: () => {\n            markConflictsAsSeen()\n          }\n        }\n      })\n    }\n  }\n}\n\nconst handleEnable = () => {\n  if (!nodePack.id) {\n    console.error('Node ID is required for enabling')\n    return\n  }\n  return enablePack({\n    id: nodePack.id,\n    version:\n      version.value ??\n      ('latest' as ManagerComponents['schemas']['SelectedVersion'])\n  })\n}\n\nconst handleDisable = () => {\n  if (!nodePack.id) {\n    console.error('Node ID is required for disabling')\n    return\n  }\n  return disablePack({\n    id: nodePack.id,\n    version:\n      version.value ??\n      ('latest' as ManagerComponents['schemas']['SelectedVersion'])\n  })\n}\n\nconst handleToggle = async (enable: boolean) => {\n  if (isLoading.value) return\n\n  isLoading.value = true\n  if (enable) {\n    await handleEnable()\n  } else {\n    await handleDisable()\n  }\n  isLoading.value = false\n}\n\nconst onToggle = debounce(\n  (enable: boolean) => {\n    void handleToggle(enable)\n  },\n  TOGGLE_DEBOUNCE_MS,\n  { trailing: true }\n)\nconst handleToggleInteraction = async (event: Event) => {\n  if (!canToggleDirectly.value) {\n    event.preventDefault()\n    showConflictModal(false)\n  }\n}\n</script>\n","<template>\n  <Button\n    :tooltip=\"$t('manager.tryUpdateTooltip')\"\n    variant=\"primary\"\n    :size\n    :disabled=\"isUpdating\"\n    @click=\"tryUpdate\"\n  >\n    <DotSpinner\n      v-if=\"isUpdating\"\n      duration=\"1s\"\n      :size=\"size === 'sm' ? 12 : 16\"\n    />\n    <i v-else class=\"icon-[lucide--refresh-cw]\" />\n    <span>{{ isUpdating ? t('g.updating') : t('manager.tryUpdate') }}</span>\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport DotSpinner from '@/components/common/DotSpinner.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport type { ButtonVariants } from '@comfyorg/design-system/button.variants'\nimport type { components } from '@/types/comfyRegistryTypes'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\n\ntype NodePack = components['schemas']['Node']\n\nconst { nodePack, size } = defineProps<{\n  nodePack: NodePack\n  size?: ButtonVariants['size']\n}>()\n\nconst { t } = useI18n()\nconst managerStore = useComfyManagerStore()\n\nconst isUpdating = ref(false)\n\nasync function tryUpdate() {\n  if (!nodePack.id) {\n    console.warn('Pack missing required id:', nodePack)\n    return\n  }\n\n  isUpdating.value = true\n  try {\n    await managerStore.updatePack.call({\n      id: nodePack.id,\n      version: 'nightly'\n    })\n    managerStore.updatePack.clear()\n  } catch (error) {\n    console.error('Nightly update failed:', error)\n  } finally {\n    isUpdating.value = false\n  }\n}\n</script>\n","<template>\n  <Button variant=\"destructive\" :size @click=\"uninstallItems\">\n    <i class=\"icon-[lucide--trash-2]\" />\n    {{\n      nodePacks.length > 1\n        ? t('manager.uninstallSelected')\n        : t('manager.uninstall')\n    }}\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport type { ButtonVariants } from '@comfyorg/design-system/button.variants'\nimport type { components } from '@/types/comfyRegistryTypes'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport type { components as ManagerComponents } from '@/workbench/extensions/manager/types/generatedManagerTypes'\n\ntype NodePack = components['schemas']['Node']\n\nconst { nodePacks, size } = defineProps<{\n  nodePacks: NodePack[]\n  size?: ButtonVariants['size']\n}>()\n\nconst managerStore = useComfyManagerStore()\nconst { t } = useI18n()\n\nconst createPayload = (\n  uninstallItem: NodePack\n): ManagerComponents['schemas']['ManagerPackInfo'] | undefined => {\n  if (!uninstallItem.id) {\n    console.error('Node ID is required for uninstallation')\n    return\n  }\n\n  return {\n    id: uninstallItem.id,\n    version: uninstallItem.latest_version?.version || 'unknown'\n  }\n}\n\nconst uninstallPack = (item: NodePack) => {\n  const payload = createPayload(item)\n  if (!payload) return\n  return managerStore.uninstallPack(payload)\n}\n\nconst uninstallItems = async () => {\n  if (!nodePacks?.length) return\n  await Promise.all(nodePacks.map(uninstallPack))\n}\n</script>\n","const SAFE_EXTERNAL_URL_SCHEMES = new Set(['http:', 'https:'])\n\n/**\n * Checks that `url` is a syntactically valid URL using only an http(s)\n * scheme, for use wherever a URL is bound to a clickable `href` (e.g. an\n * `<a>` tag) and could otherwise come from untrusted data (such as a\n * third-party registry). Unlike a bare `new URL(url)` validity check, this\n * rejects `javascript:`, `data:`, and other schemes that parse without\n * throwing but execute or render content on click.\n */\nexport function isSafeExternalUrl(url: string): boolean {\n  try {\n    return SAFE_EXTERNAL_URL_SCHEMES.has(new URL(url).protocol)\n  } catch {\n    return false\n  }\n}\n","<template>\n  <div>\n    <div v-if=\"!hasMarkdown\" class=\"wrap-break-word\" v-text=\"text\" />\n    <div v-else class=\"wrap-break-word\">\n      <template v-for=\"(segment, index) in parsedSegments\" :key=\"index\">\n        <a\n          v-if=\"segment.type === 'link' && 'url' in segment\"\n          :href=\"segment.url\"\n          target=\"_blank\"\n          rel=\"noopener noreferrer\"\n          class=\"hover:underline\"\n        >\n          <span class=\"text-blue-600\">{{ segment.text }}</span>\n        </a>\n        <strong v-else-if=\"segment.type === 'bold'\">{{ segment.text }}</strong>\n        <em v-else-if=\"segment.type === 'italic'\">{{ segment.text }}</em>\n        <code\n          v-else-if=\"segment.type === 'code'\"\n          class=\"rounded-sm px-1 py-0.5 text-xs\"\n          >{{ segment.text }}</code\n        >\n        <span v-else>{{ segment.text }}</span>\n      </template>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nconst { text } = defineProps<{\n  text: string\n}>()\n\ntype MarkdownSegment = {\n  type: 'text' | 'link' | 'bold' | 'italic' | 'code'\n  text: string\n  url?: string\n}\n\nconst hasMarkdown = computed(() => {\n  const hasMarkdown =\n    /(\\[.*?\\]\\(.*?\\)|(\\*\\*|__)(.*?)(\\*\\*|__)|(\\*|_)(.*?)(\\*|_)|`(.*?)`)/.test(\n      text\n    )\n  return hasMarkdown\n})\n\nconst parsedSegments = computed(() => {\n  if (!hasMarkdown.value) return [{ type: 'text', text }]\n\n  const segments: MarkdownSegment[] = []\n  const remainingText = text\n  let lastIndex: number = 0\n\n  const linkRegex = /\\[(.*?)\\]\\((.*?)\\)/g\n  let linkMatch: RegExpExecArray | null\n\n  while ((linkMatch = linkRegex.exec(remainingText)) !== null) {\n    // Add text before the match\n    if (linkMatch.index > lastIndex) {\n      segments.push({\n        type: 'text',\n        text: remainingText.substring(lastIndex, linkMatch.index)\n      })\n    }\n\n    // Add the link\n    segments.push({\n      type: 'link',\n      text: linkMatch[1],\n      url: linkMatch[2]\n    })\n\n    lastIndex = linkMatch.index + linkMatch[0].length\n  }\n\n  // Add remaining text after all links\n  if (lastIndex < remainingText.length) {\n    let rest = remainingText.substring(lastIndex)\n\n    // Process bold text\n    rest = rest.replace(/(\\*\\*|__)(.*?)(\\*\\*|__)/g, (_, __, p2) => {\n      segments.push({ type: 'bold', text: p2 })\n      return ''\n    })\n\n    // Process italic text\n    rest = rest.replace(/(\\*|_)(.*?)(\\*|_)/g, (_, __, p2) => {\n      segments.push({ type: 'italic', text: p2 })\n      return ''\n    })\n\n    // Process code\n    rest = rest.replace(/`(.*?)`/g, (_, p1) => {\n      segments.push({ type: 'code', text: p1 })\n      return ''\n    })\n\n    // Add any remaining text\n    if (rest) {\n      segments.push({ type: 'text', text: rest })\n    }\n  }\n\n  return segments\n})\n</script>\n","<template>\n  <div>\n    <ModelInfoField :label=\"t('g.description')\">\n      <MarkdownText\n        v-if=\"nodePack.description\"\n        :text=\"nodePack.description\"\n        class=\"text-muted-foreground\"\n      />\n      <span v-else class=\"text-muted-foreground italic\">\n        {{ t('manager.noDescription') }}\n      </span>\n    </ModelInfoField>\n    <ModelInfoField v-if=\"safeRepositoryHref\" :label=\"t('manager.repository')\">\n      <a\n        :href=\"safeRepositoryHref\"\n        target=\"_blank\"\n        rel=\"noopener noreferrer\"\n        class=\"inline-flex items-center gap-1.5 text-muted-foreground no-underline transition-colors hover:text-base-foreground\"\n      >\n        <i\n          v-if=\"isGitHubLink(safeRepositoryHref)\"\n          class=\"pi pi-github text-base\"\n        />\n        <span class=\"break-all\">{{ safeRepositoryHref }}</span>\n        <i class=\"icon-[lucide--external-link] size-4 shrink-0\" />\n      </a>\n    </ModelInfoField>\n    <ModelInfoField v-if=\"licenseInfo\" :label=\"t('manager.license')\">\n      <a\n        v-if=\"safeLicenseHref\"\n        :href=\"safeLicenseHref\"\n        target=\"_blank\"\n        rel=\"noopener noreferrer\"\n        class=\"inline-flex items-center gap-1.5 text-muted-foreground no-underline transition-colors hover:text-base-foreground\"\n      >\n        <span class=\"break-all\">{{ licenseInfo.text }}</span>\n        <i class=\"icon-[lucide--external-link] size-4 shrink-0\" />\n      </a>\n      <span v-else class=\"break-all text-muted-foreground\">\n        {{ licenseInfo.text }}\n      </span>\n    </ModelInfoField>\n    <ModelInfoField\n      v-if=\"nodePack.latest_version?.dependencies?.length\"\n      :label=\"t('manager.dependencies')\"\n    >\n      <div\n        v-for=\"(dep, index) in nodePack.latest_version.dependencies\"\n        :key=\"index\"\n        class=\"wrap-break-word text-muted-foreground\"\n      >\n        {{ dep }}\n      </div>\n    </ModelInfoField>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport ModelInfoField from '@/platform/assets/components/modelInfo/ModelInfoField.vue'\nimport type { components } from '@/types/comfyRegistryTypes'\nimport { isSafeExternalUrl } from '@/utils/urlSafety'\nimport MarkdownText from '@/workbench/extensions/manager/components/manager/infoPanel/MarkdownText.vue'\n\nconst { t } = useI18n()\n\nconst { nodePack } = defineProps<{\n  nodePack: components['schemas']['Node']\n}>()\n\n/**\n * Resolves to `nodePack.repository` only when it is a safe http(s) URL,\n * otherwise `undefined` so the template never binds an unsafe (e.g.\n * `javascript:`) value to a clickable `href`.\n */\nconst safeRepositoryHref = computed<string | undefined>(() =>\n  nodePack.repository && isSafeExternalUrl(nodePack.repository)\n    ? nodePack.repository\n    : undefined\n)\n\nconst isGitHubLink = (url: string): boolean => url.includes('github.com')\n\nconst isLicenseFile = (filename: string): boolean => {\n  // Match LICENSE, LICENSE.md, LICENSE.txt (case insensitive)\n  const licensePattern = /^license(\\.md|\\.txt)?$/i\n  return licensePattern.test(filename)\n}\n\nconst extractBaseRepoUrl = (repoUrl: string): string => {\n  const githubRepoPattern = /^(https?:\\/\\/github\\.com\\/[^/]+\\/[^/]+)/i\n  const match = repoUrl.match(githubRepoPattern)\n  return match ? match[1] : repoUrl\n}\n\nconst createLicenseUrl = (filename: string, repoUrl: string): string => {\n  if (!repoUrl || !filename) return ''\n\n  const licenseFile = isLicenseFile(filename) ? filename : 'LICENSE'\n  const baseRepoUrl = extractBaseRepoUrl(repoUrl)\n  return `${baseRepoUrl}/blob/main/${licenseFile}`\n}\n\ninterface LicenseObject {\n  file?: string\n  text?: string\n}\n\nconst parseLicenseObject = (\n  licenseObj: LicenseObject\n): { text: string; isUrl: boolean } => {\n  const licenseFile = licenseObj.file || licenseObj.text\n\n  if (\n    typeof licenseFile === 'string' &&\n    isLicenseFile(licenseFile) &&\n    nodePack.repository\n  ) {\n    const url = createLicenseUrl(licenseFile, nodePack.repository)\n    return {\n      text: url,\n      isUrl: !!url && isSafeExternalUrl(url)\n    }\n  } else if (licenseObj.text) {\n    return {\n      text: licenseObj.text,\n      isUrl: false\n    }\n  } else if (typeof licenseFile === 'string') {\n    // Return the license file name if repository is missing\n    return {\n      text: licenseFile,\n      isUrl: false\n    }\n  }\n  return {\n    text: JSON.stringify(licenseObj),\n    isUrl: false\n  }\n}\n\nconst formatLicense = (\n  license: string\n): { text: string; isUrl: boolean } | null => {\n  // Treat \"{}\" JSON string as undefined\n  if (license === '{}') return null\n\n  try {\n    const licenseObj = JSON.parse(license)\n    // Handle empty object case\n    if (Object.keys(licenseObj).length === 0) {\n      return null\n    }\n    return parseLicenseObject(licenseObj)\n  } catch (e) {\n    if (isLicenseFile(license) && nodePack.repository) {\n      const url = createLicenseUrl(license, nodePack.repository)\n      return {\n        text: url,\n        isUrl: !!url && isSafeExternalUrl(url)\n      }\n    }\n    return {\n      text: license,\n      isUrl: false\n    }\n  }\n}\n\nconst licenseInfo = computed(() => {\n  if (!nodePack.license) return null\n  return formatLicense(nodePack.license)\n})\n\n/**\n * Resolves to the license URL only when `licenseInfo` marked it safe,\n * otherwise `undefined`, so the template never binds an unsafe value to a\n * clickable `href`.\n */\nconst safeLicenseHref = computed<string | undefined>(() =>\n  licenseInfo.value?.isUrl ? licenseInfo.value.text : undefined\n)\n</script>\n","/**\n * Vue-related feature flags composable\n * Manages local settings-driven flags and LiteGraph integration\n */\nimport { createSharedComposable } from '@vueuse/core'\nimport { computed, watch } from 'vue'\n\nimport { useSettingStore } from '@/platform/settings/settingStore'\n\nimport { LiteGraph } from '../lib/litegraph/src/litegraph'\n\nfunction useVueFeatureFlagsIndividual() {\n  const settingStore = useSettingStore()\n\n  const shouldRenderVueNodes = computed(() => {\n    try {\n      return settingStore.get('Comfy.VueNodes.Enabled')\n    } catch {\n      return false\n    }\n  })\n\n  // Watch for changes and update LiteGraph immediately\n  watch(\n    shouldRenderVueNodes,\n    () => {\n      LiteGraph.vueNodesMode = shouldRenderVueNodes.value\n    },\n    { immediate: true }\n  )\n\n  return {\n    shouldRenderVueNodes\n  }\n}\n\nexport const useVueFeatureFlags = createSharedComposable(\n  useVueFeatureFlagsIndividual\n)\n","<template>\n  <div class=\"editable-text inline\">\n    <component :is=\"labelType\" v-if=\"!isEditing\" :class=\"labelClass\">\n      {{ modelValue }}\n    </component>\n    <Input\n      v-else\n      ref=\"inputRef\"\n      v-model=\"inputValue\"\n      v-focus\n      type=\"text\"\n      class=\"h-full rounded-none p-0 focus-visible:ring-0\"\n      v-bind=\"inputAttrs\"\n      @blur=\"finishEditing\"\n      @keydown.enter.capture.stop=\"inputRef?.blur()\"\n      @keydown.escape.capture.stop=\"cancelEditing\"\n      @click.stop\n      @contextmenu.stop\n      @pointerdown.stop.capture\n      @pointermove.stop.capture\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { nextTick, ref, watch } from 'vue'\n\nimport Input from '@/components/ui/input/Input.vue'\n\nconst {\n  modelValue,\n  isEditing = false,\n  inputAttrs = {},\n  labelType = 'span'\n} = defineProps<{\n  modelValue: string\n  isEditing?: boolean\n  inputAttrs?: Record<string, string>\n  labelClass?: string\n  labelType?: string\n}>()\n\nconst emit = defineEmits(['edit', 'cancel'])\nconst inputValue = ref<string>(modelValue)\nconst inputRef = ref<InstanceType<typeof Input>>()\nconst isCanceling = ref(false)\n\nfunction finishEditing() {\n  if (!isCanceling.value) {\n    emit('edit', inputValue.value)\n  }\n  isCanceling.value = false\n}\n\nfunction cancelEditing() {\n  isCanceling.value = true\n  inputValue.value = modelValue\n  emit('cancel')\n  inputRef.value?.blur()\n}\n\nwatch(\n  () => isEditing,\n  async (newVal) => {\n    if (newVal) {\n      inputValue.value = modelValue\n      await nextTick(() => {\n        if (!inputRef.value) return\n        const fileName = inputValue.value.includes('.')\n          ? inputValue.value.split('.').slice(0, -1).join('.')\n          : inputValue.value\n        inputRef.value.setSelectionRange(0, fileName.length)\n      })\n    }\n  },\n  { immediate: true }\n)\n\nconst vFocus = {\n  mounted: (el: HTMLElement) => el.focus()\n}\n</script>\n","<template>\n  <span\n    data-testid=\"credit-badge-required\"\n    :class=\"\n      cn(\n        'flex h-5 shrink-0 items-center bg-component-node-widget-background p-1 text-xs',\n        rest ? 'rounded-l-full pr-1' : 'rounded-full'\n      )\n    \"\n  >\n    <i class=\"icon-[lucide--coins] h-full bg-amber-400\" />\n    <span class=\"truncate\" v-text=\"text\" />\n  </span>\n  <span\n    v-if=\"rest\"\n    data-testid=\"credit-badge-rest\"\n    class=\"-ml-1 flex h-5 max-w-max min-w-0 grow basis-0 items-center truncate rounded-r-full bg-component-node-widget-background text-xs\"\n  >\n    <span class=\"pr-2\" v-text=\"rest\" />\n  </span>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\n\ndefineProps<{\n  text: string\n  rest?: string\n}>()\n</script>\n","<template>\n  <div\n    v-if=\"text\"\n    class=\"flex min-w-max items-center gap-1 rounded-sm bg-node-component-surface px-1 py-0.5 text-xs\"\n    :style=\"{\n      color: fgColor,\n      backgroundColor: bgColor\n    }\"\n    @click=\"(e) => onClick?.(e)\"\n  >\n    {{ text }}\n    <i v-if=\"cssIcon\" :class=\"cn(cssIcon)\" />\n  </div>\n</template>\n<script setup lang=\"ts\">\nimport type { LGraphBadge } from '@/lib/litegraph/src/LGraphBadge'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nexport interface NodeBadgeProps {\n  text: LGraphBadge['text']\n  fgColor?: LGraphBadge['fgColor']\n  bgColor?: LGraphBadge['bgColor']\n  cssIcon?: string\n  onClick?: (e: MouseEvent) => void\n}\n\nconst {\n  text,\n  fgColor = 'currentColor',\n  bgColor = '',\n  cssIcon\n} = defineProps<NodeBadgeProps>()\n</script>\n","import { computed, unref } from 'vue'\nimport type { MaybeRef } from 'vue'\n\nimport { resolveNodeDefSlotText, resolveNodeDefText, t } from '@/i18n'\nimport type { INodeSlot } from '@/lib/litegraph/src/litegraph'\nimport { RenderShape } from '@/lib/litegraph/src/types/globalEnums'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\n\n/**\n * Composable for managing Vue node tooltips\n * Provides tooltip text for node headers, slots, and widgets\n */\nexport function useNodeTooltips(nodeType: MaybeRef<string>) {\n  const nodeDefStore = useNodeDefStore()\n  const settingsStore = useSettingStore()\n\n  const tooltipsEnabled = computed(() =>\n    settingsStore.get('Comfy.EnableTooltips')\n  )\n\n  const findNodeDef = (type: string): ComfyNodeDefImpl | undefined =>\n    nodeDefStore.nodeDefsByName[type]\n  const nodeDef = computed(() => findNodeDef(unref(nodeType)))\n\n  const getNodeDescription = computed(() => {\n    if (!tooltipsEnabled.value || !nodeDef.value) return ''\n\n    return resolveNodeDefText(\n      'description',\n      unref(nodeType),\n      nodeDef.value.description || undefined\n    )\n  })\n\n  const describeInput = (inputName: string) =>\n    nodeDef.value\n      ? resolveNodeDefSlotText(\n          'tooltip',\n          unref(nodeType),\n          inputName,\n          nodeDef.value.inputs[inputName]?.tooltip\n        )\n      : ''\n\n  const getInputSlotTooltip = (\n    slot: Pick<INodeSlot, 'localized_name' | 'name'>\n  ) => {\n    if (!tooltipsEnabled.value) return ''\n\n    const inputName = slot.name || ''\n    return (\n      describeInput(inputName) ||\n      t('g.inputTooltip', { name: slot.localized_name || inputName })\n    )\n  }\n\n  const getOutputSlotTooltip = (\n    slot: Pick<INodeSlot, 'name' | 'shape'>,\n    slotIndex: number\n  ) => {\n    if (!tooltipsEnabled.value) return ''\n\n    const description = nodeDef.value\n      ? resolveNodeDefSlotText(\n          'tooltip',\n          unref(nodeType),\n          slotIndex,\n          nodeDef.value.outputs[slotIndex]?.tooltip\n        )\n      : ''\n    const text = description || `Output: ${slot.name || ''}`\n    return slot.shape === RenderShape.GRID\n      ? `${text} ${t('vueNodesSlot.iterative')}`\n      : text\n  }\n\n  const getWidgetTooltip = (\n    widget: { name: string; tooltip?: string },\n    fullValue = ''\n  ) => {\n    if (!tooltipsEnabled.value) return ''\n\n    const description = nodeDef.value\n      ? widget.tooltip || describeInput(widget.name)\n      : ''\n    return [description, fullValue].join('\\n\\n').trim()\n  }\n\n  return {\n    getNodeDescription,\n    getInputSlotTooltip,\n    getOutputSlotTooltip,\n    getWidgetTooltip\n  }\n}\n","<template>\n  <div v-if=\"renderError\" class=\"node-error p-4 text-red-500\">\n    {{ st('nodeErrors.header', 'Node Header Error') }}\n  </div>\n  <div\n    v-else\n    :class=\"\n      cn(\n        'lg-node-header w-full min-w-0 p-1 text-xs',\n        'text-node-component-slot-text',\n        headerShapeClass\n      )\n    \"\n    :data-testid=\"`node-header-${nodeData?.id || ''}`\"\n    @dblclick=\"handleDoubleClick\"\n  >\n    <div class=\"flex min-w-0 items-center justify-between gap-1\">\n      <!-- Collapse/Expand Button -->\n      <div class=\"relative mr-auto flex min-w-0 shrink items-center gap-1\">\n        <div class=\"flex shrink-0 items-center px-0.5\">\n          <Button\n            size=\"icon-sm\"\n            variant=\"textonly\"\n            class=\"hover:bg-transparent\"\n            data-testid=\"node-collapse-button\"\n            @click.stop=\"handleCollapse\"\n            @dblclick.stop\n          >\n            <i\n              :class=\"\n                cn(\n                  'icon-[lucide--chevron-down] size-4 transition-transform',\n                  collapsed && '-rotate-90'\n                )\n              \"\n              class=\"text-node-component-header-icon\"\n            />\n          </Button>\n        </div>\n        <!-- Node Title -->\n        <Tooltip :disabled=\"!tooltipText\">\n          <TooltipTrigger as-child>\n            <div\n              class=\"flex min-w-0 flex-1 items-center gap-2\"\n              data-testid=\"node-title\"\n            >\n              <div class=\"flex-1 truncate\">\n                <EditableText\n                  :model-value=\"displayTitle\"\n                  :is-editing=\"isEditing\"\n                  :input-attrs=\"{ 'data-testid': 'node-title-input' }\"\n                  @edit=\"handleTitleEdit\"\n                  @cancel=\"handleTitleCancel\"\n                />\n              </div>\n            </div>\n          </TooltipTrigger>\n          <TooltipContent>{{ tooltipText }}</TooltipContent>\n        </Tooltip>\n      </div>\n\n      <CreditBadge\n        v-for=\"badge in priceBadges ?? []\"\n        :key=\"badge.required\"\n        :text=\"badge.required\"\n        :rest=\"badge.rest\"\n      />\n      <NodeBadge v-if=\"statusBadge\" v-bind=\"statusBadge\" />\n      <i\n        v-if=\"isPinned\"\n        class=\"icon-[comfy--pin] size-4\"\n        data-testid=\"node-pin-indicator\"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, onErrorCaptured, ref } from 'vue'\n\nimport EditableText from '@/components/common/EditableText.vue'\nimport CreditBadge from '@/components/node/CreditBadge.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\nimport type { NodeState } from '@/types/nodeState'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { st } from '@/i18n'\nimport { LGraphEventMode, RenderShape } from '@/lib/litegraph/src/litegraph'\nimport NodeBadge from '@/renderer/extensions/vueNodes/components/NodeBadge.vue'\nimport { useNodeTooltips } from '@/renderer/extensions/vueNodes/composables/useNodeTooltips'\nimport { resolveNodeDisplayName } from '@/utils/nodeTitleUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport type { NodeBadgeProps } from './NodeBadge.vue'\n\ninterface NodeHeaderProps {\n  nodeData?: NodeState\n  collapsed?: boolean\n  priceBadges?: { required: string; rest?: string }[]\n}\n\nconst { nodeData, collapsed } = defineProps<NodeHeaderProps>()\n\nconst emit = defineEmits<{\n  collapse: []\n  'update:title': [newTitle: string]\n}>()\n\n// Error boundary implementation\nconst renderError = ref<string | null>(null)\nconst { toastErrorHandler } = useErrorHandling()\n\nonErrorCaptured((error) => {\n  renderError.value = error.message\n  toastErrorHandler(error)\n  return false\n})\n\n// Editing state\nconst isEditing = ref(false)\n\nconst { getNodeDescription } = useNodeTooltips(nodeData?.type || '')\n\nconst tooltipText = computed(() =>\n  isEditing.value ? '' : getNodeDescription.value\n)\n\nconst resolveTitle = (info: NodeState | undefined) => {\n  const untitledLabel = st('g.untitled', 'Untitled')\n  return resolveNodeDisplayName(info ?? null, {\n    emptyLabel: untitledLabel,\n    untitledLabel\n  })\n}\n\nconst displayTitle = computed(() => resolveTitle(nodeData))\n\nconst bypassed = computed(\n  (): boolean => nodeData?.mode === LGraphEventMode.BYPASS\n)\nconst muted = computed((): boolean => nodeData?.mode === LGraphEventMode.NEVER)\n\nconst statusBadge = computed((): NodeBadgeProps | undefined =>\n  muted.value\n    ? { text: 'Muted', cssIcon: 'icon-[lucide--ban]' }\n    : bypassed.value\n      ? { text: 'Bypassed', cssIcon: 'icon-[lucide--redo-dot]' }\n      : undefined\n)\n\nconst isPinned = computed(() => Boolean(nodeData?.flags.pinned))\n\nconst headerShapeClass = computed(() => {\n  if (collapsed) {\n    switch (nodeData?.shape) {\n      case RenderShape.BOX:\n        return 'rounded-none'\n      case RenderShape.CARD:\n        return 'rounded-tl-xl rounded-br-xl rounded-tr-none rounded-bl-none'\n      default:\n        return 'rounded-xl'\n    }\n  }\n  switch (nodeData?.shape) {\n    case RenderShape.BOX:\n      return 'rounded-t-none'\n    case RenderShape.CARD:\n      return 'rounded-tl-xl rounded-tr-none'\n    default:\n      return 'rounded-t-xl'\n  }\n})\n\n// Event handlers\nconst handleCollapse = () => {\n  emit('collapse')\n}\n\nconst handleDoubleClick = () => {\n  isEditing.value = true\n}\n\nconst handleTitleEdit = (newTitle: string) => {\n  isEditing.value = false\n  const trimmedTitle = newTitle.trim()\n  if (trimmedTitle && trimmedTitle !== displayTitle.value) {\n    // Emit for litegraph sync\n    emit('update:title', trimmedTitle)\n  }\n}\n\nconst handleTitleCancel = () => {\n  isEditing.value = false\n}\n</script>\n","import type { NodeId } from '@/types/nodeId'\nimport { toNodeId } from '@/types/nodeId'\n\nexport type SlotId = string & { readonly __brand: 'SlotId' }\nexport type SlotIndex = number\nexport type SlotDirection = 'input' | 'output'\n\nfunction toSlotId(value: string): SlotId {\n  return value as SlotId\n}\n\nexport function slotId(\n  nodeId: NodeId,\n  direction: SlotDirection,\n  index: SlotIndex\n): SlotId {\n  const type = direction === 'input' ? 'in' : 'out'\n  return toSlotId(`${String(nodeId)}-${type}-${index}`)\n}\n\nexport function parseSlotId(value: string): {\n  key: SlotId\n  nodeId: NodeId\n  direction: SlotDirection\n  index: SlotIndex\n} | null {\n  const match = /^(.*)-(in|out)-(\\d+)$/.exec(value)\n  if (!match?.[1] || !match[2] || !match[3]) return null\n  const index = Number(match[3])\n  if (!Number.isSafeInteger(index)) return null\n\n  return {\n    key: toSlotId(value),\n    nodeId: toNodeId(match[1]),\n    direction: match[2] === 'in' ? 'input' : 'output',\n    index\n  }\n}\n","import { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport { layoutStore } from '@/renderer/core/layout/store/layoutStore'\nimport type { SlotOffset, SlotOffsetMode } from '@/renderer/core/layout/types'\nimport type { NodeId } from '@/types/nodeId'\nimport { parseSlotId } from '@/types/slotId'\nimport type { UUID } from '@/utils/uuid'\n\nexport function syncSlotOffsets(\n  element: HTMLElement,\n  graphId: UUID,\n  nodeId: NodeId\n): void {\n  const nodeElement = element.closest<HTMLElement>('[data-node-id]') ?? element\n  const mode: SlotOffsetMode =\n    nodeElement.dataset.collapsed === undefined ? 'expanded' : 'collapsed'\n  const slotElements =\n    nodeElement.querySelectorAll<HTMLElement>('[data-slot-key]')\n  if (slotElements.length === 0) {\n    layoutStore.updateNodeSlotOffsets(graphId, nodeId, [], mode)\n    return\n  }\n\n  const nodeRect = nodeElement.getBoundingClientRect()\n  const scale = nodeElement.offsetWidth\n    ? nodeRect.width / nodeElement.offsetWidth\n    : 0\n  if (scale <= 0) return\n\n  const offsets: SlotOffset[] = []\n  for (const slotElement of slotElements) {\n    const slotId = parseSlotId(slotElement.dataset.slotKey ?? '')\n    if (!slotId || slotId.nodeId !== nodeId) continue\n\n    const slotRect = slotElement.getBoundingClientRect()\n    if (slotRect.width <= 0 || slotRect.height <= 0) continue\n\n    offsets.push({\n      index: slotId.index,\n      type: slotId.direction,\n      position: {\n        x:\n          mode === 'collapsed'\n            ? (slotRect.left + slotRect.width / 2 - nodeRect.x) / scale\n            : slotId.direction === 'input'\n              ? 0\n              : nodeElement.offsetWidth,\n        y:\n          (slotRect.top + slotRect.height / 2 - nodeRect.y) / scale -\n          LiteGraph.NODE_TITLE_HEIGHT\n      }\n    })\n  }\n  layoutStore.updateNodeSlotOffsets(graphId, nodeId, offsets, mode)\n}\n","import type { INodeSlot } from '@/lib/litegraph/src/interfaces'\nimport type { INodeInputSlot } from '@/lib/litegraph/src/types/slots'\nimport { useLinkStore } from '@/stores/linkStore'\nimport type { GraphScope } from '@/types/graphScopeId'\nimport type { NodeId } from '@/types/nodeId'\nimport { isSlotObject } from '@/utils/typeGuardUtil'\n\nfunction coerceINodeSlot(input: INodeInputSlot): INodeSlot {\n  return isSlotObject(input)\n    ? input\n    : {\n        name: typeof input === 'string' ? input : '',\n        type: 'any',\n        boundingRect: [0, 0, 0, 0]\n      }\n}\n\nfunction inputHasWidget(input: INodeInputSlot) {\n  return isSlotObject(input) && 'widget' in input && input.widget\n}\n\nexport function nonWidgetedInputs(\n  inputs: INodeInputSlot[] | undefined\n): INodeSlot[] {\n  if (!inputs) return []\n\n  return inputs.filter((input) => !inputHasWidget(input)).map(coerceINodeSlot)\n}\n\nexport function linkedWidgetedInputs(\n  nodeId: NodeId,\n  inputs: INodeInputSlot[] | undefined,\n  scope: GraphScope\n): INodeSlot[] {\n  if (!inputs) return []\n\n  const linkStore = useLinkStore()\n  return inputs\n    .filter(\n      (input, index) =>\n        inputHasWidget(input) &&\n        linkStore.isInputSlotConnected(scope, nodeId, index)\n    )\n    .map(coerceINodeSlot)\n}\n","import { reactive, readonly } from 'vue'\n\nimport type { LinkDirection } from '@/lib/litegraph/src/types/globalEnums'\nimport type { Point, SlotLayout } from '@/renderer/core/layout/types'\nimport type { NodeId } from '@/types/nodeId'\n\n/**\n * Slot link drag UI state\n *\n * Reactive, shared state for a single drag interaction that UI components subscribe to.\n * Tracks pointer position, source slot, and resolved drop candidate. Also exposes\n * a compatibility map used to dim incompatible slots during drag.\n */\n\ntype SlotDragType = 'input' | 'output'\n\ninterface SlotDragSource {\n  nodeId: NodeId\n  slotIndex: number\n  type: SlotDragType\n  direction: LinkDirection\n  position: Readonly<Point>\n  linkId?: number\n  movingExistingOutput?: boolean\n}\n\nexport interface SlotDropCandidate {\n  layout: SlotLayout\n  compatible: boolean\n}\n\ninterface PointerPosition {\n  client: Point\n  canvas: Point\n}\n\ninterface SlotDragState {\n  active: boolean\n  pointerId: number | null\n  source: SlotDragSource | null\n  pointer: PointerPosition\n  candidate: SlotDropCandidate | null\n  compatible: Map<string, boolean>\n}\n\nconst state = reactive<SlotDragState>({\n  active: false,\n  pointerId: null,\n  source: null,\n  pointer: {\n    client: { x: 0, y: 0 },\n    canvas: { x: 0, y: 0 }\n  },\n  candidate: null,\n  compatible: new Map<string, boolean>()\n})\n\nfunction updatePointerPosition(\n  clientX: number,\n  clientY: number,\n  canvasX: number,\n  canvasY: number\n) {\n  state.pointer.client.x = clientX\n  state.pointer.client.y = clientY\n  state.pointer.canvas.x = canvasX\n  state.pointer.canvas.y = canvasY\n}\n\nfunction setCandidate(candidate: SlotDropCandidate | null) {\n  state.candidate = candidate\n}\n\nfunction beginDrag(source: SlotDragSource, pointerId: number) {\n  state.active = true\n  state.source = source\n  state.pointerId = pointerId\n  state.candidate = null\n  state.compatible.clear()\n}\n\nfunction endDrag() {\n  state.active = false\n  state.pointerId = null\n  state.source = null\n  state.pointer.client.x = 0\n  state.pointer.client.y = 0\n  state.pointer.canvas.x = 0\n  state.pointer.canvas.y = 0\n  state.candidate = null\n  state.compatible.clear()\n}\n\nexport function useSlotLinkDragUIState() {\n  return {\n    state: readonly(state),\n    beginDrag,\n    endDrag,\n    updatePointerPosition,\n    setCandidate,\n    setCompatibleMap: (entries: Iterable<[string, boolean]>) => {\n      state.compatible.clear()\n      for (const [key, value] of entries) state.compatible.set(key, value)\n    },\n    setCompatibleForKey: (key: string, value: boolean) => {\n      state.compatible.set(key, value)\n    },\n    clearCompatible: () => state.compatible.clear()\n  }\n}\n","import { slotId } from '@/types/slotId'\nimport type { NodeId } from '@/types/nodeId'\nimport type { SlotId, SlotIndex } from '@/types/slotId'\n\nexport function getSlotKey(\n  nodeId: NodeId,\n  index: SlotIndex,\n  isInput: boolean\n): SlotId {\n  return slotId(nodeId, isInput ? 'input' : 'output', index)\n}\n","import { useSharedCanvasPositionConversion } from '@/composables/element/useCanvasPositionConversion'\nimport type {\n  CanvasPointerEvent,\n  CanvasPointerExtensions\n} from '@/lib/litegraph/src/types/events'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\n\ntype PointerOffsets = {\n  x: number\n  y: number\n}\n\nconst pointerHistory = new Map<number, PointerOffsets>()\n\nconst defineEnhancements = (\n  event: PointerEvent,\n  enhancement: CanvasPointerExtensions\n) => {\n  Object.defineProperties(event, {\n    canvasX: { value: enhancement.canvasX, configurable: true, writable: true },\n    canvasY: { value: enhancement.canvasY, configurable: true, writable: true },\n    deltaX: { value: enhancement.deltaX, configurable: true, writable: true },\n    deltaY: { value: enhancement.deltaY, configurable: true, writable: true },\n    safeOffsetX: {\n      value: enhancement.safeOffsetX,\n      configurable: true,\n      writable: true\n    },\n    safeOffsetY: {\n      value: enhancement.safeOffsetY,\n      configurable: true,\n      writable: true\n    }\n  })\n}\n\nconst createEnhancement = (event: PointerEvent): CanvasPointerExtensions => {\n  const conversion = useSharedCanvasPositionConversion()\n  conversion.update()\n\n  const [canvasX, canvasY] = conversion.clientPosToCanvasPos([\n    event.clientX,\n    event.clientY\n  ])\n\n  const canvas = useCanvasStore().getCanvas()\n  const { offset, scale } = canvas.ds\n\n  const [originClientX, originClientY] = conversion.canvasPosToClientPos([0, 0])\n  const left = originClientX - offset[0] * scale\n  const top = originClientY - offset[1] * scale\n\n  const safeOffsetX = event.clientX - left\n  const safeOffsetY = event.clientY - top\n\n  const previous = pointerHistory.get(event.pointerId)\n  const deltaX = previous ? safeOffsetX - previous.x : 0\n  const deltaY = previous ? safeOffsetY - previous.y : 0\n  pointerHistory.set(event.pointerId, { x: safeOffsetX, y: safeOffsetY })\n\n  return { canvasX, canvasY, deltaX, deltaY, safeOffsetX, safeOffsetY }\n}\n\nexport const toCanvasPointerEvent = <T extends PointerEvent>(\n  event: T\n): T & CanvasPointerEvent => {\n  const enhancement = createEnhancement(event)\n  defineEnhancements(event, enhancement)\n  return event as T & CanvasPointerEvent\n}\n\nexport const clearCanvasPointerHistory = (pointerId: number) => {\n  pointerHistory.delete(pointerId)\n}\n","import type { SlotLayout } from '@/renderer/core/layout/types'\nimport type { Point } from '@/lib/litegraph/src/interfaces'\nimport type { LGraph } from '@/lib/litegraph/src/LGraph'\nimport type { RerouteId } from '@/lib/litegraph/src/Reroute'\nimport type { LinkConnector } from '@/lib/litegraph/src/canvas/LinkConnector'\nimport type { RenderLink } from '@/lib/litegraph/src/canvas/RenderLink'\nimport type { CanvasPointerEvent } from '@/lib/litegraph/src/types/events'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport type { NodeId } from '@/types/nodeId'\nimport { isSubgraph } from '@/utils/typeGuardUtil'\n\n// Keep one adapter per graph so rendering and interaction share state.\nconst adapterByGraph = new WeakMap<LGraph, LinkConnectorAdapter>()\n\n/**\n * Renderer‑agnostic adapter around LiteGraph's LinkConnector.\n *\n * - Uses layoutStore for hit‑testing (nodes/reroutes).\n * - Exposes minimal, imperative APIs to begin link drags and query drop validity.\n * - Preserves existing Vue composable behavior.\n */\nexport class LinkConnectorAdapter {\n  constructor(\n    /** Network the links belong to (typically `app.canvas.graph`). */\n    readonly network: LGraph,\n    readonly linkConnector: LinkConnector\n  ) {}\n\n  /**\n   * The currently rendered/dragged links, typed for consumer use.\n   * Prefer this over accessing `linkConnector.renderLinks` directly.\n   */\n  get renderLinks(): ReadonlyArray<RenderLink> {\n    return this.linkConnector.renderLinks\n  }\n\n  // Drag helpers\n\n  /**\n   * Begin dragging from an output slot.\n   * @param nodeId Output node id\n   * @param outputIndex Output slot index\n   * @param opts Optional: moveExisting (shift), fromRerouteId\n   */\n  beginFromOutput(\n    nodeId: NodeId,\n    outputIndex: number,\n    opts?: { moveExisting?: boolean; fromRerouteId?: RerouteId }\n  ): void {\n    const node = this.network.getNodeById(nodeId)\n    const output = node?.outputs[outputIndex]\n    if (!node || !output) return\n\n    const fromReroute = this.network.getReroute(opts?.fromRerouteId)\n\n    if (opts?.moveExisting) {\n      this.linkConnector.moveOutputLink(this.network, node, output)\n    } else {\n      this.linkConnector.dragNewFromOutput(\n        this.network,\n        node,\n        output,\n        fromReroute\n      )\n    }\n  }\n\n  /**\n   * Begin dragging from an input slot.\n   * @param nodeId Input node id\n   * @param inputIndex Input slot index\n   * @param opts Optional: moveExisting (when a link/floating exists), fromRerouteId\n   */\n  beginFromInput(\n    nodeId: NodeId,\n    inputIndex: number,\n    opts?: {\n      fromRerouteId?: RerouteId\n      layout?: SlotLayout\n      moveExisting?: boolean\n    }\n  ): void {\n    const node = this.network.getNodeById(nodeId)\n    const input = node?.inputs[inputIndex]\n    if (!node || !input) return\n\n    const fromReroute = this.network.getReroute(opts?.fromRerouteId)\n\n    if (opts?.moveExisting) {\n      const startPoint: Point | undefined = opts.layout\n        ? [opts.layout.position.x, opts.layout.position.y]\n        : undefined\n      this.linkConnector.moveInputLink(this.network, node, input, {\n        startPoint\n      })\n    } else {\n      this.linkConnector.dragNewFromInput(\n        this.network,\n        node,\n        input,\n        fromReroute\n      )\n    }\n  }\n\n  // Validation helpers\n\n  isNodeValidDrop(nodeId: NodeId): boolean {\n    const node = this.network.getNodeById(nodeId)\n    if (!node) return false\n    return this.linkConnector.isNodeValidDrop(node)\n  }\n\n  isInputValidDrop(nodeId: NodeId, inputIndex: number): boolean {\n    const node = this.network.getNodeById(nodeId)\n    const input = node?.inputs[inputIndex]\n    if (!node || !input) return false\n    return this.linkConnector.isInputValidDrop(node, input)\n  }\n\n  isOutputValidDrop(nodeId: NodeId, outputIndex: number): boolean {\n    const node = this.network.getNodeById(nodeId)\n    const output = node?.outputs[outputIndex]\n    if (!node || !output) return false\n    return this.linkConnector.renderLinks.some((link) =>\n      link.canConnectToOutput(node, output)\n    )\n  }\n\n  isRerouteValidDrop(rerouteId: RerouteId): boolean {\n    const reroute = this.network.getReroute(rerouteId)\n    if (!reroute) return false\n    return this.linkConnector.isRerouteValidDrop(reroute)\n  }\n\n  // Drop/cancel helpers for future flows\n\n  /** Disconnects moving links (drop on canvas/no target). */\n  disconnectMovingLinks(): void {\n    this.linkConnector.disconnectLinks()\n  }\n\n  /** Drops moving links onto the canvas (no target). */\n  dropOnCanvas(event: CanvasPointerEvent): void {\n    //Add extra check for connection to subgraphInput/subgraphOutput\n    if (isSubgraph(this.network)) {\n      const { canvasX, canvasY } = event\n      const ioNode = this.network.getIoNodeOnPos(canvasX, canvasY)\n      if (ioNode) {\n        this.linkConnector.dropOnIoNode(ioNode, event)\n        return\n      }\n    }\n    this.linkConnector.dropOnNothing(event)\n  }\n\n  /** Resets connector state and clears any temporary flags. */\n  reset(): void {\n    this.linkConnector.reset()\n  }\n}\n\n/** Convenience creator using the current app canvas graph. */\nexport function createLinkConnectorAdapter(): LinkConnectorAdapter | null {\n  const canvas = useCanvasStore().canvas\n  const graph = canvas?.graph\n  if (!graph) return null\n  const connector = canvas.linkConnector\n\n  const adapter = adapterByGraph.get(graph)\n  if (adapter && adapter.linkConnector === connector) {\n    return adapter\n  }\n\n  const newAdapter = new LinkConnectorAdapter(graph, connector)\n  adapterByGraph.set(graph, newAdapter)\n  return newAdapter\n}\n","import type { LGraph } from '@/lib/litegraph/src/LGraph'\nimport type { LinkConnectorAdapter } from '@/renderer/core/canvas/links/linkConnectorAdapter'\nimport { useSlotLinkDragUIState } from '@/renderer/core/canvas/links/slotLinkDragUIState'\nimport type { SlotDropCandidate } from '@/renderer/core/canvas/links/slotLinkDragUIState'\nimport { getGraphSlotLayout } from '@/renderer/core/canvas/litegraph/slotCalculations'\nimport { getSlotKey } from '@/renderer/core/layout/slots/slotIdentifier'\nimport { layoutStore } from '@/renderer/core/layout/store/layoutStore'\nimport type { SlotLayout } from '@/renderer/core/layout/types'\nimport type { SlotLinkDragContext } from '@/renderer/extensions/vueNodes/composables/slotLinkDragContext'\nimport { toNodeId } from '@/types/nodeId'\nimport type { NodeId } from '@/types/nodeId'\nimport { parseSlotId } from '@/types/slotId'\nimport type { SlotId } from '@/types/slotId'\n\ninterface DropResolutionContext {\n  adapter: LinkConnectorAdapter | null\n  graph: LGraph | null\n  session: SlotLinkDragContext\n}\n\nfunction getCandidateSlotLayout(\n  graph: LGraph,\n  rawKey: string\n): { key: SlotId; layout: SlotLayout } | null {\n  const identifier = parseSlotId(rawKey)\n  if (!identifier) return null\n  const layout = getGraphSlotLayout(\n    graph,\n    identifier.nodeId,\n    identifier.index,\n    identifier.direction === 'input'\n  )\n\n  return layout ? { key: identifier.key, layout } : null\n}\n\nexport const resolveSlotTargetCandidate = (\n  target: EventTarget | null,\n  { adapter, graph }: DropResolutionContext\n): SlotDropCandidate | null => {\n  const { state: dragState, setCompatibleForKey } = useSlotLinkDragUIState()\n  if (!(target instanceof HTMLElement)) return null\n\n  const elWithKey = target\n    .closest('.lg-slot, .lg-node-widget')\n    ?.querySelector<HTMLElement>('[data-slot-key]')\n  const rawKey = elWithKey?.dataset['slotKey']\n  if (!rawKey) return null\n\n  if (!graph) return null\n  const candidateLayout = getCandidateSlotLayout(graph, rawKey)\n  if (!candidateLayout) return null\n  const { key, layout } = candidateLayout\n\n  const candidate: SlotDropCandidate = { layout, compatible: false }\n\n  if (adapter) {\n    const cached = dragState.compatible.get(key)\n    if (cached != null) {\n      candidate.compatible = cached\n    } else {\n      const nodeId: NodeId = layout.nodeId\n      const compatible =\n        layout.type === 'input'\n          ? adapter.isInputValidDrop(nodeId, layout.index)\n          : adapter.isOutputValidDrop(nodeId, layout.index)\n\n      setCompatibleForKey(key, compatible)\n      candidate.compatible = compatible\n    }\n  }\n\n  return candidate\n}\n\nexport const resolveNodeSurfaceSlotCandidate = (\n  target: EventTarget | null,\n  { adapter, graph, session }: DropResolutionContext\n): SlotDropCandidate | null => {\n  const { setCompatibleForKey } = useSlotLinkDragUIState()\n  if (!(target instanceof HTMLElement)) return null\n\n  const elWithNode = target.closest<HTMLElement>('[data-node-id]')\n  const nodeIdAttr = elWithNode?.dataset['nodeId']\n  if (!nodeIdAttr) return null\n\n  if (!adapter || !graph) return null\n\n  const nodeId: NodeId = toNodeId(nodeIdAttr)\n\n  const cachedPreferredSlotForNode = session.preferredSlotForNode.get(nodeId)\n  if (cachedPreferredSlotForNode !== undefined) {\n    return cachedPreferredSlotForNode\n      ? { layout: cachedPreferredSlotForNode.layout, compatible: true }\n      : null\n  }\n\n  const node = graph.getNodeById(nodeId)\n  if (!node) return null\n\n  const firstLink = adapter.renderLinks.at(0)\n  if (!firstLink) return null\n\n  const connectingTo = adapter.linkConnector.state.connectingTo\n  if (connectingTo !== 'input' && connectingTo !== 'output') return null\n\n  const isInput = connectingTo === 'input'\n  const slotType = firstLink.fromSlot.type\n\n  const result = isInput\n    ? node.findInputByType(slotType)\n    : node.findOutputByType(slotType)\n\n  const index = result?.index\n  if (index == null) {\n    session.preferredSlotForNode.set(nodeId, null)\n    return null\n  }\n\n  const key = getSlotKey(nodeId, index, isInput)\n  const offset = layoutStore.getSlotOffset(\n    graph.rootGraph.id,\n    nodeId,\n    index,\n    isInput ? 'input' : 'output',\n    node.flags.collapsed ? 'collapsed' : 'expanded'\n  )\n  if (!offset) {\n    session.preferredSlotForNode.set(nodeId, null)\n    return null\n  }\n\n  const layout = getGraphSlotLayout(graph, nodeId, index, isInput)\n  if (!layout) {\n    session.preferredSlotForNode.set(nodeId, null)\n    return null\n  }\n\n  const compatible = isInput\n    ? adapter.isInputValidDrop(nodeId, index)\n    : adapter.isOutputValidDrop(nodeId, index)\n\n  setCompatibleForKey(key, compatible)\n\n  if (!compatible) {\n    session.preferredSlotForNode.set(nodeId, null)\n    return null\n  }\n\n  const preferred = { index, key, layout }\n  session.preferredSlotForNode.set(nodeId, preferred)\n\n  return { layout, compatible: true }\n}\n","import type { SlotLayout } from '@/renderer/core/layout/types'\nimport type { NodeId } from '@/types/nodeId'\nimport type { SlotId } from '@/types/slotId'\n\n/**\n * Slot link drag context\n *\n * Non-reactive, per-drag ephemeral caches and RAF batching used during\n * link drag interactions. Keeps high-churn data out of the reactive UI state.\n */\n\ninterface PendingPointerMoveData {\n  clientX: number\n  clientY: number\n  target: EventTarget | null\n}\n\nexport interface SlotLinkDragContext {\n  preferredSlotForNode: Map<\n    NodeId,\n    { index: number; key: SlotId; layout: SlotLayout } | null\n  >\n  lastHoverSlotKey: string | null\n  lastHoverNodeId: NodeId | null\n  lastCandidateKey: string | null\n  pendingPointerMove: PendingPointerMoveData | null\n  lastPointerEventTarget: EventTarget | null\n  lastPointerTargetSlotKey: string | null\n  lastPointerTargetNodeId: NodeId | null\n  reset: () => void\n  dispose: () => void\n}\n\nexport function createSlotLinkDragContext(): SlotLinkDragContext {\n  const state: SlotLinkDragContext = {\n    preferredSlotForNode: new Map(),\n    lastHoverSlotKey: null,\n    lastHoverNodeId: null,\n    lastCandidateKey: null,\n    pendingPointerMove: null,\n    lastPointerEventTarget: null,\n    lastPointerTargetSlotKey: null,\n    lastPointerTargetNodeId: null,\n    reset: () => {\n      state.preferredSlotForNode = new Map()\n      state.lastHoverSlotKey = null\n      state.lastHoverNodeId = null\n      state.lastCandidateKey = null\n      state.pendingPointerMove = null\n      state.lastPointerEventTarget = null\n      state.lastPointerTargetSlotKey = null\n      state.lastPointerTargetNodeId = null\n    },\n    dispose: () => {\n      state.reset()\n    }\n  }\n\n  return state\n}\n","import { tryOnScopeDispose, useEventListener } from '@vueuse/core'\nimport type { Fn } from '@vueuse/core'\n\nimport { useSharedCanvasPositionConversion } from '@/composables/element/useCanvasPositionConversion'\nimport { AutoPanController } from '@/renderer/core/canvas/useAutoPan'\nimport type { LGraph } from '@/lib/litegraph/src/LGraph'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { LLink, slotFloatingLinks } from '@/lib/litegraph/src/LLink'\nimport type { Reroute } from '@/lib/litegraph/src/Reroute'\nimport type { RenderLink } from '@/lib/litegraph/src/canvas/RenderLink'\nimport type {\n  INodeInputSlot,\n  INodeOutputSlot\n} from '@/lib/litegraph/src/types/slots'\nimport { LinkDirection } from '@/lib/litegraph/src/types/globalEnums'\nimport {\n  clearCanvasPointerHistory,\n  toCanvasPointerEvent\n} from '@/renderer/core/canvas/interaction/canvasPointerEvent'\nimport { createLinkConnectorAdapter } from '@/renderer/core/canvas/links/linkConnectorAdapter'\nimport type { LinkConnectorAdapter } from '@/renderer/core/canvas/links/linkConnectorAdapter'\nimport { getGraphSlotLayout } from '@/renderer/core/canvas/litegraph/slotCalculations'\nimport {\n  resolveNodeSurfaceSlotCandidate,\n  resolveSlotTargetCandidate\n} from '@/renderer/core/canvas/links/linkDropOrchestrator'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { isLinkRevealed } from '@/lib/litegraph/src/canvas/linkRevealState'\nimport { useSlotLinkDragUIState } from '@/renderer/core/canvas/links/slotLinkDragUIState'\nimport type { SlotDropCandidate } from '@/renderer/core/canvas/links/slotLinkDragUIState'\nimport { getSlotKey } from '@/renderer/core/layout/slots/slotIdentifier'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { layoutStore } from '@/renderer/core/layout/store/layoutStore'\nimport type { Point } from '@/renderer/core/layout/types'\nimport { toPoint } from '@/renderer/core/layout/utils/geometry'\nimport { createSlotLinkDragContext } from '@/renderer/extensions/vueNodes/composables/slotLinkDragContext'\nimport { augmentToCanvasPointerEvent } from '@/renderer/extensions/vueNodes/utils/eventUtils'\nimport { app } from '@/scripts/app'\nimport { inputLink } from '@/lib/litegraph/src/node/slotLinks'\nimport { useLinkPresentationStore } from '@/stores/linkPresentationStore'\nimport { useLinkStore } from '@/stores/linkStore'\nimport { graphScopeOf } from '@/types/graphScopeId'\nimport { UNASSIGNED_NODE_ID, toNodeId } from '@/types/nodeId'\nimport type { NodeId } from '@/types/nodeId'\nimport { createRafBatch } from '@/utils/rafBatch'\n\ninterface SlotInteractionOptions {\n  nodeId?: NodeId\n  index: number\n  type: 'input' | 'output'\n}\n\ninterface SlotInteractionHandlers {\n  onClick: (event: PointerEvent) => void\n  onDoubleClick: (event: PointerEvent) => void\n  onPointerDown: (event: PointerEvent) => void\n}\n\ninterface PointerSession {\n  begin: (pointerId: number) => void\n  register: (...stops: Array<Fn | null | undefined>) => void\n  matches: (event: PointerEvent) => boolean\n  isActive: () => boolean\n  clear: () => void\n}\n\nfunction createPointerSession(): PointerSession {\n  let pointerId: number | null = null\n  let stops: Fn[] = []\n\n  const begin = (id: number) => {\n    pointerId = id\n  }\n\n  const register = (...newStops: Array<Fn | null | undefined>) => {\n    for (const stop of newStops) {\n      if (typeof stop === 'function') {\n        stops.push(stop)\n      }\n    }\n  }\n\n  const matches = (event: PointerEvent) =>\n    pointerId !== null && event.pointerId === pointerId\n\n  const isActive = () => pointerId !== null\n\n  const clear = () => {\n    for (const stop of stops) {\n      stop()\n    }\n    stops = []\n    pointerId = null\n  }\n\n  return { begin, register, matches, isActive, clear }\n}\n\n/**\n * Resolves the actual DOM element under the pointer position.\n *\n * On touch/mobile devices, pointer events have \"implicit pointer capture\" -\n * event.target stays as the element where the touch started, not the element\n * currently under the pointer. This helper uses document.elementFromPoint()\n * to get the actual element under the pointer, falling back to the provided\n * fallback target if elementFromPoint returns null.\n *\n * @param clientX - The client X coordinate of the pointer\n * @param clientY - The client Y coordinate of the pointer\n * @param fallback - Fallback target to use if elementFromPoint returns null\n * @returns The resolved target element\n */\nexport function resolvePointerTarget(\n  clientX: number,\n  clientY: number,\n  fallback: EventTarget | null\n): EventTarget | null {\n  return document.elementFromPoint(clientX, clientY) ?? fallback\n}\n\nexport function isRerouteVisibleForLinkDrag(\n  graph: Pick<LGraph, 'getLink' | 'id' | 'rootGraph'>,\n  reroute: Pick<Reroute, 'linkIds' | 'floatingLinkIds'>\n): boolean {\n  if (reroute.linkIds.size === 0 || reroute.floatingLinkIds.size > 0)\n    return true\n\n  const scope = graphScopeOf(graph)\n  for (const linkId of reroute.linkIds) {\n    const link = graph.getLink(linkId)\n    const hidden =\n      link && useLinkPresentationStore().getPresentation(scope, linkId)?.hidden\n    if (!hidden || isLinkRevealed(scope.rootGraphId, linkId)) {\n      return true\n    }\n  }\n  return false\n}\n\nexport function useSlotLinkInteraction({\n  nodeId,\n  index,\n  type\n}: SlotInteractionOptions): SlotInteractionHandlers {\n  const {\n    state,\n    beginDrag,\n    endDrag,\n    updatePointerPosition,\n    setCandidate,\n    setCompatibleForKey,\n    clearCompatible\n  } = useSlotLinkDragUIState()\n  const canvasStore = useCanvasStore()\n  const conversion = useSharedCanvasPositionConversion()\n  const pointerSession = createPointerSession()\n  let activeAdapter: LinkConnectorAdapter | null = null\n  let autoPan: AutoPanController | null = null\n\n  // Per-drag drag-state context (non-reactive caches + RAF batching)\n  const dragContext = createSlotLinkDragContext()\n\n  const resolveRenderLinkSource = (link: RenderLink): Point | null => {\n    if (link.fromReroute) {\n      const graphId = app.canvas.graph?.rootGraph.id\n      const rerouteLayout = graphId\n        ? layoutStore.getRerouteLayout(graphId, link.fromReroute.id)\n        : null\n      if (rerouteLayout) return rerouteLayout.position\n      const [x, y] = link.fromReroute.pos\n      return toPoint(x, y)\n    }\n\n    const nodeId = link.node.id\n    const isInputFrom = link.toType === 'output'\n    const graph = app.canvas.graph\n    const layout = graph\n      ? getGraphSlotLayout(graph, nodeId, link.fromSlotIndex, isInputFrom)\n      : null\n    if (layout) return layout.position\n\n    const pos = link.fromPos\n    return toPoint(pos[0], pos[1])\n  }\n\n  const syncRenderLinkOrigins = () => {\n    if (!activeAdapter) return\n    for (const link of activeAdapter.renderLinks) {\n      const origin = resolveRenderLinkSource(link)\n      if (!origin) continue\n      const x = origin.x\n      const y = origin.y\n      if (link.fromPos[0] !== x || link.fromPos[1] !== y) {\n        link.fromPos[0] = x\n        link.fromPos[1] = y\n      }\n    }\n  }\n\n  function hasCanConnectToReroute(\n    link: RenderLink\n  ): link is RenderLink & { canConnectToReroute: (r: Reroute) => boolean } {\n    return 'canConnectToReroute' in link\n  }\n\n  type ToInputLink = RenderLink & { toType: 'input' }\n  type ToOutputLink = RenderLink & { toType: 'output' }\n  const isToInputLink = (link: RenderLink): link is ToInputLink =>\n    link.toType === 'input'\n  const isToOutputLink = (link: RenderLink): link is ToOutputLink =>\n    link.toType === 'output'\n\n  function connectLinksToInput(\n    links: ReadonlyArray<RenderLink>,\n    node: LGraphNode,\n    inputSlot: INodeInputSlot\n  ): boolean {\n    const validCandidates = links\n      .filter(isToInputLink)\n      .filter((link) => link.canConnectToInput(node, inputSlot))\n\n    for (const link of validCandidates) {\n      link.connectToInput(node, inputSlot, activeAdapter?.linkConnector.events)\n    }\n\n    return validCandidates.length > 0\n  }\n\n  function connectLinksToOutput(\n    links: ReadonlyArray<RenderLink>,\n    node: LGraphNode,\n    outputSlot: INodeOutputSlot\n  ): boolean {\n    const validCandidates = links\n      .filter(isToOutputLink)\n      .filter((link) => link.canConnectToOutput(node, outputSlot))\n\n    for (const link of validCandidates) {\n      link.connectToOutput(\n        node,\n        outputSlot,\n        activeAdapter?.linkConnector.events\n      )\n    }\n\n    return validCandidates.length > 0\n  }\n\n  const resolveLinkOrigin = (\n    link: LLink | undefined\n  ): { position: Point; direction: LinkDirection } | null => {\n    if (!link) return null\n    if (link.origin_id === UNASSIGNED_NODE_ID) return null\n\n    const graph = app.canvas.graph\n    const layout = graph\n      ? getGraphSlotLayout(graph, link.origin_id, link.origin_slot, false)\n      : null\n    if (!layout) return null\n\n    return { position: { ...layout.position }, direction: LinkDirection.NONE }\n  }\n\n  const resolveExistingInputLinkAnchor = (\n    graph: LGraph,\n    nodeId: NodeId,\n    slotIndex: number,\n    inputSlot: INodeInputSlot | undefined\n  ): { position: Point; direction: LinkDirection } | null => {\n    if (!inputSlot) return null\n\n    const directLink = inputLink(graph, nodeId, slotIndex)\n    if (directLink) {\n      const reroutes = LLink.getReroutes(graph, directLink)\n      const lastReroute = reroutes.at(-1)\n      if (lastReroute) {\n        const rerouteLayout = layoutStore.getRerouteLayout(\n          graph.rootGraph.id,\n          lastReroute.id\n        )\n        if (rerouteLayout) {\n          return {\n            position: { ...rerouteLayout.position },\n            direction: LinkDirection.NONE\n          }\n        }\n\n        const pos = lastReroute.pos\n        return {\n          position: toPoint(pos[0], pos[1]),\n          direction: LinkDirection.NONE\n        }\n      }\n\n      const directAnchor = resolveLinkOrigin(directLink)\n      if (directAnchor) return directAnchor\n    }\n\n    const floatingLink = slotFloatingLinks(\n      graph,\n      'input',\n      nodeId,\n      slotIndex\n    ).at(0)\n    if (!floatingLink) return null\n\n    if (floatingLink.parentId != null) {\n      const rerouteLayout = layoutStore.getRerouteLayout(\n        graph.rootGraph.id,\n        floatingLink.parentId\n      )\n      if (rerouteLayout) {\n        return {\n          position: { ...rerouteLayout.position },\n          direction: LinkDirection.NONE\n        }\n      }\n\n      const reroute = graph.getReroute(floatingLink.parentId)\n      if (reroute) {\n        return {\n          position: toPoint(reroute.pos[0], reroute.pos[1]),\n          direction: LinkDirection.NONE\n        }\n      }\n    }\n\n    return null\n  }\n\n  const cleanupInteraction = () => {\n    autoPan?.stop()\n    autoPan = null\n    if (state.pointerId != null) {\n      clearCanvasPointerHistory(state.pointerId)\n    }\n    activeAdapter?.reset()\n    pointerSession.clear()\n    endDrag()\n    activeAdapter = null\n    raf.cancel()\n    dragContext.dispose()\n    clearCompatible()\n  }\n\n  const updatePointerState = (event: PointerEvent) => {\n    const clientX = event.clientX\n    const clientY = event.clientY\n    const [canvasX, canvasY] = conversion.clientPosToCanvasPos([\n      clientX,\n      clientY\n    ])\n\n    updatePointerPosition(clientX, clientY, canvasX, canvasY)\n  }\n\n  const processPointerMoveFrame = () => {\n    const data = dragContext.pendingPointerMove\n    if (!data) return\n    dragContext.pendingPointerMove = null\n\n    const [canvasX, canvasY] = conversion.clientPosToCanvasPos([\n      data.clientX,\n      data.clientY\n    ])\n    updatePointerPosition(data.clientX, data.clientY, canvasX, canvasY)\n\n    syncRenderLinkOrigins()\n\n    let hoveredSlotKey: string | null = null\n    let hoveredNodeId: NodeId | null = null\n    const target = resolvePointerTarget(data.clientX, data.clientY, data.target)\n    if (target === dragContext.lastPointerEventTarget) {\n      hoveredSlotKey = dragContext.lastPointerTargetSlotKey\n      hoveredNodeId = dragContext.lastPointerTargetNodeId\n    } else if (target instanceof HTMLElement) {\n      const elWithSlot = target\n        .closest('.lg-slot, .lg-node-widget')\n        ?.querySelector<HTMLElement>('[data-slot-key]')\n      const elWithNode = target.closest<HTMLElement>('[data-node-id]')\n      hoveredSlotKey = elWithSlot?.dataset['slotKey'] ?? null\n      hoveredNodeId = elWithNode?.dataset['nodeId']\n        ? toNodeId(elWithNode.dataset['nodeId'])\n        : null\n      dragContext.lastPointerEventTarget = target\n      dragContext.lastPointerTargetSlotKey = hoveredSlotKey\n      dragContext.lastPointerTargetNodeId = hoveredNodeId\n    }\n\n    const hoverChanged =\n      hoveredSlotKey !== dragContext.lastHoverSlotKey ||\n      hoveredNodeId !== dragContext.lastHoverNodeId\n\n    let candidate: SlotDropCandidate | null = state.candidate\n\n    if (hoverChanged) {\n      const adapter = activeAdapter\n      const graph = app.canvas.graph ?? null\n      const context = { adapter, graph, session: dragContext }\n      const slotCandidate = resolveSlotTargetCandidate(target, context)\n      const nodeCandidate = resolveNodeSurfaceSlotCandidate(target, context)\n      candidate = slotCandidate?.compatible ? slotCandidate : nodeCandidate\n      dragContext.lastHoverSlotKey = hoveredSlotKey\n      dragContext.lastHoverNodeId = hoveredNodeId\n\n      if (slotCandidate) {\n        const key = getSlotKey(\n          slotCandidate.layout.nodeId,\n          slotCandidate.layout.index,\n          slotCandidate.layout.type === 'input'\n        )\n        setCompatibleForKey(key, slotCandidate.compatible)\n      }\n      if (nodeCandidate && !slotCandidate?.compatible) {\n        const key = getSlotKey(\n          nodeCandidate.layout.nodeId,\n          nodeCandidate.layout.index,\n          nodeCandidate.layout.type === 'input'\n        )\n        setCompatibleForKey(key, nodeCandidate.compatible)\n      }\n    }\n\n    const newCandidate = candidate?.compatible ? candidate : null\n    const newCandidateKey = newCandidate\n      ? getSlotKey(\n          newCandidate.layout.nodeId,\n          newCandidate.layout.index,\n          newCandidate.layout.type === 'input'\n        )\n      : null\n\n    const candidateChanged = newCandidateKey !== dragContext.lastCandidateKey\n    if (candidateChanged) {\n      setCandidate(newCandidate)\n      dragContext.lastCandidateKey = newCandidateKey\n    }\n\n    let snapPosChanged = false\n    if (activeAdapter) {\n      const snapX = newCandidate\n        ? newCandidate.layout.position.x\n        : state.pointer.canvas.x\n      const snapY = newCandidate\n        ? newCandidate.layout.position.y\n        : state.pointer.canvas.y\n      const currentSnap = activeAdapter.linkConnector.state.snapLinksPos\n      snapPosChanged =\n        !currentSnap || currentSnap[0] !== snapX || currentSnap[1] !== snapY\n      if (snapPosChanged) {\n        activeAdapter.linkConnector.state.snapLinksPos = [snapX, snapY]\n      }\n    }\n\n    const shouldRedraw = candidateChanged || snapPosChanged\n    if (shouldRedraw) app.canvas.setDirty(true, true)\n  }\n  const raf = createRafBatch(processPointerMoveFrame)\n\n  const canvas = app.canvas\n  const node = nodeId ? canvas.graph?.getNodeById(nodeId) : null\n  const handlePointerMove = (event: PointerEvent) => {\n    if (!pointerSession.matches(event) || canvasStore.isReadOnly) return\n\n    event.stopPropagation()\n\n    app.canvas.last_mouse = [event.clientX, event.clientY]\n    autoPan?.updatePointer(event.clientX, event.clientY)\n\n    if (canvas.subgraph && node) {\n      augmentToCanvasPointerEvent(event, node, canvas)\n      canvas.subgraph.inputNode.onPointerMove(event)\n      canvas.subgraph.outputNode.onPointerMove(event)\n    }\n\n    dragContext.pendingPointerMove = {\n      clientX: event.clientX,\n      clientY: event.clientY,\n      target: event.target\n    }\n    raf.schedule()\n  }\n\n  // Attempt to finalize by connecting to a DOM slot candidate\n  const tryConnectToCandidate = (\n    candidate: SlotDropCandidate | null\n  ): boolean => {\n    if (!candidate?.compatible) return false\n    const graph = app.canvas.graph\n    const adapter = activeAdapter\n    if (!graph || !adapter) return false\n\n    const nodeId: NodeId = candidate.layout.nodeId\n    const targetNode = graph.getNodeById(nodeId)\n    if (!targetNode) return false\n\n    if (candidate.layout.type === 'input') {\n      const inputSlot = targetNode.inputs.at(candidate.layout.index)\n      return (\n        !!inputSlot &&\n        connectLinksToInput(adapter.renderLinks, targetNode, inputSlot)\n      )\n    }\n\n    const outputSlot = targetNode.outputs.at(candidate.layout.index)\n    return (\n      !!outputSlot &&\n      connectLinksToOutput(adapter.renderLinks, targetNode, outputSlot)\n    )\n  }\n\n  // Attempt to finalize by dropping on a reroute under the pointer\n  const tryConnectViaRerouteAtPointer = (): boolean => {\n    const graph = app.canvas.graph\n    const adapter = activeAdapter\n    if (!graph || !adapter) return false\n\n    const rerouteLayout = layoutStore.queryRerouteAtPoint(graph.rootGraph.id, {\n      x: state.pointer.canvas.x,\n      y: state.pointer.canvas.y\n    })\n    if (!rerouteLayout) return false\n\n    const reroute = graph.getReroute(rerouteLayout.id)\n    if (\n      !reroute ||\n      !isRerouteVisibleForLinkDrag(graph, reroute) ||\n      !adapter.isRerouteValidDrop(reroute.id)\n    ) {\n      return false\n    }\n\n    let didConnect = false\n\n    const results = reroute.findTargetInputs() ?? []\n    const maybeReroutes = reroute.getReroutes()\n    if (results.length && maybeReroutes !== null) {\n      const originalReroutes = maybeReroutes.slice(0, -1).reverse()\n      for (const link of adapter.renderLinks) {\n        if (!isToInputLink(link)) continue\n        for (const result of results) {\n          link.connectToRerouteInput(\n            reroute,\n            result,\n            adapter.linkConnector.events,\n            originalReroutes\n          )\n          didConnect = true\n        }\n      }\n    }\n\n    const sourceOutput = reroute.findSourceOutput()\n    if (sourceOutput) {\n      const { node, output } = sourceOutput\n      for (const link of adapter.renderLinks) {\n        if (!isToOutputLink(link)) continue\n        if (hasCanConnectToReroute(link) && !link.canConnectToReroute(reroute))\n          continue\n        link.connectToRerouteOutput(\n          reroute,\n          node,\n          output,\n          adapter.linkConnector.events\n        )\n        didConnect = true\n      }\n    }\n\n    return didConnect\n  }\n\n  const finishInteraction = (event: PointerEvent) => {\n    if (!pointerSession.matches(event)) return\n    const canvasEvent = toCanvasPointerEvent(event)\n    canvasEvent.preventDefault()\n\n    raf.flush()\n\n    if (!state.source) {\n      cleanupInteraction()\n      app.canvas.setDirty(true, true)\n      return\n    }\n\n    const snappedCandidate = state.candidate?.compatible\n      ? state.candidate\n      : null\n\n    const dropTarget = resolvePointerTarget(\n      event.clientX,\n      event.clientY,\n      canvasEvent.target\n    )\n    const hasConnected = connectByPriority(dropTarget, snappedCandidate)\n\n    if (!hasConnected && dropTarget === app.canvas.canvas) {\n      activeAdapter?.dropOnCanvas(canvasEvent)\n    }\n\n    cleanupInteraction()\n    app.canvas.setDirty(true, true)\n    useWorkflowStore().activeWorkflow?.changeTracker.captureCanvasState()\n  }\n\n  const handlePointerUp = (event: PointerEvent) => {\n    event.stopPropagation()\n    finishInteraction(event)\n  }\n\n  const handlePointerCancel = (event: PointerEvent) => {\n    if (!pointerSession.matches(event)) return\n\n    raf.flush()\n    toCanvasPointerEvent(event)\n    cleanupInteraction()\n    app.canvas.setDirty(true, true)\n  }\n\n  function connectByPriority(\n    target: EventTarget | null,\n    snappedCandidate: SlotDropCandidate | null\n  ): boolean {\n    const adapter = activeAdapter\n    const graph = app.canvas.graph ?? null\n    const context = { adapter, graph, session: dragContext }\n\n    const domSlotCandidate = resolveSlotTargetCandidate(target, context)\n    const nodeSurfaceSlotCandidate = resolveNodeSurfaceSlotCandidate(\n      target,\n      context\n    )\n\n    return (\n      tryConnectToCandidate(snappedCandidate) ||\n      tryConnectToCandidate(domSlotCandidate) ||\n      tryConnectToCandidate(nodeSurfaceSlotCandidate) ||\n      tryConnectViaRerouteAtPointer()\n    )\n  }\n\n  const onPointerDown = (event: PointerEvent) => {\n    if (event.button !== 0) return\n    if (!nodeId) return\n    if (pointerSession.isActive()) return\n    event.preventDefault()\n    event.stopPropagation()\n\n    const canvas = app.canvas\n    const graph = canvas.graph\n    if (!graph) return\n\n    activeAdapter = createLinkConnectorAdapter()\n    if (!activeAdapter) return\n    raf.cancel()\n    dragContext.reset()\n\n    const layout = getGraphSlotLayout(graph, nodeId, index, type === 'input')\n    if (!layout) return\n\n    const localNodeId: NodeId = nodeId\n    const isInputSlot = type === 'input'\n    const isOutputSlot = type === 'output'\n\n    const resolvedNode = graph.getNodeById(localNodeId)\n    const inputSlot = isInputSlot ? resolvedNode?.inputs[index] : undefined\n    const outputSlot = isOutputSlot ? resolvedNode?.outputs[index] : undefined\n\n    const ctrlOrMeta = event.ctrlKey || event.metaKey\n\n    const existingInputLink = isInputSlot\n      ? inputLink(graph, localNodeId, index)\n      : undefined\n    const inputFloatingCount = isInputSlot\n      ? slotFloatingLinks(graph, 'input', localNodeId, index).length\n      : 0\n    const hasExistingInputLink =\n      existingInputLink !== undefined || inputFloatingCount > 0\n\n    const hasExistingOutputLink =\n      isOutputSlot &&\n      (useLinkStore().isOutputSlotConnected(\n        graphScopeOf(graph),\n        localNodeId,\n        index\n      ) ||\n        slotFloatingLinks(graph, 'output', localNodeId, index).length > 0)\n\n    const shouldBreakExistingInputLink =\n      isInputSlot &&\n      hasExistingInputLink &&\n      ctrlOrMeta &&\n      event.altKey &&\n      !event.shiftKey\n\n    const shouldBatchDisconnectOutputLinks =\n      isOutputSlot &&\n      hasExistingOutputLink &&\n      ctrlOrMeta &&\n      event.altKey &&\n      !event.shiftKey\n\n    if (shouldBreakExistingInputLink && resolvedNode) {\n      resolvedNode.disconnectInput(index, true)\n    }\n\n    if (shouldBatchDisconnectOutputLinks && resolvedNode) {\n      resolvedNode.disconnectOutput(index)\n      canvas.setDirty(true, true)\n      event.preventDefault()\n      event.stopPropagation()\n      return\n    }\n\n    const baseDirection = isInputSlot\n      ? (inputSlot?.dir ?? LinkDirection.LEFT)\n      : (outputSlot?.dir ?? LinkDirection.RIGHT)\n\n    const existingAnchor =\n      isInputSlot && !shouldBreakExistingInputLink\n        ? resolveExistingInputLinkAnchor(graph, localNodeId, index, inputSlot)\n        : null\n\n    const shouldMoveExistingOutput =\n      isOutputSlot && event.shiftKey && hasExistingOutputLink\n\n    const shouldMoveExistingInput =\n      isInputSlot && !shouldBreakExistingInputLink && hasExistingInputLink\n\n    if (isOutputSlot) {\n      activeAdapter.beginFromOutput(localNodeId, index, {\n        moveExisting: shouldMoveExistingOutput\n      })\n    } else {\n      activeAdapter.beginFromInput(localNodeId, index, {\n        moveExisting: shouldMoveExistingInput,\n        layout\n      })\n    }\n\n    if (shouldMoveExistingInput && existingInputLink) {\n      existingInputLink._dragging = true\n    }\n\n    syncRenderLinkOrigins()\n\n    const direction = existingAnchor?.direction ?? baseDirection\n    const startPosition = existingAnchor?.position ?? {\n      x: layout.position.x,\n      y: layout.position.y\n    }\n\n    beginDrag(\n      {\n        nodeId,\n        slotIndex: index,\n        type,\n        direction,\n        position: startPosition,\n        linkId: !shouldBreakExistingInputLink\n          ? existingInputLink?.id\n          : undefined,\n        movingExistingOutput: shouldMoveExistingOutput\n      },\n      event.pointerId\n    )\n\n    pointerSession.begin(event.pointerId)\n\n    toCanvasPointerEvent(event)\n    updatePointerState(event)\n\n    activeAdapter.linkConnector.state.snapLinksPos = [\n      state.pointer.canvas.x,\n      state.pointer.canvas.y\n    ]\n\n    pointerSession.register(\n      useEventListener('pointermove', handlePointerMove, {\n        capture: true\n      }),\n      useEventListener('pointerup', handlePointerUp, {\n        capture: true\n      }),\n      useEventListener('pointercancel', handlePointerCancel, {\n        capture: true\n      })\n    )\n    const targetType: 'input' | 'output' = type === 'input' ? 'output' : 'input'\n    clearCompatible()\n    for (const candidateNode of graph.nodes) {\n      const slots =\n        targetType === 'input' ? candidateNode.inputs : candidateNode.outputs\n      for (const [slotIndex] of slots.entries()) {\n        const key = getSlotKey(\n          candidateNode.id,\n          slotIndex,\n          targetType === 'input'\n        )\n        const compatible =\n          targetType === 'input'\n            ? activeAdapter.isInputValidDrop(candidateNode.id, slotIndex)\n            : activeAdapter.isOutputValidDrop(candidateNode.id, slotIndex)\n        setCompatibleForKey(key, compatible)\n      }\n    }\n    autoPan = new AutoPanController({\n      canvas: canvas.canvas,\n      ds: canvas.ds,\n      maxPanSpeed: canvas.auto_pan_speed,\n      onPan: () => {\n        const [canvasX, canvasY] = conversion.clientPosToCanvasPos([\n          state.pointer.client.x,\n          state.pointer.client.y\n        ])\n        updatePointerPosition(\n          state.pointer.client.x,\n          state.pointer.client.y,\n          canvasX,\n          canvasY\n        )\n        if (activeAdapter) {\n          activeAdapter.linkConnector.state.snapLinksPos = [canvasX, canvasY]\n        }\n        canvas.setDirty(true, true)\n      }\n    })\n    autoPan.updatePointer(event.clientX, event.clientY)\n    autoPan.start()\n\n    canvas.setDirty(true, true)\n  }\n\n  tryOnScopeDispose(() => {\n    if (pointerSession.isActive()) {\n      cleanupInteraction()\n    }\n  })\n\n  function onDoubleClick(e: PointerEvent) {\n    if (!nodeId) return\n    const { graph } = app.canvas\n    if (!graph) return\n    const node = graph.getNodeById(nodeId)\n    if (!node) return\n    augmentToCanvasPointerEvent(e, node, app.canvas)\n    node.onInputDblClick?.(index, e)\n  }\n  function onClick(e: PointerEvent) {\n    if (!nodeId) return\n    const { graph } = app.canvas\n    if (!graph) return\n    const node = graph.getNodeById(nodeId)\n    if (!node) return\n    augmentToCanvasPointerEvent(e, node, app.canvas)\n    node.onInputClick?.(index, e)\n  }\n\n  return {\n    onClick,\n    onDoubleClick,\n    onPointerDown\n  }\n}\n","import { onScopeDispose } from 'vue'\n\nimport {\n  clearRevealedLinks,\n  setRevealedLinks\n} from '@/lib/litegraph/src/canvas/linkRevealState'\nimport { app } from '@/scripts/app'\nimport { useLinkPresentationStore } from '@/stores/linkPresentationStore'\nimport { useLinkStore } from '@/stores/linkStore'\nimport { graphScopeOf } from '@/types/graphScopeId'\nimport type { NodeId } from '@/types/nodeId'\n\ninterface SlotLinkRevealOptions {\n  nodeId?: NodeId\n  index: number\n  type: 'input' | 'output'\n}\n\nexport function useSlotLinkReveal(options: SlotLinkRevealOptions) {\n  const owner = {}\n\n  function revealLinks(): void {\n    const graph = app.canvas.graph\n    if (!graph || options.nodeId === undefined) return\n\n    const scope = graphScopeOf(graph)\n    const linkStore = useLinkStore()\n    const presentationStore = useLinkPresentationStore()\n    const links =\n      options.type === 'output'\n        ? [\n            ...linkStore.getOutputSlotLinks(\n              scope,\n              options.nodeId,\n              options.index\n            )\n          ]\n        : [linkStore.getInputSlotLink(scope, options.nodeId, options.index)]\n    const linkIds = links.flatMap((link) =>\n      link && presentationStore.getPresentation(scope, link.id)?.hidden\n        ? [link.id]\n        : []\n    )\n    if (setRevealedLinks(scope.rootGraphId, linkIds, owner)) {\n      app.canvas.setDirty(false, true)\n    }\n  }\n\n  function unrevealLinks(): void {\n    if (clearRevealedLinks(owner)) app.canvas.setDirty(false, true)\n  }\n\n  onScopeDispose(unrevealLinks)\n\n  return { revealLinks, unrevealLinks }\n}\n","<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport { getSlotColor, MAX_MULTITYPE_SLICES } from '@/constants/slotColors'\nimport type { INodeSlot } from '@/lib/litegraph/src/litegraph'\nimport { RenderShape } from '@/lib/litegraph/src/types/globalEnums'\nimport type { SlotId } from '@/types/slotId'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport type { ClassValue } from '@comfyorg/tailwind-utils'\n\nconst props = defineProps<{\n  slotData?: INodeSlot\n  class?: ClassValue\n  hasError?: boolean\n  multi?: boolean\n  slotKey?: SlotId\n}>()\n\nconst clipPath = computed(() => {\n  switch (props.slotData?.shape) {\n    case 6:\n      return 'url(#square)'\n    case 7:\n      return 'url(#hollow)'\n    default:\n      return undefined\n  }\n})\n\nconst types = computed(() => {\n  if (props.hasError) return ['var(--color-error)']\n  //TODO Support connected/disconnected colors?\n  if (!props.slotData) return [getSlotColor()]\n  if (props.slotData.type === '*') return ['']\n  return `${props.slotData.type}`\n    .split(',')\n    .map(getSlotColor)\n    .slice(0, MAX_MULTITYPE_SLICES)\n})\n\nconst isListShape = computed(() => props.slotData?.shape === RenderShape.GRID)\n\nconst slotClass = computed(() =>\n  cn(\n    'slot-dot bg-ink-100',\n    isListShape.value ? 'rounded-[1px]' : 'rounded-full',\n    'transition-all duration-150',\n    'border border-solid border-node-component-slot-dot-outline',\n    props.multi\n      ? 'h-5 w-2'\n      : 'size-2 cursor-crosshair group-hover/slot:scale-125 group-hover/slot:[--node-component-slot-dot-outline-opacity-mult:5]'\n  )\n)\n</script>\n\n<template>\n  <div\n    data-testid=\"slot-connection-dot\"\n    :class=\"\n      cn(\n        'group/slot relative flex size-6 items-center justify-center after:absolute after:inset-y-0 after:w-5/2',\n        props.class\n      )\n    \"\n  >\n    <div\n      v-if=\"types.length === 1 && (slotData?.shape == undefined || isListShape)\"\n      :data-slot-key=\"slotKey\"\n      :style=\"{ backgroundColor: types.length === 1 ? types[0] : undefined }\"\n      :class=\"slotClass\"\n      data-testid=\"slot-dot\"\n    />\n    <svg\n      v-else\n      :data-slot-key=\"slotKey\"\n      :class=\"slotClass\"\n      data-testid=\"slot-dot\"\n      viewBox=\"0 0 100 100\"\n      xmlns=\"http://www.w3.org/2000/svg\"\n    >\n      <defs>\n        <clipPath id=\"square\">\n          <rect x=\"20\" y=\"20\" width=\"60\" height=\"60\" />\n        </clipPath>\n        <clipPath id=\"hollow\">\n          <path\n            d=\"M-50 50\n           A100 100 0 0 1 150 50\n           A100 100 0 0 1 -50 50\n           M30 50\n           A20 20 0 0 0 70 50\n           A20 20 0 0 0 30 50\"\n          />\n        </clipPath>\n      </defs>\n      <circle\n        v-if=\"types.length === 1\"\n        :clip-path\n        cx=\"50\"\n        cy=\"50\"\n        r=\"50\"\n        :fill=\"types[0]\"\n      />\n      <g v-else-if=\"types.length === 2\" :clip-path stroke-width=\"4\">\n        <path d=\"M0 50 A 50 50 0 0 1 100 50\" :fill=\"types[0]\" />\n        <path d=\"M100 50 A 50 50 0 0 1 0 50\" :fill=\"types[1]\" />\n        <path d=\"M0 50L100 50\" stroke=\"var(--inner-stroke, black)\" />\n        <path\n          d=\"M50 2A48 48 0 0 1 50 98A48 48 0 0 1 50 2\"\n          fill=\"transparent\"\n          stroke=\"var(--outer-stroke, transparent)\"\n        />\n      </g>\n      <g v-else :clip-path stroke-width=\"4\">\n        <path d=\"M0 50A50 50 0 0 0 75 93L50 50\" :fill=\"types[0]\" />\n        <path d=\"M75 93A50 50 0 0 0 75 7L50 50\" :fill=\"types[1]\" />\n        <path d=\"M75 7A50 50 0 0 0 0 50L50 50\" :fill=\"types[2]\" />\n        <path\n          d=\"M50 50L0 50M50 50L75 93M50 50L75 7\"\n          stroke=\"var(--inner-stroke, black)\"\n        />\n        <path\n          d=\"M50 2A48 48 0 0 1 50 98A48 48 0 0 1 50 2\"\n          fill=\"transparent\"\n          stroke=\"var(--outer-stroke, transparent)\"\n        />\n      </g>\n    </svg>\n  </div>\n</template>\n","<template>\n  <div v-if=\"renderError\" class=\"node-error p-1 text-xs text-red-500\">⚠️</div>\n  <Tooltip v-else :disabled=\"!tooltipText\">\n    <TooltipTrigger as-child>\n      <div\n        :aria-label=\"standalone ? accessibleName : undefined\"\n        :class=\"\n          cn(\n            'lg-slot lg-slot--input group m-0 flex items-center rounded-r-lg',\n            'cursor-crosshair',\n            dotOnly ? 'lg-slot--dot-only' : 'h-5 pr-2',\n            {\n              'lg-slot--connected': props.connected,\n              'lg-slot--compatible': props.compatible,\n              'opacity-40': shouldDim\n            },\n            props.socketless && 'pointer-events-none invisible'\n          )\n        \"\n        @pointerenter=\"revealLinks\"\n        @pointerleave=\"unrevealLinks\"\n      >\n        <!-- Connection Dot -->\n        <SlotConnectionDot\n          :slot-key\n          :class=\"\n            cn(\n              'w-3 -translate-x-1/2',\n              hasError &&\n                'before:pointer-events-none before:absolute before:size-4 before:rounded-full before:ring-2 before:ring-error before:ring-offset-0'\n            )\n          \"\n          :slot-data\n          @click=\"onClick\"\n          @dblclick=\"onDoubleClick\"\n          @pointerdown=\"onPointerDown\"\n        />\n\n        <!-- Slot Name -->\n        <div class=\"flex h-full min-w-0 items-center\">\n          <EditableText\n            v-if=\"!props.dotOnly && !hasNoLabel\"\n            class=\"min-w-0\"\n            :label-class=\"\n              cn(\n                'block truncate text-node-component-slot-text',\n                hasError && 'font-medium text-error'\n              )\n            \"\n            :is-editing\n            :model-value=\"\n              slotData.label ||\n              slotData.localized_name ||\n              (slotData.name ?? `Input ${index}`)\n            \"\n            @cancel=\"isEditing = false\"\n            @dblclick=\"isEditing = true\"\n            @edit=\"onEditLabel\"\n          />\n        </div>\n      </div>\n    </TooltipTrigger>\n    <TooltipContent side=\"left\">{{ tooltipText }}</TooltipContent>\n  </Tooltip>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, onErrorCaptured, ref } from 'vue'\n\nimport EditableText from '@/components/common/EditableText.vue'\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport type { INodeSlot } from '@/lib/litegraph/src/litegraph'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useSlotLinkDragUIState } from '@/renderer/core/canvas/links/slotLinkDragUIState'\nimport { getSlotKey } from '@/renderer/core/layout/slots/slotIdentifier'\nimport { useNodeTooltips } from '@/renderer/extensions/vueNodes/composables/useNodeTooltips'\nimport { useSlotLinkInteraction } from '@/renderer/extensions/vueNodes/composables/useSlotLinkInteraction'\nimport { useSlotLinkReveal } from '@/renderer/extensions/vueNodes/composables/useSlotLinkReveal'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport type { NodeId } from '@/types/nodeId'\n\nimport SlotConnectionDot from './SlotConnectionDot.vue'\n\ninterface InputSlotProps {\n  slotData: INodeSlot\n  compatible?: boolean\n  connected?: boolean\n  dotOnly?: boolean\n  hasError?: boolean\n  index: number\n  nodeType?: string\n  nodeId?: NodeId\n  socketless?: boolean\n  /** The slot is the input's only rendered representation, so the dot carries the accessible name. */\n  standalone?: boolean\n}\n\nconst props = defineProps<InputSlotProps>()\n\nconst hasNoLabel = computed(\n  () =>\n    !props.slotData.label &&\n    !props.slotData.localized_name &&\n    props.slotData.name === ''\n)\nconst dotOnly = computed(() => props.dotOnly || hasNoLabel.value)\nconst accessibleName = computed(\n  () =>\n    props.slotData.label ||\n    props.slotData.localized_name ||\n    props.slotData.name ||\n    undefined\n)\nconst renderError = ref<string | null>(null)\nconst { toastErrorHandler } = useErrorHandling()\n\nconst { getInputSlotTooltip } = useNodeTooltips(props.nodeType || '')\nconst tooltipText = computed(() => getInputSlotTooltip(props.slotData))\n\nconst { revealLinks, unrevealLinks } = useSlotLinkReveal({\n  nodeId: props.nodeId,\n  index: props.index,\n  type: 'input'\n})\n\nonErrorCaptured((error) => {\n  unrevealLinks()\n  renderError.value = error.message\n  toastErrorHandler(error)\n  return false\n})\n\nconst { state: dragState } = useSlotLinkDragUIState()\nconst slotKey = computed(() =>\n  props.nodeId ? getSlotKey(props.nodeId, props.index, true) : undefined\n)\nconst shouldDim = computed(() => {\n  if (!dragState.active) return false\n  if (!slotKey.value) return false\n  return !dragState.compatible.get(slotKey.value)\n})\n\nconst { onClick, onDoubleClick, onPointerDown } = useSlotLinkInteraction({\n  nodeId: props.nodeId,\n  index: props.index,\n  type: 'input'\n})\n\nconst isEditing = ref(false)\nfunction onEditLabel(val: string) {\n  const canvas = useCanvasStore().getCanvas()\n  isEditing.value = false\n  if (!props.nodeId) return\n\n  const newLabel = val.trim() || undefined\n  const slot = canvas.graph?.getNodeById(props.nodeId)?.inputs?.[props.index]\n  if (!slot || slot.label === newLabel) return\n\n  slot.label = newLabel\n  canvas.setDirty(true, true)\n}\n</script>\n","<template>\n  <div v-if=\"renderError\" class=\"node-error p-1 text-xs text-red-500\">⚠️</div>\n  <Tooltip v-else :disabled=\"!tooltipText\">\n    <TooltipTrigger as-child>\n      <div\n        :class=\"slotWrapperClass\"\n        @pointerenter=\"revealLinks\"\n        @pointerleave=\"unrevealLinks\"\n      >\n        <div class=\"relative flex h-full min-w-0 items-center\">\n          <!-- Slot Name -->\n          <span\n            v-if=\"!props.dotOnly && !hasNoLabel\"\n            class=\"truncate text-node-component-slot-text\"\n          >\n            {{\n              slotData.label ||\n              slotData.localized_name ||\n              (slotData.name ?? `Output ${index}`)\n            }}\n          </span>\n        </div>\n        <!-- Connection Dot -->\n        <SlotConnectionDot\n          :slot-key\n          class=\"w-3 translate-x-1/2\"\n          :slot-data\n          @pointerdown=\"onPointerDown\"\n        />\n      </div>\n    </TooltipTrigger>\n    <TooltipContent side=\"right\">{{ tooltipText }}</TooltipContent>\n  </Tooltip>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, onErrorCaptured, ref } from 'vue'\n\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport type { INodeSlot } from '@/lib/litegraph/src/litegraph'\nimport { useSlotLinkDragUIState } from '@/renderer/core/canvas/links/slotLinkDragUIState'\nimport { getSlotKey } from '@/renderer/core/layout/slots/slotIdentifier'\nimport { useNodeTooltips } from '@/renderer/extensions/vueNodes/composables/useNodeTooltips'\nimport { useSlotLinkInteraction } from '@/renderer/extensions/vueNodes/composables/useSlotLinkInteraction'\nimport { useSlotLinkReveal } from '@/renderer/extensions/vueNodes/composables/useSlotLinkReveal'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport type { NodeId } from '@/types/nodeId'\n\nimport SlotConnectionDot from './SlotConnectionDot.vue'\n\ninterface OutputSlotProps {\n  nodeType?: string\n  nodeId?: NodeId\n  slotData: INodeSlot\n  index: number\n  connected?: boolean\n  compatible?: boolean\n  dotOnly?: boolean\n}\n\nconst props = defineProps<OutputSlotProps>()\n\nconst hasNoLabel = computed(\n  () => !props.slotData.localized_name && props.slotData.name === ''\n)\nconst dotOnly = computed(() => props.dotOnly || hasNoLabel.value)\n// Error boundary implementation\nconst renderError = ref<string | null>(null)\n\nconst { toastErrorHandler } = useErrorHandling()\n\nconst { getOutputSlotTooltip } = useNodeTooltips(props.nodeType || '')\nconst tooltipText = computed(() =>\n  getOutputSlotTooltip(props.slotData, props.index)\n)\n\nconst { revealLinks, unrevealLinks } = useSlotLinkReveal({\n  nodeId: props.nodeId,\n  index: props.index,\n  type: 'output'\n})\n\nonErrorCaptured((error) => {\n  unrevealLinks()\n  renderError.value = error.message\n  toastErrorHandler(error)\n  return false\n})\n\nconst { state: dragState } = useSlotLinkDragUIState()\nconst slotKey = computed(() =>\n  props.nodeId ? getSlotKey(props.nodeId, props.index, false) : undefined\n)\nconst shouldDim = computed(() => {\n  if (!dragState.active) return false\n  return !slotKey.value || !dragState.compatible.get(slotKey.value)\n})\n\nconst slotWrapperClass = computed(() =>\n  cn(\n    'lg-slot lg-slot--output group flex h-5 items-center justify-end rounded-l-lg',\n    'cursor-crosshair',\n    dotOnly.value ? 'lg-slot--dot-only justify-center' : 'pl-2',\n    {\n      'lg-slot--connected': props.connected,\n      'lg-slot--compatible': props.compatible,\n      'opacity-40': shouldDim.value\n    }\n  )\n)\n\nconst { onPointerDown } = useSlotLinkInteraction({\n  nodeId: props.nodeId,\n  index: props.index,\n  type: 'output'\n})\n</script>\n","<template>\n  <div v-if=\"renderError\" class=\"node-error p-2 text-sm text-red-500\">\n    {{ st('nodeErrors.slots', 'Node Slots Error') }}\n  </div>\n  <div\n    v-else\n    ref=\"slots\"\n    :class=\"cn('flex min-w-0 justify-between', unifiedWrapperClass)\"\n  >\n    <div\n      v-if=\"filteredInputs.length\"\n      :class=\"cn('flex min-w-0 flex-col', unifiedDotsClass)\"\n    >\n      <InputSlot\n        v-for=\"(input, index) in filteredInputs\"\n        :key=\"`input-${input.name}-${getActualInputIndex(input, index)}`\"\n        :slot-data=\"input\"\n        :node-type=\"nodeData?.type || ''\"\n        :node-id=\"nodeData.id\"\n        :has-error=\"inputHasError(input)\"\n        :index=\"getActualInputIndex(input, index)\"\n        :connected=\"isInputConnected(getActualInputIndex(input, index))\"\n      />\n    </div>\n\n    <div\n      v-if=\"nodeData.outputs.length\"\n      :class=\"cn('ml-auto flex min-w-0 flex-col', unifiedDotsClass)\"\n    >\n      <OutputSlot\n        v-for=\"(output, index) in nodeData.outputs\"\n        :key=\"`output-${output.name}-${index}`\"\n        :slot-data=\"output\"\n        :node-type=\"nodeData?.type || ''\"\n        :node-id=\"nodeData.id\"\n        :index=\"index\"\n        :connected=\"isOutputConnected(index)\"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, onErrorCaptured, ref, useTemplateRef, watch } from 'vue'\n\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { st } from '@/i18n'\nimport type { INodeSlot } from '@/lib/litegraph/src/litegraph'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { syncSlotOffsets } from '@/renderer/core/layout/slots/syncSlotOffsets'\nimport { layoutStore } from '@/renderer/core/layout/store/layoutStore'\nimport {\n  linkedWidgetedInputs,\n  nonWidgetedInputs\n} from '@/renderer/extensions/vueNodes/utils/nodeDataUtils'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { useLinkStore } from '@/stores/linkStore'\nimport type { GraphScope } from '@/types/graphScopeId'\nimport { toOwningGraphId, toRootGraphId } from '@/types/graphScopeId'\nimport type { NodeState } from '@/types/nodeState'\nimport { locatorIdFromState } from '@/utils/graphTraversalUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport InputSlot from './InputSlot.vue'\nimport OutputSlot from './OutputSlot.vue'\n\nconst {\n  nodeData,\n  unified = false,\n  syncLayout = true\n} = defineProps<{\n  nodeData: NodeState\n  unified?: boolean\n  syncLayout?: boolean\n}>()\nconst canvasStore = useCanvasStore()\nconst slots = useTemplateRef<HTMLElement>('slots')\nconst executionErrorStore = useExecutionErrorStore()\nconst linkStore = useLinkStore()\nconst nodeLocatorId = computed(() =>\n  locatorIdFromState(nodeData, canvasStore.rootGraphId)\n)\nconst nodeScope = computed<GraphScope | null>(() => {\n  const graph = canvasStore.currentGraph\n  return graph\n    ? {\n        rootGraphId: toRootGraphId(graph.rootGraph.id),\n        owningGraphId: toOwningGraphId(nodeData.graphId)\n      }\n    : null\n})\n\nconst linkedWidgetInputs = computed(() =>\n  unified && nodeScope.value\n    ? linkedWidgetedInputs(nodeData.id, nodeData.inputs, nodeScope.value)\n    : []\n)\n\nfunction isInputConnected(index: number): boolean {\n  const scope = nodeScope.value\n  if (!scope) return false\n  return linkStore.isInputSlotConnected(scope, nodeData.id, index)\n}\n\nfunction isOutputConnected(index: number): boolean {\n  const scope = nodeScope.value\n  if (!scope) return false\n  return linkStore.isOutputSlotConnected(scope, nodeData.id, index)\n}\n\nconst filteredInputs = computed(() => [\n  ...nonWidgetedInputs(nodeData.inputs),\n  ...linkedWidgetInputs.value\n])\n\nconst layoutKey = computed(() =>\n  [\n    ...filteredInputs.value.map((input, index) =>\n      getActualInputIndex(input, index)\n    ),\n    '|',\n    ...nodeData.outputs.keys(),\n    unified\n  ].join(':')\n)\n\nwatch(\n  [\n    layoutKey,\n    slots,\n    () => canvasStore.rootGraphId,\n    () => layoutStore.slotOffsetVersion\n  ],\n  () => {\n    const rootGraphId = canvasStore.rootGraphId\n    if (syncLayout && slots.value && rootGraphId) {\n      syncSlotOffsets(slots.value, rootGraphId, nodeData.id)\n    }\n  },\n  { flush: 'post' }\n)\n\nfunction inputHasError(input: INodeSlot): boolean {\n  const locatorId = nodeLocatorId.value\n  if (!locatorId) return false\n\n  return executionErrorStore.slotHasError(locatorId, input.name)\n}\n\nconst unifiedWrapperClass = computed((): string =>\n  cn(\n    unified &&\n      'pointer-events-none absolute inset-0 z-30 items-center opacity-0'\n  )\n)\nconst unifiedDotsClass = computed((): string =>\n  cn(\n    unified &&\n      'grid grid-cols-1 grid-rows-1 place-items-center gap-0 *:col-span-full *:row-span-full'\n  )\n)\n\n// Get the actual index of an input slot in the node's inputs array\n// (accounting for filtered widget slots)\nfunction getActualInputIndex(input: INodeSlot, filteredIndex: number): number {\n  const actualIndex = nodeData.inputs.findIndex((i) => i === input)\n  return actualIndex !== -1 ? actualIndex : filteredIndex\n}\n\n// Error boundary implementation\nconst renderError = ref<string | null>(null)\nconst { toastErrorHandler } = useErrorHandling()\n\nonErrorCaptured((error) => {\n  renderError.value = error.message\n  toastErrorHandler(error)\n  return false\n})\n</script>\n","<script setup lang=\"ts\">\nimport { remove } from 'es-toolkit'\nimport { computed } from 'vue'\n\nimport type { LinearInput } from '@/platform/workflow/management/stores/comfyWorkflow'\nimport { useAppModeStore } from '@/stores/appModeStore'\nimport type { WidgetId } from '@/types/widgetId'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { widgetId, name } = defineProps<{\n  widgetId?: WidgetId\n  enable: boolean\n  name: string\n}>()\n\nconst appModeStore = useAppModeStore()\nconst isPromoted = computed(() => appModeStore.selectedInputs.some(matchesThis))\n\nfunction matchesThis([storedId]: LinearInput) {\n  return widgetId !== undefined && storedId === widgetId\n}\nfunction togglePromotion() {\n  if (!widgetId) return\n  if (isPromoted.value) remove(appModeStore.selectedInputs, matchesThis)\n  else appModeStore.selectedInputs.push([widgetId, name])\n}\n</script>\n<template>\n  <div\n    v-if=\"enable\"\n    class=\"pointer-events-auto relative col-span-2 flex cursor-pointer flex-row gap-1\"\n    @pointerdown.capture.stop.prevent=\"togglePromotion\"\n    @click.capture.stop.prevent\n    @pointerup.capture.stop.prevent\n    @pointermove.capture.stop.prevent\n    @contextmenu.capture.stop.prevent\n  >\n    <div\n      :class=\"\n        cn(\n          'm-1 size-4 self-center rounded-sm border border-primary-background',\n          isPromoted && 'flex items-center bg-primary-background'\n        )\n      \"\n    >\n      <i\n        v-if=\"isPromoted\"\n        class=\"place-center icon-[lucide--check] bg-base-foreground\"\n      />\n    </div>\n    <div\n      :class=\"\n        cn(\n          'pointer-events-none grid flex-1 grid-cols-2 items-stretch rounded-lg ring-primary-background',\n          isPromoted && 'ring-2'\n        )\n      \"\n    >\n      <slot />\n    </div>\n    <div class=\"absolute size-full rounded-lg hover:bg-primary-background/10\" />\n  </div>\n  <slot v-else />\n</template>\n","/**\n * Generic Vue Element Tracking System\n *\n * Automatically tracks DOM size and position changes for Vue-rendered elements\n * and syncs them to the layout store. Uses a single shared ResizeObserver for\n * performance, with elements identified by configurable data attributes.\n *\n * Supports different element types (nodes, slots, widgets, etc.) with\n * customizable data attributes and update handlers.\n */\nimport { getCurrentInstance, onMounted, onUnmounted, watch } from 'vue'\n\nimport { useDocumentVisibility } from '@vueuse/core'\n\nimport { useSharedCanvasPositionConversion } from '@/composables/element/useCanvasPositionConversion'\nimport { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { layoutStore } from '@/renderer/core/layout/store/layoutStore'\nimport { syncSlotOffsets } from '@/renderer/core/layout/slots/syncSlotOffsets'\nimport type { Bounds, NodeId, Size } from '@/renderer/core/layout/types'\nimport { toNodeId } from '@/types/nodeId'\nimport { isSizeEqual } from '@/renderer/core/layout/utils/geometry'\nimport { removeNodeTitleHeight } from '@/renderer/core/layout/utils/nodeSizeUtil'\nimport type { UUID } from '@/utils/uuid'\n\n/**\n * Generic update item for element bounds tracking\n */\ninterface ElementBoundsUpdate {\n  id: NodeId\n  /** Updated bounds */\n  bounds: Bounds\n}\n\ninterface CachedNodeMeasurement {\n  rootGraphId: UUID\n  nodeId: NodeId\n  size: Size\n}\n\n/**\n * Configuration for different types of tracked elements\n */\ninterface ElementTrackingConfig {\n  /** Data attribute name (e.g., 'nodeId') */\n  dataAttribute: string\n  syncSlots?: boolean\n  /** Handler for processing bounds updates. Omit for signal-only entries. */\n  updateHandler?: (updates: ElementBoundsUpdate[]) => void\n}\n\n/**\n * Registry of tracking configurations by element type\n */\nconst trackingConfigs = new Map<string, ElementTrackingConfig>([\n  [\n    'node',\n    {\n      dataAttribute: 'nodeId',\n      updateHandler: (updates) => {\n        const { rootGraphId } = useCanvasStore()\n        if (!rootGraphId) return\n\n        for (const { id, bounds } of updates) {\n          layoutStore.reportContentSize(rootGraphId, id, {\n            width: bounds.width,\n            height: removeNodeTitleHeight(bounds.height)\n          })\n        }\n      }\n    }\n  ],\n  ['widgets-grid', { dataAttribute: 'widgetsGridNodeId', syncSlots: true }]\n])\n\n// Elements whose ResizeObserver fired while the tab was hidden\nconst deferredElements = new Set<HTMLElement>()\nconst elementsNeedingFreshMeasurement = new WeakSet<HTMLElement>()\nconst cachedNodeMeasurements = new WeakMap<HTMLElement, CachedNodeMeasurement>()\nconst visibility = useDocumentVisibility()\n\nfunction markElementForFreshMeasurement(element: HTMLElement) {\n  elementsNeedingFreshMeasurement.add(element)\n  cachedNodeMeasurements.delete(element)\n}\n\nwatch(visibility, (state) => {\n  if (state !== 'visible' || deferredElements.size === 0) return\n\n  // Re-observe deferred elements to trigger fresh measurements\n  for (const element of deferredElements) {\n    if (element.isConnected) {\n      resizeObserver.observe(element)\n    }\n  }\n  deferredElements.clear()\n})\n\n// Single ResizeObserver instance for all Vue elements\nconst resizeObserver = new ResizeObserver((entries) => {\n  const { linearMode, rootGraphId } = useCanvasStore()\n  if (linearMode) return\n\n  // Skip measurements when tab is hidden — bounding rects are unreliable\n  if (visibility.value === 'hidden') {\n    for (const entry of entries) {\n      if (entry.target instanceof HTMLElement) {\n        deferredElements.add(entry.target)\n        resizeObserver.unobserve(entry.target)\n      }\n    }\n    return\n  }\n\n  // Canvas is ready when this code runs; no defensive guards needed.\n  const conv = useSharedCanvasPositionConversion()\n  // Group updates by type, then flush via each config's handler\n  const updatesByType = new Map<string, ElementBoundsUpdate[]>()\n  const slotSyncElements = new Map<NodeId, HTMLElement>()\n  for (const entry of entries) {\n    if (!(entry.target instanceof HTMLElement)) continue\n    const element = entry.target\n\n    // Find which type this element belongs to\n    let elementType: string | undefined\n    let elementId: string | undefined\n\n    for (const [type, config] of trackingConfigs) {\n      const id = element.dataset[config.dataAttribute]\n      if (id) {\n        elementType = type\n        elementId = id\n        break\n      }\n    }\n\n    if (!elementType || !elementId) continue\n    const config = trackingConfigs.get(elementType)\n    const nodeId = toNodeId(elementId)\n    if (config?.syncSlots) {\n      slotSyncElements.set(nodeId, element)\n      continue\n    }\n\n    // Use borderBoxSize when available; fall back to contentRect for older engines/tests\n    // Border box is the border included FULL wxh DOM value.\n    const borderBox = Array.isArray(entry.borderBoxSize)\n      ? entry.borderBoxSize[0]\n      : {\n          inlineSize: entry.contentRect.width,\n          blockSize: entry.contentRect.height\n        }\n    const width = Math.max(0, borderBox.inlineSize)\n    const height = Math.max(0, borderBox.blockSize)\n\n    const nodeLayout =\n      nodeId && rootGraphId\n        ? layoutStore.getNodeLayout(rootGraphId, nodeId)\n        : null\n    const normalizedHeight = removeNodeTitleHeight(height)\n    const measuredSize = { width, height: normalizedHeight }\n    const previousMeasurement = cachedNodeMeasurements.get(element)\n    const reportedContentSize =\n      nodeId && rootGraphId\n        ? layoutStore.contentSizeOf(rootGraphId, nodeId)\n        : undefined\n    const hasFreshMeasurementPending =\n      elementsNeedingFreshMeasurement.has(element)\n    const hasMatchingCachedNodeMeasurement =\n      previousMeasurement != null &&\n      previousMeasurement.rootGraphId === rootGraphId &&\n      previousMeasurement.nodeId === nodeId &&\n      isSizeEqual(previousMeasurement.size, measuredSize) &&\n      reportedContentSize != null &&\n      isSizeEqual(reportedContentSize, measuredSize)\n\n    // ResizeObserver can repeat an unchanged entry (for example after an\n    // initial or changed-size delivery). Skip downstream work only when this\n    // exact element, graph, and node already reported the normalized size.\n    if (!hasFreshMeasurementPending && hasMatchingCachedNodeMeasurement) {\n      continue\n    }\n    if (rootGraphId) {\n      slotSyncElements.set(nodeId, element)\n    }\n\n    // Use existing position from layout store (source of truth) rather than\n    // converting screen-space getBoundingClientRect() back to canvas coords.\n    // The DOM→canvas conversion depends on the current canvas scale/offset,\n    // which can be stale during graph transitions (e.g. entering a subgraph\n    // before fitView runs), producing corrupted positions.\n    const existingPos = nodeLayout?.position\n    let posX: number\n    let posY: number\n    if (existingPos) {\n      posX = existingPos.x\n      posY = existingPos.y\n    } else {\n      const rect = element.getBoundingClientRect()\n      const [cx, cy] = conv.clientPosToCanvasPos([rect.left, rect.top])\n      posX = cx\n      posY = cy + LiteGraph.NODE_TITLE_HEIGHT\n    }\n    const bounds: Bounds = {\n      x: posX,\n      y: posY,\n      width,\n      height\n    }\n    elementsNeedingFreshMeasurement.delete(element)\n    if (nodeId && rootGraphId) {\n      cachedNodeMeasurements.set(element, {\n        rootGraphId,\n        nodeId,\n        size: measuredSize\n      })\n    }\n\n    let updates = updatesByType.get(elementType)\n    if (!updates) {\n      updates = []\n      updatesByType.set(elementType, updates)\n    }\n    updates.push({ id: nodeId, bounds })\n  }\n\n  for (const [type, updates] of updatesByType) {\n    const config = trackingConfigs.get(type)\n    if (config?.updateHandler && updates.length) config.updateHandler(updates)\n  }\n  if (rootGraphId) {\n    for (const [nodeId, element] of slotSyncElements) {\n      syncSlotOffsets(element, rootGraphId, nodeId)\n    }\n  }\n})\n\n/**\n * Tracks DOM element size/position changes for a Vue component and syncs to layout store\n *\n * Sets up automatic ResizeObserver tracking when the component mounts and cleans up\n * when unmounted. The tracked element is identified by a data attribute set on the\n * component's root DOM element.\n *\n * @param appIdentifier - Application-level identifier for this tracked element (not a DOM ID)\n *                       Example: node ID like 'node-123', widget ID like 'widget-456'\n * @param trackingType - Type of element being tracked, determines which tracking config to use\n *                      Example: 'node' for Vue nodes, 'widget' for UI widgets\n *\n * @example\n * ```ts\n * // Track a Vue node component with ID 'my-node-123'\n * useVueElementTracking('my-node-123', 'node')\n *\n * // Would set data-node-id=\"my-node-123\" on the component's root element\n * // and sync size changes to layoutStore.batchUpdateNodeBounds()\n * ```\n */\nexport function useVueElementTracking(\n  appIdentifier: string,\n  trackingType: string\n) {\n  onMounted(() => {\n    const element = getCurrentInstance()?.proxy?.$el\n    if (!(element instanceof HTMLElement) || !appIdentifier) return\n\n    const config = trackingConfigs.get(trackingType)\n    if (!config) return\n\n    // Set the data attribute expected by the RO pipeline for this type\n    element.dataset[config.dataAttribute] = appIdentifier\n    markElementForFreshMeasurement(element)\n    resizeObserver.observe(element)\n  })\n\n  onUnmounted(() => {\n    const element = getCurrentInstance()?.proxy?.$el\n    if (!(element instanceof HTMLElement)) return\n\n    const config = trackingConfigs.get(trackingType)\n    if (!config) return\n\n    // Remove the data attribute and observer\n    delete element.dataset[config.dataAttribute]\n    cachedNodeMeasurements.delete(element)\n    elementsNeedingFreshMeasurement.delete(element)\n    deferredElements.delete(element)\n    resizeObserver.unobserve(element)\n  })\n}\n","/**\n * Widget type registry and component mapping for Vue-based widgets\n */\nimport { defineAsyncComponent } from 'vue'\nimport type { Component } from 'vue'\n\nconst WidgetButton = defineAsyncComponent(\n  () => import('../components/WidgetButton.vue')\n)\nconst WidgetInputText = defineAsyncComponent(\n  () => import('../components/WidgetInputText.vue')\n)\nconst WidgetInputNumber = defineAsyncComponent(\n  () => import('../components/WidgetInputNumber.vue')\n)\nconst WidgetToggleSwitch = defineAsyncComponent(\n  () => import('../components/WidgetToggleSwitch.vue')\n)\nconst WidgetSelect = defineAsyncComponent(\n  () => import('../components/WidgetSelect.vue')\n)\nconst WidgetColorPicker = defineAsyncComponent(\n  () => import('../components/WidgetColorPicker.vue')\n)\nconst WidgetTextarea = defineAsyncComponent(\n  () => import('../components/WidgetTextarea.vue')\n)\nconst WidgetChart = defineAsyncComponent(\n  () => import('../components/WidgetChart.vue')\n)\nconst WidgetImageCompare = defineAsyncComponent(\n  () => import('../components/WidgetImageCompare.vue')\n)\nconst WidgetGalleria = defineAsyncComponent(\n  () => import('../components/WidgetGalleria.vue')\n)\nconst WidgetMarkdown = defineAsyncComponent(\n  () => import('../components/WidgetMarkdown.vue')\n)\nconst WidgetTextPreview = defineAsyncComponent(\n  () => import('../components/WidgetTextPreview.vue')\n)\nconst WidgetLegacy = defineAsyncComponent(\n  () => import('../components/WidgetLegacy.vue')\n)\nconst WidgetRecordAudio = defineAsyncComponent(\n  () => import('../components/WidgetRecordAudio.vue')\n)\nconst AudioPreviewPlayer = defineAsyncComponent(\n  () => import('../components/audio/AudioPreviewPlayer.vue')\n)\nconst Load3D = defineAsyncComponent(\n  () => import('@/components/load3d/Load3D.vue')\n)\nconst Load3DAdvanced = defineAsyncComponent(\n  () => import('@/components/load3d/Load3DAdvanced.vue')\n)\nconst CameraInfo = defineAsyncComponent(\n  () => import('@/components/cameraInfo/CameraInfo.vue')\n)\nconst CameraAngle = defineAsyncComponent(\n  () => import('@/components/cameraAngle/CameraAngle.vue')\n)\nconst LightInfo = defineAsyncComponent(\n  () => import('@/components/lightInfo/LightInfo.vue')\n)\nconst WidgetImageCrop = defineAsyncComponent(\n  () => import('@/components/imagecrop/WidgetImageCrop.vue')\n)\nconst WidgetBoundingBox = defineAsyncComponent(\n  () => import('@/components/boundingbox/WidgetBoundingBox.vue')\n)\nconst WidgetCurve = defineAsyncComponent(\n  () => import('@/components/curve/WidgetCurve.vue')\n)\nconst WidgetPainter = defineAsyncComponent(\n  () => import('@/components/painter/WidgetPainter.vue')\n)\nconst WidgetCompositor = defineAsyncComponent(\n  () =>\n    import('@/renderer/extensions/compositor/components/WidgetCompositor.vue')\n)\nconst WidgetRange = defineAsyncComponent(\n  () => import('@/components/range/WidgetRange.vue')\n)\nconst WidgetBoundingBoxes = defineAsyncComponent(\n  () => import('@/components/boundingBoxes/WidgetBoundingBoxes.vue')\n)\nconst WidgetVideoEdit = defineAsyncComponent(\n  () => import('@/components/videoEdit/WidgetVideoEdit.vue')\n)\nconst WidgetColors = defineAsyncComponent(\n  () => import('@/components/palette/WidgetColors.vue')\n)\nconst WidgetResolutionPreview = defineAsyncComponent(\n  () => import('../components/WidgetResolutionPreview.vue')\n)\n\nexport const FOR_TESTING = {\n  WidgetButton,\n  WidgetColorPicker,\n  WidgetInputNumber,\n  WidgetInputText,\n  WidgetMarkdown,\n  WidgetSelect,\n  WidgetTextarea,\n  WidgetToggleSwitch\n} as const\n\ninterface WidgetDefinition {\n  component: Component\n  aliases: string[]\n  essential: boolean\n}\n\nconst coreWidgetDefinitions: Array<[string, WidgetDefinition]> = [\n  [\n    'dynamic_group_row',\n    {\n      component: defineAsyncComponent(\n        () => import('../components/WidgetDynamicGroupRow.vue')\n      ),\n      aliases: [],\n      essential: false\n    }\n  ],\n  [\n    'button',\n    { component: WidgetButton, aliases: ['BUTTON'], essential: false }\n  ],\n  [\n    'string',\n    {\n      component: WidgetInputText,\n      aliases: ['STRING', 'text'],\n      essential: false\n    }\n  ],\n  ['int', { component: WidgetInputNumber, aliases: ['INT'], essential: true }],\n  [\n    'float',\n    {\n      component: WidgetInputNumber,\n      aliases: ['FLOAT', 'number', 'slider', 'gradientslider'],\n      essential: true\n    }\n  ],\n  [\n    'boolean',\n    {\n      component: WidgetToggleSwitch,\n      aliases: ['BOOLEAN', 'toggle'],\n      essential: true\n    }\n  ],\n  [\n    'combo',\n    { component: WidgetSelect, aliases: ['COMBO', 'asset'], essential: true }\n  ],\n  [\n    'color',\n    { component: WidgetColorPicker, aliases: ['COLOR'], essential: false }\n  ],\n  [\n    'textarea',\n    {\n      component: WidgetTextarea,\n      aliases: ['TEXTAREA', 'multiline', 'customtext'],\n      essential: false\n    }\n  ],\n  ['chart', { component: WidgetChart, aliases: ['CHART'], essential: false }],\n  [\n    'imagecompare',\n    {\n      component: WidgetImageCompare,\n      aliases: ['IMAGECOMPARE'],\n      essential: false\n    }\n  ],\n  [\n    'galleria',\n    { component: WidgetGalleria, aliases: ['GALLERIA'], essential: false }\n  ],\n  [\n    'markdown',\n    {\n      component: WidgetMarkdown,\n      aliases: ['MARKDOWN', 'progressText'],\n      essential: false\n    }\n  ],\n  [\n    'textPreview',\n    {\n      component: WidgetTextPreview,\n      aliases: ['TEXT_PREVIEW'],\n      essential: false\n    }\n  ],\n  ['legacy', { component: WidgetLegacy, aliases: [], essential: true }],\n  [\n    'audiorecord',\n    {\n      component: WidgetRecordAudio,\n      aliases: ['AUDIO_RECORD', 'AUDIORECORD'],\n      essential: false\n    }\n  ],\n  [\n    'audioUI',\n    {\n      component: AudioPreviewPlayer,\n      aliases: ['AUDIOUI', 'AUDIO_UI'],\n      essential: false\n    }\n  ],\n  ['load3D', { component: Load3D, aliases: ['LOAD_3D'], essential: false }],\n  [\n    'load3DAdvanced',\n    {\n      component: Load3DAdvanced,\n      aliases: ['LOAD_3D_ADVANCED'],\n      essential: false\n    }\n  ],\n  [\n    'cameraInfo',\n    {\n      component: CameraInfo,\n      aliases: ['CAMERA_INFO_STATE'],\n      essential: false\n    }\n  ],\n  [\n    'cameraAngle',\n    {\n      component: CameraAngle,\n      aliases: ['CAMERA_ANGLE_VIEW'],\n      essential: false\n    }\n  ],\n  [\n    'lightinfo',\n    {\n      component: LightInfo,\n      aliases: ['LIGHT_INFO_PREVIEW', 'lightInfo'],\n      essential: false\n    }\n  ],\n  [\n    'imagecrop',\n    {\n      component: WidgetImageCrop,\n      aliases: ['IMAGECROP'],\n      essential: false\n    }\n  ],\n  [\n    'boundingbox',\n    {\n      component: WidgetBoundingBox,\n      aliases: ['BOUNDING_BOX'],\n      essential: false\n    }\n  ],\n  [\n    'curve',\n    {\n      component: WidgetCurve,\n      aliases: ['CURVE'],\n      essential: false\n    }\n  ],\n  [\n    'painter',\n    {\n      component: WidgetPainter,\n      aliases: ['PAINTER'],\n      essential: false\n    }\n  ],\n  [\n    'compositor',\n    {\n      component: WidgetCompositor,\n      aliases: ['COMPOSITOR'],\n      essential: false\n    }\n  ],\n  [\n    'range',\n    {\n      component: WidgetRange,\n      aliases: ['RANGE'],\n      essential: false\n    }\n  ],\n  [\n    'boundingboxes',\n    {\n      component: WidgetBoundingBoxes,\n      aliases: ['BOUNDING_BOXES'],\n      essential: false\n    }\n  ],\n  [\n    'videoedit',\n    {\n      component: WidgetVideoEdit,\n      aliases: ['VIDEO_EDIT'],\n      essential: false\n    }\n  ],\n  [\n    'colors',\n    {\n      component: WidgetColors,\n      aliases: ['COLORS'],\n      essential: false\n    }\n  ],\n  [\n    'resolutionpreview',\n    {\n      component: WidgetResolutionPreview,\n      aliases: ['RESOLUTION_PREVIEW'],\n      essential: false\n    }\n  ]\n]\n\n// Build lookup maps\nconst widgets = new Map<string, WidgetDefinition>()\nconst aliasMap = new Map<string, string>()\n\nfor (const [type, def] of coreWidgetDefinitions) {\n  widgets.set(type, def)\n  for (const alias of def.aliases) {\n    aliasMap.set(alias, type)\n  }\n}\n\n// Utility functions\nconst getCanonicalType = (type: string): string => aliasMap.get(type) || type\n\nexport const getComponent = (type: string): Component | null => {\n  const canonicalType = getCanonicalType(type)\n  return widgets.get(canonicalType)?.component || null\n}\n\nexport const isEssential = (type: string): boolean => {\n  const canonicalType = getCanonicalType(type)\n  return widgets.get(canonicalType)?.essential || false\n}\n\nconst EXPANDING_TYPES = [\n  'textarea',\n  'markdown',\n  'textPreview',\n  'load3D',\n  'load3DAdvanced',\n  'cameraInfo',\n  'cameraAngle',\n  'lightinfo',\n  'curve',\n  'painter',\n  'compositor',\n  'imagecompare',\n  'range',\n  'boundingboxes',\n  'videoedit'\n] as const\n\nexport function shouldExpand(type: string): boolean {\n  const canonicalType = getCanonicalType(type)\n  return EXPANDING_TYPES.includes(\n    canonicalType as (typeof EXPANDING_TYPES)[number]\n  )\n}\n","<template>\n  <div\n    ref=\"grid\"\n    data-testid=\"node-widgets\"\n    class=\"lg-node-widgets grid grid-cols-[min-content_minmax(80px,min-content)_minmax(125px,1fr)] gap-y-1 pr-3\"\n    :style=\"{\n      'grid-template-rows': gridTemplateRows,\n      flex: gridTemplateRows.includes('auto') ? 1 : undefined\n    }\"\n  >\n    <div\n      v-for=\"section in sections\"\n      :key=\"section.key\"\n      :role=\"section.role\"\n      :aria-label=\"section.label\"\n      class=\"col-span-full grid grid-cols-subgrid grid-rows-subgrid\"\n      :style=\"{ gridRow: `span ${section.rows.length}` }\"\n    >\n      <template v-for=\"row in section.rows\" :key=\"row.widget.renderKey\">\n        <div\n          :data-testid=\"row.testId\"\n          :data-widget-name=\"row.widget.simplified.name\"\n          :class=\"\n            cn(\n              'group col-span-full grid grid-cols-subgrid items-stretch',\n              row.showsControl && 'lg-node-widget'\n            )\n          \"\n        >\n          <div :class=\"row.slotClass\">\n            <InputSlot\n              v-if=\"row.widget.slotMetadata\"\n              :key=\"`widget-slot-${row.widget.simplified.name}-${row.widget.slotMetadata.index}`\"\n              :slot-data=\"{\n                name: row.widget.simplified.name,\n                label: row.widget.simplified.label,\n                type: row.widget.slotMetadata.type,\n                boundingRect: [0, 0, 0, 0]\n              }\"\n              :node-id\n              :has-error=\"row.widget.hasError\"\n              :index=\"row.widget.slotMetadata.index\"\n              :socketless=\"row.widget.simplified.spec?.socketless\"\n              :standalone=\"row.standalone\"\n              :dot-only=\"row.showsControl\"\n            />\n          </div>\n          <AppInput\n            v-if=\"row.showsControl\"\n            :widget-id=\"row.widget.widgetId\"\n            :name=\"row.widget.simplified.name\"\n            :enable=\"\n              canSelectInputs && !row.widget.simplified.options?.disabled\n            \"\n          >\n            <Tooltip :disabled=\"!row.widget.tooltipText\">\n              <TooltipTrigger as-child>\n                <div class=\"col-span-2 grid grid-cols-subgrid\">\n                  <component\n                    :is=\"row.widget.vueComponent\"\n                    :model-value=\"row.widget.simplified.value\"\n                    :widget=\"row.widget.simplified\"\n                    :node-id\n                    :node-type\n                    :invalid=\"row.widget.hasError\"\n                    :aria-invalid=\"row.widget.hasError || undefined\"\n                    :class=\"\n                      cn(\n                        'col-span-2',\n                        row.widget.hasError &&\n                          'font-bold text-node-stroke-error'\n                      )\n                    \"\n                    @update:model-value=\"row.widget.updateHandler\"\n                    @contextmenu=\"row.widget.handleContextMenu\"\n                    @removed=\"restoreRowFocus\"\n                  />\n                </div>\n              </TooltipTrigger>\n              <TooltipContent side=\"left\">{{\n                row.widget.tooltipText\n              }}</TooltipContent>\n            </Tooltip>\n          </AppInput>\n        </div>\n      </template>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, nextTick, useTemplateRef, watch } from 'vue'\n\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { syncSlotOffsets } from '@/renderer/core/layout/slots/syncSlotOffsets'\nimport AppInput from '@/renderer/extensions/linearMode/AppInput.vue'\nimport { useVueElementTracking } from '@/renderer/extensions/vueNodes/composables/useVueNodeResizeTracking'\nimport type { WidgetGridItem } from '@/renderer/extensions/vueNodes/types/widgetGrid'\nimport { shouldExpand } from '@/renderer/extensions/vueNodes/widgets/registry/widgetRegistry'\nimport type { NodeId } from '@/types/nodeId'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport InputSlot from './InputSlot.vue'\n\nconst grid = useTemplateRef<HTMLElement>('grid')\n\nconst isConvertedWidgetType = (type: string) =>\n  type === 'converted-widget' || type.startsWith('converted-widget:')\n\nconst {\n  processedWidgets,\n  nodeType,\n  canSelectInputs = false,\n  nodeId,\n  syncLayout = true\n} = defineProps<{\n  processedWidgets: WidgetGridItem[]\n  nodeType: string\n  canSelectInputs?: boolean\n  nodeId?: NodeId\n  syncLayout?: boolean\n}>()\n\nuseVueElementTracking(syncLayout ? String(nodeId ?? '') : '', 'widgets-grid')\nconst canvasStore = useCanvasStore()\nconst renderedRows = computed(() =>\n  processedWidgets.flatMap((widget) => {\n    const isConverted = isConvertedWidgetType(widget.simplified.type)\n    const showsControl = !isConverted && widget.visible\n    const shouldRender = isConverted\n      ? !!widget.slotMetadata\n      : widget.visible ||\n        (!!widget.suppressedByConnection && !!widget.slotMetadata)\n    if (!shouldRender) return []\n\n    return [\n      {\n        widget,\n        showsControl,\n        slotClass: cn(\n          'z-10 flex items-stretch',\n          showsControl\n            ? 'w-3 opacity-0 transition-opacity duration-150 group-hover:opacity-100'\n            : 'col-span-full',\n          widget.slotMetadata?.linked && 'opacity-100'\n        ),\n        standalone: !showsControl && !!widget.suppressedByConnection,\n        testId: showsControl ? 'node-widget' : undefined,\n        rowSize:\n          showsControl &&\n          (shouldExpand(widget.simplified.type) || widget.hasLayoutSize)\n            ? 'auto'\n            : 'min-content'\n      }\n    ]\n  })\n)\n\nfunction withShortFieldLabel(\n  widget: WidgetGridItem,\n  groupName: string,\n  groupLabel?: string\n) {\n  const field =\n    widget.simplified.spec?.display_name ??\n    widget.simplified.name.slice(groupName.length + 1)\n  return widget.simplified.label === `${groupLabel} ${field}`\n    ? {\n        ...widget,\n        simplified: { ...widget.simplified, displayLabel: field }\n      }\n    : widget\n}\n\nconst sections = computed(() => {\n  const result: {\n    key: string\n    name?: string\n    label?: string\n    role?: 'group'\n    rows: typeof renderedRows.value\n  }[] = []\n  for (const row of renderedRows.value) {\n    const { name, type, label } = row.widget.simplified\n    if (type === 'dynamic_group_row') {\n      result.push({\n        key: row.widget.renderKey,\n        name,\n        label,\n        role: label ? 'group' : undefined,\n        rows: [row]\n      })\n      continue\n    }\n    const section = result.at(-1)\n    if (!section?.name || !name.startsWith(`${section.name}.`)) {\n      result.push({ key: row.widget.renderKey, rows: [row] })\n      continue\n    }\n    section.rows.push({\n      ...row,\n      widget: withShortFieldLabel(row.widget, section.name, section.label)\n    })\n  }\n  return result\n})\n\nasync function restoreRowFocus(name: string) {\n  const group = name.slice(0, name.lastIndexOf('.'))\n  await nextTick()\n  const remaining = sections.value.filter((section) =>\n    section.name?.startsWith(`${group}.`)\n  )\n  const candidates = [\n    name,\n    ...remaining.map((section) => section.name).reverse(),\n    `${group}.$add`\n  ]\n  for (const candidate of candidates) {\n    if (!candidate) continue\n    const button = grid.value?.querySelector<HTMLButtonElement>(\n      `[data-widget-name=\"${CSS.escape(candidate)}\"] button:not(:disabled)`\n    )\n    if (button) {\n      button.focus()\n      return\n    }\n  }\n}\n\nconst gridTemplateRows = computed(() =>\n  renderedRows.value.map((row) => row.rowSize).join(' ')\n)\n\nconst layoutKey = computed(() =>\n  renderedRows.value\n    .map(\n      ({ widget, showsControl }) =>\n        `${widget.renderKey}:${widget.slotMetadata?.index ?? ''}:${showsControl}`\n    )\n    .join('|')\n)\n\nwatch(\n  layoutKey,\n  () => {\n    const rootGraphId = canvasStore.rootGraphId\n    if (syncLayout && grid.value && rootGraphId && nodeId) {\n      syncSlotOffsets(grid.value, rootGraphId, nodeId)\n    }\n  },\n  { flush: 'post' }\n)\n</script>\n","<template>\n  <div\n    :data-node-id=\"nodeData.id\"\n    :class=\"\n      cn(\n        'lg-node flex w-[350px] touch-none flex-col rounded-2xl border border-solid border-node-stroke bg-component-node-background pb-1 outline-2 outline-transparent contain-layout contain-style',\n        position\n      )\n    \"\n  >\n    <div\n      class=\"pointer-events-none relative flex flex-col items-center justify-center\"\n    >\n      <NodeHeader :node-data=\"nodeData\" />\n    </div>\n    <div\n      class=\"pointer-events-none flex flex-1 flex-col gap-1 pb-2\"\n      data-testid=\"node-preview-body\"\n    >\n      <NodeSlots :node-data=\"nodeData\" :sync-layout=\"false\" />\n\n      <WidgetGrid\n        v-if=\"previewWidgets.length\"\n        :processed-widgets=\"previewWidgets\"\n        :node-type=\"nodeData.type\"\n        :node-id=\"nodeData.id\"\n        :sync-layout=\"false\"\n        class=\"pointer-events-none\"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport type {\n  INodeInputSlot,\n  INodeOutputSlot\n} from '@/lib/litegraph/src/types/slots'\nimport { LGraphEventMode, RenderShape } from '@/lib/litegraph/src/litegraph'\nimport NodeHeader from '@/renderer/extensions/vueNodes/components/NodeHeader.vue'\nimport NodeSlots from '@/renderer/extensions/vueNodes/components/NodeSlots.vue'\nimport WidgetGrid from '@/renderer/extensions/vueNodes/components/WidgetGrid.vue'\nimport type { WidgetGridItem } from '@/renderer/extensions/vueNodes/types/widgetGrid'\nimport WidgetLegacy from '@/renderer/extensions/vueNodes/widgets/components/WidgetLegacy.vue'\nimport { getComponent } from '@/renderer/extensions/vueNodes/widgets/registry/widgetRegistry'\nimport { dynamicComboOptionKeys } from '@/schemas/nodeDef/inputSpecTree'\nimport type { ComfyNodeDef as ComfyNodeDefV2 } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport { useWidgetStore } from '@/stores/widgetStore'\nimport { toNodeId } from '@/types/nodeId'\nimport type { NodeState } from '@/types/nodeState'\nimport type { WidgetValue } from '@/types/simplifiedWidget'\nimport { zeroUuid } from '@/utils/uuid'\nimport { matchesWidgetName } from '@/utils/widgetBinding'\nimport type { WidgetValueBinding } from '@/utils/widgetBinding'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  nodeDef,\n  position = 'absolute',\n  widgetValues\n} = defineProps<{\n  nodeDef: ComfyNodeDefV2\n  position?: 'absolute' | 'relative'\n  widgetValues?: readonly WidgetValueBinding[]\n}>()\n\nconst widgetStore = useWidgetStore()\n\nconst previewInputs = computed<INodeInputSlot[]>(() =>\n  Object.entries(nodeDef.inputs || {})\n    .filter(([, input]) => !widgetStore.inputIsWidget(input))\n    .map(([name, input]) => ({\n      name,\n      type: input.type,\n      shape: input.isOptional ? RenderShape.HollowCircle : undefined,\n      boundingRect: [0, 0, 0, 0],\n      link: null\n    }))\n)\n\nconst previewOutputs = computed<INodeOutputSlot[]>(() =>\n  (nodeDef.outputs || []).map((output) => {\n    if (typeof output === 'string') {\n      return {\n        name: output,\n        type: output,\n        boundingRect: [0, 0, 0, 0],\n        links: []\n      }\n    }\n    return {\n      ...output,\n      boundingRect: [0, 0, 0, 0],\n      links: []\n    }\n  })\n)\n\nconst nodeData = computed<NodeState>(() => ({\n  id: toNodeId(`preview-${nodeDef.name}`),\n  graphId: zeroUuid,\n  title: nodeDef.display_name || nodeDef.name,\n  type: nodeDef.name,\n  mode: LGraphEventMode.ALWAYS,\n  flags: {\n    collapsed: false\n  },\n  inputs: previewInputs.value,\n  outputs: previewOutputs.value,\n  properties: {}\n}))\n\nconst widgetInputs = computed(() =>\n  Object.entries(nodeDef.inputs || {}).filter(([, input]) =>\n    widgetStore.inputIsWidget(input)\n  )\n)\n\nconst resolvedWidgetValues = computed(() =>\n  Object.fromEntries(\n    (widgetValues ?? []).flatMap(({ selector, value }) => {\n      const input = widgetInputs.value.find(([name]) =>\n        matchesWidgetName(name, selector)\n      )\n      return input ? [[input[0], value]] : []\n    })\n  )\n)\n\nconst previewWidgets = computed<WidgetGridItem[]>(() =>\n  widgetInputs.value\n    .filter(([, input]) => !input.hidden && !input.advanced)\n    .map(([name, input]) => {\n      const isDynamicCombo = input.type === 'COMFY_DYNAMICCOMBO_V3'\n      const comboValues = isDynamicCombo\n        ? dynamicComboOptionKeys(input)\n        : input.type === 'COMBO' && Array.isArray(input.options)\n          ? input.options\n          : undefined\n      const leadValue = resolvedWidgetValues.value[name]\n      const value = (leadValue ??\n        input.default ??\n        comboValues?.[0] ??\n        '') as WidgetValue\n      const type = isDynamicCombo ? 'COMBO' : input.widgetType || input.type\n      const values =\n        leadValue !== undefined && comboValues\n          ? [leadValue, ...comboValues.filter((option) => option !== leadValue)]\n          : comboValues\n      return {\n        visible: true,\n        renderKey: `preview:${nodeDef.name}:${name}`,\n        vueComponent: getComponent(type) ?? WidgetLegacy,\n        simplified: { name, type, value, options: { values }, spec: input }\n      }\n    })\n)\n</script>\n","import { inputSpecTree } from '@/schemas/nodeDef/inputSpecTree'\nimport type { InputSpec as InputSpecV2 } from '@/schemas/nodeDef/nodeDefSchemaV2'\n\n/**\n * Returns the node's top-level input specs plus every input nested inside a\n * dynamic control, deduped by name (first occurrence wins).\n *\n * Intentionally includes all DynamicCombo options' inputs as a flat union --\n * the Info tab is reference documentation, not live widget state tied to the\n * currently-selected option.\n *\n * @param inputs The node's top-level input specs\n * @returns Flattened input specs including nested dynamic control inputs\n */\nexport function flattenInputSpecs(\n  inputs: Record<string, InputSpecV2>\n): InputSpecV2[] {\n  const seenNames = new Set<string>()\n  const result: InputSpecV2[] = []\n\n  for (const spec of Object.values(inputs)) {\n    for (const nested of inputSpecTree(spec)) {\n      if (seenNames.has(nested.name)) continue\n      seenNames.add(nested.name)\n      result.push(nested)\n    }\n  }\n\n  return result\n}\n","<!-- Reference:\nhttps://github.com/Nuked88/ComfyUI-N-Sidebar/blob/7ae7da4a9761009fb6629bc04c683087a3e168db/app/js/functions/sb_fn.js#L149\n-->\n<template>\n  <LGraphNodePreview\n    v-if=\"shouldRenderVueNodes\"\n    :node-def=\"nodeDef\"\n    :position=\"position\"\n  />\n  <div\n    v-else\n    class=\"_sb_node_preview bg-component-node-background\"\n    data-testid=\"node-preview\"\n  >\n    <div class=\"_sb_table\">\n      <div\n        class=\"node_header text-ellipsis\"\n        data-testid=\"node-header\"\n        :title=\"nodeDef.display_name\"\n        :style=\"{\n          backgroundColor: litegraphColors.NODE_DEFAULT_COLOR,\n          color: litegraphColors.NODE_TITLE_COLOR\n        }\"\n      >\n        <div class=\"_sb_dot headdot pr-3\" data-testid=\"head-dot\" />\n        {{ nodeDef.display_name }}\n      </div>\n      <div class=\"_sb_preview_badge\">{{ $t('g.preview') }}</div>\n\n      <!-- Node slot I/O -->\n      <div\n        v-for=\"[slotInput, slotOutput] in zip(slotInputDefs, allOutputDefs)\"\n        :key=\"(slotInput?.name || '') + (slotOutput?.index.toString() || '')\"\n        class=\"_sb_row slot_row\"\n      >\n        <div class=\"_sb_col\">\n          <div v-if=\"slotInput\" :class=\"['_sb_dot', slotInput.type]\" />\n        </div>\n        <div class=\"_sb_col\">\n          {{ slotInput ? slotInput.name : '' }}\n        </div>\n        <div class=\"_sb_col middle-column\" />\n        <div\n          class=\"_sb_col _sb_inherit\"\n          :style=\"{\n            color: litegraphColors.NODE_TEXT_COLOR\n          }\"\n        >\n          {{ slotOutput ? slotOutput.name : '' }}\n        </div>\n        <div class=\"_sb_col\">\n          <div v-if=\"slotOutput\" :class=\"['_sb_dot', slotOutput.type]\" />\n        </div>\n      </div>\n\n      <!-- Node widget inputs -->\n      <div\n        v-for=\"widgetInput in widgetInputDefs\"\n        :key=\"widgetInput.name\"\n        class=\"_sb_row _long_field\"\n      >\n        <div class=\"_sb_col _sb_arrow\">&#x25C0;</div>\n        <div\n          class=\"_sb_col\"\n          :style=\"{\n            color: litegraphColors.WIDGET_SECONDARY_TEXT_COLOR\n          }\"\n        >\n          {{ widgetInput.name }}\n        </div>\n        <div class=\"_sb_col middle-column\" />\n        <div\n          class=\"_sb_col _sb_inherit\"\n          :style=\"{ color: litegraphColors.WIDGET_TEXT_COLOR }\"\n        >\n          {{ truncateDefaultValue(widgetInput.default) }}\n        </div>\n        <div class=\"_sb_col _sb_arrow\">&#x25B6;</div>\n      </div>\n    </div>\n    <SanitizedHtml\n      v-if=\"renderedDescription\"\n      class=\"_sb_description\"\n      data-testid=\"node-description\"\n      :style=\"{\n        color: litegraphColors.WIDGET_SECONDARY_TEXT_COLOR,\n        backgroundColor: litegraphColors.WIDGET_BGCOLOR\n      }\"\n      :html=\"renderedDescription\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { truncate, zip } from 'es-toolkit/compat'\nimport { computed } from 'vue'\n\nimport SanitizedHtml from '@/components/common/SanitizedHtml.vue'\nimport { useVueFeatureFlags } from '@/composables/useVueFeatureFlags'\nimport LGraphNodePreview from '@/renderer/extensions/vueNodes/components/LGraphNodePreview.vue'\nimport type { ComfyNodeDef as ComfyNodeDefV2 } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport { flattenInputSpecs } from '@/schemas/nodeDef/inputSpecUtil'\nimport { useWidgetStore } from '@/stores/widgetStore'\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\nimport { renderMarkdownToHtml } from '@/utils/markdownRendererUtil'\n\nconst { nodeDef, position = 'absolute' } = defineProps<{\n  nodeDef: ComfyNodeDefV2\n  position?: 'absolute' | 'relative'\n}>()\n\nconst { shouldRenderVueNodes } = useVueFeatureFlags()\n\nconst colorPaletteStore = useColorPaletteStore()\nconst litegraphColors = computed(\n  () => colorPaletteStore.completedActivePalette.colors.litegraph_base\n)\n\nconst widgetStore = useWidgetStore()\n\nconst { description } = nodeDef\nconst renderedDescription = computed(() => {\n  if (!description) return ''\n  return renderMarkdownToHtml(description)\n})\n\nconst allInputDefs = flattenInputSpecs(nodeDef.inputs)\nconst allOutputDefs = nodeDef.outputs\nconst slotInputDefs = allInputDefs.filter(\n  (input) => !widgetStore.inputIsWidget(input)\n)\nconst widgetInputDefs = allInputDefs.filter((input) =>\n  widgetStore.inputIsWidget(input)\n)\nconst truncateDefaultValue = (\n  value: unknown,\n  charLimit: number = 32\n): string => {\n  let stringValue: string\n\n  if (typeof value === 'object' && value !== null) {\n    stringValue = JSON.stringify(value)\n  } else if (Array.isArray(value)) {\n    stringValue = JSON.stringify(value)\n  } else if (typeof value === 'string') {\n    stringValue = value\n  } else {\n    stringValue = String(value)\n  }\n\n  return truncate(stringValue, { length: charLimit })\n}\n</script>\n\n<style scoped>\n.slot_row {\n  padding: 2px;\n}\n\n/* Original N-Sidebar styles */\n._sb_dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  background-color: grey;\n}\n\n.node_header {\n  line-height: 1;\n  padding: 8px 13px 7px;\n  margin-bottom: 5px;\n  font-size: 15px;\n  text-wrap: nowrap;\n  overflow: hidden;\n  display: flex;\n  align-items: center;\n}\n\n.headdot {\n  width: 10px;\n  height: 10px;\n  float: inline-start;\n  margin-right: 8px;\n}\n\n.IMAGE {\n  background-color: #64b5f6;\n}\n\n.VAE {\n  background-color: #ff6e6e;\n}\n\n.LATENT {\n  background-color: #ff9cf9;\n}\n\n.MASK {\n  background-color: #81c784;\n}\n\n.CONDITIONING {\n  background-color: #ffa931;\n}\n\n.CLIP {\n  background-color: #ffd500;\n}\n\n.MODEL {\n  background-color: #b39ddb;\n}\n\n.CONTROL_NET {\n  background-color: #a5d6a7;\n}\n\n._sb_node_preview {\n  color: var(--descrip-text);\n  border: 1px solid var(--descrip-text);\n  min-width: 300px;\n  width: min-content;\n  height: fit-content;\n  z-index: 9999;\n  border-radius: 12px;\n  overflow: hidden;\n  font-size: 12px;\n  padding-bottom: 10px;\n}\n\n._sb_node_preview ._sb_description {\n  margin: 10px;\n  padding: 6px;\n  background: var(--border-color);\n  border-radius: 5px;\n  font-style: italic;\n  font-weight: 500;\n  font-size: 0.9rem;\n  word-break: break-word;\n}\n\n._sb_table {\n  display: grid;\n\n  grid-column-gap: 10px;\n  /* Spazio tra le colonne */\n  width: 100%;\n  /* Imposta la larghezza della tabella al 100% del contenitore */\n}\n\n._sb_row {\n  display: grid;\n  grid-template-columns: 10px 1fr 1fr 1fr 10px;\n  grid-column-gap: 10px;\n  align-items: center;\n  padding-left: 9px;\n  padding-right: 9px;\n}\n\n._sb_row_string {\n  grid-template-columns: 10px 1fr 1fr 10fr 1fr;\n}\n\n._sb_col {\n  border: 0 solid #000;\n  display: flex;\n  align-items: flex-end;\n  flex-direction: row-reverse;\n  flex-wrap: nowrap;\n  align-content: flex-start;\n  justify-content: flex-end;\n}\n\n._sb_inherit {\n  display: inherit;\n}\n\n._long_field {\n  background: var(--bg-color);\n  border: 2px solid var(--border-color);\n  margin: 5px 5px 0;\n  border-radius: 10px;\n  line-height: 1.7;\n  text-wrap: nowrap;\n}\n\n._sb_arrow {\n  color: var(--fg-color);\n}\n\n._sb_preview_badge {\n  text-align: center;\n  background: var(--comfy-input-bg);\n  font-weight: 700;\n  color: var(--error-text);\n}\n</style>\n","import { transformInputSpecV1ToV2 } from '@/schemas/nodeDef/migration'\nimport type {\n  ComfyNodeDef as ComfyNodeDefV2,\n  InputSpec\n} from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyNodeDef as ComfyNodeDefV1 } from '@/schemas/nodeDefSchema'\nimport type { components } from '@/types/comfyRegistryTypes'\n\nconst registryToFrontendV2NodeOutputs = (\n  registryDef: components['schemas']['ComfyNode']\n): ComfyNodeDefV2['outputs'] => {\n  const returnTypes = JSON.parse(registryDef.return_types ?? '{}')\n  if (!returnTypes.length) return []\n\n  const returnNames = JSON.parse(registryDef.return_names ?? '{}')\n  const outputsIsList = registryDef.output_is_list ?? []\n\n  const outputs = []\n  for (let i = 0; i < returnTypes.length; i++) {\n    outputs.push({\n      type: returnTypes[i],\n      name: returnNames[i] || returnTypes[i],\n      is_list: outputsIsList[i] ?? false,\n      index: i\n    })\n  }\n\n  return outputs\n}\n\nconst registryToFrontendV2NodeInputs = (\n  registryDef: components['schemas']['ComfyNode']\n): ComfyNodeDefV2['inputs'] => {\n  const inputTypes = JSON.parse(\n    registryDef.input_types ?? '{}'\n  ) as ComfyNodeDefV1['input']\n  if (!inputTypes || !Object.keys(inputTypes).length) return {}\n\n  const inputsV2: Record<string, InputSpec> = {}\n\n  if (inputTypes.required) {\n    Object.entries(inputTypes.required).forEach(([name, inputSpecV1]) => {\n      inputsV2[name] = transformInputSpecV1ToV2(inputSpecV1, {\n        name,\n        isOptional: false\n      })\n    })\n  }\n\n  if (inputTypes.optional) {\n    Object.entries(inputTypes.optional).forEach(([name, inputSpecV1]) => {\n      inputsV2[name] = transformInputSpecV1ToV2(inputSpecV1, {\n        name,\n        isOptional: true\n      })\n    })\n  }\n\n  return inputsV2\n}\n\nexport const registryToFrontendV2NodeDef = (\n  nodeDef: components['schemas']['ComfyNode'],\n  nodePack: components['schemas']['Node']\n): ComfyNodeDefV2 => {\n  const name = nodeDef.comfy_node_name ?? 'Node Name'\n  return {\n    category: nodeDef.category ?? 'unknown',\n    description: nodeDef.description ?? '',\n    display_name: name,\n    name,\n    inputs: registryToFrontendV2NodeInputs(nodeDef),\n    outputs: registryToFrontendV2NodeOutputs(nodeDef),\n    output_node: false,\n    python_module: nodePack.name ?? nodePack.id ?? 'unknown'\n  }\n}\n","<template>\n  <div class=\"flex flex-col gap-1 text-sm\">\n    <template v-if=\"mappedNodeDefs?.length\">\n      <div class=\"flex flex-col gap-2\">\n        <div\n          v-for=\"nodeDef in mappedNodeDefs\"\n          :key=\"createNodeDefKey(nodeDef)\"\n          class=\"scale-75\"\n        >\n          <NodePreview :node-def=\"nodeDef\" class=\"min-w-full!\" />\n        </div>\n      </div>\n    </template>\n    <template v-else-if=\"isLoading\">\n      <Spinner />\n    </template>\n    <template v-else-if=\"nodeNames.length\">\n      <div v-for=\"node in nodeNames\" :key=\"node\" class=\"truncate text-muted\">\n        {{ node }}\n      </div>\n    </template>\n    <template v-else>\n      <NoResultsPlaceholder\n        :title=\"$t('manager.noNodesFound')\"\n        :message=\"$t('manager.noNodesFoundDescription')\"\n      />\n    </template>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { whenever } from '@vueuse/core'\nimport { computed, ref, shallowRef, useId } from 'vue'\n\nimport NoResultsPlaceholder from '@/components/common/NoResultsPlaceholder.vue'\nimport Spinner from '@/components/ui/spinner/Spinner.vue'\nimport NodePreview from '@/components/node/NodePreview.vue'\nimport { useComfyRegistryStore } from '@/stores/comfyRegistryStore'\nimport type { components, operations } from '@/types/comfyRegistryTypes'\nimport { registryToFrontendV2NodeDef } from '@/utils/mapperUtil'\n\ntype ListComfyNodesResponse =\n  operations['ListComfyNodes']['responses'][200]['content']['application/json']['comfy_nodes']\n\nconst { nodePack, nodeNames } = defineProps<{\n  nodePack: components['schemas']['Node']\n  nodeNames: string[]\n}>()\n\nconst { getNodeDefs } = useComfyRegistryStore()\n\nconst isLoading = ref(false)\nconst registryNodeDefs = shallowRef<ListComfyNodesResponse | null>(null)\n\nconst fetchNodeDefs = async () => {\n  getNodeDefs.cancel()\n  isLoading.value = true\n\n  const { id: packId } = nodePack\n  const version = nodePack.latest_version?.version\n\n  if (!packId || !version) {\n    registryNodeDefs.value = null\n  } else {\n    const response = await getNodeDefs.call({\n      packId,\n      version,\n      page: 1,\n      limit: 256\n    })\n    registryNodeDefs.value = response?.comfy_nodes ?? null\n  }\n\n  isLoading.value = false\n}\n\nwhenever(() => nodePack, fetchNodeDefs, { immediate: true, deep: true })\n\nconst toFrontendNodeDef = (nodeDef: components['schemas']['ComfyNode']) => {\n  try {\n    return registryToFrontendV2NodeDef(nodeDef, nodePack)\n  } catch (error) {\n    return null\n  }\n}\nconst mappedNodeDefs = computed(() => {\n  if (!registryNodeDefs.value) return null\n  return registryNodeDefs.value\n    .map(toFrontendNodeDef)\n    .filter((nodeDef) => nodeDef !== null)\n})\n\nconst createNodeDefKey = (nodeDef: components['schemas']['ComfyNode']) =>\n  `${nodeDef.category}${nodeDef.comfy_node_name ?? useId()}`\n</script>\n","<template>\n  <div class=\"flex flex-col gap-3\">\n    <div\n      v-for=\"(conflict, index) in conflictResult?.conflicts || []\"\n      :key=\"index\"\n      class=\"rounded-md bg-secondary-background/60\"\n    >\n      <!-- Import failed conflicts show detailed error message -->\n      <template v-if=\"conflict.type === 'import_failed'\">\n        <div\n          v-if=\"conflict.required_value\"\n          class=\"overflow-x-hidden rounded-sm\"\n        >\n          <p class=\"m-0 font-mono text-xs break-all text-muted-foreground\">\n            {{ conflict.required_value }}\n          </p>\n        </div>\n      </template>\n\n      <!-- Other conflict types use standard message -->\n      <template v-else>\n        <div class=\"text-sm wrap-break-word\">\n          {{ getConflictMessage(conflict, $t) }}\n        </div>\n      </template>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { ConflictDetectionResult } from '@/workbench/extensions/manager/types/conflictDetectionTypes'\nimport { getConflictMessage } from '@/workbench/extensions/manager/utils/conflictMessageUtil'\n\nconst { conflictResult } = defineProps<{\n  conflictResult: ConflictDetectionResult | null | undefined\n}>()\n</script>\n","import type { InjectionKey, Ref } from 'vue'\n\nimport type { AlgoliaNodePack } from '@/types/algoliaTypes'\nimport type { components } from '@/types/comfyRegistryTypes'\n\n/**\n * Identifier for a node pack from the Comfy Registry / Manager.\n *\n * Backed by the registry pack's `id` (typically a slug like `cnr_id` or\n * `aux_id`, possibly suffixed with `@version` for disabled packs). This alias\n * names that primitive at use sites (manager store, services, composables)\n * without changing structural typing.\n */\nexport type NodePackId = string\n\nexport type RegistryPack = components['schemas']['Node']\nexport type MergedNodePack = RegistryPack & AlgoliaNodePack\nexport const isMergedNodePack = (\n  nodePack: RegistryPack | AlgoliaNodePack\n): nodePack is MergedNodePack => 'comfy_nodes' in nodePack\n\nexport const IsInstallingKey: InjectionKey<Ref<boolean>> =\n  Symbol('isInstalling')\n\nexport enum ManagerTab {\n  All = 'all',\n  NotInstalled = 'notInstalled',\n  AllInstalled = 'allInstalled',\n  UpdateAvailable = 'updateAvailable',\n  Conflicting = 'conflicting',\n  Workflow = 'workflow',\n  Missing = 'missing',\n  Unresolved = 'unresolved'\n}\n\nexport type TaskLog = {\n  taskName: string\n  taskId: string\n  logs: string[]\n}\n\nexport interface UseNodePacksOptions {\n  immediate?: boolean\n  maxConcurrent?: number\n}\n\nexport enum SortableAlgoliaField {\n  Downloads = 'total_install',\n  Created = 'create_time',\n  Updated = 'update_time',\n  Publisher = 'publisher_id',\n  Name = 'name'\n}\n\nexport interface ManagerState {\n  selectedTabId: ManagerTab\n  searchQuery: string\n  searchMode: 'nodes' | 'packs'\n  sortField: string\n}\n","import type { ComputedRef, InjectionKey } from 'vue'\n\ninterface ImportFailedContext {\n  importFailed: ComputedRef<boolean>\n  showImportFailedDialog: () => void\n}\n\nexport const ImportFailedKey: InjectionKey<ImportFailedContext> =\n  Symbol('ImportFailed')\n","<template>\n  <template v-if=\"nodePack\">\n    <div\n      ref=\"scrollContainer\"\n      class=\"flex scrollbar-custom h-full flex-col overflow-y-auto\"\n    >\n      <PropertiesAccordionItem v-if=\"!importFailed\" :class=\"accordionClass\">\n        <template #label>\n          <span class=\"font-inter text-xs uppercase\">\n            {{ t('manager.actions') }}\n          </span>\n        </template>\n        <div class=\"flex flex-col gap-1 px-4\">\n          <template v-if=\"canTryNightlyUpdate\">\n            <PackTryUpdateButton :node-pack=\"nodePack\" size=\"md\" />\n            <PackUninstallButton :node-packs=\"[nodePack]\" size=\"md\" />\n          </template>\n          <template v-else-if=\"isAllInstalled && !isNightlyPack\">\n            <PackUpdateButton :node-packs=\"[nodePack]\" size=\"md\" />\n            <PackUninstallButton :node-packs=\"[nodePack]\" size=\"md\" />\n          </template>\n          <template v-else-if=\"isAllInstalled\">\n            <PackUninstallButton :node-packs=\"[nodePack]\" size=\"md\" />\n          </template>\n          <template v-else>\n            <PackInstallButton\n              :node-packs=\"[nodePack]\"\n              size=\"md\"\n              :has-conflict=\"hasCompatibilityIssues || hasConflictInfo\"\n              :conflict-info=\"conflictInfo\"\n            />\n          </template>\n        </div>\n      </PropertiesAccordionItem>\n\n      <PropertiesAccordionItem :class=\"accordionClass\">\n        <template #label>\n          <span class=\"font-inter text-xs uppercase\">\n            {{ t('manager.basicInfo') }}\n          </span>\n        </template>\n        <ModelInfoField :label=\"t('g.name')\">\n          <span class=\"text-muted-foreground\">{{ nodePack.name }}</span>\n        </ModelInfoField>\n        <ModelInfoField\n          v-if=\"!importFailed && isPackInstalled(nodePack.id)\"\n          :label=\"t('manager.filter.enabled')\"\n        >\n          <PackEnableToggle\n            :node-pack=\"nodePack\"\n            :has-conflict=\"hasCompatibilityIssues\"\n          />\n        </ModelInfoField>\n        <ModelInfoField\n          v-for=\"item in infoItems\"\n          v-show=\"item.value !== undefined && item.value !== null\"\n          :key=\"item.key\"\n          :label=\"item.label\"\n        >\n          <span class=\"text-muted-foreground\">{{ item.value }}</span>\n        </ModelInfoField>\n        <ModelInfoField :label=\"t('g.status')\">\n          <PackStatusMessage\n            :has-import-failed=\"importFailed\"\n            :status-type=\"\n              nodePack.status as components['schemas']['NodeVersionStatus']\n            \"\n            :has-compatibility-issues=\"hasCompatibilityIssues\"\n          />\n        </ModelInfoField>\n        <ModelInfoField :label=\"t('manager.version')\">\n          <PackVersionBadge :node-pack=\"nodePack\" :is-selected=\"true\" />\n        </ModelInfoField>\n      </PropertiesAccordionItem>\n\n      <PropertiesAccordionItem :class=\"accordionClass\">\n        <template #label>\n          <span class=\"font-inter text-xs uppercase\">\n            {{ t('g.description') }}\n          </span>\n        </template>\n        <DescriptionTabPanel :node-pack=\"nodePack\" />\n      </PropertiesAccordionItem>\n\n      <PropertiesAccordionItem\n        v-if=\"hasCompatibilityIssues\"\n        :class=\"accordionClass\"\n      >\n        <template #label>\n          <span class=\"font-inter text-xs uppercase\">\n            ⚠️ {{ importFailed ? t('g.error') : t('g.warning') }}\n          </span>\n        </template>\n        <div class=\"px-4 py-2\">\n          <WarningTabPanel :conflict-result=\"conflictResult\" />\n        </div>\n      </PropertiesAccordionItem>\n\n      <PropertiesAccordionItem :class=\"accordionClass\">\n        <template #label>\n          <span class=\"font-inter text-xs uppercase\">\n            {{ t('g.nodes') }}\n          </span>\n        </template>\n        <div class=\"px-4 py-2\">\n          <NodesTabPanel :node-pack=\"nodePack\" :node-names=\"nodeNames\" />\n        </div>\n      </PropertiesAccordionItem>\n    </div>\n  </template>\n  <template v-else>\n    <div class=\"flex-1 overflow-hidden px-8 pt-4 text-sm\">\n      {{ $t('manager.infoPanelEmpty') }}\n    </div>\n  </template>\n</template>\n\n<script setup lang=\"ts\">\nimport { whenever } from '@vueuse/core'\nimport { computed, provide, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport PropertiesAccordionItem from '@/components/rightSidePanel/layout/PropertiesAccordionItem.vue'\nimport ModelInfoField from '@/platform/assets/components/modelInfo/ModelInfoField.vue'\nimport type { components } from '@/types/comfyRegistryTypes'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport PackStatusMessage from '@/workbench/extensions/manager/components/manager/PackStatusMessage.vue'\nimport PackVersionBadge from '@/workbench/extensions/manager/components/manager/PackVersionBadge.vue'\nimport PackEnableToggle from '@/workbench/extensions/manager/components/manager/button/PackEnableToggle.vue'\nimport PackInstallButton from '@/workbench/extensions/manager/components/manager/button/PackInstallButton.vue'\nimport PackTryUpdateButton from '@/workbench/extensions/manager/components/manager/button/PackTryUpdateButton.vue'\nimport PackUninstallButton from '@/workbench/extensions/manager/components/manager/button/PackUninstallButton.vue'\nimport PackUpdateButton from '@/workbench/extensions/manager/components/manager/button/PackUpdateButton.vue'\nimport DescriptionTabPanel from '@/workbench/extensions/manager/components/manager/infoPanel/tabs/DescriptionTabPanel.vue'\nimport NodesTabPanel from '@/workbench/extensions/manager/components/manager/infoPanel/tabs/NodesTabPanel.vue'\nimport WarningTabPanel from '@/workbench/extensions/manager/components/manager/infoPanel/tabs/WarningTabPanel.vue'\nimport { usePackUpdateStatus } from '@/workbench/extensions/manager/composables/nodePack/usePackUpdateStatus'\nimport { useConflictDetection } from '@/workbench/extensions/manager/composables/useConflictDetection'\nimport { useImportFailedDetection } from '@/workbench/extensions/manager/composables/useImportFailedDetection'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport { useConflictDetectionStore } from '@/workbench/extensions/manager/stores/conflictDetectionStore'\nimport {\n  IsInstallingKey,\n  isMergedNodePack\n} from '@/workbench/extensions/manager/types/comfyManagerTypes'\nimport type {\n  ConflictDetail,\n  ConflictDetectionResult\n} from '@/workbench/extensions/manager/types/conflictDetectionTypes'\nimport { ImportFailedKey } from '@/workbench/extensions/manager/types/importFailedTypes'\n\ninterface InfoItem {\n  key: string\n  label: string\n  value: string | number | undefined\n}\n\nconst { nodePack } = defineProps<{\n  nodePack: components['schemas']['Node']\n}>()\n\nconst scrollContainer = ref<HTMLElement | null>(null)\n\nconst accordionClass = cn(\n  'border-t border-border-default bg-modal-panel-background'\n)\n\nconst managerStore = useComfyManagerStore()\nconst { isPackInstalled } = managerStore\nconst isInstalled = computed(() => isPackInstalled(nodePack.id))\nconst isInstalling = ref(false)\nprovide(IsInstallingKey, isInstalling)\nwhenever(isInstalled, () => {\n  isInstalling.value = false\n})\n\nconst { canTryNightlyUpdate, isNightlyPack } = usePackUpdateStatus(\n  () => nodePack\n)\n\nconst isAllInstalled = computed(() => isPackInstalled(nodePack.id))\n\nconst { checkNodeCompatibility } = useConflictDetection()\n\nconst conflictInfo = computed<ConflictDetail[]>(() => {\n  const compatibility = checkNodeCompatibility(nodePack)\n  return compatibility.conflicts ?? []\n})\n\nconst hasConflictInfo = computed(() => conflictInfo.value.length > 0)\nconst { getConflictsForPackageByID } = useConflictDetectionStore()\n\nconst { t, d, n } = useI18n()\n\n// Check compatibility once and pass to children\nconst conflictResult = computed((): ConflictDetectionResult | null => {\n  // For installed packages, use stored conflict data\n  if (isInstalled.value && nodePack.id) {\n    return getConflictsForPackageByID(nodePack.id) || null\n  }\n\n  // For non-installed packages, perform compatibility check\n  const compatibility = checkNodeCompatibility(nodePack)\n\n  if (compatibility.hasConflict) {\n    return {\n      package_id: nodePack.id || '',\n      package_name: nodePack.name || '',\n      has_conflict: true,\n      conflicts: compatibility.conflicts,\n      is_compatible: false\n    }\n  }\n\n  return null\n})\n\nconst hasCompatibilityIssues = computed(() => {\n  return conflictResult.value?.has_conflict\n})\n\nconst packageId = computed(() => nodePack.id || '')\nconst { importFailed, showImportFailedDialog } =\n  useImportFailedDetection(packageId)\n\nprovide(ImportFailedKey, {\n  importFailed,\n  showImportFailedDialog\n})\n\nconst nodeNames = computed(() => {\n  return isMergedNodePack(nodePack) ? (nodePack.comfy_nodes ?? []) : []\n})\n\nconst infoItems = computed<InfoItem[]>(() => [\n  {\n    key: 'publisher',\n    label: t('manager.createdBy'),\n    value: nodePack.publisher?.name ?? nodePack.publisher?.id\n  },\n  {\n    key: 'downloads',\n    label: t('manager.downloads'),\n    value: nodePack.downloads ? n(nodePack.downloads) : undefined\n  },\n  {\n    key: 'lastUpdated',\n    label: t('manager.lastUpdated'),\n    value: nodePack.latest_version?.createdAt\n      ? d(nodePack.latest_version.createdAt, {\n          dateStyle: 'medium'\n        })\n      : undefined\n  }\n])\n\nwhenever(\n  () => nodePack.id,\n  (nodePackId, oldNodePackId) => {\n    if (nodePackId !== oldNodePackId && scrollContainer.value) {\n      scrollContainer.value.scrollTop = 0\n    }\n  },\n  { immediate: true }\n)\n</script>\n","import { computed } from 'vue'\nimport type { Ref } from 'vue'\n\nimport type { components } from '@/types/comfyRegistryTypes'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport { isNightlyVersion } from '@/workbench/extensions/manager/utils/packUpdateStatus'\n\ntype NodePack = components['schemas']['Node']\n\ntype SelectionState = 'all-installed' | 'none-installed' | 'mixed'\n\n/**\n * Composable for managing multi-package selection states\n * Handles installation status tracking and selection state determination\n */\nexport function usePacksSelection(nodePacks: Ref<NodePack[]>) {\n  const managerStore = useComfyManagerStore()\n\n  const installedPacks = computed(() =>\n    nodePacks.value.filter((pack) => managerStore.isPackInstalled(pack.id))\n  )\n\n  const notInstalledPacks = computed(() =>\n    nodePacks.value.filter((pack) => !managerStore.isPackInstalled(pack.id))\n  )\n\n  const isAllInstalled = computed(\n    () => installedPacks.value.length === nodePacks.value.length\n  )\n\n  const isNoneInstalled = computed(\n    () => notInstalledPacks.value.length === nodePacks.value.length\n  )\n\n  const isMixed = computed(\n    () => installedPacks.value.length > 0 && notInstalledPacks.value.length > 0\n  )\n\n  const selectionState = computed<SelectionState>(() => {\n    if (isAllInstalled.value) return 'all-installed'\n    if (isNoneInstalled.value) return 'none-installed'\n    return 'mixed'\n  })\n\n  /**\n   * Nightly packs are installed packs with a non-semver version (git hash)\n   * that are also enabled\n   */\n  const nightlyPacks = computed(() =>\n    installedPacks.value.filter((pack) => {\n      if (!pack.id) return false\n      const version = managerStore.getInstalledPackVersion(pack.id)\n      const isEnabled = managerStore.isPackEnabled(pack.id)\n      return isNightlyVersion(version) && isEnabled\n    })\n  )\n\n  const hasNightlyPacks = computed(() => nightlyPacks.value.length > 0)\n\n  return {\n    installedPacks,\n    notInstalledPacks,\n    isAllInstalled,\n    isNoneInstalled,\n    isMixed,\n    selectionState,\n    nightlyPacks,\n    hasNightlyPacks\n  }\n}\n","import { computed } from 'vue'\nimport type { Ref } from 'vue'\n\nimport type { components } from '@/types/comfyRegistryTypes'\nimport { useConflictDetectionStore } from '@/workbench/extensions/manager/stores/conflictDetectionStore'\n\ntype NodePack = components['schemas']['Node']\ntype NodeStatus = components['schemas']['NodeStatus']\ntype NodeVersionStatus = components['schemas']['NodeVersionStatus']\n\nconst STATUS_PRIORITY = [\n  'NodeStatusBanned',\n  'NodeVersionStatusBanned',\n  'NodeStatusDeleted',\n  'NodeVersionStatusDeleted',\n  'NodeVersionStatusFlagged',\n  'NodeVersionStatusPending',\n  'NodeStatusActive',\n  'NodeVersionStatusActive'\n] as const\n\n/**\n * Composable for managing package status with priority\n * Handles import failures and determines the most important status\n */\nexport function usePacksStatus(nodePacks: Ref<NodePack[]>) {\n  const conflictDetectionStore = useConflictDetectionStore()\n\n  const hasImportFailed = computed(() => {\n    return nodePacks.value.some((pack) => {\n      if (!pack.id) return false\n      const conflicts = conflictDetectionStore.getConflictsForPackageByID(\n        pack.id\n      )\n      return (\n        conflicts?.conflicts.some((c) => c.type === 'import_failed') || false\n      )\n    })\n  })\n\n  const overallStatus = computed<NodeStatus | NodeVersionStatus>(() => {\n    // Check for import failed first (highest priority for installed packages)\n    if (hasImportFailed.value) {\n      // Import failed doesn't have a specific status enum, so we return active\n      // but the PackStatusMessage will handle it via hasImportFailed prop\n      return 'NodeVersionStatusActive'\n    }\n\n    // Find the highest priority status from all packages\n    for (const priorityStatus of STATUS_PRIORITY) {\n      if (nodePacks.value.some((pack) => pack.status === priorityStatus)) {\n        return priorityStatus\n      }\n    }\n\n    // Default to active if no specific status found\n    return 'NodeVersionStatusActive'\n  })\n\n  return {\n    hasImportFailed,\n    overallStatus\n  }\n}\n","<template>\n  <div\n    v-if=\"nodePacks?.length\"\n    class=\"flex scrollbar-custom h-full flex-col overflow-y-auto\"\n  >\n    <PropertiesAccordionItem :class=\"accordionClass\">\n      <template #label>\n        <span class=\"font-inter text-xs uppercase\">\n          {{ t('manager.actions') }}\n        </span>\n      </template>\n      <div class=\"flex flex-col gap-1 px-4\">\n        <!-- Mixed: Don't show any button -->\n        <div v-if=\"isMixed\" class=\"text-sm text-neutral-500\">\n          {{ $t('manager.mixedSelectionMessage') }}\n        </div>\n        <!-- All installed: Show update (if nightly) and uninstall buttons -->\n        <template v-else-if=\"isAllInstalled\">\n          <Button\n            v-if=\"hasNightlyPacks\"\n            :tooltip=\"$t('manager.tryUpdateTooltip')\"\n            variant=\"textonly\"\n            size=\"md\"\n            :disabled=\"isUpdatingSelected\"\n            @click=\"updateSelectedNightlyPacks\"\n          >\n            <DotSpinner v-if=\"isUpdatingSelected\" duration=\"1s\" :size=\"16\" />\n            <span>{{ updateSelectedLabel }}</span>\n          </Button>\n          <PackUninstallButton size=\"md\" :node-packs=\"installedPacks\" />\n        </template>\n        <!-- None installed: Show install button -->\n        <PackInstallButton\n          v-else-if=\"isNoneInstalled\"\n          size=\"md\"\n          :node-packs=\"notInstalledPacks\"\n          :has-conflict=\"hasConflicts\"\n          :conflict-info=\"conflictInfo\"\n        />\n      </div>\n    </PropertiesAccordionItem>\n\n    <PropertiesAccordionItem :class=\"accordionClass\">\n      <template #label>\n        <span class=\"font-inter text-xs uppercase\">\n          {{ t('manager.basicInfo') }}\n        </span>\n      </template>\n      <ModelInfoField :label=\"t('manager.selected')\">\n        <span>\n          <span class=\"font-bold text-blue-500\">{{ nodePacks.length }}</span>\n          {{ t('manager.packsSelected') }}\n        </span>\n      </ModelInfoField>\n      <ModelInfoField :label=\"t('g.status')\">\n        <PackStatusMessage\n          :has-import-failed=\"hasImportFailed\"\n          :status-type=\"overallStatus\"\n          :has-compatibility-issues=\"hasConflicts\"\n        />\n      </ModelInfoField>\n      <ModelInfoField :label=\"t('manager.totalNodes')\">\n        <span class=\"text-muted-foreground\">{{ totalNodesCount }}</span>\n      </ModelInfoField>\n    </PropertiesAccordionItem>\n  </div>\n  <div v-else class=\"mx-8 mt-4 flex-1 overflow-hidden text-sm\">\n    {{ $t('manager.infoPanelEmpty') }}\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useAsyncState } from '@vueuse/core'\nimport { computed, onUnmounted, ref, toRef } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport DotSpinner from '@/components/common/DotSpinner.vue'\nimport PropertiesAccordionItem from '@/components/rightSidePanel/layout/PropertiesAccordionItem.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport ModelInfoField from '@/platform/assets/components/modelInfo/ModelInfoField.vue'\nimport { useComfyRegistryStore } from '@/stores/comfyRegistryStore'\nimport type { components } from '@/types/comfyRegistryTypes'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport PackStatusMessage from '@/workbench/extensions/manager/components/manager/PackStatusMessage.vue'\nimport PackInstallButton from '@/workbench/extensions/manager/components/manager/button/PackInstallButton.vue'\nimport PackUninstallButton from '@/workbench/extensions/manager/components/manager/button/PackUninstallButton.vue'\nimport { usePacksSelection } from '@/workbench/extensions/manager/composables/nodePack/usePacksSelection'\nimport { usePacksStatus } from '@/workbench/extensions/manager/composables/nodePack/usePacksStatus'\nimport { useConflictDetection } from '@/workbench/extensions/manager/composables/useConflictDetection'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport type { ConflictDetail } from '@/workbench/extensions/manager/types/conflictDetectionTypes'\n\nconst { nodePacks } = defineProps<{\n  nodePacks: components['schemas']['Node'][]\n}>()\n\nconst { t } = useI18n()\n\nconst accordionClass = cn(\n  'border-t border-border-default bg-modal-panel-background'\n)\n\nconst managerStore = useComfyManagerStore()\nconst nodePacksRef = toRef(() => nodePacks)\n\n// Use new composables for cleaner code\nconst {\n  installedPacks,\n  notInstalledPacks,\n  isAllInstalled,\n  isNoneInstalled,\n  isMixed,\n  nightlyPacks,\n  hasNightlyPacks\n} = usePacksSelection(nodePacksRef)\n\nconst { hasImportFailed, overallStatus } = usePacksStatus(nodePacksRef)\n\n// Batch update state for nightly packs\nconst isUpdatingSelected = ref(false)\n\nasync function updateSelectedNightlyPacks() {\n  if (nightlyPacks.value.length === 0) return\n\n  isUpdatingSelected.value = true\n  try {\n    for (const pack of nightlyPacks.value) {\n      if (!pack.id) continue\n      await managerStore.updatePack.call({\n        id: pack.id,\n        version: 'nightly'\n      })\n    }\n    managerStore.updatePack.clear()\n  } catch (error) {\n    console.error('Batch nightly update failed:', error)\n  } finally {\n    isUpdatingSelected.value = false\n  }\n}\n\nconst updateSelectedLabel = computed(() =>\n  isUpdatingSelected.value ? t('g.updating') : t('manager.updateSelected')\n)\n\nconst { checkNodeCompatibility } = useConflictDetection()\nconst { getNodeDefs } = useComfyRegistryStore()\n\n// Check for conflicts in not-installed packages - keep original logic but simplified\nconst packageConflicts = computed(() => {\n  const conflictsByPackage = new Map<string, ConflictDetail[]>()\n\n  for (const pack of notInstalledPacks.value) {\n    const compatibilityCheck = checkNodeCompatibility(pack)\n    if (compatibilityCheck.hasConflict && pack.id) {\n      conflictsByPackage.set(pack.id, compatibilityCheck.conflicts)\n    }\n  }\n\n  return conflictsByPackage\n})\n\n// Aggregate all unique conflicts for display\nconst conflictInfo = computed<ConflictDetail[]>(() => {\n  const conflictMap = new Map<string, ConflictDetail>()\n\n  packageConflicts.value.forEach((conflicts) => {\n    conflicts.forEach((conflict) => {\n      const key = `${conflict.type}-${conflict.current_value}-${conflict.required_value}`\n      if (!conflictMap.has(key)) {\n        conflictMap.set(key, conflict)\n      }\n    })\n  })\n\n  return Array.from(conflictMap.values())\n})\n\nconst hasConflicts = computed(() => conflictInfo.value.length > 0)\n\nconst getPackNodes = async (pack: components['schemas']['Node']) => {\n  if (!pack.latest_version?.version) return []\n  const nodeDefs = await getNodeDefs.call({\n    packId: pack.id,\n    version: pack.latest_version?.version,\n    // Fetch all nodes.\n    // TODO: Render all nodes previews and handle pagination.\n    // For determining length, use the `totalNumberOfPages` field of response\n    limit: 8192\n  })\n  return nodeDefs?.comfy_nodes ?? []\n}\n\nconst { state: allNodeDefs } = useAsyncState(\n  () => Promise.all(nodePacks.map(getPackNodes)),\n  [],\n  {\n    immediate: true\n  }\n)\n\nconst totalNodesCount = computed(() =>\n  allNodeDefs.value.reduce(\n    (total, nodeDefs) => total + (nodeDefs?.length || 0),\n    0\n  )\n)\n\nonUnmounted(() => {\n  getNodeDefs.cancel()\n})\n</script>\n","<template>\n  <div class=\"z-0 aspect-7/3 w-full overflow-hidden\">\n    <!-- default banner show -->\n    <div v-if=\"showDefaultBanner\" class=\"size-full\">\n      <img\n        :src=\"DEFAULT_BANNER\"\n        :alt=\"$t('g.defaultBanner')\"\n        class=\"size-full object-cover\"\n      />\n    </div>\n    <!-- banner_url or icon show -->\n    <div v-else class=\"relative size-full\">\n      <!-- blur background -->\n      <div\n        v-if=\"imgSrc\"\n        class=\"absolute inset-0 bg-cover bg-center bg-no-repeat opacity-30\"\n        :style=\"{\n          backgroundImage: `url(${imgSrc})`,\n          filter: 'blur(10px)'\n        }\"\n      ></div>\n      <!-- image -->\n      <img\n        :src=\"isImageError ? DEFAULT_BANNER : imgSrc\"\n        :alt=\"nodePack.name + ' banner'\"\n        :class=\"\n          isImageError\n            ? 'relative z-10 size-full object-cover'\n            : 'relative z-10 size-full object-contain'\n        \"\n        @error=\"isImageError = true\"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\n\nimport type { components } from '@/types/comfyRegistryTypes'\n\nconst DEFAULT_BANNER = '/assets/images/fallback-gradient-avatar.svg'\n\nconst { nodePack } = defineProps<{\n  nodePack: components['schemas']['Node']\n}>()\n\nconst isImageError = ref(false)\n\nconst showDefaultBanner = computed(() => !nodePack.banner_url && !nodePack.icon)\nconst imgSrc = computed(() => nodePack.banner_url || nodePack.icon)\n</script>\n","<template>\n  <div\n    class=\"flex min-h-12 items-center justify-between px-4 py-2 text-xs/3 font-medium text-muted\"\n  >\n    <div v-if=\"nodePack.downloads\" class=\"flex items-center gap-1.5\">\n      <i class=\"pi pi-download text-muted\"></i>\n      <span>{{ formattedDownloads }}</span>\n    </div>\n    <div v-else></div>\n    <PackInstallButton\n      v-if=\"!isInstalled\"\n      :node-packs=\"[nodePack]\"\n      :is-installing=\"isInstalling\"\n      :has-conflict=\"hasConflicts\"\n      :conflict-info=\"conflictInfo\"\n    />\n    <PackEnableToggle v-else :node-pack=\"nodePack\" />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, inject } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport type { components } from '@/types/comfyRegistryTypes'\nimport PackEnableToggle from '@/workbench/extensions/manager/components/manager/button/PackEnableToggle.vue'\nimport PackInstallButton from '@/workbench/extensions/manager/components/manager/button/PackInstallButton.vue'\nimport { useConflictDetection } from '@/workbench/extensions/manager/composables/useConflictDetection'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport { IsInstallingKey } from '@/workbench/extensions/manager/types/comfyManagerTypes'\nimport type { ConflictDetail } from '@/workbench/extensions/manager/types/conflictDetectionTypes'\n\nconst { nodePack } = defineProps<{\n  nodePack: components['schemas']['Node']\n}>()\n\nconst { isPackInstalled } = useComfyManagerStore()\nconst isInstalled = computed(() => isPackInstalled(nodePack?.id))\nconst isInstalling = inject(IsInstallingKey)\n\nconst { n } = useI18n()\n\nconst formattedDownloads = computed(() =>\n  nodePack.downloads ? n(nodePack.downloads) : ''\n)\n\n// Add conflict detection for the card button\nconst { checkNodeCompatibility } = useConflictDetection()\n\n// Check for conflicts with this specific node pack\nconst conflictInfo = computed<ConflictDetail[]>(() => {\n  if (!nodePack) return []\n  const compatibilityCheck = checkNodeCompatibility(nodePack)\n  return compatibilityCheck.conflicts || []\n})\n\nconst hasConflicts = computed(() => conflictInfo.value.length > 0)\n</script>\n","<template>\n  <div\n    :class=\"\n      cn(\n        'flex size-full cursor-pointer flex-col overflow-hidden rounded-lg bg-modal-card-background transition-colors duration-200 select-none',\n        isSelected\n          ? 'ring-3 ring-modal-card-border-highlighted'\n          : 'hover:bg-modal-card-background-hovered',\n        isDisabled && 'opacity-60'\n      )\n    \"\n  >\n    <!-- Banner -->\n    <div class=\"w-full rounded-t-lg\">\n      <PackBanner :node-pack=\"nodePack\" />\n    </div>\n\n    <!-- Content -->\n    <div class=\"flex min-h-0 flex-1 flex-col rounded-lg\">\n      <div class=\"size-full px-3 py-2\">\n        <div class=\"flex size-full flex-col gap-y-1\">\n          <span\n            class=\"truncate overflow-hidden text-xs font-bold text-ellipsis\"\n          >\n            {{ nodePack.name }}\n          </span>\n          <p\n            v-if=\"nodePack.description\"\n            class=\"my-0 mb-1 line-clamp-3 min-h-12 flex-1 overflow-hidden text-xs/4 font-medium wrap-break-word text-muted\"\n          >\n            {{ nodePack.description }}\n          </p>\n          <div class=\"flex flex-col gap-y-2\">\n            <div class=\"flex flex-1 items-center gap-2\">\n              <div v-if=\"nodesLabel\" class=\"p-2 pl-0 text-xs\">\n                {{ nodesLabel }}\n              </div>\n              <PackVersionBadge\n                :node-pack=\"nodePack\"\n                :is-selected=\"isSelected\"\n                :fill=\"false\"\n                :class=\"isInstalling ? 'pointer-events-none' : ''\"\n              />\n              <div\n                v-if=\"formattedLatestVersionDate\"\n                class=\"flex items-center justify-center gap-1 px-2 py-1 text-xs font-medium text-muted\"\n              >\n                {{ formattedLatestVersionDate }}\n              </div>\n            </div>\n            <div class=\"flex\">\n              <span\n                v-if=\"publisherName\"\n                class=\"max-w-40 truncate text-xs/3 font-medium text-muted\"\n              >\n                {{ publisherName }}\n              </span>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- Footer -->\n    <div class=\"border-t border-border-default\">\n      <PackCardFooter :node-pack=\"nodePack\" :is-installing=\"isInstalling\" />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, provide } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { cn } from '@comfyorg/tailwind-utils'\nimport PackVersionBadge from '@/workbench/extensions/manager/components/manager/PackVersionBadge.vue'\nimport PackBanner from '@/workbench/extensions/manager/components/manager/packBanner/PackBanner.vue'\nimport PackCardFooter from '@/workbench/extensions/manager/components/manager/packCard/PackCardFooter.vue'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport {\n  IsInstallingKey,\n  isMergedNodePack\n} from '@/workbench/extensions/manager/types/comfyManagerTypes'\nimport type {\n  MergedNodePack,\n  RegistryPack\n} from '@/workbench/extensions/manager/types/comfyManagerTypes'\n\nconst { nodePack, isSelected = false } = defineProps<{\n  nodePack: MergedNodePack | RegistryPack\n  isSelected?: boolean\n}>()\n\nconst { d, t } = useI18n()\n\nconst { isPackInstalled, isPackEnabled, isPackInstalling } =\n  useComfyManagerStore()\n\nconst isInstalling = computed(() => isPackInstalling(nodePack?.id))\nprovide(IsInstallingKey, isInstalling)\n\nconst isInstalled = computed(() => isPackInstalled(nodePack?.id))\nconst isDisabled = computed(\n  () => isInstalled.value && !isPackEnabled(nodePack?.id)\n)\n\nconst nodesCount = computed(() =>\n  isMergedNodePack(nodePack) ? nodePack.comfy_nodes?.length : undefined\n)\nconst nodesLabel = computed(() =>\n  nodesCount.value ? t('g.nodesCount', nodesCount.value) : ''\n)\nconst publisherName = computed(() => {\n  if (!nodePack) return null\n\n  const { publisher, author } = nodePack\n  return publisher?.name ?? publisher?.id ?? author\n})\n\nconst formattedLatestVersionDate = computed(() => {\n  if (!nodePack.latest_version?.createdAt) return null\n\n  return d(new Date(nodePack.latest_version.createdAt), {\n    dateStyle: 'medium'\n  })\n})\n</script>\n","<template>\n  <div\n    class=\"flex h-full flex-col overflow-hidden rounded-lg shadow-sm\"\n    data-virtual-grid-item\n  >\n    <!-- Card header - flush with top, approximately 15% of height -->\n    <div class=\"flex w-full items-center justify-between px-4 py-3\">\n      <div class=\"flex items-center\">\n        <div class=\"flex size-6 items-center justify-center\">\n          <Skeleton class=\"size-6 rounded-full\" />\n        </div>\n        <Skeleton class=\"ml-2 h-4 w-20\" />\n      </div>\n      <Skeleton class=\"h-7 w-16 rounded-xl\" />\n    </div>\n\n    <!-- Card content with icon on left and text on right -->\n    <div class=\"flex flex-1 p-4\">\n      <!-- Left icon - 64x64 -->\n      <div class=\"mr-4 shrink-0\">\n        <Skeleton class=\"size-16 rounded-lg\" />\n      </div>\n\n      <!-- Right content -->\n      <div class=\"flex flex-1 flex-col overflow-hidden\">\n        <!-- Title -->\n        <Skeleton class=\"mb-2 h-4 w-4/5\" />\n\n        <!-- Description -->\n        <div class=\"mb-3\">\n          <Skeleton class=\"mb-1 h-3 w-full\" />\n          <Skeleton class=\"mb-1 h-3 w-19/20\" />\n          <Skeleton class=\"h-3 w-9/10\" />\n        </div>\n\n        <!-- Tags/Badges -->\n        <div class=\"flex gap-2\">\n          <Skeleton class=\"h-6 w-16 rounded-xl\" />\n          <Skeleton class=\"h-6 w-20 rounded-xl\" />\n        </div>\n      </div>\n    </div>\n\n    <!-- Card footer - similar to header -->\n    <div class=\"flex w-full items-center justify-between px-5 py-4\">\n      <Skeleton class=\"h-3 w-16\" />\n      <Skeleton class=\"h-3 w-24\" />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport Skeleton from '@/components/ui/skeleton/Skeleton.vue'\n</script>\n","<template>\n  <div :style=\"gridStyle\">\n    <PackCardSkeleton v-for=\"n in skeletonCardCount\" :key=\"n\" />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport PackCardSkeleton from '@/workbench/extensions/manager/components/manager/skeleton/PackCardSkeleton.vue'\n\nconst { skeletonCardCount = 12, gridStyle } = defineProps<{\n  skeletonCardCount?: number\n  gridStyle: {\n    display: string\n    gridTemplateColumns: string\n    padding: string\n    gap: string\n  }\n}>()\n</script>\n","<template>\n  <div class=\"flex flex-col items-center gap-3 p-8\">\n    <i class=\"icon-[lucide--triangle-alert] text-4xl text-warning-background\" />\n    <h3 class=\"text-base font-semibold\">\n      {{ $t('manager.unresolvedNodes.title') }}\n    </h3>\n    <p class=\"text-center text-sm text-muted-foreground\">\n      {{ $t('manager.unresolvedNodes.message') }}\n    </p>\n    <ul class=\"mt-2 flex flex-col gap-1 rounded-lg bg-secondary-background p-2\">\n      <li\n        v-for=\"name in nodeNames\"\n        :key=\"name\"\n        class=\"px-3 py-1.5 font-mono text-sm\"\n      >\n        {{ name }}\n      </li>\n    </ul>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\ndefineProps<{\n  nodeNames: string[]\n}>()\n</script>\n","import { createSharedComposable, useEventListener } from '@vueuse/core'\nimport { computed, onUnmounted, ref } from 'vue'\n\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { ComfyWorkflowJSON } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { app } from '@/scripts/app'\nimport { useComfyRegistryStore } from '@/stores/comfyRegistryStore'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { useSystemStatsStore } from '@/stores/systemStatsStore'\nimport type { components } from '@/types/comfyRegistryTypes'\nimport { mapAllNodes } from '@/utils/graphTraversalUtil'\nimport { useNodePacks } from '@/workbench/extensions/manager/composables/nodePack/useNodePacks'\n\nexport type WorkflowPack = {\n  id: ComfyWorkflowJSON['nodes'][number]['properties']['cnr_id']\n\n  version: ComfyWorkflowJSON['nodes'][number]['properties']['ver']\n}\n\nconst CORE_NODES_PACK_NAME = 'comfy-core'\n\n/**\n * Handles parsing node pack metadata from nodes on the graph and fetching the\n * associated node packs from the registry.\n * This is a shared singleton composable - all components use the same instance.\n */\nconst _useWorkflowPacks = () => {\n  const nodeDefStore = useNodeDefStore()\n  const systemStatsStore = useSystemStatsStore()\n  const { inferPackFromNodeName } = useComfyRegistryStore()\n\n  const workflowPacks = ref<WorkflowPack[]>([])\n  const unresolvedNodeNames = ref<string[]>([])\n\n  /** A fetch asked for before the graph existed, owed a retry on `configured`. */\n  let fetchDeferredUntilConfigured = false\n\n  let fetchGeneration = 0\n\n  const getWorkflowNodePackId = (node: LGraphNode): string | undefined => {\n    if (typeof node.properties.cnr_id === 'string') {\n      return node.properties.cnr_id\n    }\n    if (typeof node.properties.aux_id === 'string') {\n      return node.properties.aux_id\n    }\n    return undefined\n  }\n\n  /**\n   * Clean the version string to be used in the registry search.\n   * Removes the leading 'v' and trims whitespace and line terminators.\n   */\n  const cleanVersionString = (version: string) =>\n    version.replace(/^v/, '').trim()\n\n  /**\n   * Infer the pack for a node by searching the registry for packs that have nodes\n   * with the same name.\n   */\n  const inferPack = async (\n    node: LGraphNode\n  ): Promise<WorkflowPack | undefined> => {\n    const nodeName = node.type\n\n    if (nodeDefStore.nodeDefsByName[nodeName]?.isCoreNode) {\n      if (!systemStatsStore.systemStats) {\n        await systemStatsStore.refetchSystemStats()\n      }\n      return {\n        id: CORE_NODES_PACK_NAME,\n        version:\n          systemStatsStore.systemStats?.system.comfyui_version ?? 'nightly'\n      }\n    }\n\n    // Query the registry to find which pack provides this node\n    const pack = await inferPackFromNodeName.call(nodeName)\n\n    if (pack) {\n      return {\n        id: pack.id,\n        version: pack.latest_version?.version ?? 'nightly'\n      }\n    }\n\n    // No pack found - this node doesn't exist in the registry or couldn't be\n    // extracted from the parent node pack successfully\n    return undefined\n  }\n\n  /**\n   * Map a workflow node to its pack using the node pack metadata.\n   * If the node pack metadata is not available, fallback to searching the\n   * registry for packs that have nodes with the same name.\n   */\n  const workflowNodeToPack = async (\n    node: LGraphNode\n  ): Promise<WorkflowPack | undefined> => {\n    const packId = getWorkflowNodePackId(node)\n    if (!packId) return inferPack(node) // Fallback\n    if (packId === CORE_NODES_PACK_NAME) return undefined\n\n    const version =\n      typeof node.properties.ver === 'string'\n        ? cleanVersionString(node.properties.ver)\n        : undefined\n\n    return {\n      id: packId,\n      version\n    }\n  }\n\n  /**\n   * Get the node packs for all nodes in the workflow (including subgraphs).\n   * Nodes that have no local definition and no registry match are tracked\n   * as unresolved so downstream consumers can surface them to the user.\n   *\n   * @returns `undefined` when the root graph does not exist yet.\n   */\n  const getWorkflowPacks = async () => {\n    const rootGraph = app.rootGraphOrUndefined\n    if (!rootGraph) return undefined\n\n    const resolvedPacks: WorkflowPack[] = []\n    const unresolved: string[] = []\n\n    await Promise.all(\n      mapAllNodes(rootGraph, async (node) => {\n        const pack = await workflowNodeToPack(node)\n        if (pack) {\n          resolvedPacks.push(pack)\n        }\n      })\n    )\n\n    return { resolvedPacks, unresolved }\n  }\n\n  const packsToUniqueIds = (packs: WorkflowPack[]) =>\n    packs.reduce((acc, pack) => {\n      if (pack.id) acc.add(pack.id)\n      return acc\n    }, new Set<string>())\n\n  const workflowPacksIds = computed(() =>\n    Array.from(packsToUniqueIds(workflowPacks.value))\n  )\n\n  const { startFetch, cleanup, error, isLoading, nodePacks, isReady } =\n    useNodePacks(workflowPacksIds)\n\n  const isIdInWorkflow = (packId: string) =>\n    workflowPacksIds.value.includes(packId)\n\n  const filterWorkflowPack = (packs: components['schemas']['Node'][]) =>\n    packs.filter((pack) => !!pack.id && isIdInWorkflow(pack.id))\n\n  const startFetchWorkflowPacks = async () => {\n    const generation = ++fetchGeneration\n\n    const parsed = await getWorkflowPacks()\n    if (generation !== fetchGeneration) return\n\n    fetchDeferredUntilConfigured = !parsed\n    if (!parsed) return\n\n    workflowPacks.value = parsed.resolvedPacks\n    unresolvedNodeNames.value = [...new Set(parsed.unresolved)]\n    await startFetch()\n  }\n\n  // Retry on `configured`, not on `isGraphReady`: `setup()` installs an empty\n  // graph before the workflow is configured into it.\n  useEventListener(\n    () => (app.isGraphReady ? app.rootGraph.events : undefined),\n    'configured',\n    () => {\n      if (!fetchDeferredUntilConfigured) return\n      startFetchWorkflowPacks().catch((err: unknown) => {\n        error.value = err instanceof Error ? err : new Error(String(err))\n      })\n    }\n  )\n\n  onUnmounted(() => {\n    cleanup()\n  })\n\n  return {\n    error,\n    isLoading,\n    isReady,\n    workflowPacks: nodePacks,\n    unresolvedNodeNames,\n    startFetchWorkflowPacks,\n    filterWorkflowPack\n  }\n}\n\nexport const useWorkflowPacks = createSharedComposable(_useWorkflowPacks)\n","import { groupBy } from 'es-toolkit/compat'\nimport { createSharedComposable, useEventListener } from '@vueuse/core'\nimport { computed, ref, watch } from 'vue'\n\nimport type { NodeProperty } from '@/lib/litegraph/src/LGraphNode'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { app } from '@/scripts/app'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport type { components } from '@/types/comfyRegistryTypes'\nimport { collectAllNodes } from '@/utils/graphTraversalUtil'\nimport { useWorkflowPacks } from '@/workbench/extensions/manager/composables/nodePack/useWorkflowPacks'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\n\n/**\n * Composable to find missing NodePacks from workflow\n * Automatically fetches workflow pack data when initialized\n * This is a shared singleton composable - all components use the same instance\n */\nexport const useMissingNodes = createSharedComposable(() => {\n  const nodeDefStore = useNodeDefStore()\n  const comfyManagerStore = useComfyManagerStore()\n  const workflowStore = useWorkflowStore()\n  const {\n    workflowPacks,\n    unresolvedNodeNames,\n    isLoading,\n    error,\n    startFetchWorkflowPacks\n  } = useWorkflowPacks()\n\n  const filterMissingPacks = (packs: components['schemas']['Node'][]) =>\n    packs.filter((pack) => !comfyManagerStore.isPackInstalled(pack.id))\n\n  // Filter only uninstalled packs from workflow packs\n  const missingNodePacks = computed(() => {\n    if (!workflowPacks.value.length) return []\n    return filterMissingPacks(workflowPacks.value)\n  })\n\n  /**\n   * Check if a pack is the ComfyUI builtin node pack (nodes that come pre-installed)\n   * @param packId - The id of the pack to check\n   * @returns True if the pack is the comfy-core pack, false otherwise\n   */\n  const isCorePack = (packId: NodeProperty) => {\n    return packId === 'comfy-core'\n  }\n\n  /**\n   * Check if a node is a missing core node\n   * A missing core node is a node that is in the workflow and originates from\n   * the comfy-core pack (pre-installed) but not registered in the node def\n   * store (the node def was not found on the server)\n   * @param node - The node to check\n   * @returns True if the node is a missing core node, false otherwise\n   */\n  const isMissingCoreNode = (node: LGraphNode) => {\n    const packId = node.properties.cnr_id\n    if (packId === undefined || !isCorePack(packId)) return false\n    const nodeName = node.type\n    const isRegisteredNodeDef = !!nodeDefStore.nodeDefsByName[nodeName]\n    return !isRegisteredNodeDef\n  }\n\n  const graphConfiguredCount = ref(0)\n  useEventListener(\n    () => (app.isGraphReady ? app.rootGraph.events : undefined),\n    'configured',\n    () => {\n      graphConfiguredCount.value++\n    }\n  )\n\n  const missingCoreNodes = computed<Record<string, LGraphNode[]>>(() => {\n    void graphConfiguredCount.value\n\n    const rootGraph = app.rootGraphOrUndefined\n    if (!rootGraph) return {}\n\n    const missingNodes = collectAllNodes(rootGraph, isMissingCoreNode)\n    return groupBy(missingNodes, (node) => String(node.properties.ver || ''))\n  })\n\n  // Check if workflow has any missing nodes\n  const hasMissingNodes = computed(() => {\n    return (\n      missingNodePacks.value.length > 0 ||\n      Object.keys(missingCoreNodes.value).length > 0 ||\n      unresolvedNodeNames.value.length > 0\n    )\n  })\n\n  // Re-fetch workflow packs when active workflow changes\n  watch(\n    () => workflowStore.activeWorkflow,\n    async () => {\n      await startFetchWorkflowPacks()\n    },\n    { immediate: true }\n  )\n\n  return {\n    missingNodePacks,\n    missingCoreNodes,\n    unresolvedNodeNames,\n    hasMissingNodes,\n    isLoading,\n    error\n  }\n})\n","import { computed, onMounted } from 'vue'\n\nimport type { components } from '@/types/comfyRegistryTypes'\nimport { useInstalledPacks } from '@/workbench/extensions/manager/composables/nodePack/useInstalledPacks'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport { getPackUpdateStatus } from '@/workbench/extensions/manager/utils/packUpdateStatus'\n\n/**\n * Composable to find NodePacks that have updates available\n * Automatically fetches installed pack data when initialized\n */\nexport const useUpdateAvailableNodes = () => {\n  const comfyManagerStore = useComfyManagerStore()\n  const { installedPacks, isLoading, error, startFetchInstalled } =\n    useInstalledPacks()\n\n  const isOutdatedPack = (pack: components['schemas']['Node']) =>\n    getPackUpdateStatus(pack, comfyManagerStore).isUpdateAvailable\n\n  const filterOutdatedPacks = (packs: components['schemas']['Node'][]) =>\n    packs.filter(isOutdatedPack)\n\n  // Filter only outdated packs from installed packs\n  const updateAvailableNodePacks = computed(() => {\n    if (!installedPacks.value.length) return []\n    return filterOutdatedPacks(installedPacks.value)\n  })\n\n  // Filter only enabled outdated packs\n  const enabledUpdateAvailableNodePacks = computed(() => {\n    return updateAvailableNodePacks.value.filter((pack) =>\n      comfyManagerStore.isPackEnabled(pack.id)\n    )\n  })\n\n  // Check if there are any enabled outdated packs\n  const hasUpdateAvailable = computed(() => {\n    return enabledUpdateAvailableNodePacks.value.length > 0\n  })\n\n  // Check if there are disabled packs with updates\n  const hasDisabledUpdatePacks = computed(() => {\n    return (\n      updateAvailableNodePacks.value.length >\n      enabledUpdateAvailableNodePacks.value.length\n    )\n  })\n\n  // Automatically fetch installed pack data when composable is used\n  onMounted(async () => {\n    if (!installedPacks.value.length && !isLoading.value) {\n      await startFetchInstalled()\n    }\n  })\n\n  return {\n    updateAvailableNodePacks,\n    enabledUpdateAvailableNodePacks,\n    hasUpdateAvailable,\n    hasDisabledUpdatePacks,\n    isLoading,\n    error\n  }\n}\n","import type { components } from '@/types/comfyRegistryTypes'\nimport { SortableAlgoliaField } from '@/workbench/extensions/manager/types/comfyManagerTypes'\n\ntype NodePack = components['schemas']['Node']\n\nexport interface SortableField<T = string> {\n  id: T\n  label: string\n  direction: 'asc' | 'desc'\n}\n\nexport const PACK_SORTABLE_FIELDS: SortableField[] = [\n  { id: SortableAlgoliaField.Downloads, label: 'Downloads', direction: 'desc' },\n  { id: SortableAlgoliaField.Created, label: 'Created', direction: 'desc' },\n  { id: SortableAlgoliaField.Updated, label: 'Updated', direction: 'desc' },\n  { id: SortableAlgoliaField.Publisher, label: 'Publisher', direction: 'asc' },\n  { id: SortableAlgoliaField.Name, label: 'Name', direction: 'asc' }\n]\n\nconst toTime = (value: string | undefined | null): number =>\n  value ? new Date(value).getTime() : 0\n\nexport const getPackSortValue = (\n  pack: NodePack,\n  field: string\n): string | number => {\n  switch (field) {\n    case SortableAlgoliaField.Downloads:\n      return pack.downloads ?? 0\n    case SortableAlgoliaField.Created:\n      return toTime(pack.created_at)\n    case SortableAlgoliaField.Updated:\n      return toTime(pack.latest_version?.createdAt)\n    case SortableAlgoliaField.Publisher:\n      return pack.publisher?.name ?? ''\n    case SortableAlgoliaField.Name:\n      return pack.name ?? ''\n    default:\n      return 0\n  }\n}\n","import { whenever } from '@vueuse/core'\nimport { orderBy } from 'es-toolkit/compat'\nimport { computed, toValue } from 'vue'\nimport type { MaybeRefOrGetter } from 'vue'\n\nimport type { components } from '@/types/comfyRegistryTypes'\nimport { useInstalledPacks } from '@/workbench/extensions/manager/composables/nodePack/useInstalledPacks'\nimport { useWorkflowPacks } from '@/workbench/extensions/manager/composables/nodePack/useWorkflowPacks'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport { useConflictDetectionStore } from '@/workbench/extensions/manager/stores/conflictDetectionStore'\nimport { ManagerTab } from '@/workbench/extensions/manager/types/comfyManagerTypes'\nimport {\n  PACK_SORTABLE_FIELDS,\n  getPackSortValue\n} from '@/workbench/extensions/manager/utils/nodePackSort'\nimport { getPackUpdateStatus } from '@/workbench/extensions/manager/utils/packUpdateStatus'\n\ntype NodePack = components['schemas']['Node']\n\nexport function useManagerDisplayPacks(\n  selectedTabId: MaybeRefOrGetter<string | null>,\n  searchResults: MaybeRefOrGetter<NodePack[]>,\n  searchQuery: MaybeRefOrGetter<string>,\n  sortField: MaybeRefOrGetter<string>\n) {\n  const comfyManagerStore = useComfyManagerStore()\n  const conflictDetectionStore = useConflictDetectionStore()\n\n  const {\n    startFetchInstalled,\n    filterInstalledPack,\n    installedPacks,\n    isLoading: isLoadingInstalled,\n    isReady: installedPacksReady\n  } = useInstalledPacks()\n\n  const {\n    startFetchWorkflowPacks,\n    filterWorkflowPack,\n    workflowPacks,\n    isLoading: isLoadingWorkflow,\n    isReady: workflowPacksReady\n  } = useWorkflowPacks()\n\n  const tabType = computed(() => toValue(selectedTabId) as ManagerTab | null)\n  const isEmptySearch = computed(() => toValue(searchQuery) === '')\n\n  const sortPacks = (packs: NodePack[]) => {\n    const field = toValue(sortField)\n    if (!field || packs.length === 0) return packs\n\n    const fieldConfig = PACK_SORTABLE_FIELDS.find((f) => f.id === field)\n    const direction = fieldConfig?.direction || 'desc'\n\n    return orderBy(\n      packs,\n      [(pack) => getPackSortValue(pack, field)],\n      [direction]\n    )\n  }\n\n  // Filter functions\n  const filterNotInstalled = (packs: NodePack[]) =>\n    packs.filter((p) => !comfyManagerStore.isPackInstalled(p.id))\n\n  const filterConflicting = (packs: NodePack[]) =>\n    packs.filter(\n      (p) =>\n        !!p.id &&\n        conflictDetectionStore.conflictedPackages.some(\n          (c) => c.package_id === p.id\n        )\n    )\n\n  const filterOutdated = (packs: NodePack[]) =>\n    packs.filter(\n      (p) => getPackUpdateStatus(p, comfyManagerStore).isUpdateAvailable\n    )\n\n  // Data fetching triggers using whenever\n  const needsInstalledPacks = computed(() =>\n    [\n      ManagerTab.AllInstalled,\n      ManagerTab.UpdateAvailable,\n      ManagerTab.Conflicting\n    ].includes(tabType.value as ManagerTab)\n  )\n\n  const needsWorkflowPacks = computed(() =>\n    [ManagerTab.Workflow, ManagerTab.Missing].includes(\n      tabType.value as ManagerTab\n    )\n  )\n\n  // Sorting only applies to fully-fetched tabs with no active search; paged\n  // search/listing results (All, NotInstalled) are shown in the API's order.\n  const isSortable = computed(\n    () =>\n      isEmptySearch.value &&\n      (needsInstalledPacks.value || needsWorkflowPacks.value)\n  )\n\n  whenever(\n    () =>\n      needsInstalledPacks.value &&\n      !installedPacksReady.value &&\n      !isLoadingInstalled.value,\n    () => startFetchInstalled()\n  )\n\n  whenever(\n    () =>\n      needsWorkflowPacks.value &&\n      !workflowPacksReady.value &&\n      !isLoadingWorkflow.value,\n    () => startFetchWorkflowPacks()\n  )\n\n  // For Missing tab, also need installed packs to determine what's missing\n  whenever(\n    () =>\n      tabType.value === ManagerTab.Missing &&\n      !installedPacksReady.value &&\n      !isLoadingInstalled.value,\n    () => startFetchInstalled()\n  )\n\n  // Single computed for display packs - replaces 7 watches\n  const displayPacks = computed(() => {\n    const tab = tabType.value\n    const hasSearch = !isEmptySearch.value\n    const results = toValue(searchResults)\n\n    switch (tab) {\n      case ManagerTab.All:\n        return results\n\n      case ManagerTab.NotInstalled:\n        return filterNotInstalled(results)\n\n      case ManagerTab.AllInstalled:\n        return hasSearch\n          ? filterInstalledPack(results)\n          : sortPacks(installedPacks.value)\n\n      case ManagerTab.UpdateAvailable:\n        return hasSearch\n          ? filterOutdated(filterInstalledPack(results))\n          : sortPacks(filterOutdated(installedPacks.value))\n\n      case ManagerTab.Conflicting:\n        return hasSearch\n          ? filterConflicting(filterInstalledPack(results))\n          : sortPacks(filterConflicting(installedPacks.value))\n\n      case ManagerTab.Workflow:\n        return hasSearch\n          ? filterWorkflowPack(results)\n          : sortPacks(workflowPacks.value)\n\n      case ManagerTab.Missing:\n        return hasSearch\n          ? filterNotInstalled(filterWorkflowPack(results))\n          : sortPacks(filterNotInstalled(workflowPacks.value))\n\n      case ManagerTab.Unresolved:\n        return []\n\n      default:\n        return results\n    }\n  })\n\n  // Loading state - single computed\n  const isLoading = computed(() => {\n    const tab = tabType.value\n    if (\n      [\n        ManagerTab.AllInstalled,\n        ManagerTab.UpdateAvailable,\n        ManagerTab.Conflicting\n      ].includes(tab as ManagerTab)\n    ) {\n      return isLoadingInstalled.value\n    }\n    if ([ManagerTab.Workflow, ManagerTab.Missing].includes(tab as ManagerTab)) {\n      return isLoadingWorkflow.value\n    }\n    return false\n  })\n\n  const missingNodePacks = computed(() =>\n    filterNotInstalled(workflowPacks.value)\n  )\n\n  return {\n    displayPacks,\n    isSortable,\n    isLoading,\n    isLoadingInstalled,\n    isLoadingWorkflow,\n    installedPacks,\n    workflowPacks,\n    filterInstalledPack,\n    filterWorkflowPack,\n    missingNodePacks\n  }\n}\n","import type { ManagerState } from '@/workbench/extensions/manager/types/comfyManagerTypes'\nimport {\n  ManagerTab,\n  SortableAlgoliaField\n} from '@/workbench/extensions/manager/types/comfyManagerTypes'\n\nconst STORAGE_KEY = 'Comfy.Manager.UI.State'\n\nexport const useManagerStatePersistence = () => {\n  /**\n   * Load the UI state from localStorage.\n   */\n  const loadStoredState = (): ManagerState => {\n    try {\n      const stored = localStorage.getItem(STORAGE_KEY)\n      if (stored) {\n        return JSON.parse(stored)\n      }\n    } catch (e) {\n      console.error('Failed to load manager UI state:', e)\n    }\n    return {\n      selectedTabId: ManagerTab.All,\n      searchQuery: '',\n      searchMode: 'packs',\n      sortField: SortableAlgoliaField.Downloads\n    }\n  }\n\n  /**\n   * Persist the UI state to localStorage.\n   */\n  const persistState = (state: ManagerState) => {\n    localStorage.setItem(STORAGE_KEY, JSON.stringify(state))\n  }\n\n  /**\n   * Reset the UI state to the default values.\n   */\n  const reset = () => {\n    persistState({\n      selectedTabId: ManagerTab.All,\n      searchQuery: '',\n      searchMode: 'packs',\n      sortField: SortableAlgoliaField.Downloads\n    })\n  }\n\n  return {\n    loadStoredState,\n    persistState,\n    reset\n  }\n}\n","import QuickLRU from '@alloc/quick-lru'\nimport type {\n  SearchQuery,\n  SearchResponse\n} from 'algoliasearch/dist/lite/browser'\nimport { liteClient as algoliasearch } from 'algoliasearch/dist/lite/builds/browser'\nimport { memoize, omit } from 'es-toolkit/compat'\n\nimport {\n  MIN_CHARS_FOR_SUGGESTIONS_ALGOLIA,\n  SEARCH_CACHE_MAX_SIZE\n} from '@/constants/searchConstants'\nimport type {\n  AlgoliaNodePack,\n  NodesIndexSuggestion,\n  SearchAttribute,\n  SearchNodePacksParams\n} from '@/types/algoliaTypes'\nimport type { components } from '@/types/comfyRegistryTypes'\nimport type {\n  NodePackSearchProvider,\n  SearchPacksResult\n} from '@/types/searchServiceTypes'\nimport { paramsToCacheKey } from '@/utils/formatUtil'\n\ntype RegistryNodePack = components['schemas']['Node']\n\nconst RETRIEVE_ATTRIBUTES: SearchAttribute[] = [\n  'comfy_nodes',\n  'name',\n  'description',\n  'latest_version',\n  'status',\n  'publisher_id',\n  'total_install',\n  'create_time',\n  'update_time',\n  'license',\n  'repository_url',\n  'latest_version_status',\n  'comfy_node_extract_status',\n  'id',\n  'icon_url',\n  'github_stars',\n  'supported_os',\n  'supported_comfyui_version',\n  'supported_comfyui_frontend_version',\n  'supported_accelerators',\n  'banner_url'\n]\n\nconst searchPacksCache = new QuickLRU<string, SearchPacksResult>({\n  maxSize: SEARCH_CACHE_MAX_SIZE\n})\n\nconst toRegistryLatestVersion = (\n  algoliaNode: AlgoliaNodePack\n): RegistryNodePack['latest_version'] => {\n  return {\n    version: algoliaNode.latest_version,\n    createdAt: algoliaNode.update_time,\n    status: algoliaNode.latest_version_status,\n    comfy_node_extract_status:\n      algoliaNode.comfy_node_extract_status ?? undefined\n  }\n}\n\nconst toRegistryPublisher = (\n  algoliaNode: AlgoliaNodePack\n): RegistryNodePack['publisher'] => {\n  return {\n    id: algoliaNode.publisher_id,\n    name: algoliaNode.publisher_id\n  }\n}\n\n/**\n * Convert from node pack in Algolia format to Comfy Registry format\n */\nconst toRegistryPack = memoize(\n  (\n    algoliaNode: AlgoliaNodePack\n  ): RegistryNodePack & { comfy_nodes: string[] } => {\n    return {\n      id: algoliaNode.id ?? algoliaNode.objectID,\n      name: algoliaNode.name,\n      description: algoliaNode.description,\n      repository: algoliaNode.repository_url,\n      license: algoliaNode.license,\n      downloads: algoliaNode.total_install,\n      status: algoliaNode.status,\n      icon: algoliaNode.icon_url,\n      latest_version: toRegistryLatestVersion(algoliaNode),\n      publisher: toRegistryPublisher(algoliaNode),\n      created_at: algoliaNode.create_time,\n      category: algoliaNode.category,\n      author: algoliaNode.author,\n      tags: algoliaNode.tags,\n      github_stars: algoliaNode.github_stars,\n      supported_os: algoliaNode.supported_os,\n      supported_comfyui_version: algoliaNode.supported_comfyui_version,\n      supported_comfyui_frontend_version:\n        algoliaNode.supported_comfyui_frontend_version,\n      supported_accelerators: algoliaNode.supported_accelerators,\n      banner_url: algoliaNode.banner_url,\n      comfy_nodes: algoliaNode.comfy_nodes\n    }\n  },\n  (algoliaNode: AlgoliaNodePack) => algoliaNode.id\n)\n\nexport const useAlgoliaSearchProvider = (): NodePackSearchProvider => {\n  const searchClient = algoliasearch(__ALGOLIA_APP_ID__, __ALGOLIA_API_KEY__)\n\n  /**\n   * Search for node packs in Algolia (internal method)\n   */\n  const searchPacksInternal = async (\n    query: string,\n    params: SearchNodePacksParams\n  ): Promise<SearchPacksResult> => {\n    const { pageSize, pageNumber } = params\n    const rest = omit(params, ['pageSize', 'pageNumber'])\n\n    const requests: SearchQuery[] = [\n      {\n        query,\n        indexName: 'nodes_index',\n        attributesToRetrieve: RETRIEVE_ATTRIBUTES,\n        ...rest,\n        hitsPerPage: pageSize,\n        page: pageNumber\n      }\n    ]\n\n    const shouldQuerySuggestions =\n      query.length >= MIN_CHARS_FOR_SUGGESTIONS_ALGOLIA\n\n    // If the query is long enough, also query the suggestions index\n    if (shouldQuerySuggestions) {\n      requests.push({\n        indexName: 'nodes_index_query_suggestions',\n        query\n      })\n    }\n\n    const { results } = await searchClient.search<\n      AlgoliaNodePack | NodesIndexSuggestion\n    >({\n      requests,\n      strategy: 'none'\n    })\n\n    const [nodePacks, querySuggestions] = results as [\n      SearchResponse<AlgoliaNodePack>,\n      SearchResponse<NodesIndexSuggestion>?\n    ]\n\n    // Convert Algolia hits to RegistryNodePack format\n    const registryPacks = nodePacks.hits.map(toRegistryPack)\n\n    // Extract query suggestions from search results\n    const suggestions =\n      querySuggestions?.hits.map((suggestion) => ({\n        query: suggestion.query,\n        popularity: suggestion.popularity\n      })) ?? []\n\n    return {\n      nodePacks: registryPacks,\n      querySuggestions: suggestions\n    }\n  }\n\n  /**\n   * Search for node packs in Algolia with caching.\n   */\n  const searchPacks = async (\n    query: string,\n    params: SearchNodePacksParams\n  ): Promise<SearchPacksResult> => {\n    const cacheKey = paramsToCacheKey({ query, ...params })\n    const cachedResult = searchPacksCache.get(cacheKey)\n    if (cachedResult !== undefined) return cachedResult\n\n    const result = await searchPacksInternal(query, params)\n    searchPacksCache.set(cacheKey, result)\n    return result\n  }\n\n  const clearSearchCache = () => {\n    searchPacksCache.clear()\n  }\n\n  return {\n    searchPacks,\n    clearSearchCache\n  }\n}\n","import { useComfyRegistryStore } from '@/stores/comfyRegistryStore'\nimport type { SearchNodePacksParams } from '@/types/algoliaTypes'\nimport type {\n  NodePackSearchProvider,\n  SearchPacksResult\n} from '@/types/searchServiceTypes'\n\n/**\n * Search provider for the Comfy Registry.\n * Uses public Comfy Registry API.\n */\nexport const useComfyRegistrySearchProvider = (): NodePackSearchProvider => {\n  const registryStore = useComfyRegistryStore()\n\n  /**\n   * Search for node packs using the Comfy Registry API.\n   */\n  const searchPacks = async (\n    query: string,\n    params: SearchNodePacksParams\n  ): Promise<SearchPacksResult> => {\n    const { pageSize, pageNumber, restrictSearchableAttributes } = params\n\n    // For empty queries, use the cached listAllPacks endpoint instead of search\n    if (!query || query.trim() === '') {\n      const listParams = {\n        limit: pageSize,\n        page: pageNumber + 1 // Registry API uses 1-based pagination\n        // Note: omitting 'latest' parameter defaults to cached result\n      }\n\n      const listResult = await registryStore.listAllPacks.call(listParams)\n      const nodePacks = listResult?.nodes ?? []\n\n      return {\n        nodePacks,\n        querySuggestions: []\n      }\n    }\n\n    // For non-empty queries, use the search endpoint\n    const isNodeSearch = restrictSearchableAttributes?.includes('comfy_nodes')\n\n    const searchParams = {\n      search: isNodeSearch ? undefined : query,\n      comfy_node_search: isNodeSearch ? query : undefined,\n      limit: pageSize,\n      page: pageNumber + 1\n    }\n\n    const searchResult = await registryStore.search.call(searchParams)\n    const nodePacks = searchResult?.nodes ?? []\n\n    return {\n      nodePacks,\n      querySuggestions: [] // Registry doesn't support query suggestions\n    }\n  }\n\n  const clearSearchCache = () => {\n    registryStore.search.clear()\n    registryStore.listAllPacks.clear()\n  }\n\n  return {\n    searchPacks,\n    clearSearchCache\n  }\n}\n","import { useAlgoliaSearchProvider } from '@/services/providers/algoliaSearchProvider'\nimport { useComfyRegistrySearchProvider } from '@/services/providers/registrySearchProvider'\nimport type { SearchNodePacksParams } from '@/types/algoliaTypes'\nimport type {\n  NodePackSearchProvider,\n  SearchPacksResult\n} from '@/types/searchServiceTypes'\nimport { toError } from '@/utils/errorUtil'\n\ninterface ProviderState {\n  provider: NodePackSearchProvider\n  name: string\n  isHealthy: boolean\n  lastError?: Error\n  lastAttempt?: Date\n  consecutiveFailures: number\n}\n\nconst CIRCUIT_BREAKER_THRESHOLD = 3 // Number of failures before circuit opens\nconst CIRCUIT_BREAKER_TIMEOUT = 60000 // 1 minute before retry\n\n/**\n * API Gateway for registry search providers with circuit breaker pattern.\n * Acts as a single entry point that routes search requests to appropriate providers\n * and handles failures gracefully by falling back to alternative providers.\n *\n * Implements:\n * - Gateway pattern: Single entry point for all search requests\n * - Circuit breaker: Prevents repeated calls to failed services\n * - Automatic failover: Cascades through providers on failure\n */\nexport const useRegistrySearchGateway = (): NodePackSearchProvider => {\n  const providers: ProviderState[] = []\n  let activeProviderIndex = 0\n\n  // Initialize providers in priority order\n  try {\n    providers.push({\n      provider: useAlgoliaSearchProvider(),\n      name: 'Algolia',\n      isHealthy: true,\n      consecutiveFailures: 0\n    })\n  } catch (error) {\n    console.warn('Failed to initialize Algolia provider:', error)\n  }\n\n  providers.push({\n    provider: useComfyRegistrySearchProvider(),\n    name: 'ComfyRegistry',\n    isHealthy: true,\n    consecutiveFailures: 0\n  })\n\n  // TODO: Add an \"offline\" provider that operates on a local cache of the registry.\n\n  /**\n   * Check if a provider's circuit breaker should be closed (available to try)\n   */\n  const isCircuitClosed = (providerState: ProviderState): boolean => {\n    if (providerState.consecutiveFailures < CIRCUIT_BREAKER_THRESHOLD) {\n      return true\n    }\n\n    // Check if enough time has passed to retry\n    if (providerState.lastAttempt) {\n      const timeSinceLastAttempt =\n        Date.now() - providerState.lastAttempt.getTime()\n      if (timeSinceLastAttempt > CIRCUIT_BREAKER_TIMEOUT) {\n        return true\n      }\n    }\n\n    return false\n  }\n\n  /**\n   * Record a successful call to a provider\n   */\n  const recordSuccess = (providerState: ProviderState) => {\n    providerState.isHealthy = true\n    providerState.consecutiveFailures = 0\n    providerState.lastError = undefined\n  }\n\n  /**\n   * Record a failed call to a provider\n   */\n  const recordFailure = (providerState: ProviderState, error: Error) => {\n    providerState.consecutiveFailures++\n    providerState.lastError = error\n    providerState.lastAttempt = new Date()\n\n    if (providerState.consecutiveFailures >= CIRCUIT_BREAKER_THRESHOLD) {\n      providerState.isHealthy = false\n      console.warn(\n        `${providerState.name} provider circuit breaker opened after ${providerState.consecutiveFailures} failures`\n      )\n    }\n  }\n\n  /**\n   * Get the currently active provider based on circuit breaker states\n   */\n  const getActiveProvider = (): NodePackSearchProvider => {\n    // First, try to use the current active provider if it's healthy\n    const currentProvider = providers[activeProviderIndex]\n    if (isCircuitClosed(currentProvider)) {\n      return currentProvider.provider\n    }\n\n    // Otherwise, find the first healthy provider\n    for (let i = 0; i < providers.length; i++) {\n      const providerState = providers[i]\n      if (isCircuitClosed(providerState)) {\n        activeProviderIndex = i\n        return providerState.provider\n      }\n    }\n\n    throw new Error('No available search providers')\n  }\n\n  /**\n   * Update the active provider index after a failure.\n   * Move to the next provider if available.\n   */\n  const updateActiveProviderOnFailure = () => {\n    if (activeProviderIndex < providers.length - 1) {\n      activeProviderIndex++\n    }\n  }\n\n  /**\n   * Search for node packs.\n   */\n  const searchPacks = async (\n    query: string,\n    params: SearchNodePacksParams\n  ): Promise<SearchPacksResult> => {\n    let lastError: Error | null = null\n\n    // Start with the current active provider\n    for (let attempts = 0; attempts < providers.length; attempts++) {\n      try {\n        const provider = getActiveProvider()\n        const providerState = providers[activeProviderIndex]\n\n        const result = await provider.searchPacks(query, params)\n        recordSuccess(providerState)\n        return result\n      } catch (error) {\n        lastError = toError(error)\n        const providerState = providers[activeProviderIndex]\n        recordFailure(providerState, lastError)\n        console.warn(\n          `${providerState.name} search provider failed (${providerState.consecutiveFailures} failures):`,\n          error\n        )\n\n        // Try the next provider\n        updateActiveProviderOnFailure()\n      }\n    }\n\n    // If we get here, all providers failed\n    throw new Error(\n      `All search providers failed. Last error: ${lastError?.message || 'Unknown error'}`\n    )\n  }\n\n  /**\n   * Clear the search cache for all providers that implement it.\n   */\n  const clearSearchCache = () => {\n    for (const providerState of providers) {\n      try {\n        providerState.provider.clearSearchCache()\n      } catch (error) {\n        console.warn(\n          `Failed to clear cache for ${providerState.name} provider:`,\n          error\n        )\n      }\n    }\n  }\n\n  return {\n    searchPacks,\n    clearSearchCache\n  }\n}\n","import { computed, ref, toValue, watch } from 'vue'\nimport type { MaybeRefOrGetter, Ref } from 'vue'\n\nimport { DEFAULT_PAGE_SIZE } from '@/constants/searchConstants'\nimport { useRegistrySearchGateway } from '@/services/gateway/registrySearchGateway'\nimport type { SearchAttribute } from '@/types/algoliaTypes'\nimport type { components } from '@/types/comfyRegistryTypes'\nimport type { QuerySuggestion, SearchMode } from '@/types/searchServiceTypes'\nimport { usePreemptableQueue } from '@/utils/pagedList'\nimport type { PagedList } from '@/utils/pagedList'\n\ntype RegistryNodePack = components['schemas']['Node']\n\n/**\n * Offset-paged registry search as a {@link PagedList}. Query inputs are reactive\n * so a change resets and reloads from the first page. A relevance-ranked index\n * has no head cursor and no per-item staleness, so `loadNew`/`invalidate` both\n * reduce to reloading from the first page.\n */\nexport function useRegistrySearch(inputs: {\n  query: MaybeRefOrGetter<string>\n  searchMode: MaybeRefOrGetter<SearchMode>\n}): PagedList<RegistryNodePack> & {\n  suggestions: Readonly<Ref<QuerySuggestion[]>>\n} {\n  const { searchPacks } = useRegistrySearchGateway()\n\n  let pageNumber = 0\n  const items = ref<RegistryNodePack[]>([])\n  const morePages = ref(true)\n  const suggestions = ref<QuerySuggestion[]>([])\n  const { enqueue, preempt, running: isLoading } = usePreemptableQueue()\n\n  const searchableAttributes = (): SearchAttribute[] =>\n    toValue(inputs.searchMode) === 'nodes'\n      ? ['comfy_nodes']\n      : ['name', 'description']\n\n  async function doLoadMore() {\n    if (!morePages.value) return\n    try {\n      const { nodePacks, querySuggestions } = await searchPacks(\n        toValue(inputs.query),\n        {\n          pageSize: DEFAULT_PAGE_SIZE,\n          pageNumber,\n          restrictSearchableAttributes: searchableAttributes()\n        }\n      )\n      morePages.value = nodePacks.length >= DEFAULT_PAGE_SIZE\n      items.value.push(...nodePacks)\n      suggestions.value = querySuggestions\n      pageNumber++\n    } catch (err) {\n      console.error(err)\n      morePages.value = false\n    }\n  }\n\n  const reload = () =>\n    preempt(async () => {\n      pageNumber = 0\n      morePages.value = true\n      items.value = []\n      await doLoadMore()\n    })\n\n  async function loadMore() {\n    const startingPage = pageNumber\n    await enqueue('loadMore', doLoadMore)\n    return pageNumber > startingPage\n  }\n\n  watch(\n    () => [toValue(inputs.query), toValue(inputs.searchMode)],\n    () => void reload(),\n    { immediate: true }\n  )\n\n  return {\n    items,\n    hasMore: computed(() => morePages.value),\n    isLoading,\n    loadMore,\n    loadNew: reload,\n    invalidate: reload,\n    suggestions\n  }\n}\n","import type { Ref } from 'vue'\nimport { computed } from 'vue'\n\nconst LEGACY_MANAGER_KEYWORDS = [\n  'manager',\n  'comfyui-manager',\n  'manager comfyui',\n  'comfyui manager'\n] as const\n\nexport function useLegacySearchTip(\n  searchQuery: Ref<string>,\n  isNewManagerUI: Ref<boolean>\n) {\n  const isLegacyManagerSearch = computed(() => {\n    if (!isNewManagerUI.value) return false\n    const query = searchQuery.value.toLowerCase().trim()\n    if (!query) return false\n    return LEGACY_MANAGER_KEYWORDS.some((keyword) => query.includes(keyword))\n  })\n\n  return {\n    isLegacyManagerSearch\n  }\n}\n","<template>\n  <!-- `manager-dialog` carries no styles; PackVersionBadge scopes its popover\n       to it via closest(). Removing it silently widens that boundary. -->\n  <BaseModalLayout\n    v-model:right-panel-open=\"isRightPanelOpen\"\n    :content-title=\"$t('manager.discoverCommunityContent')\"\n    :right-panel-title=\"$t('manager.nodePackInfo')\"\n    size=\"lg\"\n    class=\"manager-dialog\"\n  >\n    <template #leftPanelHeaderTitle>\n      <i class=\"icon-[comfy--extensions-blocks]\" />\n      <h2 class=\"text-base text-base-foreground\">{{ $t('manager.title') }}</h2>\n    </template>\n    <template #leftPanel>\n      <LeftSidePanel v-model=\"selectedNavId\" :nav-items=\"navItems\" />\n    </template>\n\n    <template #header>\n      <div class=\"flex w-full items-center justify-between gap-2\">\n        <div class=\"flex w-full items-center gap-2\">\n          <SingleSelect\n            v-model=\"searchMode\"\n            class=\"min-w-34\"\n            :options=\"filterOptions\"\n          />\n          <SearchAutocomplete\n            v-model=\"searchQuery\"\n            :suggestions=\"suggestions\"\n            :placeholder=\"$t('manager.searchPlaceholder')\"\n            option-label=\"query\"\n            autofocus\n            size=\"lg\"\n            class=\"max-w-96 flex-1\"\n            @select=\"onOptionSelect\"\n          />\n        </div>\n        <PackInstallButton\n          v-if=\"isMissingTab && missingNodePacks.length > 0\"\n          :disabled=\"isMissingLoading || !!missingError\"\n          :node-packs=\"missingNodePacks\"\n          size=\"lg\"\n          :label=\"$t('manager.installAllMissingNodes')\"\n        />\n        <PackUpdateButton\n          v-if=\"isUpdateAvailableTab && hasUpdateAvailable\"\n          :node-packs=\"enabledUpdateAvailableNodePacks\"\n          :has-disabled-update-packs=\"hasDisabledUpdatePacks\"\n          size=\"lg\"\n        />\n      </div>\n    </template>\n\n    <template #contentFilter>\n      <!-- Conflict Warning Banner -->\n      <div\n        v-if=\"shouldShowManagerBanner\"\n        class=\"relative mx-6 mt-3 mb-4 flex items-center gap-6 rounded-lg bg-yellow-500/20 p-4\"\n      >\n        <i\n          class=\"icon-[lucide--triangle-alert] text-lg text-warning-background\"\n        />\n        <div class=\"flex flex-1 flex-col gap-2\">\n          <p class=\"m-0 text-sm font-bold\">\n            {{ $t('manager.conflicts.warningBanner.title') }}\n          </p>\n          <p class=\"m-0 text-xs\">\n            {{ $t('manager.conflicts.warningBanner.message') }}\n          </p>\n          <p\n            class=\"m-0 cursor-pointer text-sm font-bold\"\n            @click=\"onClickWarningLink\"\n          >\n            {{ $t('manager.conflicts.warningBanner.button') }}\n          </p>\n        </div>\n        <Button\n          class=\"absolute top-0 right-0\"\n          variant=\"textonly\"\n          size=\"icon\"\n          @click=\"dismissWarningBanner\"\n        >\n          <i class=\"pi pi-times text-xs text-base-foreground\"></i>\n        </Button>\n      </div>\n\n      <!-- Sort Options -->\n      <div v-if=\"isSortable\" class=\"flex justify-end px-6 pb-4\">\n        <SingleSelect\n          v-model=\"sortField\"\n          :label=\"$t('g.sort')\"\n          :options=\"availableSortOptions\"\n          class=\"w-48\"\n        >\n          <template #icon>\n            <i class=\"icon-[lucide--arrow-up-down] text-muted-foreground\" />\n          </template>\n        </SingleSelect>\n      </div>\n    </template>\n\n    <template #content>\n      <div v-if=\"isLoading\" class=\"size-full scrollbar-hide overflow-auto\">\n        <GridSkeleton :grid-style=\"GRID_STYLE\" :skeleton-card-count />\n      </div>\n      <UnresolvedNodesMessage\n        v-else-if=\"isUnresolvedTab\"\n        :node-names=\"unresolvedNodeNames\"\n      />\n      <NoResultsPlaceholder\n        v-else-if=\"displayPacks.length === 0 && !canLoadMorePacks\"\n        :title=\"emptyStateTitle\"\n        :message=\"emptyStateMessage\"\n      />\n      <div v-else class=\"size-full\" @click=\"handleGridContainerClick\">\n        <VirtualGrid\n          id=\"results-grid\"\n          :items=\"resultsWithKeys\"\n          :buffer-rows=\"4\"\n          :grid-style=\"GRID_STYLE\"\n          :on-load-more=\"loadMorePacks\"\n          :can-load-more=\"canLoadMorePacks\"\n        >\n          <template #item=\"{ item }\">\n            <PackCard\n              :node-pack=\"item\"\n              :is-selected=\"\n                selectedNodePacks.some((pack) => pack.id === item.id)\n              \"\n              @click.stop=\"(event: MouseEvent) => selectNodePack(item, event)\"\n            />\n          </template>\n        </VirtualGrid>\n      </div>\n    </template>\n\n    <template #rightPanel>\n      <InfoPanel\n        v-if=\"!hasMultipleSelections && selectedNodePack\"\n        :node-pack=\"selectedNodePack\"\n      />\n      <InfoPanelMultiItem v-else :node-packs=\"selectedNodePacks\" />\n    </template>\n  </BaseModalLayout>\n</template>\n\n<script setup lang=\"ts\">\nimport { refDebounced, until, whenever } from '@vueuse/core'\nimport { merge } from 'es-toolkit/compat'\nimport {\n  computed,\n  onBeforeUnmount,\n  onMounted,\n  onUnmounted,\n  provide,\n  ref,\n  toValue,\n  watch,\n  watchEffect\n} from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport NoResultsPlaceholder from '@/components/common/NoResultsPlaceholder.vue'\nimport VirtualGrid from '@/components/common/VirtualGrid.vue'\nimport SingleSelect from '@/components/ui/single-select/SingleSelect.vue'\nimport SearchAutocomplete from '@/components/ui/search-input/SearchAutocomplete.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport BaseModalLayout from '@/components/widget/layout/BaseModalLayout.vue'\nimport LeftSidePanel from '@/components/widget/panel/LeftSidePanel.vue'\nimport { useExternalLink } from '@/composables/useExternalLink'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useComfyRegistryStore } from '@/stores/comfyRegistryStore'\nimport type { components } from '@/types/comfyRegistryTypes'\nimport type { NavGroupData, NavItemData } from '@/types/navTypes'\nimport type { QuerySuggestion, SearchMode } from '@/types/searchServiceTypes'\nimport { OnCloseKey } from '@/types/widgetTypes'\nimport PackInstallButton from '@/workbench/extensions/manager/components/manager/button/PackInstallButton.vue'\nimport PackUpdateButton from '@/workbench/extensions/manager/components/manager/button/PackUpdateButton.vue'\nimport InfoPanel from '@/workbench/extensions/manager/components/manager/infoPanel/InfoPanel.vue'\nimport InfoPanelMultiItem from '@/workbench/extensions/manager/components/manager/infoPanel/InfoPanelMultiItem.vue'\nimport PackCard from '@/workbench/extensions/manager/components/manager/packCard/PackCard.vue'\nimport GridSkeleton from '@/workbench/extensions/manager/components/manager/skeleton/GridSkeleton.vue'\nimport UnresolvedNodesMessage from '@/workbench/extensions/manager/components/manager/UnresolvedNodesMessage.vue'\nimport { useMissingNodes } from '@/workbench/extensions/manager/composables/nodePack/useMissingNodes'\nimport { useUpdateAvailableNodes } from '@/workbench/extensions/manager/composables/nodePack/useUpdateAvailableNodes'\nimport { useConflictAcknowledgment } from '@/workbench/extensions/manager/composables/useConflictAcknowledgment'\nimport { useManagerDisplayPacks } from '@/workbench/extensions/manager/composables/useManagerDisplayPacks'\nimport { useManagerStatePersistence } from '@/workbench/extensions/manager/composables/useManagerStatePersistence'\nimport { useRegistrySearch } from '@/workbench/extensions/manager/composables/useRegistrySearch'\nimport { useConflictDetectionStore } from '@/workbench/extensions/manager/stores/conflictDetectionStore'\nimport { useLegacySearchTip } from '@/workbench/extensions/manager/composables/useLegacySearchTip'\nimport { useManagerState } from '@/workbench/extensions/manager/composables/useManagerState'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport { ManagerTab } from '@/workbench/extensions/manager/types/comfyManagerTypes'\nimport { PACK_SORTABLE_FIELDS } from '@/workbench/extensions/manager/utils/nodePackSort'\n\nconst { initialTab, initialPackId, onClose } = defineProps<{\n  initialTab?: ManagerTab\n  initialPackId?: string\n  onClose: () => void\n}>()\n\nprovide(OnCloseKey, onClose)\n\nconst { t } = useI18n()\nconst { buildDocsUrl } = useExternalLink()\nconst comfyManagerStore = useComfyManagerStore()\nconst { getPackById } = useComfyRegistryStore()\nconst conflictAcknowledgment = useConflictAcknowledgment()\nconst conflictDetectionStore = useConflictDetectionStore()\nconst { isNewManagerUI } = useManagerState()\nconst workflowStore = useWorkflowStore()\nconst persistedState = useManagerStatePersistence()\nconst initialState = persistedState.loadStoredState()\n\nconst GRID_STYLE = {\n  display: 'grid',\n  gridTemplateColumns: 'repeat(auto-fill, minmax(14rem, 1fr))',\n  gap: '1rem',\n  padding: '0.5rem'\n} as const\n\nconst {\n  shouldShowManagerBanner,\n  dismissWarningBanner,\n  dismissRedDotNotification\n} = conflictAcknowledgment\n\n// Missing nodes composable\nconst {\n  missingNodePacks,\n  unresolvedNodeNames,\n  isLoading: isMissingLoading,\n  error: missingError\n} = useMissingNodes()\n\n// Update available nodes composable\nconst {\n  hasUpdateAvailable,\n  enabledUpdateAvailableNodePacks,\n  hasDisabledUpdatePacks\n} = useUpdateAvailableNodes()\n\n// Get the current workflow name for the nav item\nconst workflowName = computed(\n  () => workflowStore.activeWorkflow?.filename ?? t('manager.inWorkflow')\n)\n\n// Navigation items for LeftSidePanel\nconst navItems = computed<(NavItemData | NavGroupData)[]>(() => [\n  {\n    id: ManagerTab.All,\n    label: t('manager.nav.allExtensions'),\n    icon: 'icon-[lucide--list]'\n  },\n  {\n    id: ManagerTab.NotInstalled,\n    label: t('manager.nav.notInstalled'),\n    icon: 'icon-[lucide--globe]'\n  },\n  {\n    title: t('manager.nav.installedSection'),\n    items: [\n      {\n        id: ManagerTab.AllInstalled,\n        label: t('manager.nav.allInstalled'),\n        icon: 'icon-[lucide--download]'\n      },\n      {\n        id: ManagerTab.UpdateAvailable,\n        label: t('manager.nav.updatesAvailable'),\n        icon: 'icon-[lucide--refresh-cw]'\n      },\n      {\n        id: ManagerTab.Conflicting,\n        label: t('manager.nav.conflicting'),\n        icon: 'icon-[lucide--triangle-alert]',\n        badge: conflictDetectionStore.conflictedPackages.length || undefined\n      }\n    ]\n  },\n  {\n    title: t('manager.nav.inWorkflowSection'),\n    items: [\n      {\n        id: ManagerTab.Workflow,\n        label: t('manager.nav.allInWorkflow', {\n          workflowName: workflowName.value\n        }),\n        icon: 'icon-[lucide--share-2]'\n      },\n      {\n        id: ManagerTab.Missing,\n        label: t('manager.nav.missingNodes'),\n        icon: 'icon-[lucide--triangle-alert]'\n      },\n      ...(unresolvedNodeNames.value.length > 0\n        ? [\n            {\n              id: ManagerTab.Unresolved,\n              label: t('manager.nav.unresolvedNodes'),\n              icon: 'icon-[lucide--help-circle]',\n              badge: unresolvedNodeNames.value.length\n            }\n          ]\n        : [])\n    ]\n  }\n])\n\nconst initialTabId = initialTab ?? initialState.selectedTabId ?? ManagerTab.All\nconst selectedNavId = ref<string | null>(initialTabId)\n\n// Helper to find a nav item by id in the nested structure\nconst findNavItemById = (\n  items: (NavItemData | NavGroupData)[],\n  id: string | null\n): NavItemData | undefined => {\n  for (const item of items) {\n    if ('items' in item) {\n      const found = item.items.find((subItem) => subItem.id === id)\n      if (found) return found\n    } else if (item.id === id) {\n      return item\n    }\n  }\n  return undefined\n}\n\nconst selectedTab = computed(() =>\n  findNavItemById(navItems.value, selectedNavId.value)\n)\n\nwatch(navItems, (items) => {\n  if (selectedNavId.value && !findNavItemById(items, selectedNavId.value)) {\n    selectedNavId.value = ManagerTab.Missing\n  }\n})\n\nconst SEARCH_DEBOUNCE_MS = 320\n\nconst searchQuery = ref(\n  initialTabId === ManagerTab.Missing\n    ? ''\n    : (initialPackId ?? initialState.searchQuery)\n)\nconst searchMode = ref<SearchMode>(\n  initialPackId && initialTabId !== ManagerTab.Missing\n    ? 'packs'\n    : initialState.searchMode\n)\nconst sortField = ref<string>(initialState.sortField)\n\nconst isSearchBacked = computed(() => {\n  const tab = selectedTab.value?.id\n  return (\n    tab === ManagerTab.All ||\n    tab === ManagerTab.NotInstalled ||\n    (searchQuery.value !== '' && tab !== ManagerTab.Unresolved)\n  )\n})\nconst packs = useRegistrySearch({\n  query: refDebounced(searchQuery, SEARCH_DEBOUNCE_MS),\n  searchMode\n})\nconst searchResults = computed(() => [...toValue(packs.items)])\nconst isSearchLoading = computed(\n  () => isSearchBacked.value && toValue(packs.isLoading)\n)\nconst hasMorePacks = computed(() => toValue(packs.hasMore))\nconst suggestions = computed(() => toValue(packs.suggestions))\nconst sortOptions = PACK_SORTABLE_FIELDS\nconst { isLegacyManagerSearch } = useLegacySearchTip(\n  searchQuery,\n  isNewManagerUI\n)\nconst filterOptions = computed(() => [\n  { name: t('manager.filter.nodePack'), value: 'packs' },\n  { name: t('g.nodes'), value: 'nodes' }\n])\nconst availableSortOptions = computed(() =>\n  sortOptions.map((field) => ({\n    name: field.label,\n    value: field.id\n  }))\n)\nconst onOptionSelect = (suggestion: QuerySuggestion) => {\n  searchQuery.value = suggestion.query\n}\nconst loadMorePacks = () => packs.loadMore()\nconst canLoadMorePacks = computed(\n  () => hasMorePacks.value && !isSearchLoading.value && isSearchBacked.value\n)\nconst isInitialLoad = computed(\n  () =>\n    isSearchBacked.value &&\n    searchResults.value.length === 0 &&\n    searchQuery.value === ''\n)\n// Use the new composable for tab-based display packs\nconst {\n  displayPacks,\n  isSortable,\n  isLoading: isTabLoading,\n  workflowPacks\n} = useManagerDisplayPacks(selectedNavId, searchResults, searchQuery, sortField)\n\n// Tab helpers for template\nconst isUpdateAvailableTab = computed(\n  () => selectedTab.value?.id === ManagerTab.UpdateAvailable\n)\nconst isMissingTab = computed(\n  () => selectedTab.value?.id === ManagerTab.Missing\n)\nconst isUnresolvedTab = computed(\n  () => selectedTab.value?.id === ManagerTab.Unresolved\n)\n\n// Map of tab IDs to their empty state i18n key suffixes\nconst tabEmptyStateKeys: Record<string, string> = {\n  [ManagerTab.AllInstalled]: 'allInstalled',\n  [ManagerTab.UpdateAvailable]: 'updateAvailable',\n  [ManagerTab.Conflicting]: 'conflicting',\n  [ManagerTab.Workflow]: 'workflow',\n  [ManagerTab.Missing]: 'missing'\n}\n\nconst managerApiDependentTabs = new Set<string>([\n  ManagerTab.AllInstalled,\n  ManagerTab.UpdateAvailable,\n  ManagerTab.Conflicting,\n  ManagerTab.NotInstalled,\n  ManagerTab.Missing\n])\n\nconst isManagerErrorRelevant = computed(() => {\n  const tabId = selectedTab.value?.id\n  return (\n    !!comfyManagerStore.error && !!tabId && managerApiDependentTabs.has(tabId)\n  )\n})\n\n// Empty state messages based on current tab and search state\nconst emptyStateTitle = computed(() => {\n  if (isManagerErrorRelevant.value) return t('manager.errorConnecting')\n  if (searchQuery.value) return t('manager.noResultsFound')\n\n  const tabId = selectedTab.value?.id\n  const emptyStateKey = tabId ? tabEmptyStateKeys[tabId] : undefined\n\n  return emptyStateKey\n    ? t(`manager.emptyState.${emptyStateKey}.title`)\n    : t('manager.noResultsFound')\n})\n\nconst emptyStateMessage = computed(() => {\n  if (isManagerErrorRelevant.value) return t('manager.tryAgainLater')\n  if (searchQuery.value) {\n    const baseMessage = t('manager.tryDifferentSearch')\n    if (isLegacyManagerSearch.value) {\n      return `${baseMessage}\\n\\n${t('manager.legacyManagerSearchTip')}`\n    }\n    return baseMessage\n  }\n\n  const tabId = selectedTab.value?.id\n  const emptyStateKey = tabId ? tabEmptyStateKeys[tabId] : undefined\n\n  return emptyStateKey\n    ? t(`manager.emptyState.${emptyStateKey}.message`)\n    : t('manager.tryDifferentSearch')\n})\n\nconst onClickWarningLink = () => {\n  window.open(\n    buildDocsUrl('/troubleshooting/custom-node-issues', {\n      includeLocale: true\n    }),\n    '_blank'\n  )\n}\n\nconst isLoading = computed(() => {\n  if (isSearchLoading.value) return searchResults.value.length === 0\n  if (isTabLoading.value) return true\n  return isInitialLoad.value\n})\n\nconst resultsWithKeys = computed(\n  () =>\n    displayPacks.value.map((item) => ({\n      ...item,\n      key: item.id || item.name\n    })) as (components['schemas']['Node'] & { key: string })[]\n)\n\nconst selectedNodePacks = ref<components['schemas']['Node'][]>([])\nconst selectedNodePack = computed<components['schemas']['Node'] | null>(() =>\n  selectedNodePacks.value.length === 1 ? selectedNodePacks.value[0] : null\n)\nconst isRightPanelOpen = ref(false)\n\nwatch(\n  () => selectedNodePacks.value.length,\n  (length, oldLength) => {\n    if (length > 0 && oldLength === 0) {\n      isRightPanelOpen.value = true\n    }\n  }\n)\n\n// Auto-select the pack matching initialPackId once\nif (initialPackId) {\n  until(resultsWithKeys)\n    .toMatch((packs) => packs.some((p) => p.id === initialPackId))\n    .then((packs) => {\n      const target = packs.find((p) => p.id === initialPackId)\n      if (target && selectedNodePacks.value.length === 0) {\n        selectedNodePacks.value = [target]\n        isRightPanelOpen.value = true\n      }\n    })\n}\n\nconst getLoadingCount = () => {\n  switch (selectedTab.value?.id) {\n    case ManagerTab.AllInstalled:\n      return comfyManagerStore.installedPacksIds?.size\n    case ManagerTab.Workflow:\n      return workflowPacks.value?.length\n    case ManagerTab.Missing:\n      return workflowPacks.value?.filter?.(\n        (pack) => !comfyManagerStore.isPackInstalled(pack.id)\n      )?.length\n    default:\n      return searchResults.value.length\n  }\n}\n\nconst skeletonCardCount = computed(() => {\n  const loadingCount = getLoadingCount()\n  if (loadingCount) return loadingCount\n  return 16\n})\n\nconst selectNodePack = (\n  nodePack: components['schemas']['Node'],\n  event: MouseEvent\n) => {\n  if (event.shiftKey || event.ctrlKey || event.metaKey) {\n    const index = selectedNodePacks.value.findIndex(\n      (pack) => pack.id === nodePack.id\n    )\n\n    if (index === -1) {\n      selectedNodePacks.value = [...selectedNodePacks.value, nodePack]\n    } else {\n      selectedNodePacks.value = selectedNodePacks.value.filter(\n        (pack) => pack.id !== nodePack.id\n      )\n    }\n  } else {\n    selectedNodePacks.value = [nodePack]\n  }\n}\n\nconst unSelectItems = () => {\n  selectedNodePacks.value = []\n}\nconst handleGridContainerClick = (event: MouseEvent) => {\n  const targetElement = event.target as HTMLElement\n  if (targetElement && !targetElement.closest('[data-virtual-grid-item]')) {\n    unSelectItems()\n  }\n}\n\nconst hasMultipleSelections = computed(() => selectedNodePacks.value.length > 1)\n\nconst lastFetchedPackId = ref<string | null>(null)\n\nwhenever(selectedNodePack, async () => {\n  getPackById.cancel()\n  const pack = selectedNodePack.value\n  if (!pack?.id) return\n  if (hasMultipleSelections.value) return\n  if (lastFetchedPackId.value === pack.id) return\n  const data = await getPackById.call(pack.id)\n  if (data?.id === pack.id) {\n    lastFetchedPackId.value = pack.id\n    const mergedPack = merge({}, pack, data)\n    const packIndex = selectedNodePacks.value.findIndex(\n      (p) => p.id === mergedPack.id\n    )\n    if (packIndex !== -1) {\n      selectedNodePacks.value.splice(packIndex, 1, mergedPack)\n    }\n  }\n})\n\nlet gridContainer: HTMLElement | null = null\nonMounted(() => {\n  gridContainer = document.getElementById('results-grid')\n})\nwatch([searchQuery, selectedNavId], () => {\n  gridContainer ??= document.getElementById('results-grid')\n  if (gridContainer) {\n    gridContainer.scrollTop = 0\n  }\n  unSelectItems()\n})\n\nwatchEffect(() => {\n  dismissRedDotNotification()\n})\n\nonBeforeUnmount(() => {\n  persistedState.persistState({\n    selectedTabId: (selectedTab.value?.id as ManagerTab) ?? ManagerTab.All,\n    searchQuery: searchQuery.value,\n    searchMode: searchMode.value,\n    sortField: sortField.value\n  })\n})\n\nonUnmounted(() => {\n  getPackById.cancel()\n})\n</script>\n","import { useDialogService } from '@/services/dialogService'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport type { ManagerTab } from '@/workbench/extensions/manager/types/comfyManagerTypes'\nimport ManagerDialog from '@/workbench/extensions/manager/components/manager/ManagerDialog.vue'\n\nconst DIALOG_KEY = 'global-manager'\n\nexport function useManagerDialog() {\n  const dialogService = useDialogService()\n  const dialogStore = useDialogStore()\n\n  function hide() {\n    dialogStore.closeDialog({ key: DIALOG_KEY })\n  }\n\n  function show(initialTab?: ManagerTab, initialPackId?: string) {\n    dialogService.showLayoutDialog({\n      key: DIALOG_KEY,\n      component: ManagerDialog,\n      props: {\n        onClose: hide,\n        initialTab,\n        initialPackId\n      }\n    })\n  }\n\n  return {\n    show,\n    hide\n  }\n}\n","import { storeToRefs } from 'pinia'\nimport { computed, readonly, watch } from 'vue'\n\nimport { t } from '@/i18n'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useSettingsDialog } from '@/platform/settings/composables/useSettingsDialog'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { api } from '@/scripts/api'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useSystemStatsStore } from '@/stores/systemStatsStore'\nimport { useManagerDialog } from '@/workbench/extensions/manager/composables/useManagerDialog'\nimport type { ManagerTab } from '@/workbench/extensions/manager/types/comfyManagerTypes'\n\nexport enum ManagerUIState {\n  DISABLED = 'disabled',\n  LEGACY_UI = 'legacy',\n  NEW_UI = 'new',\n  INCOMPATIBLE = 'incompatible'\n}\n\n/**\n * Module-level flag to ensure the INCOMPATIBLE upgrade toast fires exactly\n * once per app session, even when useManagerState() is invoked from many\n * components. Without this, every consumer would register its own watcher\n * and stack duplicate toasts on the first transition.\n */\nlet incompatibleToastShown = false\n\nconst showIncompatibleToast = (): void => {\n  if (incompatibleToastShown) return\n  incompatibleToastShown = true\n  useToast().warning(t('manager.incompatibleVersion.title'), {\n    description: t('manager.incompatibleVersion.message'),\n    duration: 15000\n  })\n}\n\nexport function useManagerState() {\n  const systemStatsStore = useSystemStatsStore()\n  const { systemStats, isInitialized: systemInitialized } =\n    storeToRefs(systemStatsStore)\n  const managerDialog = useManagerDialog()\n\n  /**\n   * The current manager UI state.\n   * Computed once and cached until dependencies change (which they don't during runtime).\n   * This follows Vue's conventions and provides better performance through caching.\n   */\n  const managerUIState = readonly(\n    computed((): ManagerUIState => {\n      // Wait for systemStats to be initialized\n      if (!systemInitialized.value) {\n        // Default to DISABLED while loading\n        return ManagerUIState.DISABLED\n      }\n\n      // Get current values\n      const clientSupportsV4 =\n        api.getClientFeatureFlags().supports_manager_v4_ui === true\n      const serverSupportsV4 = api.getServerFeature(\n        'extension.manager.supports_v4'\n      )\n\n      const supportsCsrfPost = api.getServerFeature(\n        'extension.manager.supports_csrf_post'\n      )\n\n      // Check command line args first (highest priority)\n      // --enable-manager flag enables the manager (opposite of old --disable-manager)\n      const hasEnableManager =\n        systemStats.value?.system.argv.includes('--enable-manager')\n\n      // If --enable-manager is NOT present, manager is disabled\n      if (!hasEnableManager) {\n        return ManagerUIState.DISABLED\n      }\n\n      if (\n        systemStats.value?.system.argv.includes('--enable-manager-legacy-ui')\n      ) {\n        return ManagerUIState.LEGACY_UI\n      }\n\n      // Server exposes v4 but is missing the CSRF-hardened POST endpoints\n      // (Manager < 4.2.1). Treat as INCOMPATIBLE — hide manager UI and\n      // prompt user to upgrade. csrf_post is an independent axis from v4.\n      //\n      // !== true (not === false) is deliberate: feature_flags arrive atomically\n      // via a single WebSocket payload (src/scripts/api.ts:751-758), so undefined\n      // here means the server did not publish the flag (i.e. Manager 4.2.0),\n      // not a transient partial-delivery state. Using === false would let\n      // flag-less Manager 4.2.0 fall through to NEW_UI → POST → 405 regression.\n      if (serverSupportsV4 === true && supportsCsrfPost !== true) {\n        return ManagerUIState.INCOMPATIBLE\n      }\n\n      // Both client and server support v4 = NEW_UI\n      if (clientSupportsV4 && serverSupportsV4 === true) {\n        return ManagerUIState.NEW_UI\n      }\n\n      if (serverSupportsV4 === true && !clientSupportsV4) {\n        return ManagerUIState.LEGACY_UI\n      }\n\n      // Server explicitly doesn't support v4 = LEGACY_UI\n      if (serverSupportsV4 === false) {\n        return ManagerUIState.LEGACY_UI\n      }\n\n      // If server feature flags haven't loaded yet, default to NEW_UI\n      // This is a temporary state - feature flags are exchanged immediately on WebSocket connection\n      // NEW_UI is the safest default since v2 API is the current standard\n      // If the server doesn't support v2, API calls will fail with 404 and be handled gracefully\n      if (serverSupportsV4 === undefined) {\n        return ManagerUIState.NEW_UI\n      }\n\n      // Should never reach here, but if we do, disable manager\n      return ManagerUIState.DISABLED\n    })\n  )\n\n  /**\n   * Check if manager is enabled (not DISABLED and not INCOMPATIBLE)\n   * INCOMPATIBLE is treated as \"not installed\" from a UX perspective —\n   * the user must upgrade the Manager backend before the UI becomes usable.\n   */\n  const isManagerEnabled = readonly(\n    computed((): boolean => {\n      return (\n        managerUIState.value !== ManagerUIState.DISABLED &&\n        managerUIState.value !== ManagerUIState.INCOMPATIBLE\n      )\n    })\n  )\n\n  /**\n   * Check if manager UI is in NEW_UI mode\n   */\n  const isNewManagerUI = readonly(\n    computed((): boolean => {\n      return managerUIState.value === ManagerUIState.NEW_UI\n    })\n  )\n\n  /**\n   * Check if manager UI is in LEGACY_UI mode\n   */\n  const isLegacyManagerUI = readonly(\n    computed((): boolean => {\n      return managerUIState.value === ManagerUIState.LEGACY_UI\n    })\n  )\n\n  /**\n   * Check if the installed Manager backend is too old to use safely\n   * (lacks the CSRF-hardened POST endpoints introduced in Manager 4.2.1).\n   */\n  const isIncompatibleManager = readonly(\n    computed((): boolean => {\n      return managerUIState.value === ManagerUIState.INCOMPATIBLE\n    })\n  )\n\n  /**\n   * Check if install button should be shown (only in NEW_UI mode)\n   */\n  const shouldShowInstallButton = readonly(\n    computed((): boolean => {\n      return isNewManagerUI.value\n    })\n  )\n\n  /**\n   * Check if manager buttons should be shown.\n   * Hidden when DISABLED (flag missing) or INCOMPATIBLE (backend too old).\n   */\n  const shouldShowManagerButtons = readonly(\n    computed((): boolean => {\n      return isManagerEnabled.value\n    })\n  )\n\n  /**\n   * The top bar Extensions button also opens the cloud custom nodes survey,\n   * so it stays visible on cloud where the manager itself is disabled.\n   */\n  const shouldShowExtensionsButton = readonly(\n    computed((): boolean => isCloud || shouldShowManagerButtons.value)\n  )\n\n  // Fire the upgrade-required toast once when we first observe the\n  // INCOMPATIBLE state. immediate: true handles the common case where the\n  // composable is mounted after feature flags have already arrived.\n  watch(\n    managerUIState,\n    (state) => {\n      if (state === ManagerUIState.INCOMPATIBLE) {\n        showIncompatibleToast()\n      }\n    },\n    { immediate: true }\n  )\n\n  /**\n   * Opens the manager UI based on current state\n   * Centralizes the logic for opening manager across the app\n   * @param options - Optional configuration for opening the manager\n   * @param options.initialTab - Initial tab to show (for NEW_UI mode)\n   * @param options.legacyCommand - Legacy command to execute (for LEGACY_UI mode)\n   * @param options.showToastOnLegacyError - Whether to show toast on legacy command failure\n   * @param options.isLegacyOnly - If true, shows error in NEW_UI mode instead of opening manager\n   */\n  const openManager = async (options?: {\n    initialTab?: ManagerTab\n    initialPackId?: string\n    legacyCommand?: string\n    showToastOnLegacyError?: boolean\n    isLegacyOnly?: boolean\n  }): Promise<void> => {\n    const state = managerUIState.value\n    const settingsDialog = useSettingsDialog()\n    const commandStore = useCommandStore()\n\n    switch (state) {\n      case ManagerUIState.DISABLED:\n        settingsDialog.show('extension')\n        break\n\n      case ManagerUIState.INCOMPATIBLE:\n        // Re-emit the upgrade toast on explicit user action. We intentionally\n        // bypass the once-per-session guard so repeated clicks on a hidden\n        // entry point (e.g. a stale shortcut) still surface guidance,\n        // without redirecting into settings like DISABLED does.\n        incompatibleToastShown = false\n        showIncompatibleToast()\n        break\n\n      case ManagerUIState.LEGACY_UI: {\n        const command =\n          options?.legacyCommand || 'Comfy.Manager.Menu.ToggleVisibility'\n        try {\n          await commandStore.execute(command)\n        } catch {\n          // If legacy command doesn't exist\n          if (options?.showToastOnLegacyError !== false) {\n            useToast().error(t('g.error'), {\n              description: t('manager.legacyMenuNotAvailable')\n            })\n          }\n          // Fallback to extensions panel if not showing toast\n          if (options?.showToastOnLegacyError === false) {\n            settingsDialog.show('extension')\n          }\n        }\n        break\n      }\n\n      case ManagerUIState.NEW_UI:\n        if (options?.isLegacyOnly) {\n          useToast().error(t('g.error'), {\n            description: t('manager.legacyMenuNotAvailable')\n          })\n        } else {\n          managerDialog.show(options?.initialTab, options?.initialPackId)\n        }\n        break\n    }\n  }\n\n  return {\n    managerUIState,\n    isManagerEnabled,\n    isNewManagerUI,\n    isLegacyManagerUI,\n    isIncompatibleManager,\n    shouldShowInstallButton,\n    shouldShowManagerButtons,\n    shouldShowExtensionsButton,\n    openManager\n  }\n}\n\n// Test-only export: resets the once-per-session toast guard so unit tests\n// can assert toast firing across multiple `useManagerState()` invocations.\nexport const __resetIncompatibleToastGuard = (): void => {\n  incompatibleToastShown = false\n}\n","import type { AxiosError, AxiosResponse } from 'axios'\nimport axios from 'axios'\nimport { v4 as uuidv4 } from 'uuid'\nimport { ref } from 'vue'\n\nimport { api } from '@/scripts/api'\nimport { isAbortError } from '@/utils/typeGuardUtil'\nimport { useManagerState } from '@/workbench/extensions/manager/composables/useManagerState'\nimport type { components } from '@/workbench/extensions/manager/types/generatedManagerTypes'\n\ntype ManagerQueueStatus = components['schemas']['QueueStatus']\ntype InstallPackParams = components['schemas']['InstallPackParams']\ntype InstalledPacksResponse = components['schemas']['InstalledPacksResponse']\ntype UpdateAllPacksParams = components['schemas']['UpdateAllPacksParams']\ntype UpdateComfyUIParams = components['schemas']['UpdateComfyUIParams']\ntype ManagerTaskHistory = components['schemas']['HistoryResponse']\ntype QueueTaskItem = components['schemas']['QueueTaskItem']\n\nconst GENERIC_SECURITY_ERR_MSG =\n  'Forbidden: A security error has occurred. Please check the terminal logs'\n\n/**\n * API routes for ComfyUI Manager\n */\nenum ManagerRoute {\n  START_QUEUE = 'manager/queue/start',\n  RESET_QUEUE = 'manager/queue/reset',\n  QUEUE_STATUS = 'manager/queue/status',\n  UPDATE_ALL = 'manager/queue/update_all',\n  UPDATE_COMFYUI = 'manager/queue/update_comfyui',\n  LIST_INSTALLED = 'customnode/installed',\n  GET_NODES = 'customnode/getmappings',\n  IMPORT_FAIL_INFO = 'customnode/import_fail_info',\n  IMPORT_FAIL_INFO_BULK = 'customnode/import_fail_info_bulk',\n  REBOOT = 'manager/reboot',\n  IS_LEGACY_MANAGER_UI = 'manager/is_legacy_manager_ui',\n  TASK_HISTORY = 'manager/queue/history',\n  QUEUE_TASK = 'manager/queue/task'\n}\n\nconst managerApiClient = axios.create({\n  baseURL: api.apiURL('/v2/'),\n  headers: {\n    'Content-Type': 'application/json'\n  }\n})\n\n/**\n * Service for interacting with the ComfyUI Manager API\n * Provides methods for managing packs, ComfyUI-Manager queue operations, and system functions\n * Note: This service should only be used when Manager state is NEW_UI\n */\nexport const useComfyManagerService = () => {\n  const isLoading = ref(false)\n  const error = ref<string | null>(null)\n\n  // Check if manager service should be available\n  const isManagerServiceAvailable = () => {\n    const managerState = useManagerState()\n    return managerState.isNewManagerUI.value\n  }\n\n  const handleRequestError = (\n    err: unknown,\n    context: string,\n    routeSpecificErrors?: Record<number, string>\n  ) => {\n    // Don't treat cancellation as an error\n    if (isAbortError(err)) return\n\n    let message: string\n    if (!axios.isAxiosError(err)) {\n      message = `${context} failed: ${err instanceof Error ? err.message : String(err)}`\n    } else {\n      const axiosError = err as AxiosError<{ message: string }>\n      const status = axiosError.response?.status\n      if (status && routeSpecificErrors?.[status]) {\n        message = routeSpecificErrors[status]\n      } else if (status === 404) {\n        message = 'Could not connect to ComfyUI-Manager'\n      } else {\n        message =\n          axiosError.response?.data.message ??\n          `${context} failed with status ${status}`\n      }\n    }\n\n    error.value = message\n  }\n\n  const executeRequest = async <T>(\n    requestCall: () => Promise<AxiosResponse<T>>,\n    options: {\n      errorContext: string\n      routeSpecificErrors?: Record<number, string>\n    }\n  ): Promise<T | null> => {\n    const { errorContext, routeSpecificErrors } = options\n\n    // Block service calls if not in NEW_UI state\n    if (!isManagerServiceAvailable()) {\n      error.value = 'Manager service is not available in current mode'\n      return null\n    }\n\n    isLoading.value = true\n    error.value = null\n\n    try {\n      const response = await requestCall()\n      return response.data\n    } catch (err) {\n      handleRequestError(err, errorContext, routeSpecificErrors)\n      return null\n    } finally {\n      isLoading.value = false\n    }\n  }\n\n  const startQueue = async (signal?: AbortSignal) => {\n    const errorContext = 'Starting ComfyUI-Manager job queue'\n    const routeSpecificErrors = {\n      403: GENERIC_SECURITY_ERR_MSG\n    }\n\n    return executeRequest<string>(\n      () => managerApiClient.post(ManagerRoute.START_QUEUE, null, { signal }),\n      { errorContext, routeSpecificErrors }\n    )\n  }\n\n  const getQueueStatus = async (client_id?: string, signal?: AbortSignal) => {\n    const errorContext = 'Getting ComfyUI-Manager queue status'\n\n    return executeRequest<ManagerQueueStatus>(\n      () =>\n        managerApiClient.get(ManagerRoute.QUEUE_STATUS, {\n          params: client_id ? { client_id } : undefined,\n          signal\n        }),\n      { errorContext }\n    )\n  }\n\n  const listInstalledPacks = async (signal?: AbortSignal) => {\n    const errorContext = 'Fetching installed packs'\n\n    return executeRequest<InstalledPacksResponse>(\n      () => managerApiClient.get(ManagerRoute.LIST_INSTALLED, { signal }),\n      { errorContext }\n    )\n  }\n\n  const getImportFailInfo = async (signal?: AbortSignal) => {\n    const errorContext = 'Fetching import failure information'\n\n    return executeRequest<Record<string, unknown>>(\n      () => managerApiClient.get(ManagerRoute.IMPORT_FAIL_INFO, { signal }),\n      { errorContext }\n    )\n  }\n\n  const getImportFailInfoBulk = async (\n    params: components['schemas']['ImportFailInfoBulkRequest'] = {},\n    signal?: AbortSignal\n  ) => {\n    const errorContext = 'Fetching bulk import failure information'\n\n    if (!params.cnr_ids?.length && !params.urls?.length) {\n      return {}\n    }\n\n    return executeRequest<components['schemas']['ImportFailInfoBulkResponse']>(\n      () =>\n        managerApiClient.post(ManagerRoute.IMPORT_FAIL_INFO_BULK, params, {\n          signal\n        }),\n      { errorContext }\n    )\n  }\n\n  const queueTask = async (\n    kind: QueueTaskItem['kind'],\n    params: QueueTaskItem['params'],\n    ui_id?: string,\n    signal?: AbortSignal\n  ) => {\n    const task: QueueTaskItem = {\n      kind,\n      params,\n      ui_id: ui_id || uuidv4(),\n      client_id: api.clientId ?? api.initialClientId ?? 'unknown'\n    }\n\n    const errorContext = `Queueing ${task.kind} task`\n    const routeSpecificErrors = {\n      403: GENERIC_SECURITY_ERR_MSG,\n      404: `Not Found: Task could not be queued`\n    }\n\n    return executeRequest<string>(\n      () => managerApiClient.post(ManagerRoute.QUEUE_TASK, task, { signal }),\n      { errorContext, routeSpecificErrors }\n    )\n  }\n\n  const installPack = async (\n    params: InstallPackParams,\n    ui_id?: string,\n    signal?: AbortSignal\n  ) => {\n    return queueTask('install', params, ui_id, signal)\n  }\n\n  const uninstallPack = async (\n    params: components['schemas']['UninstallPackParams'],\n    ui_id?: string,\n    signal?: AbortSignal\n  ) => {\n    return queueTask('uninstall', params, ui_id, signal)\n  }\n\n  const disablePack = async (\n    params: components['schemas']['DisablePackParams'],\n    ui_id?: string,\n    signal?: AbortSignal\n  ) => {\n    return queueTask('disable', params, ui_id, signal)\n  }\n\n  const enablePack = async (\n    params: components['schemas']['EnablePackParams'],\n    ui_id?: string,\n    signal?: AbortSignal\n  ) => {\n    return queueTask('enable', params, ui_id, signal)\n  }\n\n  const updatePack = async (\n    params: components['schemas']['UpdatePackParams'],\n    ui_id?: string,\n    signal?: AbortSignal\n  ) => {\n    return queueTask('update', params, ui_id, signal)\n  }\n\n  const updateAllPacks = async (\n    params: UpdateAllPacksParams = {},\n    ui_id?: string,\n    signal?: AbortSignal\n  ) => {\n    const errorContext = 'Updating all packs'\n    const routeSpecificErrors = {\n      403: 'Forbidden: To use this action, a security_level of `middle or below` is required',\n      401: 'Unauthorized: ComfyUI-Manager job queue is busy'\n    }\n\n    const queryParams = {\n      mode: params.mode,\n      client_id: api.clientId ?? api.initialClientId ?? 'unknown',\n      ui_id: ui_id || uuidv4()\n    }\n\n    return executeRequest<string>(\n      () =>\n        managerApiClient.post(ManagerRoute.UPDATE_ALL, null, {\n          params: queryParams,\n          signal\n        }),\n      { errorContext, routeSpecificErrors }\n    )\n  }\n\n  const updateComfyUI = async (\n    params: UpdateComfyUIParams = { is_stable: true },\n    ui_id?: string,\n    signal?: AbortSignal\n  ) => {\n    const errorContext = 'Updating ComfyUI'\n    const routeSpecificErrors = {\n      400: 'Bad Request: Missing required parameters',\n      403: 'Forbidden: To use this action, a security_level of `middle or below` is required'\n    }\n\n    const queryParams = {\n      client_id: api.clientId ?? api.initialClientId ?? 'unknown',\n      ui_id: ui_id || uuidv4(),\n      ...params\n    }\n\n    return executeRequest<string>(\n      () =>\n        managerApiClient.post(ManagerRoute.UPDATE_COMFYUI, null, {\n          params: queryParams,\n          signal\n        }),\n      { errorContext, routeSpecificErrors }\n    )\n  }\n\n  const rebootComfyUI = async (signal?: AbortSignal) => {\n    const errorContext = 'Rebooting ComfyUI'\n    const routeSpecificErrors = {\n      403: 'Forbidden: Rebooting ComfyUI requires security_level of middle or below'\n    }\n\n    return executeRequest<null>(\n      () => managerApiClient.post(ManagerRoute.REBOOT, null, { signal }),\n      { errorContext, routeSpecificErrors }\n    )\n  }\n\n  const isLegacyManagerUI = async (signal?: AbortSignal) => {\n    const errorContext = 'Checking if user set Manager to use the legacy UI'\n\n    return executeRequest<{ is_legacy_manager_ui: boolean }>(\n      () => managerApiClient.get(ManagerRoute.IS_LEGACY_MANAGER_UI, { signal }),\n      { errorContext }\n    )\n  }\n\n  const getTaskHistory = async (\n    options: {\n      ui_id?: string\n      max_items?: number\n      client_id?: string\n      offset?: number\n    } = {},\n    signal?: AbortSignal\n  ) => {\n    const errorContext = 'Getting ComfyUI-Manager task history'\n\n    return executeRequest<ManagerTaskHistory>(\n      () =>\n        managerApiClient.get(ManagerRoute.TASK_HISTORY, {\n          params: options,\n          signal\n        }),\n      { errorContext }\n    )\n  }\n\n  return {\n    // State\n    isLoading,\n    error,\n\n    // Queue operations\n    startQueue,\n    getQueueStatus,\n    getTaskHistory,\n\n    // Pack management\n    listInstalledPacks,\n    getImportFailInfo,\n    getImportFailInfoBulk,\n    installPack,\n    uninstallPack,\n    enablePack,\n    disablePack,\n    updatePack,\n    updateAllPacks,\n\n    // System operations\n    updateComfyUI,\n    rebootComfyUI,\n    isLegacyManagerUI\n  }\n}\n","import { useEventListener, whenever } from '@vueuse/core'\nimport { defineStore } from 'pinia'\nimport { v4 as uuidv4 } from 'uuid'\nimport { computed, ref, watch } from 'vue'\n\nimport { t } from '@/i18n'\nimport { useCachedRequest } from '@/composables/useCachedRequest'\nimport { useServerLogs } from '@/composables/useServerLogs'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { api } from '@/scripts/api'\nimport { app } from '@/scripts/app'\nimport { useComfyRegistryService } from '@/services/comfyRegistryService'\n\nimport { normalizePackKeys } from '@/utils/packUtils'\nimport { useManagerQueue } from '@/workbench/extensions/manager/composables/useManagerQueue'\nimport { useComfyManagerService } from '@/workbench/extensions/manager/services/comfyManagerService'\nimport type {\n  NodePackId,\n  RegistryPack,\n  TaskLog\n} from '@/workbench/extensions/manager/types/comfyManagerTypes'\nimport type { components } from '@/workbench/extensions/manager/types/generatedManagerTypes'\nimport { versionStatusFilters } from '@/workbench/extensions/manager/utils/nodePackVersionUtil'\n\ntype InstallPackParams = components['schemas']['InstallPackParams']\ntype InstalledPacksResponse = components['schemas']['InstalledPacksResponse']\ntype ManagerPackInfo = components['schemas']['ManagerPackInfo']\ntype ManagerPackInstalled = components['schemas']['ManagerPackInstalled']\ntype ManagerTaskHistory = Record<\n  string,\n  components['schemas']['TaskHistoryItem']\n>\ntype ManagerTaskQueue = components['schemas']['TaskStateMessage']\ntype UpdateAllPacksParams = components['schemas']['UpdateAllPacksParams']\n\nfunction isTaskForRequest(taskId: string, requestId: string) {\n  return taskId === requestId || taskId.startsWith(`${requestId}_`)\n}\n\n/**\n * Store for state of installed node packs\n */\nexport const useComfyManagerStore = defineStore('comfyManager', () => {\n  const managerService = useComfyManagerService()\n  const toast = useToast()\n\n  const installedPacks = ref<InstalledPacksResponse>({})\n  const enabledPacksIds = ref<Set<NodePackId>>(new Set())\n  const disabledPacksIds = ref<Set<NodePackId>>(new Set())\n  const installedPacksIds = ref<Set<NodePackId>>(new Set())\n  const installingPacksIds = ref<Set<NodePackId>>(new Set())\n  const updatingPacksIds = ref<Set<NodePackId>>(new Set())\n  const isStale = ref(true)\n  const taskLogs = ref<TaskLog[]>([])\n  const succeededTasksLogs = ref<TaskLog[]>([])\n  const failedTasksLogs = ref<TaskLog[]>([])\n\n  const serverTaskHistory = ref<ManagerTaskHistory>({})\n  const requestFailures = ref<ManagerTaskHistory>({})\n  const taskHistory = computed(() => ({\n    ...requestFailures.value,\n    ...serverTaskHistory.value\n  }))\n  const queueError = ref<string | null>(null)\n  const succeededTasksIds = ref<string[]>([])\n  const failedTasksIds = ref<string[]>([])\n  const taskQueue = ref<ManagerTaskQueue>({\n    history: {},\n    running_queue: [],\n    pending_queue: [],\n    installed_packs: {}\n  })\n\n  // Track task ID to pack ID mapping for proper state cleanup\n  const taskIdToPackId = ref(new Map<string, NodePackId>())\n\n  const managerQueue = useManagerQueue(\n    serverTaskHistory,\n    taskQueue,\n    installedPacks\n  )\n  const pendingRequests = ref(\n    new Map<string, 'submitting' | 'queued' | 'confirmed'>()\n  )\n  let queueStartRequest = 0\n  const isProcessingTasks = computed(\n    () =>\n      managerQueue.isProcessing.value ||\n      pendingRequests.value.size > 0 ||\n      updatingPacksIds.value.size > 0\n  )\n\n  useEventListener(\n    app.api,\n    ['cm-task-started', 'cm-task-completed'],\n    (\n      event: CustomEvent<\n        | components['schemas']['MessageTaskStarted']\n        | components['schemas']['MessageTaskDone']\n      >\n    ) => {\n      const { ui_id: taskId, state } = event.detail\n      const observedIds = [\n        ...state.running_queue.map((task) => task.ui_id),\n        ...state.pending_queue.map((task) => task.ui_id),\n        ...Object.keys(state.history)\n      ]\n      for (const id of observedIds) {\n        delete requestFailures.value[id]\n      }\n      for (const [requestId, requestState] of pendingRequests.value) {\n        if (\n          requestState === 'confirmed' ||\n          observedIds.some((id) => isTaskForRequest(id, requestId))\n        ) {\n          pendingRequests.value.delete(requestId)\n        }\n      }\n      if (event.type === 'cm-task-completed') {\n        const packId = taskIdToPackId.value.get(taskId)\n        if (packId) installingPacksIds.value.delete(packId)\n        taskIdToPackId.value.delete(taskId)\n      }\n      if (\n        managerQueue.currentQueueLength.value > 0 ||\n        !isProcessingTasks.value\n      ) {\n        queueError.value = null\n      }\n    }\n  )\n\n  const setStale = () => {\n    isStale.value = true\n  }\n\n  function isTaskFailed(requestId: string) {\n    return failedTasksIds.value.some((id) => isTaskForRequest(id, requestId))\n  }\n\n  function isTaskInProgress(requestId: string) {\n    return (\n      pendingRequests.value.has(requestId) ||\n      [...taskQueue.value.running_queue, ...taskQueue.value.pending_queue].some(\n        (task) => isTaskForRequest(task.ui_id, requestId)\n      )\n    )\n  }\n\n  const partitionTaskLogs = () => {\n    const successTaskLogs: TaskLog[] = []\n    const failTaskLogs: TaskLog[] = []\n    for (const log of taskLogs.value) {\n      if (isTaskFailed(log.taskId)) {\n        failTaskLogs.push(log)\n      } else {\n        successTaskLogs.push(log)\n      }\n    }\n    succeededTasksLogs.value = successTaskLogs\n    failedTasksLogs.value = failTaskLogs\n  }\n\n  const partitionTasks = () => {\n    const successTasksIds = []\n    const failTasksIds = []\n    for (const task of Object.values(taskHistory.value)) {\n      if (task.status?.status_str === 'success') {\n        successTasksIds.push(task.ui_id)\n      } else {\n        failTasksIds.push(task.ui_id)\n      }\n    }\n    succeededTasksIds.value = successTasksIds\n    failedTasksIds.value = failTasksIds\n  }\n\n  whenever(\n    taskHistory,\n    () => {\n      partitionTasks()\n      partitionTaskLogs()\n    },\n    { deep: true }\n  )\n\n  const getPackId = (pack: ManagerPackInstalled) => pack.cnr_id || pack.aux_id\n\n  const isInstalledPackId = (packName: NodePackId | undefined): boolean =>\n    !!packName && installedPacksIds.value.has(packName)\n\n  const isEnabledPackId = (packName: NodePackId | undefined): boolean =>\n    !!packName &&\n    isInstalledPackId(packName) &&\n    enabledPacksIds.value.has(packName)\n\n  const isInstallingPackId = (packName: NodePackId | undefined): boolean =>\n    !!packName &&\n    (installingPacksIds.value.has(packName) ||\n      updatingPacksIds.value.has(packName))\n\n  const packsToIdSet = (packs: ManagerPackInstalled[]) =>\n    packs.reduce((acc, pack) => {\n      const id = pack.cnr_id || pack.aux_id\n      if (id) acc.add(id)\n      return acc\n    }, new Set<NodePackId>())\n\n  /**\n   * A pack is disabled if there is a disabled entry and no corresponding\n   * enabled entry. If `packname@1.0.2` is disabled, but `packname@1.0.3` is\n   * enabled, then `packname` is considered enabled.\n   *\n   * @example\n   * installedPacks = {\n   *   \"packname@1_0_2\": { enabled: false, cnr_id: \"packname\" },\n   *   \"packname\": { enabled: true, cnr_id: \"packname\" }\n   * }\n   * isDisabled(\"packname\") // false\n   *\n   * installedPacks = {\n   *   \"packname@1_0_2\": { enabled: false, cnr_id: \"packname\" },\n   * }\n   * isDisabled(\"packname\") // true\n   */\n  const updateDisabledIds = (packs: ManagerPackInstalled[]) => {\n    // Use temporary variables to avoid triggering reactivity\n    const enabledIds = new Set<NodePackId>()\n    const disabledIds = new Set<NodePackId>()\n\n    for (const pack of packs) {\n      const id = getPackId(pack)\n      if (!id) continue\n\n      const { enabled } = pack\n\n      if (enabled) enabledIds.add(id)\n      else disabledIds.add(id)\n\n      // If pack in both (has a disabled and enabled version), remove from disabled\n      const inBothSets = enabledIds.has(id) && disabledIds.has(id)\n      if (inBothSets) disabledIds.delete(id)\n    }\n\n    enabledPacksIds.value = enabledIds\n    disabledPacksIds.value = disabledIds\n  }\n\n  const updateInstalledIds = (packs: ManagerPackInstalled[]) => {\n    installedPacksIds.value = packsToIdSet(packs)\n  }\n\n  const onPacksChanged = () => {\n    const packs = Object.values(installedPacks.value)\n    updateDisabledIds(packs)\n    updateInstalledIds(packs)\n  }\n\n  watch(installedPacks, onPacksChanged, { deep: true })\n\n  const refreshInstalledList = async () => {\n    const packs = await managerService.listInstalledPacks()\n    if (packs) {\n      // Normalize pack keys to ensure consistent access\n      installedPacks.value = normalizePackKeys(packs)\n    }\n    isStale.value = false\n  }\n\n  whenever(isStale, refreshInstalledList, { immediate: true })\n\n  async function confirmQueuedRequests() {\n    const queuedRequests = [...pendingRequests.value]\n      .filter(([, state]) => state !== 'submitting')\n      .map(([id]) => id)\n    if (!queuedRequests.length) return true\n\n    const runningQueue = taskQueue.value.running_queue\n    const requestId = queueStartRequest\n    const status = await managerService.getQueueStatus(\n      api.clientId ?? api.initialClientId ?? 'unknown'\n    )\n    if (requestId !== queueStartRequest) return true\n    if (status === null) return false\n\n    const hasNewQueueState = taskQueue.value.running_queue !== runningQueue\n    for (const id of queuedRequests) {\n      if (status.total_count > 0 && !hasNewQueueState) {\n        pendingRequests.value.set(id, 'confirmed')\n      } else {\n        pendingRequests.value.delete(id)\n      }\n    }\n    return true\n  }\n\n  async function startQueue() {\n    const requestId = ++queueStartRequest\n    queueError.value = null\n    const result = await managerService.startQueue()\n    if (requestId !== queueStartRequest) return\n    if (result !== null && (await confirmQueuedRequests())) return\n\n    if (requestId === queueStartRequest && isProcessingTasks.value) {\n      queueError.value = managerService.error.value ?? t('g.unknownError')\n      toast.error(t('g.error'), { description: queueError.value })\n    }\n  }\n\n  const enqueueTaskWithLogs = async (\n    task: (taskId: string) => Promise<string | null>,\n    taskName: string\n  ) => {\n    const taskId = uuidv4()\n    const { logs } = useServerLogs({\n      ui_id: taskId,\n      immediate: true\n    })\n\n    pendingRequests.value.set(taskId, 'submitting')\n    taskLogs.value.push({ taskName, taskId, logs: logs.value })\n    partitionTaskLogs()\n\n    const result = await task(taskId)\n    if (result === null) {\n      const packId = taskIdToPackId.value.get(taskId)\n      if (packId) installingPacksIds.value.delete(packId)\n      taskIdToPackId.value.delete(taskId)\n      pendingRequests.value.delete(taskId)\n      const message = managerService.error.value ?? t('g.unknownError')\n      toast.error(t('g.error'), { description: message })\n\n      requestFailures.value[taskId] = {\n        ui_id: taskId,\n        client_id: api.clientId || 'unknown',\n        kind: 'error',\n        result: 'failed',\n        status: {\n          status_str: 'error',\n          completed: false,\n          messages: [message]\n        },\n        timestamp: new Date().toISOString()\n      }\n      return\n    }\n    if (pendingRequests.value.has(taskId)) {\n      pendingRequests.value.set(taskId, 'queued')\n    }\n    await startQueue()\n  }\n\n  const installPack = useCachedRequest<InstallPackParams, void>(\n    async (params: InstallPackParams, signal?: AbortSignal) => {\n      if (!params.id || installingPacksIds.value.has(params.id)) return\n\n      let actionDescription = t('g.installing')\n      if (installedPacksIds.value.has(params.id)) {\n        const installedPack = installedPacks.value[params.id]\n\n        if (installedPack.ver !== params.selected_version) {\n          actionDescription = t('manager.changingVersion', {\n            from: installedPack.ver,\n            to: params.selected_version\n          })\n        } else {\n          actionDescription = t('g.enabling')\n        }\n      }\n\n      installingPacksIds.value.add(params.id)\n      const task = (taskId: string) => {\n        taskIdToPackId.value.set(taskId, params.id)\n        return managerService.installPack(params, taskId, signal)\n      }\n      await enqueueTaskWithLogs(task, `${actionDescription} ${params.id}`)\n    },\n    { maxSize: 1 }\n  )\n\n  async function switchPack(\n    pack: RegistryPack & { id: NodePackId },\n    policy: keyof typeof versionStatusFilters\n  ) {\n    const registry = useComfyRegistryService()\n    const packName = pack.name ?? pack.id\n    const versions = await registry.getPackVersions(pack.id, {\n      statuses: versionStatusFilters[policy]\n    })\n    if (!isEnabledPackId(pack.id)) return\n    if (versions === null) {\n      toast.error(packName, {\n        description: registry.error.value ?? t('manager.errorConnecting')\n      })\n      return\n    }\n    const version = versions[0]?.version\n    if (!version) {\n      toast.warning(packName, { description: t('manager.noUpdateVersion') })\n      return\n    }\n    if (version === getInstalledPackVersion(pack.id)) {\n      toast.info(packName, {\n        description: t('manager.updateVersionInstalled', { version })\n      })\n      return\n    }\n    await installPack.call({\n      id: pack.id,\n      version,\n      selected_version: version,\n      repository: pack.repository ?? '',\n      channel: 'default',\n      mode: 'cache'\n    })\n  }\n\n  async function updatePacks(\n    packs: RegistryPack[],\n    policy: keyof typeof versionStatusFilters = 'active'\n  ) {\n    const packsToUpdate = packs.filter(\n      (pack): pack is RegistryPack & { id: NodePackId } =>\n        isEnabledPackId(pack.id) && !isInstallingPackId(pack.id)\n    )\n    if (!packsToUpdate.length) return\n    for (const pack of packsToUpdate) {\n      updatingPacksIds.value.add(pack.id)\n    }\n    try {\n      for (const pack of packsToUpdate) {\n        await switchPack(pack, policy)\n      }\n    } catch (error) {\n      reportError(error, {\n        surface: 'platform',\n        errorType: 'failure_updating_node_packs'\n      })\n      toast.error(t('manager.update'), {\n        description: t('manager.updateFailed')\n      })\n    } finally {\n      for (const pack of packsToUpdate) {\n        updatingPacksIds.value.delete(pack.id)\n      }\n      installPack.clear()\n    }\n  }\n\n  const uninstallPack = async (\n    params: ManagerPackInfo,\n    signal?: AbortSignal\n  ) => {\n    installPack.clear()\n    installPack.cancel()\n\n    installingPacksIds.value.add(params.id)\n    const uninstallParams: components['schemas']['UninstallPackParams'] = {\n      node_name: params.id,\n      is_unknown: false\n    }\n    const task = (taskId: string) => {\n      taskIdToPackId.value.set(taskId, params.id)\n      return managerService.uninstallPack(uninstallParams, taskId, signal)\n    }\n    await enqueueTaskWithLogs(\n      task,\n      t('manager.uninstalling', { id: params.id })\n    )\n  }\n\n  const updatePack = useCachedRequest<ManagerPackInfo, void>(\n    async (params: ManagerPackInfo, signal?: AbortSignal) => {\n      updateAllPacks.cancel()\n      const updateParams: components['schemas']['UpdatePackParams'] = {\n        node_name: params.id,\n        node_ver: params.version\n      }\n      const task = (taskId: string) =>\n        managerService.updatePack(updateParams, taskId, signal)\n      await enqueueTaskWithLogs(task, t('g.updating', { id: params.id }))\n    },\n    { maxSize: 1 }\n  )\n\n  const updateAllPacks = useCachedRequest<UpdateAllPacksParams, void>(\n    async (params: UpdateAllPacksParams, signal?: AbortSignal) => {\n      const task = (taskId: string) =>\n        managerService.updateAllPacks(params, taskId, signal)\n      await enqueueTaskWithLogs(task, t('manager.updatingAllPacks'))\n    },\n    { maxSize: 1 }\n  )\n\n  const disablePack = async (params: ManagerPackInfo, signal?: AbortSignal) => {\n    const disableParams: components['schemas']['DisablePackParams'] = {\n      node_name: params.id,\n      is_unknown: false\n    }\n    const task = (taskId: string) =>\n      managerService.disablePack(disableParams, taskId, signal)\n    await enqueueTaskWithLogs(task, t('g.disabling', { id: params.id }))\n  }\n\n  const enablePack = async (params: ManagerPackInfo, signal?: AbortSignal) => {\n    const enableParams: components['schemas']['EnablePackParams'] = {\n      cnr_id: params.id\n    }\n    const task = (taskId: string) =>\n      managerService.enablePack(enableParams, taskId, signal)\n    await enqueueTaskWithLogs(task, t('g.enabling', { id: params.id }))\n  }\n\n  const getInstalledPackVersion = (packId: NodePackId) => {\n    if (!Object.hasOwn(installedPacks.value, packId)) return\n    const pack = installedPacks.value[packId]\n    return pack.ver\n  }\n\n  const clearLogs = () => {\n    taskLogs.value = []\n  }\n\n  const resetTaskState = () => {\n    queueError.value = null\n    // Clear all task-related reactive state for fresh start after restart\n    taskLogs.value = []\n    serverTaskHistory.value = {}\n    requestFailures.value = {}\n    succeededTasksIds.value = []\n    failedTasksIds.value = []\n    succeededTasksLogs.value = []\n    failedTasksLogs.value = []\n    installingPacksIds.value.clear()\n    updatingPacksIds.value.clear()\n    taskIdToPackId.value.clear()\n    pendingRequests.value.clear()\n    queueStartRequest++\n    managerQueue.isProcessing.value = false\n\n    // Reset task queue to initial state\n    taskQueue.value = {\n      history: {},\n      running_queue: [],\n      pending_queue: [],\n      installed_packs: {}\n    }\n  }\n\n  return {\n    // Manager state\n    isLoading: managerService.isLoading,\n    error: managerService.error,\n    taskLogs,\n    clearLogs,\n    resetTaskState,\n    setStale,\n\n    // Installed packs state\n    installedPacks,\n    installedPacksIds,\n    isPackInstalled: isInstalledPackId,\n    isPackEnabled: isEnabledPackId,\n    isPackInstalling: isInstallingPackId,\n    getInstalledPackVersion,\n    refreshInstalledList,\n\n    // Task queue state and actions\n    taskHistory,\n    taskQueue,\n    queueError,\n    startQueue,\n    isProcessingTasks,\n    succeededTasksIds,\n    failedTasksIds,\n    isTaskFailed,\n    isTaskInProgress,\n    succeededTasksLogs,\n    failedTasksLogs,\n    managerQueue,\n\n    // Pack actions\n    installPack,\n    uninstallPack,\n    updatePack,\n    updatePacks,\n    updateAllPacks,\n    disablePack,\n    enablePack\n  }\n})\n","import { whenever } from '@vueuse/core'\nimport { computed, onUnmounted, ref } from 'vue'\n\nimport type { components } from '@/types/comfyRegistryTypes'\nimport { useNodePacks } from '@/workbench/extensions/manager/composables/nodePack/useNodePacks'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport type { UseNodePacksOptions } from '@/workbench/extensions/manager/types/comfyManagerTypes'\n\nexport const useInstalledPacks = (options: UseNodePacksOptions = {}) => {\n  const comfyManagerStore = useComfyManagerStore()\n\n  // Flag to prevent duplicate fetches during initialization\n  const isInitializing = ref(false)\n  const lastFetchedIds = ref<string>('')\n\n  const installedPackIds = computed(() =>\n    Array.from(comfyManagerStore.installedPacksIds)\n  )\n\n  const { startFetch, cleanup, error, isLoading, nodePacks, isReady } =\n    useNodePacks(installedPackIds, options)\n\n  const filterInstalledPack = (packs: components['schemas']['Node'][]) =>\n    packs.filter((pack) => comfyManagerStore.isPackInstalled(pack.id))\n\n  const startFetchInstalled = async () => {\n    // Prevent duplicate calls during initialization\n    if (isInitializing.value) {\n      return\n    }\n\n    isInitializing.value = true\n    try {\n      if (comfyManagerStore.installedPacksIds.size === 0) {\n        await comfyManagerStore.refreshInstalledList()\n      }\n      await startFetch()\n    } finally {\n      isInitializing.value = false\n    }\n  }\n\n  // When installedPackIds changes, we need to update the nodePacks\n  // But only if the IDs actually changed (not just array reference)\n  whenever(installedPackIds, async (newIds) => {\n    const newIdsStr = newIds.sort().join(',')\n    if (newIdsStr !== lastFetchedIds.value && !isInitializing.value) {\n      lastFetchedIds.value = newIdsStr\n      await startFetch()\n    }\n  })\n\n  onUnmounted(() => {\n    cleanup()\n  })\n\n  // Create a computed property that provides installed pack info with versions\n  const installedPacksWithVersions = computed(() => {\n    const result: Array<{ id: string; version: string }> = []\n\n    for (const pack of Object.values(comfyManagerStore.installedPacks)) {\n      const id = pack.cnr_id || pack.aux_id\n      if (id) {\n        result.push({\n          id,\n          version: pack.ver\n        })\n      }\n    }\n\n    return result\n  })\n\n  return {\n    error,\n    isLoading,\n    isReady,\n    installedPacks: nodePacks,\n    installedPacksWithVersions,\n    startFetchInstalled,\n    filterInstalledPack\n  }\n}\n","import { isEmpty, isNil } from 'es-toolkit/compat'\n\nimport type {\n  RegistryAccelerator,\n  RegistryOS\n} from '@/workbench/extensions/manager/types/compatibility.types'\nimport type { ConflictDetail } from '@/workbench/extensions/manager/types/conflictDetectionTypes'\n\n/**\n * Maps system OS string to Registry OS format\n * @param systemOS Raw OS string from system stats ('darwin', 'win32', 'linux', etc)\n * @returns Registry OS or undefined if unknown\n */\nfunction getRegistryOS(systemOS?: string): RegistryOS | undefined {\n  if (!systemOS) return undefined\n\n  const lower = systemOS.toLowerCase()\n  // Check darwin first to avoid matching 'win' in 'darwin'\n  if (lower.includes('darwin') || lower.includes('mac')) return 'macOS'\n  if (lower.includes('win')) return 'Windows'\n  if (lower.includes('linux')) return 'Linux'\n\n  return undefined\n}\n\n/**\n * Maps device type to Registry accelerator format\n * @param deviceType Raw device type from system stats ('cuda', 'mps', 'rocm', 'cpu', etc)\n * @returns Registry accelerator\n */\nfunction getRegistryAccelerator(deviceType?: string): RegistryAccelerator {\n  if (!deviceType) return 'CPU'\n\n  const lower = deviceType.toLowerCase()\n  if (lower === 'cuda') return 'CUDA'\n  if (lower === 'mps') return 'Metal'\n  if (lower === 'rocm') return 'ROCm'\n\n  return 'CPU'\n}\n\n/**\n * Checks OS compatibility\n * @param supported Supported OS list from Registry (null/undefined = all OS supported)\n * @param current Current system OS\n * @returns ConflictDetail if incompatible, null if compatible\n */\nexport function checkOSCompatibility(\n  supported?: RegistryOS[] | null,\n  current?: string\n): ConflictDetail | null {\n  // null/undefined/empty = all OS supported\n  if (isNil(supported) || isEmpty(supported)) return null\n\n  const currentOS = getRegistryOS(current)\n  if (!currentOS) {\n    return {\n      type: 'os',\n      current_value: 'Unknown',\n      required_value: supported.join(', ')\n    }\n  }\n\n  if (!supported.includes(currentOS)) {\n    return {\n      type: 'os',\n      current_value: currentOS,\n      required_value: supported.join(', ')\n    }\n  }\n\n  return null\n}\n\n/**\n * Checks accelerator compatibility\n * @param supported Supported accelerators from Registry (null/undefined = all accelerators supported)\n * @param current Current device type\n * @returns ConflictDetail if incompatible, null if compatible\n */\nexport function checkAcceleratorCompatibility(\n  supported?: RegistryAccelerator[] | null,\n  current?: string\n): ConflictDetail | null {\n  // null/undefined/empty = all accelerator supported\n  if (isNil(supported) || isEmpty(supported)) return null\n\n  const currentAcc = getRegistryAccelerator(current)\n\n  if (!supported.includes(currentAcc)) {\n    return {\n      type: 'accelerator',\n      current_value: currentAcc,\n      required_value: supported.join(', ')\n    }\n  }\n\n  return null\n}\n\n/**\n * Normalizes OS values from Registry API\n * Handles edge cases like \"OS Independent\"\n * @returns undefined if all OS supported, otherwise filtered valid OS list\n */\nexport function normalizeOSList(\n  osValues?: string[] | null\n): RegistryOS[] | undefined {\n  if (isNil(osValues) || isEmpty(osValues)) return undefined\n\n  // \"OS Independent\" means all OS supported\n  if (osValues.some((os) => os.toLowerCase() === 'os independent')) {\n    return undefined\n  }\n\n  // Filter to valid Registry OS values only\n  const validOS: RegistryOS[] = []\n  osValues.forEach((os) => {\n    if (os === 'Windows' || os === 'macOS' || os === 'Linux') {\n      if (!validOS.includes(os)) validOS.push(os)\n    }\n  })\n\n  return validOS.length > 0 ? validOS : undefined\n}\n","import { isEmpty, isNil } from 'es-toolkit/compat'\nimport { clean, satisfies } from 'semver'\n\nimport config from '@/config'\nimport type {\n  ConflictDetail,\n  ConflictType\n} from '@/workbench/extensions/manager/types/conflictDetectionTypes'\n\n/**\n * Cleans a version string by removing common prefixes and normalizing format\n * @param version Raw version string (e.g., \"v1.2.3\", \"1.2.3-alpha\")\n * @returns Cleaned version string or original if cleaning fails\n */\nfunction cleanVersion(version: string): string {\n  return clean(version) || version\n}\n\n/**\n * Checks version compatibility and returns conflict details.\n * Supports all semver ranges including >=, <=, >, <, ~, ^ operators.\n * @param type Conflict type (e.g., 'comfyui_version', 'frontend_version')\n * @param currentVersion Current version string\n * @param supportedVersion Required version range string\n * @returns ConflictDetail object if incompatible, null if compatible\n */\nexport function checkVersionCompatibility(\n  type: ConflictType,\n  currentVersion?: string,\n  supportedVersion?: string\n): ConflictDetail | null {\n  // If current version is unknown, assume compatible (no conflict)\n  if (isNil(currentVersion) || isEmpty(currentVersion)) {\n    return null\n  }\n\n  // If no version requirement specified, assume compatible (no conflict)\n  if (isNil(supportedVersion) || isEmpty(supportedVersion.trim())) {\n    return null\n  }\n\n  // Clean and check version compatibility\n  const cleanCurrent = cleanVersion(currentVersion)\n\n  // Check if version satisfies the range\n  let isCompatible: boolean\n  try {\n    isCompatible = satisfies(cleanCurrent, supportedVersion)\n  } catch {\n    // If semver can't parse it, return conflict\n    return {\n      type,\n      current_value: currentVersion,\n      required_value: supportedVersion\n    }\n  }\n\n  if (isCompatible) return null\n\n  return {\n    type,\n    current_value: currentVersion,\n    required_value: supportedVersion\n  }\n}\n\n/**\n * get frontend version from config.\n * @returns frontend version string or undefined\n */\nexport function getFrontendVersion(): string | undefined {\n  return config.app_version || import.meta.env.VITE_APP_VERSION || undefined\n}\n","import { groupBy, uniqBy } from 'es-toolkit/compat'\n\nimport { normalizePackId } from '@/utils/packUtils'\nimport type {\n  RegistryAccelerator,\n  RegistryOS\n} from '@/workbench/extensions/manager/types/compatibility.types'\nimport type {\n  ConflictDetail,\n  ConflictDetectionResult,\n  SystemEnvironment\n} from '@/workbench/extensions/manager/types/conflictDetectionTypes'\nimport {\n  checkAcceleratorCompatibility,\n  checkOSCompatibility\n} from '@/workbench/extensions/manager/utils/systemCompatibility'\nimport { checkVersionCompatibility } from '@/workbench/extensions/manager/utils/versionUtil'\n\n/**\n * Checks for banned package status conflicts.\n */\nexport function createBannedConflict(\n  isBanned?: boolean\n): ConflictDetail | null {\n  if (isBanned === true) {\n    return {\n      type: 'banned',\n      current_value: 'installed',\n      required_value: 'not_banned'\n    }\n  }\n  return null\n}\n\n/**\n * Checks for pending package status conflicts.\n */\nexport function createPendingConflict(\n  isPending?: boolean\n): ConflictDetail | null {\n  if (isPending === true) {\n    return {\n      type: 'pending',\n      current_value: 'installed',\n      required_value: 'not_pending'\n    }\n  }\n  return null\n}\n\n/**\n * Single source of truth for mapping a Node/NodeVersion status string to\n * banned/pending booleans. NodeStatusBanned is a Node-only value; NodeVersion\n * has no pending-equivalent Node status, so isPending only checks the\n * NodeVersion enum.\n */\nexport function deriveStatusFlags(status?: string): {\n  isBanned: boolean\n  isPending: boolean\n} {\n  return {\n    isBanned:\n      status === 'NodeStatusBanned' || status === 'NodeVersionStatusBanned',\n    isPending: status === 'NodeVersionStatusPending'\n  }\n}\n\n/**\n * Normalized compatibility inputs for a single package, produced by each call\n * site from its own source shape. Banned/pending are pre-derived booleans\n * (see {@link deriveStatusFlags}) since the two callers read status from\n * different source shapes (Node vs NodeVersion).\n */\nexport interface CompatibilityInput {\n  supported_os?: RegistryOS[]\n  supported_accelerators?: RegistryAccelerator[]\n  supported_comfyui_version?: string\n  supported_comfyui_frontend_version?: string\n  isBanned: boolean\n  isPending: boolean\n}\n\n/**\n * Runs the six compatibility leaf checks and collects the conflicts that fire.\n *\n * Canonical order = comfyui_version → frontend_version → OS → accelerator →\n * banned → pending; every consumer filters conflicts by `.type`, so the order\n * is cosmetic only.\n */\nexport function evaluateCompatibility(\n  input: CompatibilityInput,\n  env: SystemEnvironment\n): ConflictDetail[] {\n  const conflicts: ConflictDetail[] = []\n\n  const versionConflict = checkVersionCompatibility(\n    'comfyui_version',\n    env.comfyui_version,\n    input.supported_comfyui_version\n  )\n  if (versionConflict) conflicts.push(versionConflict)\n\n  const frontendConflict = checkVersionCompatibility(\n    'frontend_version',\n    env.frontend_version,\n    input.supported_comfyui_frontend_version\n  )\n  if (frontendConflict) conflicts.push(frontendConflict)\n\n  const osConflict = checkOSCompatibility(input.supported_os, env.os)\n  if (osConflict) conflicts.push(osConflict)\n\n  const acceleratorConflict = checkAcceleratorCompatibility(\n    input.supported_accelerators,\n    env.accelerator\n  )\n  if (acceleratorConflict) conflicts.push(acceleratorConflict)\n\n  const bannedConflict = createBannedConflict(input.isBanned)\n  if (bannedConflict) conflicts.push(bannedConflict)\n\n  const pendingConflict = createPendingConflict(input.isPending)\n  if (pendingConflict) conflicts.push(pendingConflict)\n\n  return conflicts\n}\n\n/**\n * Groups and deduplicates conflicts by normalized package name.\n * Consolidates multiple conflict sources (registry checks, import failures, disabled packages with version suffix)\n * into a single UI entry per package.\n *\n * Example:\n * - Input: [{name: \"pack@1_0_3\", conflicts: [...]}, {name: \"pack\", conflicts: [...]}]\n * - Output: [{name: \"pack\", conflicts: [...combined unique conflicts...]}]\n *\n * @param conflicts Array of conflict detection results (may have duplicate packages with version suffixes)\n * @returns Array of deduplicated conflict results grouped by normalized package name\n */\nexport function consolidateConflictsByPackage(\n  conflicts: ConflictDetectionResult[]\n): ConflictDetectionResult[] {\n  // Group conflicts by normalized package name using es-toolkit\n  const grouped = groupBy(conflicts, (conflict) =>\n    normalizePackId(conflict.package_name)\n  )\n\n  // Merge conflicts for each group\n  return Object.entries(grouped).map(([packageName, packageConflicts]) => {\n    // Flatten all conflicts from the group\n    const allConflicts = packageConflicts.flatMap((pc) => pc.conflicts)\n\n    // Remove duplicate conflicts using uniqBy\n    const uniqueConflicts = uniqBy(\n      allConflicts,\n      (conflict) =>\n        `${conflict.type}|${conflict.current_value}|${conflict.required_value}`\n    )\n\n    // Use the first item as base and update with merged data\n    const baseItem = packageConflicts[0]\n    return {\n      ...baseItem,\n      package_name: packageName, // Use normalized name\n      conflicts: uniqueConflicts,\n      has_conflict: uniqueConflicts.length > 0,\n      is_compatible: uniqueConflicts.length === 0\n    }\n  })\n}\n","import { until } from '@vueuse/core'\nimport { find } from 'es-toolkit/compat'\nimport { computed, getCurrentInstance, onUnmounted, readonly, ref } from 'vue'\n\nimport { useComfyRegistryService } from '@/services/comfyRegistryService'\nimport { useSystemStatsStore } from '@/stores/systemStatsStore'\nimport type { components } from '@/types/comfyRegistryTypes'\nimport { useInstalledPacks } from '@/workbench/extensions/manager/composables/nodePack/useInstalledPacks'\nimport { useConflictAcknowledgment } from '@/workbench/extensions/manager/composables/useConflictAcknowledgment'\nimport { useManagerState } from '@/workbench/extensions/manager/composables/useManagerState'\nimport { useComfyManagerService } from '@/workbench/extensions/manager/services/comfyManagerService'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport { useConflictDetectionStore } from '@/workbench/extensions/manager/stores/conflictDetectionStore'\nimport type {\n  RegistryAccelerator,\n  RegistryOS\n} from '@/workbench/extensions/manager/types/compatibility.types'\nimport type {\n  ConflictDetectionResponse,\n  ConflictDetectionResult,\n  ImportFailureMap,\n  Node,\n  NodeRequirements,\n  SystemEnvironment\n} from '@/workbench/extensions/manager/types/conflictDetectionTypes'\nimport {\n  consolidateConflictsByPackage,\n  deriveStatusFlags,\n  evaluateCompatibility\n} from '@/workbench/extensions/manager/utils/conflictUtils'\nimport { normalizeOSList } from '@/workbench/extensions/manager/utils/systemCompatibility'\nimport { getFrontendVersion } from '@/workbench/extensions/manager/utils/versionUtil'\n\n/**\n * Composable for conflict detection system.\n * Error-resilient and asynchronous to avoid affecting other components.\n */\nexport function useConflictDetection() {\n  const managerStore = useComfyManagerStore()\n\n  const {\n    startFetchInstalled,\n    installedPacks,\n    installedPacksWithVersions,\n    isReady: installedPacksReady\n  } = useInstalledPacks()\n\n  const isDetecting = ref(false)\n  const lastDetectionTime = ref<string | null>(null)\n  const detectionError = ref<string | null>(null)\n\n  const systemEnvironment = ref<SystemEnvironment | null>(null)\n\n  const detectionResults = ref<ConflictDetectionResult[]>([])\n  // Store merged conflicts separately for testing\n  const storedMergedConflicts = ref<ConflictDetectionResult[]>([])\n\n  // Registry API request cancellation\n  const abortController = ref<AbortController | null>(null)\n\n  const acknowledgment = useConflictAcknowledgment()\n\n  const conflictStore = useConflictDetectionStore()\n\n  const hasConflicts = computed(() => conflictStore.hasConflicts)\n  const conflictedPackages = computed(() => {\n    return conflictStore.conflictedPackages\n  })\n\n  const bannedPackages = computed(() => conflictStore.bannedPackages)\n  const securityPendingPackages = computed(\n    () => conflictStore.securityPendingPackages\n  )\n\n  /**\n   * Collects current system environment information.\n   * Continues with default values even if errors occur.\n   * @returns Promise that resolves to system environment information\n   */\n  async function collectSystemEnvironment(): Promise<SystemEnvironment> {\n    try {\n      // Get system stats from store (primary source of system information)\n      // Wait for systemStats to be initialized if not already\n      const systemStatsStore = useSystemStatsStore()\n      const { systemStats } = systemStatsStore\n\n      // Wait for initialization using the store's isInitialized property (correct reactive way)\n      await until(() => systemStatsStore.isInitialized).toBe(true)\n\n      const frontendVersion = getFrontendVersion()\n\n      const environment: SystemEnvironment = {\n        comfyui_version: systemStats?.system.comfyui_version ?? '',\n        frontend_version: frontendVersion,\n        os: systemStats?.system.os ?? '',\n        accelerator: systemStats?.devices[0]?.type ?? ''\n      }\n\n      systemEnvironment.value = environment\n      return environment\n    } catch {\n      const fallbackEnvironment: SystemEnvironment = {\n        comfyui_version: undefined,\n        frontend_version: undefined,\n        os: undefined,\n        accelerator: undefined\n      }\n      systemEnvironment.value = fallbackEnvironment\n      return fallbackEnvironment\n    }\n  }\n\n  /**\n   * Fetches requirement information for installed packages using Registry Store.\n   *\n   * This function combines local installation data with Registry API compatibility metadata\n   * using the established store layer pattern with caching and batch requests.\n   *\n   * Process\n   * 1. Get locally installed packages\n   * 2. Batch fetch Registry data using store layer\n   * 3. Combine local + Registry data\n   * 4. Extract compatibility requirements\n   *\n   * @returns Promise that resolves to array of node pack requirements\n   */\n  async function buildNodeRequirements(): Promise<NodeRequirements[]> {\n    try {\n      // Step 1: Use installed packs composable instead of direct API calls\n      await startFetchInstalled() // Ensure data is loaded\n\n      if (!installedPacksReady.value || installedPacks.value.length === 0) {\n        console.warn(\n          '[ConflictDetection] No installed packages available from useInstalledPacks'\n        )\n        return []\n      }\n\n      // Step 2: Get Registry service for bulk API calls\n      const registryService = useComfyRegistryService()\n\n      // Step 3: Setup abort controller for request cancellation\n      abortController.value = new AbortController()\n\n      // Step 4: Use bulk API to fetch all version data in a single request\n      const versionDataMap = new Map<\n        string,\n        components['schemas']['NodeVersion']\n      >()\n\n      // Prepare bulk request with actual installed versions from Manager API\n      const nodeVersions = installedPacksWithVersions.value.map((pack) => ({\n        node_id: pack.id,\n        version: pack.version\n      }))\n\n      if (nodeVersions.length > 0) {\n        try {\n          const bulkResponse = await registryService.getBulkNodeVersions(\n            nodeVersions,\n            abortController.value.signal\n          )\n\n          if (bulkResponse && bulkResponse.node_versions.length > 0) {\n            // Process bulk response\n            bulkResponse.node_versions.forEach((result) => {\n              if (result.status === 'success' && result.node_version) {\n                versionDataMap.set(\n                  result.identifier.node_id,\n                  result.node_version\n                )\n              } else if (result.status === 'error') {\n                console.warn(\n                  `[ConflictDetection] Failed to fetch version data for ${result.identifier.node_id}@${result.identifier.version}:`,\n                  result.error_message\n                )\n              }\n            })\n          }\n        } catch (error) {\n          console.warn(\n            '[ConflictDetection] Failed to fetch bulk version data:',\n            error\n          )\n        }\n      }\n\n      // Step 5: Combine local installation data with Registry version data\n      const requirements: NodeRequirements[] = []\n\n      // IMPORTANT: Use installedPacksWithVersions to check ALL installed packages\n      // not just the ones that exist in Registry (installedPacks)\n      for (const installedPackVersion of installedPacksWithVersions.value) {\n        const versionData = versionDataMap.get(installedPackVersion.id)\n        const isEnabled = managerStore.isPackEnabled(installedPackVersion.id)\n\n        // Find the pack info from Registry if available\n        const packInfo = find(installedPacks.value, {\n          id: installedPackVersion.id\n        })\n\n        if (versionData) {\n          const { isBanned, isPending } = deriveStatusFlags(versionData.status)\n\n          // Combine local installation data with version-specific Registry data\n          const requirement: NodeRequirements = {\n            // Basic package info\n            id: installedPackVersion.id,\n            name: packInfo?.name || installedPackVersion.id,\n            installed_version: installedPackVersion.version,\n            is_enabled: isEnabled,\n\n            // Version-specific compatibility data\n            supported_comfyui_version: versionData.supported_comfyui_version,\n            supported_comfyui_frontend_version:\n              versionData.supported_comfyui_frontend_version,\n            supported_os: normalizeOSList(versionData.supported_os),\n            supported_accelerators: versionData.supported_accelerators,\n\n            // Status information\n            version_status: versionData.status,\n            is_banned: isBanned,\n            is_pending: isPending\n          }\n\n          requirements.push(requirement)\n        } else {\n          console.warn(\n            `[ConflictDetection] No Registry data found for ${installedPackVersion.id}, using fallback`\n          )\n\n          // Create fallback requirement without Registry data\n          const fallbackRequirement: NodeRequirements = {\n            id: installedPackVersion.id,\n            name: packInfo?.name || installedPackVersion.id,\n            installed_version: installedPackVersion.version,\n            is_enabled: isEnabled,\n            is_banned: false,\n            is_pending: false\n          }\n\n          requirements.push(fallbackRequirement)\n        }\n      }\n\n      return requirements\n    } catch (error) {\n      console.warn(\n        '[ConflictDetection] Failed to fetch package requirements:',\n        error\n      )\n      return []\n    }\n  }\n\n  /**\n   * Detects conflicts for an individual package using Registry API data.\n   *\n   * @param packageReq Package requirements from Registry\n   * @param sysEnv Current system environment\n   * @returns Conflict detection result for the package\n   */\n  function analyzePackageConflicts(\n    packageReq: NodeRequirements,\n    systemEnvInfo: SystemEnvironment\n  ): ConflictDetectionResult {\n    const conflicts = evaluateCompatibility(\n      {\n        supported_os: packageReq.supported_os as RegistryOS[] | undefined,\n        supported_accelerators: packageReq.supported_accelerators as\n          | RegistryAccelerator[]\n          | undefined,\n        supported_comfyui_version: packageReq.supported_comfyui_version,\n        supported_comfyui_frontend_version:\n          packageReq.supported_comfyui_frontend_version,\n        isBanned: packageReq.is_banned,\n        isPending: packageReq.is_pending\n      },\n      systemEnvInfo\n    )\n\n    const hasConflict = conflicts.length > 0\n\n    return {\n      package_id: packageReq.id ?? '',\n      package_name: packageReq.name ?? '',\n      has_conflict: hasConflict,\n      conflicts,\n      is_compatible: !hasConflict\n    }\n  }\n\n  /**\n   * Fetches Python import failure information from ComfyUI Manager.\n   * Gets installed packages and checks each one for import failures using bulk API.\n   * @returns Promise that resolves to import failure data\n   */\n  async function fetchImportFailInfo(): Promise<ImportFailureMap> {\n    try {\n      const comfyManagerService = useComfyManagerService()\n\n      // Use installedPacksWithVersions to match what versions bulk API uses\n      // This ensures both APIs check the same set of packages\n      if (installedPacksWithVersions.value.length === 0) {\n        console.warn(\n          '[ConflictDetection] No installed packages available for import failure check'\n        )\n        return {}\n      }\n\n      const packageIds = installedPacksWithVersions.value.map((pack) => pack.id)\n\n      // Use bulk API to get import failure info for all packages at once\n      const bulkResult = await comfyManagerService.getImportFailInfoBulk(\n        { cnr_ids: packageIds },\n        abortController.value?.signal\n      )\n\n      if (bulkResult) {\n        // Filter out null values (packages without import failures)\n        const importFailures: ImportFailureMap = {}\n\n        Object.entries(bulkResult).forEach(([packageId, failInfo]) => {\n          if (failInfo !== null) {\n            importFailures[packageId] = failInfo\n          }\n        })\n\n        return importFailures\n      }\n\n      return {}\n    } catch (error) {\n      console.warn(\n        '[ConflictDetection] Failed to fetch import failure information:',\n        error\n      )\n      return {}\n    }\n  }\n\n  /**\n   * Detects runtime conflicts from Python import failures.\n   * @param importFailInfo Import failure data from Manager API\n   * @returns Array of conflict detection results for failed imports\n   */\n  function detectImportFailConflicts(\n    importFailInfo: ImportFailureMap\n  ): ConflictDetectionResult[] {\n    const results: ConflictDetectionResult[] = []\n    if (typeof importFailInfo !== 'object') {\n      return results\n    }\n\n    // Process import failures\n    for (const [packageId, failureInfo] of Object.entries(importFailInfo)) {\n      if (!failureInfo || typeof failureInfo !== 'object') continue\n\n      const errorMsg = failureInfo.error || 'Unknown import error'\n      const fullErrorInfo = failureInfo.traceback || errorMsg\n\n      results.push({\n        package_id: packageId,\n        package_name: packageId,\n        has_conflict: true,\n        conflicts: [\n          {\n            type: 'import_failed',\n            current_value: errorMsg,\n            required_value: fullErrorInfo\n          }\n        ],\n        is_compatible: false\n      })\n\n      console.warn(\n        `[ConflictDetection] Python import failure detected for ${packageId}:`,\n        errorMsg\n      )\n    }\n\n    return results\n  }\n\n  /**\n   * Performs complete conflict detection.\n   * @returns Promise that resolves to conflict detection response\n   */\n  async function runFullConflictAnalysis(): Promise<ConflictDetectionResponse> {\n    if (isDetecting.value) {\n      return {\n        success: false,\n        error_message: 'Already detecting conflicts',\n        results: detectionResults.value\n      }\n    }\n\n    isDetecting.value = true\n    detectionError.value = null\n\n    try {\n      // 1. Collect system environment information\n      const systemEnvInfo = await collectSystemEnvironment()\n\n      // 2. Collect installed node requirement information\n      const installedNodeRequirements = await buildNodeRequirements()\n\n      // 3. Detect conflicts for each package (parallel processing)\n      const conflictDetectionTasks = installedNodeRequirements.map(\n        async (packageReq) => {\n          try {\n            return analyzePackageConflicts(packageReq, systemEnvInfo)\n          } catch (error) {\n            console.warn(\n              `[ConflictDetection] Failed to detect conflicts for package ${packageReq.name}:`,\n              error\n            )\n            // Return null for failed packages, will be filtered out\n            return null\n          }\n        }\n      )\n\n      const conflictResults = await Promise.allSettled(conflictDetectionTasks)\n      const packageResults: ConflictDetectionResult[] = conflictResults\n        .map((result) => (result.status === 'fulfilled' ? result.value : null))\n        .filter((result): result is ConflictDetectionResult => result !== null)\n\n      // 4. Detect Python import failures\n      const importFailInfo = await fetchImportFailInfo()\n      const importFailResults = detectImportFailConflicts(importFailInfo)\n\n      // 5. Combine all results\n      const allResults = [...packageResults, ...importFailResults]\n\n      // 6. Update state\n      detectionResults.value = allResults\n      lastDetectionTime.value = new Date().toISOString()\n\n      // Store conflict results for later UI display\n      // Dialog will be shown based on specific events, not on app mount\n      if (allResults.some((result) => result.has_conflict)) {\n        const conflictedResults = allResults.filter(\n          (result) => result.has_conflict\n        )\n\n        // Merge conflicts for packages with the same name\n        const mergedConflicts = consolidateConflictsByPackage(conflictedResults)\n\n        // Store merged conflicts in Pinia store for UI usage\n        conflictStore.setConflictedPackages(mergedConflicts)\n\n        // Also update local state for backward compatibility\n        detectionResults.value = [...mergedConflicts]\n        storedMergedConflicts.value = [...mergedConflicts]\n\n        // Use merged conflicts in response as well\n        const response: ConflictDetectionResponse = {\n          success: true,\n          results: mergedConflicts,\n          detected_system_environment: systemEnvInfo\n        }\n        return response\n      } else {\n        // No conflicts detected, clear the results\n        conflictStore.clearConflicts()\n        detectionResults.value = []\n      }\n\n      const response: ConflictDetectionResponse = {\n        success: true,\n        results: allResults,\n        detected_system_environment: systemEnvInfo\n      }\n\n      return response\n    } catch (error) {\n      console.error(\n        '[ConflictDetection] Error during conflict detection:',\n        error\n      )\n      detectionError.value =\n        error instanceof Error ? error.message : String(error)\n\n      return {\n        success: false,\n        error_message: detectionError.value,\n        results: []\n      }\n    } finally {\n      isDetecting.value = false\n      // Clear abort controller to prevent memory leaks\n      if (abortController.value) {\n        abortController.value = null\n      }\n    }\n  }\n\n  /**\n   * Error-resilient initialization (called on app mount).\n   * Async function that doesn't block UI setup.\n   * Ensures proper order: system_stats -> manager state -> installed -> versions bulk -> import_fail_info_bulk\n   */\n  async function initializeConflictDetection(): Promise<void> {\n    try {\n      // First, wait for systemStats to be initialized\n      const systemStatsStore = useSystemStatsStore()\n      await until(() => systemStatsStore.isInitialized).toBe(true)\n\n      // Now check if manager is new Manager\n      const managerState = useManagerState()\n\n      if (!managerState.isNewManagerUI.value) {\n        return\n      }\n\n      // Manager is new Manager, perform conflict detection\n      // The useInstalledPacks will handle fetching installed list if needed\n      await runFullConflictAnalysis()\n    } catch (error) {\n      console.warn(\n        '[ConflictDetection] Error during initialization (ignored):',\n        error\n      )\n      // Errors do not affect other parts of the app\n    }\n  }\n\n  // Cleanup function for request cancellation\n  function cancelRequests(): void {\n    if (abortController.value) {\n      abortController.value.abort()\n      abortController.value = null\n    }\n  }\n\n  // Auto-cleanup on component unmount\n  // Only register lifecycle hooks if we're in a Vue component context\n  const instance = getCurrentInstance()\n  if (instance) {\n    onUnmounted(() => {\n      cancelRequests()\n    })\n  }\n\n  // Helper functions (implementations at the bottom of the file)\n\n  /**\n   * Check if conflicts should trigger modal display after \"What's New\" dismissal\n   */\n  async function shouldShowConflictModalAfterUpdate(): Promise<boolean> {\n    // Ensure conflict detection has run\n    if (detectionResults.value.length === 0) {\n      await runFullConflictAnalysis()\n    }\n\n    // Check if this is a version update scenario\n    // In a real scenario, this would check actual version change\n    // For now, we'll assume it's an update if we have conflicts and modal hasn't been dismissed\n    const hasActualConflicts = hasConflicts.value\n    const canShowModal = acknowledgment.shouldShowConflictModal.value\n\n    return hasActualConflicts && canShowModal\n  }\n\n  /**\n   * Check compatibility for a node.\n   * Used by components like PackVersionSelectorPopover.\n   */\n  function checkNodeCompatibility(\n    node: Node | components['schemas']['NodeVersion']\n  ) {\n    const { isBanned, isPending } = deriveStatusFlags(node.status)\n    const conflicts = evaluateCompatibility(\n      {\n        supported_os: normalizeOSList(node.supported_os),\n        supported_accelerators:\n          node.supported_accelerators as RegistryAccelerator[],\n        supported_comfyui_version: node.supported_comfyui_version,\n        supported_comfyui_frontend_version:\n          node.supported_comfyui_frontend_version,\n        isBanned,\n        isPending\n      },\n      {\n        comfyui_version: systemEnvironment.value?.comfyui_version,\n        frontend_version: getFrontendVersion(),\n        os: systemEnvironment.value?.os,\n        accelerator: systemEnvironment.value?.accelerator\n      }\n    )\n\n    return {\n      hasConflict: conflicts.length > 0,\n      conflicts\n    }\n  }\n\n  return {\n    // State\n    isDetecting: readonly(isDetecting),\n    lastDetectionTime: readonly(lastDetectionTime),\n    detectionError: readonly(detectionError),\n    systemEnvironment: readonly(systemEnvironment),\n    detectionResults: readonly(detectionResults),\n\n    // Computed\n    hasConflicts,\n    conflictedPackages,\n    bannedPackages,\n    securityPendingPackages,\n\n    // Methods\n    runFullConflictAnalysis,\n    collectSystemEnvironment,\n    initializeConflictDetection,\n    cancelRequests,\n    shouldShowConflictModalAfterUpdate,\n\n    // Helper functions for other components\n    checkNodeCompatibility\n  }\n}\n"],"file":"useConflictDetection-eg6t2cFw.js"}"""

